const COLLECTION_DATA = {
  cms:         { title: 'Count-Min Sketch',              file: 'collection/cms.html',         tag: 'Algorithm' },
  topk:        { title: 'Top-K End-to-End Design',       file: 'collection/topk.html',        tag: 'System Design' },
  ai_handbook: { title: 'AI Leadership Handbook',        file: 'collection/ai_handbook.html', tag: 'AI / Leadership' },
  databases:   { title: 'Databases Compared',            srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Databases Compared \u2014 FAANG Interview Guide</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#1a1814;--page:#faf8f4;--surface:#f0ede6;--border:#e0dbd0;--muted:#7a7468;--pg:#2d6a9f;--pg-bg:#eef4fb;--mg:#1a8a45;--mg-bg:#edfaf2;--dy:#c47a00;--dy-bg:#fdf5e8;--ca:#0e7a8a;--ca-bg:#eaf6f8;--red:#b83030;--red-bg:#fdf0f0;--green:#1a6e40;--green-bg:#edf7f0;--amber:#b87010;--amber-bg:#fdf5e3;--blue:#1a4a90;--blue-bg:#eef2fb;--mono:'JetBrains Mono',monospace;--sans:'Source Sans 3',sans-serif;--serif:'Playfair Display',serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#f0ede6;padding:52px 24px 44px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 39px,rgba(255,255,255,.02) 40px),repeating-linear-gradient(90deg,transparent,transparent 39px,rgba(255,255,255,.02) 40px);}\n.hero-inner{max-width:920px;margin:0 auto;position:relative;z-index:1;}\n.eyebrow{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6858;text-transform:uppercase;margin-bottom:18px;display:flex;align-items:center;gap:10px;}\n.eyebrow::before{content:'';width:24px;height:1px;background:#3a3828;}\nh1{font-family:var(--serif);font-size:clamp(28px,5vw,52px);font-weight:900;line-height:1.05;letter-spacing:-1px;margin-bottom:16px;}\nh1 .acc{color:#e8b84b;}\n.hero-desc{font-size:15px;color:#7a7868;max-width:600px;line-height:1.7;margin-bottom:24px;}\n.db-badges{display:flex;flex-wrap:wrap;gap:8px;}\n.db-badge{font-family:var(--mono);font-size:10px;padding:4px 12px;border-radius:3px;font-weight:600;letter-spacing:.5px;}\n.db-pg{background:var(--pg);color:#fff;}.db-mg{background:var(--mg);color:#fff;}.db-dy{background:var(--dy);color:#fff;}.db-ca{background:var(--ca);color:#fff;}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1d18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#5a5850;text-decoration:none;padding:13px 13px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:920px;margin:0 auto;padding:0 20px;}\nsection{padding:48px 0 32px;border-bottom:2px solid var(--border);}section:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(20px,3.5vw,30px);font-weight:700;letter-spacing:-.3px;line-height:1.15;margin-bottom:14px;color:var(--ink);}\nh3{font-family:var(--serif);font-size:17px;font-weight:700;margin:28px 0 10px;color:var(--ink);border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;max-width:760px;}strong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:12px;background:var(--surface);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.callout{border-radius:4px;padding:14px 18px;margin:16px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;max-width:none;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2808;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0808;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.steps{list-style:none;margin:16px 0;counter-reset:s;}\n.steps li{counter-increment:s;display:flex;gap:14px;align-items:flex-start;padding:14px 16px;background:white;border:1px solid var(--border);border-radius:6px;margin-bottom:8px;}\n.steps li::before{content:counter(s);font-family:var(--mono);font-size:11px;font-weight:700;color:white;background:var(--ink);min-width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;}\n.step-title{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:4px;}\n.step-desc{font-size:13px;color:#5a5848;line-height:1.65;}\n.step-desc ul{margin:6px 0 0 16px;}.step-desc li{margin-bottom:4px;font-size:13px;color:#5a5848;}\n.blist{list-style:none;margin:12px 0;}\n.blist li{padding:7px 0 7px 20px;position:relative;font-size:14px;color:#3a3830;border-bottom:1px solid var(--border);line-height:1.65;}\n.blist li:last-child{border:none;}.blist li::before{content:'\u2192';position:absolute;left:0;color:var(--amber);font-weight:700;}\n.codeblock{background:var(--ink);border-radius:6px;padding:18px 22px;font-family:var(--mono);font-size:12px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;}\n.db-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0;}\n@media(max-width:640px){.db-grid{grid-template-columns:1fr;}}\n.db-card{background:white;border:1px solid var(--border);border-radius:6px;padding:18px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}.db-card.mg::before{background:var(--mg);}.db-card.dy::before{background:var(--dy);}.db-card.ca::before{background:var(--ca);}\n.db-card-name{font-family:var(--serif);font-size:18px;font-weight:700;margin:10px 0 4px;}\n.db-card.pg .db-card-name{color:var(--pg);}.db-card.mg .db-card-name{color:var(--mg);}.db-card.dy .db-card-name{color:var(--dy);}.db-card.ca .db-card-name{color:var(--ca);}\n.db-card-role{font-size:12px;color:var(--muted);margin-bottom:12px;font-family:var(--mono);}\n.db-row{display:flex;justify-content:space-between;align-items:flex-start;font-size:12.5px;padding:6px 0;border-top:1px solid var(--surface);}\n.db-k{color:var(--muted);flex-shrink:0;width:110px;}.db-v{font-family:var(--mono);font-size:11.5px;color:var(--ink);text-align:right;flex:1;}\n.db-v.g{color:var(--green);}.db-v.a{color:var(--amber);}.db-v.r{color:var(--red);}\n.matrix{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.matrix th{font-family:var(--mono);font-size:9px;letter-spacing:2px;padding:10px 12px;border:1px solid var(--border);background:var(--surface);color:var(--muted);text-transform:uppercase;}\n.matrix td{padding:11px 12px;border:1px solid var(--border);color:#3a3830;vertical-align:top;line-height:1.6;}\n.matrix .rh{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.badge{display:inline-block;font-family:var(--mono);font-size:10px;padding:2px 8px;border-radius:3px;border:1px solid;font-weight:500;vertical-align:middle;margin:2px;}\n.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}.b-b{background:var(--blue-bg);border-color:var(--blue);color:var(--blue);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}\n.faq{border:1px solid var(--border);border-radius:5px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:600;user-select:none;transition:background .15s;}\n.faq-q:hover{background:var(--surface);}\n.faq-tog{font-size:18px;color:var(--amber);transition:transform .2s;flex-shrink:0;margin-left:12px;}\n.faq-a{display:none;padding:16px 18px;background:var(--surface);border-top:1px solid var(--border);font-size:13.5px;color:#3a3830;line-height:1.75;}\n.faq.open .faq-a{display:block;}.faq.open .faq-tog{transform:rotate(45deg);}\n.faq-a ul,.faq-a ol{padding-left:20px;margin:8px 0;}.faq-a li{margin-bottom:6px;font-size:13.5px;color:#3a3830;line-height:1.65;}\n.dtree{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;margin:20px 0;}\n.dtree-node{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);}\n.dtree-node:last-child{border:none;}\n.dtree-q{font-weight:600;font-size:13.5px;color:var(--ink);flex:1;}\n.dtree-a{font-family:var(--mono);font-size:11px;padding:3px 10px;border-radius:3px;flex-shrink:0;margin-left:8px;border:1px solid;}\n.dtree-a.pg{background:var(--pg-bg);color:var(--pg);border-color:var(--pg);}.dtree-a.mg{background:var(--mg-bg);color:var(--mg);border-color:var(--mg);}.dtree-a.dy{background:var(--dy-bg);color:var(--dy);border-color:var(--dy);}.dtree-a.ca{background:var(--ca-bg);color:var(--ca);border-color:var(--ca);}.dtree-a.ask{background:var(--surface);color:var(--muted);border-color:var(--border);}\n.oneliner{background:var(--ink);color:var(--page);border-radius:10px;padding:32px 28px;text-align:center;margin:44px 0;}\n.oneliner .lbl{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:#5a5850;margin-bottom:14px;}\n.oneliner blockquote{font-family:var(--serif);font-size:clamp(14px,2.2vw,18px);font-weight:700;line-height:1.65;color:#e8e0d0;font-style:italic;}\nfooter{background:var(--ink);text-align:center;padding:32px 20px;font-family:var(--mono);font-size:10px;color:#3a3828;letter-spacing:2px;}\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"eyebrow\">FAANG Interview Prep \u00b7 Database Selection</div>\n    <h1>PostgreSQL \u00b7 MongoDB<br><span class=\"acc\">DynamoDB \u00b7 Cassandra</span></h1>\n    <p class=\"hero-desc\">Every dimension that matters in a system design interview \u2014 explained from first principles so a layman would understand, with real examples and every follow-up question.</p>\n    <div class=\"db-badges\">\n      <span class=\"db-badge db-pg\">PostgreSQL \u2014 Relational</span>\n      <span class=\"db-badge db-mg\">MongoDB \u2014 Document</span>\n      <span class=\"db-badge db-dy\">DynamoDB \u2014 Key-Value</span>\n      <span class=\"db-badge db-ca\">Cassandra \u2014 Wide-Column</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#mental-model\">Mental Model</a><a href=\"#four-dbs\">The Four DBs</a>\n  <a href=\"#dimensions\">Every Dimension</a><a href=\"#sharding\">Sharding</a>\n  <a href=\"#cap\">CAP Theorem</a><a href=\"#when-to-use\">When to Use</a>\n  <a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"mental-model\">\n  <div class=\"sec-tag\">01 \u00b7 The Mental Model</div>\n  <h2>Why four databases exist \u2014 the core trade-off</h2>\n  <p>Every database makes one fundamental choice: <strong>how do you organise and find your data?</strong> That choice determines write speed, query flexibility, how it scales, and what breaks under pressure.</p>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">\ud83c\udfe0 The Filing Cabinet Analogy</div>\n    <p><strong>PostgreSQL</strong> = A perfectly organised office with labelled folders, cross-references, and a master index. Find anything, join anything. Adding a new filing cabinet (scaling) requires reorganising everything.</p>\n    <p style=\"margin-top:6px;\"><strong>MongoDB</strong> = A drawer of envelopes, each containing a complete self-contained document. Easy to add envelopes. Hard to cross-reference across them.</p>\n    <p style=\"margin-top:6px;\"><strong>DynamoDB</strong> = A lookup table. You know the key \u2192 you get the value instantly. Anything else must be pre-designed into the table.</p>\n    <p style=\"margin-top:6px;\"><strong>Cassandra</strong> = A distributed ledger across 100 filing cabinets in 10 cities. Every cabinet holds the same data (replication). Writes land everywhere fast. Reading anything you didn't pre-plan is painful.</p>\n  </div>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">\ud83d\udcac Say This First in Your Interview</div>\n    <p><em>\"Before I pick a database, I need to understand two things: (1) What is the write pattern \u2014 writes/sec and shape? (2) What are the read patterns \u2014 do I need flexible queries or do I always know exactly what key I'm looking for?\"</em></p>\n    <p style=\"margin-top:6px;\">This eliminates wrong choices before drawing a single box.</p>\n  </div>\n</section>\n\n<section id=\"four-dbs\">\n  <div class=\"sec-tag\">02 \u00b7 The Four Databases</div>\n  <h2>Core identity of each</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card pg\">\n      <div class=\"db-card-name\">PostgreSQL</div><div class=\"db-card-role\">Relational \u00b7 ACID \u00b7 Row storage</div>\n      <div class=\"db-row\"><span class=\"db-k\">Best for</span><span class=\"db-v\">Complex queries, joins, transactions</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Write TPS</span><span class=\"db-v a\">~5K\u201310K/sec single node</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Read</span><span class=\"db-v g\">Full SQL \u2014 most expressive</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Scaling</span><span class=\"db-v a\">Vertical first, hard to shard</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">ACID</span><span class=\"db-v g\">Full multi-table ACID</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">FAANG use</span><span class=\"db-v\">User profiles, payments, orders</span></div>\n    </div>\n    <div class=\"db-card mg\">\n      <div class=\"db-card-name\">MongoDB</div><div class=\"db-card-role\">Document \u00b7 Flexible schema \u00b7 BSON</div>\n      <div class=\"db-row\"><span class=\"db-k\">Best for</span><span class=\"db-v\">Variable schema, nested docs, rapid iteration</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Write TPS</span><span class=\"db-v g\">~20K\u201350K/sec with replication</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Read</span><span class=\"db-v g\">Rich MQL, aggregation pipeline</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Scaling</span><span class=\"db-v g\">Built-in horizontal sharding</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">ACID</span><span class=\"db-v a\">Single-doc ACID, multi-doc with cost</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">FAANG use</span><span class=\"db-v\">Product catalogues, CMS, event logs</span></div>\n    </div>\n    <div class=\"db-card dy\">\n      <div class=\"db-card-name\">DynamoDB</div><div class=\"db-card-role\">Key-Value \u00b7 Managed \u00b7 AWS native</div>\n      <div class=\"db-row\"><span class=\"db-k\">Best for</span><span class=\"db-v\">Known-key access, massive scale, serverless</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Write TPS</span><span class=\"db-v g\">Unlimited \u2014 auto-scales</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Read</span><span class=\"db-v r\">Only PK/SK + GSI for extras</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Scaling</span><span class=\"db-v g\">Fully managed, zero ops</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">ACID</span><span class=\"db-v a\">Single-item; multi-item costs</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">FAANG use</span><span class=\"db-v\">Sessions, carts, rate limiting</span></div>\n    </div>\n    <div class=\"db-card ca\">\n      <div class=\"db-card-name\">Cassandra</div><div class=\"db-card-role\">Wide-Column \u00b7 AP \u00b7 Write-optimised</div>\n      <div class=\"db-row\"><span class=\"db-k\">Best for</span><span class=\"db-v\">Extreme write throughput, time-series</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Write TPS</span><span class=\"db-v g\">100K\u20131M+/sec cluster-wide</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Read</span><span class=\"db-v r\">Partition key only \u2014 pre-planned</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">Scaling</span><span class=\"db-v g\">Linear \u2014 add nodes, capacity doubles</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">ACID</span><span class=\"db-v r\">No ACID \u2014 eventual by default</span></div>\n      <div class=\"db-row\"><span class=\"db-k\">FAANG use</span><span class=\"db-v\">Metrics, time-series, IoT feeds</span></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"dimensions\">\n  <div class=\"sec-tag\">03 \u00b7 Every Dimension That Matters</div>\n  <h2>The full comparison matrix</h2>\n  <table class=\"matrix\">\n    <thead><tr><th>Dimension</th><th>PostgreSQL</th><th>MongoDB</th><th>DynamoDB</th><th>Cassandra</th></tr></thead>\n    <tbody>\n      <tr><td class=\"rh\">Data model</td><td>Tables, fixed schema, rows. Schema changes need migrations (ALTER TABLE).</td><td>JSON documents (BSON). No fixed schema \u2014 documents in same collection can differ completely.</td><td>Items with Partition Key + optional Sort Key. Other attributes are free-form.</td><td>Rows with Partition Key. Wide columns per row can vary. Like a multi-dimensional hashmap.</td></tr>\n      <tr><td class=\"rh\">Query language</td><td>Full SQL \u2014 JOINs, window functions, aggregations, subqueries. Most expressive.</td><td>MQL (MongoDB Query Language) \u2014 rich JSON queries, aggregation pipeline. No cross-collection joins.</td><td>GetItem/Query by PK only. For other access patterns: Global Secondary Index (GSI) at extra cost.</td><td>CQL \u2014 looks like SQL but no JOINs, no GROUP BY, no subqueries. Every query must hit partition key.</td></tr>\n      <tr><td class=\"rh\">ACID transactions</td><td><span class=\"dot g\"></span>Full ACID across rows and tables. Multi-table atomic commits.</td><td><span class=\"dot g\"></span>Single-document ACID. Multi-document transactions exist (v4.0+) but cost performance.</td><td><span class=\"dot a\"></span>Single-item ACID. Multi-item via TransactWriteItems \u2014 limited to 25 items, expensive in WCUs.</td><td><span class=\"dot r\"></span>Lightweight transactions via Paxos (compare-and-set). 4\u00d7 performance penalty. Avoid.</td></tr>\n      <tr><td class=\"rh\">Write throughput</td><td>~5K\u201310K TPS single node. WAL + MVCC overhead is the bottleneck. Partitioning helps.</td><td>~20K\u201350K TPS with primary acknowledgement. Higher with <code>w:0</code> fire-and-forget.</td><td>Effectively unlimited \u2014 on-demand auto-scales. No pre-configuration needed.</td><td>100K\u20131M+ TPS cluster-wide. LSM-tree + commit log: appends never block, no locking.</td></tr>\n      <tr><td class=\"rh\">Read latency</td><td>1\u201310ms for indexed reads. Full table scan is slow on large tables.</td><td>1\u201310ms for indexed reads. Aggregation pipeline on large collections needs proper indexes.</td><td>&lt;1ms single-digit p99 for GetItem by key. Consistent at any scale.</td><td>1\u20135ms for partition key reads. Lower consistency level = lower latency.</td></tr>\n      <tr><td class=\"rh\">Scaling model</td><td>Vertical first (bigger machine). Read replicas for read scale. Manual sharding is complex (CitusDB, Vitess).</td><td>Built-in sharding. Shard key choice is critical \u2014 wrong key creates hotspots.</td><td>Fully managed by AWS. No ops. Hot partition design issue still exists if partition key is bad.</td><td>Masterless \u2014 every node is equal. Add a node, capacity scales linearly. No single point of failure.</td></tr>\n      <tr><td class=\"rh\">Consistency</td><td>Strong \u2014 reads always see latest committed write.</td><td>Eventual by default. Primary read = strong. Secondary read = possibly stale.</td><td>Eventual by default. Strongly consistent reads available at 2\u00d7 read capacity cost.</td><td>Tunable: ONE (eventual, fast) \u2192 QUORUM (majority) \u2192 ALL (strong, slow). W + R &gt; RF = strong.</td></tr>\n      <tr><td class=\"rh\">Failure handling</td><td>Primary fails \u2192 failover via Patroni/PgBouncer. Replicas can lag. Brief unavailability.</td><td>Replica set election \u2014 auto failover in 10\u201330s. Risk of data loss in election window.</td><td>AWS manages HA. Multi-AZ by default. Global Tables for cross-region.</td><td>Node failure is invisible \u2014 Hinted Handoff queues writes for the dead node. No downtime for queries.</td></tr>\n      <tr><td class=\"rh\">Cost model</td><td>Instance-based. Open source \u2014 no licence cost. Expensive at very large scale.</td><td>Instance or Atlas (managed). More expensive than Postgres at equivalent instance size.</td><td>Per request (on-demand) or per WCU/RCU (provisioned). Very expensive for large scans.</td><td>Instance-based (self-hosted) or DataStax Astra. Cheap per write at scale. Ops overhead costly.</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"sharding\">\n  <div class=\"sec-tag\">04 \u00b7 Sharding Deep Dive</div>\n  <h2>How each database splits data across machines</h2>\n  <p>Sharding = distributing data across multiple nodes so no single machine holds everything. When your dataset outgrows one machine, you shard. Every database does this differently.</p>\n  <h3>Step-by-step: what happens when you shard</h3>\n  <ol class=\"steps\">\n    <li><div><div class=\"step-title\">Choose a partition key (shard key)</div><div class=\"step-desc\">The most important decision. Determines which machine holds which data.\n      <ul><li><strong>Good key:</strong> <code>user_id</code> \u2014 high cardinality, uniform distribution, no single value dominates traffic</li><li><strong>Bad key:</strong> <code>country</code> \u2014 only ~200 values, US alone is 40% of traffic \u2192 hot shard immediately</li><li><strong>Bad key:</strong> <code>created_at</code> (timestamp) \u2014 all new writes go to the \"latest\" shard \u2192 write hotspot</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Hash the key to select the shard</div><div class=\"step-desc\">Most databases compute <code>hash(partition_key) % num_shards</code> to pick a shard node.\n      <ul><li><strong>Consistent hashing</strong> (Cassandra, DynamoDB): adding a node only remaps 1/N of keys, not everything \u2014 much less reshuffling</li><li><strong>Range-based sharding</strong> (MongoDB option): adjacent keys on same shard \u2014 great for range queries but creates monotonic hotspots</li><li><strong>Hash-based sharding</strong> (MongoDB option): uniform distribution, no hotspots, but range queries must scatter across all shards</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Route the request to the correct shard</div><div class=\"step-desc\">The database (or a proxy) maps the key to the correct shard and routes the query.\n      <ul><li><strong>Cassandra:</strong> Any node acts as coordinator \u2014 client connects to any node, coordinator routes internally</li><li><strong>DynamoDB:</strong> Routing is completely invisible \u2014 AWS handles it, developer never sees it</li><li><strong>MongoDB:</strong> <code>mongos</code> router process handles routing transparently to the application</li><li><strong>PostgreSQL:</strong> No built-in routing \u2014 application must know which shard to query (or use Citus extension)</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Handle cross-shard (scatter-gather) queries</div><div class=\"step-desc\">If your query needs data from multiple shards, you fan-out to all shards and merge. This is expensive.\n      <ul><li><strong>Cassandra:</strong> Querying without partition key = scatter across all nodes, merge on coordinator \u2192 avoid at all costs</li><li><strong>MongoDB:</strong> mongos fans out to all shards, merges \u2014 acceptable but slower than single-shard queries</li><li><strong>DynamoDB:</strong> Requires a Global Secondary Index (GSI) \u2014 data replicated to separate internal table, eventually consistent, extra cost</li><li><strong>The rule:</strong> Design your access patterns first, then choose partition key. Not the other way around.</li></ul></div></div></li>\n  </ol>\n  <div class=\"callout cl-red\">\n    <div class=\"cl-lbl\">\ud83d\udd25 Hot Partition \u2014 The Most Common Interview Trap</div>\n    <p><strong>Problem:</strong> One shard receives 80% of writes because the partition key is unevenly distributed. <code>\"celebrity_user_id\"</code> with 50M followers generates all writes to one Cassandra node while others sit idle.</p>\n    <p style=\"margin-top:8px;\"><strong>Fix \u2014 Key Salting:</strong> Append a random suffix 0\u20137 to the key: write to <code>\"celebrity#0\"</code> through <code>\"celebrity#7\"</code>. Distributes across 8 shards. On read: fan-out to all 8 partitions and sum the counts. Trade-off: read requires 8 queries instead of 1.</p>\n    <p style=\"margin-top:8px;\"><strong>DynamoDB-specific:</strong> AWS Adaptive Capacity now auto-rebalances hot partitions. Also, use write sharding with suffix 1\u201310 and parallel reads to recombine.</p>\n  </div>\n</section>\n\n<section id=\"cap\">\n  <div class=\"sec-tag\">05 \u00b7 CAP Theorem</div>\n  <h2>The constraint every distributed database lives with</h2>\n  <p>During a network partition \u2014 when nodes cannot communicate with each other \u2014 a distributed system must choose between two options. It cannot have both.</p>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">\ud83c\udfe7 The ATM Analogy</div>\n    <p><strong>Consistent + Partition-tolerant (CP):</strong> The ATM refuses your withdrawal if it cannot reach the bank's server to verify balance. You get an error. Your money is safe. Banking systems do this intentionally.</p>\n    <p style=\"margin-top:8px;\"><strong>Available + Partition-tolerant (AP):</strong> The ATM lets you withdraw even without reaching the server. You get your cash immediately. The bank might temporarily let your balance go negative. Cassandra chooses this by default.</p>\n  </div>\n  <table class=\"matrix\">\n    <thead><tr><th>Database</th><th>CAP Choice</th><th>What That Means in Practice</th><th>When It Matters</th></tr></thead>\n    <tbody>\n      <tr><td class=\"rh\">PostgreSQL</td><td><span class=\"badge b-b\">CP</span></td><td>Strong consistency always. During primary failover: brief unavailability. Never serves stale data.</td><td>Payments, inventory \u2014 correctness over availability</td></tr>\n      <tr><td class=\"rh\">MongoDB</td><td><span class=\"badge b-a\">AP</span>/<span class=\"badge b-b\">CP</span></td><td>Read from primary = CP. Read from secondary = AP (may be stale). Write concern controls durability.</td><td>Tune per use case: strong writes, eventual reads</td></tr>\n      <tr><td class=\"rh\">DynamoDB</td><td><span class=\"badge b-a\">AP</span>/<span class=\"badge b-b\">CP</span></td><td>Eventually consistent by default (AP). Strongly consistent reads at 2\u00d7 cost (CP). Global Tables = AP.</td><td>Sessions = AP fine. Inventory = strongly consistent reads</td></tr>\n      <tr><td class=\"rh\">Cassandra</td><td><span class=\"badge b-a\">AP</span> tunable</td><td>Masterless, AP by default. Tunable to CP via QUORUM: W + R &gt; replication factor = strong consistency.</td><td>Metrics/logs = ONE (AP). Financial counters = QUORUM (CP)</td></tr>\n    </tbody>\n  </table>\n  <h3>Cassandra consistency levels \u2014 know these cold</h3>\n  <ol class=\"steps\">\n    <li><div><div class=\"step-title\">ONE \u2014 fastest, weakest guarantee</div><div class=\"step-desc\">Write or read succeeds when ONE replica responds. Fastest possible \u2014 but if that replica dies before replicating, data is lost.\n      <ul><li>Use for: metrics, logs, analytics where occasional data loss is acceptable</li><li>Never use for: anything financial, anything users will notice missing</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">QUORUM \u2014 the production standard (most common choice)</div><div class=\"step-desc\">Requires majority of replicas (\u230aRF/2\u230b + 1) to respond. With RF=3: need 2 of 3 nodes.\n      <ul><li>Write QUORUM + Read QUORUM guarantees strong consistency: the read will always see the latest write</li><li>The formula: W + R &gt; RF \u2192 strong consistency. So with RF=3: W=2 + R=2 = 4 &gt; 3 \u2192 \u2705</li><li>Handles: one node down, one slow node \u2014 the other two still give quorum</li><li>Netflix, Instagram, Discord all use QUORUM for critical data</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">ALL \u2014 strongest but fragile</div><div class=\"step-desc\">Every single replica must respond. One slow or dead node blocks everything.\n      <ul><li>Rarely used in production \u2014 single node failure = full availability failure</li><li>Only for critical financial records where you accept unavailability over any chance of staleness</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">LOCAL_QUORUM \u2014 multi-datacenter standard</div><div class=\"step-desc\">Quorum within the local datacenter only. Cross-datacenter replication is async.\n      <ul><li>Best balance of latency and consistency in multi-region deployments</li><li>Write acknowledges quickly (local DC), replicates to remote DC in background</li><li>Standard choice for Netflix, Apple iCloud, Discord at scale</li></ul></div></div></li>\n  </ol>\n</section>\n\n<section id=\"when-to-use\">\n  <div class=\"sec-tag\">06 \u00b7 When to Use Each</div>\n  <h2>Real system design examples</h2>\n  <h3>PostgreSQL \u2014 use when you need joins and ACID</h3>\n  <ul class=\"blist\">\n    <li><strong>Payments &amp; banking:</strong> A fund transfer debits one account and credits another \u2014 both must succeed or both must fail. This needs a multi-row ACID transaction. Cassandra cannot guarantee this. PostgreSQL does it natively.</li>\n    <li><strong>E-commerce orders:</strong> Creating an order touches inventory (decrement), payments (charge), and orders (create record) \u2014 three tables that must stay consistent. Failed payment must roll back the inventory decrement atomically.</li>\n    <li><strong>User profiles with complex queries:</strong> \"Find users aged 25\u201335 in Bangalore, signed up in last 30 days, with Electronics purchase.\" This is a 3-table JOIN with multiple filters \u2014 PostgreSQL handles this in one query. Cassandra would require pre-computing every permutation.</li>\n    <li><strong>Internal analytics and reporting:</strong> BI tools, dashboards, operational reporting on structured data. PostgreSQL with proper indexes handles hundreds of millions of rows. Beyond that, move to ClickHouse/BigQuery.</li>\n  </ul>\n  <h3>MongoDB \u2014 use when schema evolves or structure varies by entity</h3>\n  <ul class=\"blist\">\n    <li><strong>Product catalogues:</strong> A T-shirt has colour/size. A laptop has RAM/CPU/battery/screen. A book has ISBN/author. Storing these in one Postgres table means hundreds of nullable columns. MongoDB stores each product as a self-contained document with exactly the fields it needs.</li>\n    <li><strong>Content management:</strong> Blog posts, news articles \u2014 each with variable metadata, nested tags, author info, embedded media. The document model maps directly to how content is consumed and rendered.</li>\n    <li><strong>Rapid-iteration startups:</strong> When schema is unstable (new features every sprint), MongoDB avoids costly ALTER TABLE migrations. Add a new field \u2014 it just exists in new documents; old documents simply lack it.</li>\n    <li><strong>Geospatial queries:</strong> \"Find restaurants within 2km of me.\" MongoDB has native GeoJSON support and 2dsphere indexes. A single MongoDB query with <code>$near</code> handles this. PostgreSQL needs PostGIS extension.</li>\n  </ul>\n  <h3>DynamoDB \u2014 use when access pattern is known and scale is extreme</h3>\n  <ul class=\"blist\">\n    <li><strong>User sessions:</strong> Key = session_id. Value = user data + expiry. Always looked up by session_id \u2014 never \"find all sessions for user X.\" DynamoDB: &lt;1ms, infinite scale, TTL auto-expires stale sessions. Amazon built DynamoDB precisely for this use case.</li>\n    <li><strong>Shopping carts:</strong> Key = user_id. Value = serialised cart. Always fetched by user_id. No joins, no aggregations. Amazon's shopping cart runs on DynamoDB \u2014 millions of concurrent users, sub-millisecond reads.</li>\n    <li><strong>Rate limiting:</strong> Key = (user_id + endpoint). Value = counter + window. Atomic increment via <code>UpdateItem ADD count 1 SET expiry = :ttl</code>. Consistent, fast, infinitely scalable.</li>\n    <li><strong>Gaming leaderboards:</strong> Partition key = game_id, Sort key = score (descending). <code>QUERY</code> returns top 10 in one call. But \"rank of a specific player globally\" cannot be done efficiently without pre-computing \u2014 DynamoDB does not support COUNT of items with higher score in real time.</li>\n  </ul>\n  <h3>Cassandra \u2014 use when write throughput is extreme and access is pre-planned</h3>\n  <ul class=\"blist\">\n    <li><strong>Time-series metrics:</strong> Partition key = (metric_name, date). Clustering key = timestamp DESC. All metrics for server_01 on 2026-03-20 land in one partition, sorted by time. Query \"CPU metrics 2pm\u20133pm\" = single fast partition scan. Netflix uses this for their telemetry pipeline \u2014 billions of metrics/day.</li>\n    <li><strong>IoT event streams:</strong> 100K+ sensor readings/second. Pure appends \u2014 no updates, no deletes. Cassandra's LSM-tree model is built for this. Reads always \"latest N readings for sensor X\" = partition key lookup.</li>\n    <li><strong>Activity feeds (pre-computed fan-out):</strong> On write, distribute tweet to each follower's timeline partition. On read: single partition scan. No JOINs at read time. Twitter's timeline service used Cassandra for this at 300K writes/sec.</li>\n    <li><strong>Aggregated counts in Top-K:</strong> Partition key = (entity_type, region). Clustering key = (window_bucket DESC, entity_id). Flink writes 50K rows/sec of aggregated counts. Cassandra handles this; PostgreSQL at this write rate would WAL-bottleneck immediately.</li>\n  </ul>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">07 \u00b7 Decision Tree</div>\n  <h2>Pick your database in 60 seconds</h2>\n  <div class=\"dtree\">\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Do you need multi-row / multi-table ACID transactions? (payments, deduct inventory + create order atomically)</div><div class=\"dtree-a pg\">\u2192 PostgreSQL</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Is your schema highly variable or evolving rapidly? (product catalogue with different attributes, CMS, embedded nested objects)</div><div class=\"dtree-a mg\">\u2192 MongoDB</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Is write throughput &gt;50K/sec and access is always by a known partition key? (time-series, IoT, activity feeds)</div><div class=\"dtree-a ca\">\u2192 Cassandra</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Pure key-value lookup (session by ID, cart by user ID, rate limit counter) with zero ops overhead?</div><div class=\"dtree-a dy\">\u2192 DynamoDB</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Full-text search, geospatial, graph traversal?</div><div class=\"dtree-a ask\">Elasticsearch / PostGIS / Neo4j</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Historical analytics, GROUP BY across billions of rows, dashboards?</div><div class=\"dtree-a ask\">ClickHouse / BigQuery / Redshift</div></div>\n  </div>\n  <div class=\"callout cl-green\">\n    <div class=\"cl-lbl\">\ud83c\udfc6 The Real-World Reality</div>\n    <p>Most FAANG-scale systems use <strong>multiple databases</strong> for different parts of the same product. Uber: PostgreSQL for driver/rider profiles, Cassandra for location history, Redis for current driver positions, ClickHouse for analytics. The interview is about choosing the right tool for each part \u2014 not one database for everything.</p>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">08 \u00b7 Every Hard Follow-up</div>\n  <h2>Questions interviewers always ask</h2>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">Why not use PostgreSQL for everything? It has JSONB, pgBouncer, and read replicas.<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>PostgreSQL is excellent and many companies scale it to hundreds of millions of rows with partitioning and read replicas. The argument for specialised databases:</p>\n    <ul>\n      <li><strong>Write throughput ceiling:</strong> PostgreSQL's WAL (Write-Ahead Log) and MVCC (Multi-Version Concurrency Control) create fundamental limits. At 50K+ writes/sec sustained, you're fighting the engine. Cassandra at the same rate is at 10% capacity.</li>\n      <li><strong>Sharding complexity:</strong> Sharding PostgreSQL manually (CitusDB, Vitess, or application-level) is significant engineering. DynamoDB gives this for free, managed by AWS.</li>\n      <li><strong>JSONB is powerful but not document-native:</strong> PostgreSQL JSONB still pays for row-level locking and WAL overhead. MongoDB is optimised end-to-end for document workloads.</li>\n      <li><strong>Honest answer:</strong> If your scale fits PostgreSQL (many systems with &lt;10M users do), use it. The complexity of Cassandra/DynamoDB is only justified when PostgreSQL is genuinely the bottleneck.</li>\n    </ul>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">DynamoDB vs Cassandra \u2014 when do you choose one over the other?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <ul>\n      <li><strong>Ops overhead:</strong> DynamoDB = zero. AWS manages scaling, replication, backups, patches. Cassandra = your team manages nodes, repairs, compactions, upgrades. This alone is often the deciding factor.</li>\n      <li><strong>Query flexibility:</strong> Cassandra's CQL is more expressive. Range queries on clustering columns work natively. DynamoDB needs GSIs for non-PK access \u2014 extra cost, eventual consistency.</li>\n      <li><strong>Cost:</strong> DynamoDB on-demand is convenient for bursty workloads but expensive at sustained high throughput. Cassandra on EC2 has predictable cost \u2014 often cheaper at steady 100K+ writes/sec.</li>\n      <li><strong>Multi-region:</strong> DynamoDB Global Tables is trivial to set up. Cassandra multi-DC requires manual topology but gives more control.</li>\n      <li><strong>Rule:</strong> AWS shop, want zero ops, bursty traffic \u2192 DynamoDB. Self-hosted/multi-cloud, steady high throughput, need more query flexibility \u2192 Cassandra.</li>\n    </ul>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does Cassandra handle a node going down mid-write? Is data lost?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>Cassandra uses <strong>Hinted Handoff</strong>:</p>\n    <ol>\n      <li>Write arrives at coordinator node. Coordinator tries to write to all replica nodes (e.g., RF=3 \u2192 3 replicas).</li>\n      <li>One replica is down. If consistency = QUORUM (2 of 3), write still succeeds \u2014 2 live replicas acknowledge.</li>\n      <li>Coordinator stores a <em>hint</em>: a temporary record saying \"this write needs to go to node X when it comes back.\"</li>\n      <li>When the dead node restarts, the coordinator delivers queued hints. Node becomes fully consistent.</li>\n    </ol>\n    <p style=\"margin-top:8px;\"><strong>Edge case \u2014 data loss:</strong> If the node is down longer than the hint window (3 hours default), or if ALL replicas were down simultaneously, data can be lost. This is why QUORUM is recommended \u2014 write to majority before acknowledging, so losing any one node is safe.</p>\n    <p style=\"margin-top:8px;\"><strong>Anti-entropy repair:</strong> Cassandra runs periodic background repairs using Merkle trees to find and fix inconsistencies across replicas. Netflix runs repairs continuously in the background to keep all replicas in sync.</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">Cassandra has no JOINs \u2014 how does a social app handle \"get tweets liked by users I follow\"?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>The key mental shift: <strong>denormalise and pre-compute at write time, instead of joining at read time.</strong></p>\n    <p style=\"margin-top:6px;\"><strong>Relational approach:</strong> <code>SELECT tweets.* FROM tweets JOIN likes ON tweets.id = likes.tweet_id JOIN follows ON likes.user_id = follows.follower_id WHERE follows.follower_id = ?</code> \u2014 3-table JOIN, impossible at Twitter scale.</p>\n    <p style=\"margin-top:6px;\"><strong>Cassandra approach \u2014 fan-out on write:</strong></p>\n    <ul>\n      <li>Table: <code>user_timeline (user_id PK, tweet_time CK DESC, tweet_id, content)</code></li>\n      <li>When user A posts a tweet, write to the timeline partition of every follower of A (fan-out).</li>\n      <li>Read query: <code>SELECT * FROM user_timeline WHERE user_id = ? LIMIT 20</code> \u2014 single partition, no JOIN, &lt;1ms.</li>\n    </ul>\n    <p style=\"margin-top:6px;\"><strong>Trade-off:</strong> Storage \u00d7 follower count. A celebrity with 10M followers: 10M timeline writes per tweet. Twitter handles this with a hybrid \u2014 fan-out on write for normal users, fan-in on read for celebrities (fetch celebrity tweets at read time and merge with timeline).</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">What are DynamoDB GSIs and why are they expensive?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>DynamoDB only lets you query by Partition Key by default. A <strong>Global Secondary Index (GSI)</strong> lets you query by a different attribute \u2014 but DynamoDB physically replicates the data to a separate internal table for each GSI.</p>\n    <ul>\n      <li><strong>Cost:</strong> Every write to the base table also writes to each GSI. 1 write = 1 + N WCUs (where N = number of GSIs). Each GSI also has its own separate read/write capacity billing.</li>\n      <li><strong>Consistency:</strong> GSI replication is asynchronous \u2014 write a record, immediately query the GSI \u2192 might not see it yet (eventually consistent). This surprises many developers.</li>\n      <li><strong>Limit:</strong> Max 20 GSIs per table.</li>\n      <li><strong>Interview signal:</strong> If you find yourself adding 5+ GSIs to support different access patterns, that signals the access patterns are too varied for DynamoDB. Consider MongoDB or PostgreSQL instead.</li>\n    </ul>\n    <p style=\"margin-top:6px;\"><strong>Local Secondary Index (LSI):</strong> Same partition key, different sort key. Defined at table creation only \u2014 cannot add later. Stored on same partition (no extra replication cost). Limited to 10GB per partition key value. Consistent reads allowed.</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is MVCC in PostgreSQL and why does it limit write throughput?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>MVCC = Multi-Version Concurrency Control. PostgreSQL's mechanism for readers and writers to coexist without blocking each other.</p>\n    <p style=\"margin-top:6px;\"><strong>How it works:</strong></p>\n    <ul>\n      <li>When you UPDATE a row, PostgreSQL does NOT overwrite it. It marks the old row as dead and writes a new version.</li>\n      <li>A reader that started before your update sees the old version. A reader after sees the new version. They never block each other.</li>\n      <li>This is why PostgreSQL reads don't block even during heavy writes.</li>\n    </ul>\n    <p style=\"margin-top:6px;\"><strong>The cost \u2014 table bloat and VACUUM:</strong> Dead rows accumulate over time. PostgreSQL's VACUUM garbage-collector must periodically scan tables and reclaim dead rows. On write-heavy tables, autovacuum may not keep up \u2014 the physical table file grows far larger than its live data (table bloat), and VACUUM itself causes I/O spikes.</p>\n    <p style=\"margin-top:6px;\"><strong>Why Cassandra is faster for writes:</strong> Cassandra uses an LSM-tree (Log-Structured Merge-tree) \u2014 all writes are appends to an in-memory buffer (MemTable) + sequential disk log (CommitLog). No random writes, no row-level locking, no VACUUM. Compaction happens in background without blocking writes.</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">System has both transactional (orders) and analytical (reports) workloads \u2014 how do you handle this?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>This is the HTAP (Hybrid Transactional/Analytical Processing) problem. The standard FAANG answer: <strong>separate the workloads entirely.</strong></p>\n    <ul>\n      <li><strong>OLTP:</strong> PostgreSQL, DynamoDB, or Cassandra handles the live product \u2014 low-latency, high-throughput transactional writes.</li>\n      <li><strong>OLAP:</strong> ClickHouse, BigQuery, or Redshift handles analytics \u2014 batch reads, GROUP BY across billions of rows, dashboards.</li>\n      <li><strong>Bridge \u2014 Change Data Capture (CDC):</strong> Debezium reads the PostgreSQL WAL and streams changes to Kafka \u2192 Kafka connector writes to ClickHouse. Analytics data is typically 5\u201330 minutes stale. Fine for BI dashboards.</li>\n    </ul>\n    <p style=\"margin-top:6px;\"><strong>Why you cannot run analytics on the OLTP database:</strong> A <code>GROUP BY COUNT(*)</code> full-table-scan across 100M rows while the live product serves thousands of writes/sec will spike p99 latency for real users. Always separate.</p>\n    <p style=\"margin-top:6px;\"><strong>Modern alternatives:</strong> Snowflake and Databricks claim to do HTAP \u2014 but at 100K+ writes/sec + complex analytics simultaneously, the separation is still the gold standard at FAANG scale.</p>\n  </div></div>\n\n</section>\n\n<div class=\"oneliner\">\n  <div class=\"lbl\">The one rule to remember</div>\n  <blockquote>\"PostgreSQL for ACID and complex queries. MongoDB for flexible schema and nested documents. DynamoDB for known-key access at any scale with zero ops. Cassandra for extreme write throughput with pre-planned access patterns. The access pattern determines the database \u2014 not the other way around.\"</blockquote>\n</div>\n</div>\n<footer>DATABASES \u00b7 POSTGRESQL \u00b7 MONGODB \u00b7 DYNAMODB \u00b7 CASSANDRA \u00b7 MANISH-ALMANAC</footer>\n\u003cscript>function toggle(el){var item=el.parentElement;var isOpen=item.classList.contains('open');document.querySelectorAll('.faq.open').forEach(function(f){f.classList.remove('open');});if(!isOpen)item.classList.add('open');}<\/script>\n</body></html>\n<section id=\"concepts-db\">\n  <div class=\"sec-tag\">08 \u00b7 Concepts Deep Dive</div>\n  <h2>The database internals every interviewer probes</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">B-Tree Index</div><div class=\"concept-def\"><strong>The default index structure in PostgreSQL and MySQL. Balanced tree, O(log N) read/write.</strong><br>\n      Nodes store sorted keys + pointers to child nodes or rows. Range queries efficient: scan leaf nodes sequentially. Updates maintain balance via splits and merges.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Excellent for: equality lookups, range scans, ORDER BY, multi-column indexes. The right default for 90% of indexing needs.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Write amplification on updates \u2014 every write may trigger re-balancing. LSM trees (Cassandra, RocksDB) are better for write-heavy workloads.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">LSM Tree<br>(Log-Structured Merge)</div><div class=\"concept-def\"><strong>Write-optimised tree: writes always go to an in-memory buffer (memtable), then sequential disk writes (SSTables). Used by Cassandra, RocksDB, LevelDB.</strong><br>\n      Write: append to WAL + write to memtable (in-memory sorted tree). Memtable flushes to SSTable on disk when full. Background compaction merges SSTables.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Sequential writes only \u2192 10\u2013100x faster writes than B-Tree on spinning disks. Even on SSDs: fewer random writes = better endurance. Used for: Cassandra, ClickHouse MergeTree, RocksDB (used by MyRocks, TiKV).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Read amplification: must check multiple SSTables for a key (fixed with Bloom filters). Space amplification during compaction.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">MVCC<br>(Multi-Version Concurrency)</div><div class=\"concept-def\"><strong>PostgreSQL and MySQL InnoDB use MVCC to allow readers and writers to not block each other.</strong><br>\n      Every write creates a new version of the row with a transaction timestamp. Readers see the consistent snapshot from when their transaction started \u2014 never see uncommitted data, never blocked by writers.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No reader-writer locking. Long-running queries do not block inserts/updates. The foundation of Postgres's excellent read performance under concurrent writes.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Dead tuples accumulate \u2014 old row versions must be cleaned up by VACUUM. High write volume without VACUUM \u2192 table bloat \u2192 performance degradation.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Connection Pooling</div><div class=\"concept-def\"><strong>PostgreSQL spawns one OS process per connection. 1,000 connections = 1,000 processes = severe memory and context-switching overhead.</strong><br>\n      PgBouncer in transaction-mode pooling: application connects to PgBouncer (thousands of connections OK). PgBouncer maintains a pool of 50\u2013100 real PostgreSQL connections. Real connection only held during an active transaction.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 1,000 app connections \u2192 50 real DB connections. Reduces memory from ~50MB/connection to near-zero overhead for idle connections. Standard for any PostgreSQL production deployment.</span></div></div>\n  </div>\n\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Database Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need ACID transactions across multiple entities?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>PostgreSQL</strong> (single region) or <strong>CockroachDB / Spanner</strong> (global). Never sacrifice ACID for write-heavy workloads unless you have proven you cannot scale PostgreSQL \u2014 which handles 50K writes/sec with proper indexing and connection pooling.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Go to Step 2. NoSQL may be appropriate.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your primary access pattern?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Key-value / document lookups \u2192</span><span class=\"opt-text\"><strong>DynamoDB</strong> (fully managed, infinite scale) or <strong>MongoDB</strong> (flexible schema, rich queries). DynamoDB: design your access patterns first, denormalise aggressively. MongoDB: better for ad-hoc queries and evolving schemas.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Wide column / time series \u2192</span><span class=\"opt-text\"><strong>Cassandra</strong> (self-managed) or <strong>ScyllaDB</strong> (Cassandra-compatible, 10x faster). Design partition key for even distribution. Never allow unbounded partition growth.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Graph traversal \u2192</span><span class=\"opt-text\"><strong>Neo4j</strong> or <strong>Amazon Neptune.</strong> For: social graph (friends-of-friends), fraud detection (transaction networks), knowledge graphs. SQL with recursive CTEs handles simple graphs; dedicated graph DB needed for deep traversals.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Instagram \u2014 Multi-Database Architecture</div><span class=\"sd-example-tag\">POLYGLOT PERSISTENCE</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">USER DATA</div><div class=\"choice-val\"><span class=\"badge b-g\">PostgreSQL \u2713</span> User profiles, follow relationships, account settings. Strong ACID \u2014 a follow must atomically update both users' counts. Sharded by user_id across 1,000+ PostgreSQL shards. PgBouncer for connection pooling on each shard.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FEED / POSTS</div><div class=\"choice-val\"><span class=\"badge b-g\">Cassandra \u2713</span> Post metadata and pre-computed feeds. Wide-column: partition key = user_id, clustering key = post_timestamp. Feed reads are single-partition: give me last 20 posts for user X. Handles Instagram's scale (100M+ posts/day) with consistent write throughput.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">MEDIA</div><div class=\"choice-val\"><span class=\"badge b-g\">S3 + CDN \u2713</span> Photos and videos stored in S3. Never in a database. Pre-signed URLs for upload. CloudFront CDN for delivery. The DB stores only the S3 key (path), never the bytes.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SEARCH</div><div class=\"choice-val\"><span class=\"badge b-g\">Elasticsearch \u2713</span> Username and hashtag search. CDC from PostgreSQL \u2192 Kafka \u2192 ES indexing. Full-text BM25 for search, geo queries for location-based discovery. PostgreSQL is never touched for search.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">CACHE</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis \u2713</span> Hot user profiles, feed fragments, session tokens. Cache-aside with TTL. Offloads ~90% of PostgreSQL read traffic for hot users. Celebrity profiles cached with longer TTL + local cache in each app server.</div></div>\n    </div>\n  </div>\n  <div class=\"concept-grid\" style=\"margin-top:16px;\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Write-Ahead Log<br>(WAL)</div><div class=\"concept-def\"><strong>Every write in PostgreSQL is first written to the WAL before the actual data pages are modified.</strong><br>\n      On crash: replay the WAL from the last checkpoint to recover all committed transactions. This is why PostgreSQL can guarantee durability (D in ACID) without fsyncing every data page on every write.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 WAL is also used for replication: streaming replication sends WAL records to replicas in real time. And for CDC: Debezium reads the WAL to capture every insert/update/delete for streaming to Kafka.</span></div></div>\n  <div class=\"sd-example\" style=\"margin-top:16px;\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Uber \u2014 Database-per-Service Architecture</div><span class=\"sd-example-tag\">MICROSERVICES \u00b7 POLYGLOT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TRIPS</div><div class=\"choice-val\"><span class=\"badge b-g\">MySQL/PostgreSQL \u2713</span> Trip records with ACID transactions: fare calculation, driver payment, passenger charge must all succeed atomically. Sharded by city_id for geographic locality. 2PC via Saga for cross-shard trip completion flows.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DRIVER LOCATION</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis GEO \u2713</span> Driver GPS positions updated every 4 seconds. GEOADD for writes, GEORADIUS for \"find drivers within 2km.\" In-memory \u2192 &lt;1ms. Persistence: not critical \u2014 positions go stale in 4 seconds anyway. Redis Sentinel for HA.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PRICING</div><div class=\"choice-val\"><span class=\"badge b-g\">Cassandra \u2713</span> Surge pricing history per zone per minute (time-series). Partition key = (city, zone), clustering key = minute_timestamp. Wide-column gives fast range reads: \"give me all surge records for zone BLR-3 in the last 24 hours\" \u2014 single partition scan.</div></div>\n    </div>\n  </div>\n    <div class=\"concept-row\"><div class=\"concept-term\">DynamoDB Single-Table<br>Design</div><div class=\"concept-def\"><strong>DynamoDB is designed for one table per application \u2014 not one table per entity like SQL.</strong><br>\n      All entities (users, orders, products, sessions) coexist in one table with different partition keys. Overloaded attributes: the same attribute name means different things per entity type.<br>\n      Access patterns must be designed upfront: each GSI (Global Secondary Index) is a pre-planned access pattern. Adding a new access pattern after launch may require a new GSI or table migration.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">This is the hardest part of DynamoDB. The \"working backwards from access patterns\" discipline is what separates DynamoDB experts from novices.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">MongoDB Change<br>Streams</div><div class=\"concept-def\"><strong>MongoDB change streams allow applications to subscribe to all data changes in real time \u2014 similar to PostgreSQL WAL-based CDC.</strong><br>\n      Use for: real-time notifications (user's order status changed \u2192 push notification), cache invalidation (MongoDB write \u2192 invalidate Redis cache), event sourcing (stream all changes to Kafka for downstream consumers).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Change streams require a replica set (at least 3-node), not standalone MongoDB. Each change event includes the full document before and after the change.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Cassandra Tombstones</div><div class=\"concept-def\"><strong>Cassandra \"deletes\" are actually tombstone markers \u2014 the data is not removed immediately.</strong><br>\n      Delete a row: Cassandra writes a tombstone (a deletion marker with a timestamp). Compaction eventually removes both the tombstone and the original data when tombstone gc_grace_seconds (default 10 days) expires.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Tombstone accumulation: high-delete workloads (e.g., TTL expiry, message queues) can create millions of tombstones that Cassandra must scan on every read. Monitor tombstone warnings in query logs. Anti-pattern: using Cassandra as a queue where messages are constantly deleted.</span></div></div>\n  </div>\n</section>\n\n<section id=\"faq-db\">\n  <div class=\"sec-tag\">09 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">When should you denormalise a relational database?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Denormalise when join cost at read time exceeds storage and write complexity cost.</strong><br><br>\n  Signs it is time to denormalise: (1) the same JOIN appears in every query and drives latency. (2) The joined tables are rarely updated (so maintaining the denormalised copy is cheap). (3) You have measured the query and confirmed the JOIN is the bottleneck \u2014 not something else.<br><br>\n  How to denormalise safely: add a pre-computed column (e.g., store user_country directly on the orders table instead of joining to users every time). Update it on write via a trigger or application logic. Accept the storage cost and write overhead in exchange for read speed.<br><br>\n  The rule: normalise first for correctness and simplicity. Denormalise only where profiling shows a specific join is a bottleneck. Never denormalise speculatively.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you choose between DynamoDB and PostgreSQL for a new system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>The question is not \"which is better\" \u2014 it is \"which access pattern dominates.\"</strong><br><br>\n  <strong>Choose PostgreSQL when:</strong> your queries are ad-hoc and hard to predict upfront, you need complex JOINs across multiple entities, you need ACID transactions, your team knows SQL well, or your scale is below ~50K writes/sec (which is the vast majority of systems).<br><br>\n  <strong>Choose DynamoDB when:</strong> your access patterns are known and fixed (you can design the table schema around them), you need infinite scale with zero ops (DynamoDB auto-scales), your primary access is by a known primary key (user_id, order_id), and you're building on AWS and want fully managed infrastructure.<br><br>\n  <strong>The common mistake:</strong> choosing DynamoDB because it \"scales better\" without verifying you actually need that scale. DynamoDB's single-table design discipline is a significant upfront investment. Most systems genuinely do not need it.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle a slow query that cannot be easily indexed?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>A systematic approach: profile first, then fix the actual bottleneck.</strong><br><br>\n  Step 1 \u2014 <code>EXPLAIN ANALYZE</code>: run it and look for: Seq Scan on large tables (missing index), Hash Join with large estimated rows (wrong statistics), high actual vs estimated rows (stale statistics \u2014 run ANALYZE).<br><br>\n  Step 2 \u2014 Fix in order of impact:<br>\n  (a) Add a missing index. B-tree for equality/range, partial index for filtered queries (WHERE status='active'), covering index (INCLUDE) to avoid table heap access.<br>\n  (b) Rewrite the query: avoid SELECT *, avoid functions on indexed columns (WHERE date_trunc('day', created_at) = ... defeats the index \u2014 use range instead).<br>\n  (c) Materialised view: pre-compute complex aggregations. Refresh on schedule or on trigger. Trades staleness for speed.<br>\n  (d) Denormalise: if the join is always the same, pre-compute it.<br>\n  (e) Move to a different store: if it is fundamentally an analytics query (full table scan, aggregation), PostgreSQL is the wrong tool \u2014 use ClickHouse or Redshift.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does Cassandra handle a node failure \u2014 what actually happens to reads and writes?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Cassandra is designed to keep working through node failures \u2014 but the behaviour depends on your consistency level.</strong><br><br>\n  <strong>Write path on node failure (QUORUM consistency, RF=3):</strong> The coordinator tries to write to all 3 replica nodes. If 2 succeed (quorum) and 1 is down, the write succeeds. The failed node misses the write. When it recovers: Cassandra's hinted handoff replays missed writes (stored as \"hints\" on other nodes for up to 3 hours). For longer outages: the recovering node runs repair to sync from peers.<br><br>\n  <strong>Read path on node failure (QUORUM consistency):</strong> Coordinator requests from 2 of 3 replicas. If the healthy 2 respond, read succeeds. Read repair: if those 2 have inconsistent data, Cassandra repairs the stale one asynchronously. If only 1 replica is available (2 nodes down): QUORUM fails \u2014 you need to drop to ONE consistency level to keep reading (at the cost of possible stale data).<br><br>\n  <strong>The key point:</strong> with RF=3 and QUORUM, you can lose 1 node (out of 3) without any service impact. With RF=3 and ONE consistency, you can lose 2 nodes. Design your RF and consistency level based on your availability and consistency requirements.</div></div>\n</section>", tag: 'Databases' },
  olap:        { title: 'OLAP Engines Compared',         srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>OLAP Engines Compared \u2014 FAANG Interview Guide</title>\n<link href=\"https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#12100e;--page:#f8f6f1;--surface:#eeebe4;--border:#ddd9d0;--muted:#78746a;--ch:#cc0000;--ch-bg:#fff0f0;--dr:#2d8fd4;--dr-bg:#eef6ff;--bq:#3a6fd8;--bq-bg:#eef2ff;--rs:#e07800;--rs-bg:#fff5e8;--red:#b83030;--red-bg:#fdf0f0;--green:#1a6e40;--green-bg:#edf7f0;--amber:#a86c00;--amber-bg:#fdf5e3;--blue:#1a4a90;--blue-bg:#eef2fb;--mono:'JetBrains Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'DM Serif Display',serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#f0ece4;padding:52px 24px 44px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 30px,rgba(255,255,255,.015) 31px);}\n.hero-inner{max-width:920px;margin:0 auto;position:relative;z-index:1;}\n.eyebrow{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#5a5848;text-transform:uppercase;margin-bottom:18px;}\nh1{font-family:var(--serif);font-size:clamp(28px,5vw,54px);line-height:1.05;margin-bottom:16px;color:#f0ece4;}\nh1 .acc{color:#e8b84b;}\n.hero-desc{font-size:15px;color:#7a7868;max-width:600px;line-height:1.7;margin-bottom:24px;}\n.eng-badges{display:flex;flex-wrap:wrap;gap:8px;}\n.eng-badge{font-family:var(--mono);font-size:10px;padding:4px 12px;border-radius:3px;font-weight:600;}\n.e-ch{background:var(--ch);color:#fff;}.e-dr{background:var(--dr);color:#fff;}.e-bq{background:var(--bq);color:#fff;}.e-rs{background:var(--rs);color:#fff;}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#5a5850;text-decoration:none;padding:13px 13px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:920px;margin:0 auto;padding:0 20px;}\nsection{padding:48px 0 32px;border-bottom:2px solid var(--border);}section:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(20px,3.5vw,32px);line-height:1.15;margin-bottom:14px;color:var(--ink);}\nh3{font-family:var(--serif);font-size:18px;margin:28px 0 10px;color:var(--ink);border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;max-width:760px;}strong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:12px;background:var(--surface);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.callout{border-radius:4px;padding:14px 18px;margin:16px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;max-width:none;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2808;}.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0808;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.steps{list-style:none;margin:16px 0;counter-reset:s;}\n.steps li{counter-increment:s;display:flex;gap:14px;align-items:flex-start;padding:14px 16px;background:white;border:1px solid var(--border);border-radius:6px;margin-bottom:8px;}\n.steps li::before{content:counter(s);font-family:var(--mono);font-size:11px;font-weight:700;color:white;background:var(--ink);min-width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;}\n.step-title{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:4px;}\n.step-desc{font-size:13px;color:#5a5848;line-height:1.65;}\n.step-desc ul{margin:6px 0 0 16px;}.step-desc li{margin-bottom:4px;font-size:13px;}\n.blist{list-style:none;margin:12px 0;}\n.blist li{padding:7px 0 7px 20px;position:relative;font-size:14px;color:#3a3830;border-bottom:1px solid var(--border);line-height:1.65;}\n.blist li:last-child{border:none;}.blist li::before{content:'\u2192';position:absolute;left:0;color:var(--amber);font-weight:700;}\n.codeblock{background:var(--ink);border-radius:6px;padding:18px 22px;font-family:var(--mono);font-size:12px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}\n.eng-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0;}\n@media(max-width:640px){.eng-grid{grid-template-columns:1fr;}}\n.eng-card{background:white;border:1px solid var(--border);border-radius:6px;padding:18px;position:relative;overflow:hidden;}\n.eng-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.eng-card.ch::before{background:var(--ch);}.eng-card.dr::before{background:var(--dr);}.eng-card.bq::before{background:var(--bq);}.eng-card.rs::before{background:var(--rs);}\n.eng-name{font-family:var(--serif);font-size:18px;margin:10px 0 4px;}\n.eng-card.ch .eng-name{color:var(--ch);}.eng-card.dr .eng-name{color:var(--dr);}.eng-card.bq .eng-name{color:var(--bq);}.eng-card.rs .eng-name{color:var(--rs);}\n.eng-role{font-size:12px;color:var(--muted);margin-bottom:12px;font-family:var(--mono);}\n.eng-row{display:flex;justify-content:space-between;align-items:flex-start;font-size:12.5px;padding:6px 0;border-top:1px solid var(--surface);}\n.eng-k{color:var(--muted);flex-shrink:0;width:100px;}.eng-v{font-family:var(--mono);font-size:11.5px;color:var(--ink);text-align:right;flex:1;}\n.eng-v.g{color:var(--green);}.eng-v.a{color:var(--amber);}.eng-v.r{color:var(--red);}\n.matrix{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.matrix th{font-family:var(--mono);font-size:9px;letter-spacing:2px;padding:10px 12px;border:1px solid var(--border);background:var(--surface);color:var(--muted);text-transform:uppercase;}\n.matrix td{padding:11px 12px;border:1px solid var(--border);color:#3a3830;vertical-align:top;line-height:1.6;}\n.matrix .rh{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.badge{display:inline-block;font-family:var(--mono);font-size:10px;padding:2px 8px;border-radius:3px;border:1px solid;font-weight:500;vertical-align:middle;margin:2px;}\n.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}.b-b{background:var(--blue-bg);border-color:var(--blue);color:var(--blue);}\n.faq{border:1px solid var(--border);border-radius:5px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:600;user-select:none;transition:background .15s;}\n.faq-q:hover{background:var(--surface);}\n.faq-tog{font-size:18px;color:var(--amber);transition:transform .2s;flex-shrink:0;margin-left:12px;}\n.faq-a{display:none;padding:16px 18px;background:var(--surface);border-top:1px solid var(--border);font-size:13.5px;color:#3a3830;line-height:1.75;}\n.faq.open .faq-a{display:block;}.faq.open .faq-tog{transform:rotate(45deg);}\n.faq-a ul,.faq-a ol{padding-left:20px;margin:8px 0;}.faq-a li{margin-bottom:6px;font-size:13.5px;line-height:1.65;}\n.dtree{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;margin:20px 0;}\n.dtree-node{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);}\n.dtree-node:last-child{border:none;}\n.dtree-q{font-weight:600;font-size:13.5px;color:var(--ink);flex:1;}\n.dtree-a{font-family:var(--mono);font-size:11px;padding:3px 10px;border-radius:3px;flex-shrink:0;margin-left:8px;border:1px solid;}\n.dtree-a.ch{background:var(--ch-bg);color:var(--ch);border-color:var(--ch);}.dtree-a.dr{background:var(--dr-bg);color:var(--dr);border-color:var(--dr);}.dtree-a.bq{background:var(--bq-bg);color:var(--bq);border-color:var(--bq);}.dtree-a.rs{background:var(--rs-bg);color:var(--rs);border-color:var(--rs);}\n.oneliner{background:var(--ink);color:var(--page);border-radius:10px;padding:32px 28px;text-align:center;margin:44px 0;}\n.oneliner .lbl{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:#5a5850;margin-bottom:14px;}\n.oneliner blockquote{font-family:var(--serif);font-size:clamp(14px,2.2vw,18px);line-height:1.65;color:#e8e0d0;font-style:italic;}\nfooter{background:var(--ink);text-align:center;padding:32px 20px;font-family:var(--mono);font-size:10px;color:#3a3828;letter-spacing:2px;}\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"eyebrow\">FAANG Interview Prep \u00b7 Analytics Databases</div>\n    <h1>OLAP Engines<br><span class=\"acc\">Decoded</span></h1>\n    <p class=\"hero-desc\">ClickHouse \u00b7 Apache Druid \u00b7 BigQuery \u00b7 Redshift \u2014 every dimension that matters, explained so clearly a layman would get it, with every FAANG follow-up answered.</p>\n    <div class=\"eng-badges\">\n      <span class=\"eng-badge e-ch\">ClickHouse \u2014 Columnar Write-Heavy</span>\n      <span class=\"eng-badge e-dr\">Apache Druid \u2014 Pre-Aggregation</span>\n      <span class=\"eng-badge e-bq\">BigQuery \u2014 Serverless Analytics</span>\n      <span class=\"eng-badge e-rs\">Redshift \u2014 Cloud Data Warehouse</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#what-is-olap\">What Is OLAP</a><a href=\"#columnar\">Columnar Storage</a>\n  <a href=\"#engines\">The Engines</a><a href=\"#internals\">How They Work</a>\n  <a href=\"#dimensions\">Every Dimension</a><a href=\"#when-to-use\">When to Use</a>\n  <a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"what-is-olap\">\n  <div class=\"sec-tag\">01 \u00b7 What Is OLAP and Why Does It Exist</div>\n  <h2>OLAP vs OLTP \u2014 the fundamental split</h2>\n  <p>Most databases are built for <strong>OLTP</strong> (Online Transaction Processing) \u2014 fast individual row reads and writes that power the live product. A user signs up, an order is placed, a message is sent \u2014 these are OLTP queries. They affect a few rows at a time and need to be fast (sub-millisecond).</p>\n  <p><strong>OLAP</strong> (Online Analytical Processing) is the opposite. Queries read millions or billions of rows, scan entire columns, compute aggregations: \"total revenue per country last quarter,\" \"top 1000 videos in the last hour,\" \"average session duration by device type over 30 days.\" These queries are slow on OLTP databases but fast on OLAP engines \u2014 because they're built completely differently.</p>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">\ud83c\udfea The Supermarket Analogy</div>\n    <p><strong>OLTP</strong> = The checkout register. Processes one transaction at a time, extremely fast. Does not care about sales trends across all 10,000 products.</p>\n    <p style=\"margin-top:6px;\"><strong>OLAP</strong> = The weekly inventory report. Reads all 10,000 products across all 50 stores, computes which products sold most, what was the average price per category. No individual transaction is urgent. You need the full picture fast.</p>\n    <p style=\"margin-top:6px;\">You would never use the checkout register to produce the inventory report. You need a separate system designed for scanning everything at once.</p>\n  </div>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">\ud83d\udcac Say This in Your Interview</div>\n    <p><em>\"Our OLTP database (Postgres/DynamoDB/Cassandra) handles the live product. But analytical queries \u2014 GROUP BY, window functions, aggregations across billions of events \u2014 would kill OLTP p99 latency if run directly. We push data to an OLAP engine via CDC or a stream, and run analytics there. The two systems have completely different read/write contracts.\"</em></p>\n  </div>\n</section>\n\n<section id=\"columnar\">\n  <div class=\"sec-tag\">02 \u00b7 Columnar Storage \u2014 The Core Insight</div>\n  <h2>Why columnar storage makes analytics 100\u00d7 faster</h2>\n  <p>Every OLAP engine is columnar. Understanding this is the key to understanding everything else about them.</p>\n  <h3>Row storage (OLTP) vs columnar storage (OLAP)</h3>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">\ud83d\udce6 The Filing Cabinet vs Spreadsheet Analogy</div>\n    <p><strong>Row storage:</strong> All data for one customer is stored together \u2014 name, email, age, city, purchase_count, revenue. Like a filing cabinet where each folder contains everything about one person. Fast to get all info for one person. Slow to answer \"what is the average age of all customers\" \u2014 you must open every folder and extract just the age field.</p>\n    <p style=\"margin-top:6px;\"><strong>Columnar storage:</strong> All ages for all customers are stored together, all cities together, all revenues together. Like a spreadsheet where each column is stored as one contiguous block on disk. To compute average age, you read only the age column \u2014 10\u00d7 less data to scan. To compute revenue by city, you read only revenue and city \u2014 everything else is untouched.</p>\n  </div>\n  <h3>Step-by-step: how columnar query execution works</h3>\n  <ol class=\"steps\">\n    <li><div><div class=\"step-title\">Parse the query and identify columns needed</div><div class=\"step-desc\">For <code>SELECT city, SUM(revenue) FROM orders WHERE date &gt; '2026-01-01' GROUP BY city</code>:\n      <ul><li>Columns needed: only <code>city</code>, <code>revenue</code>, <code>date</code> \u2014 3 of potentially 50 columns</li><li>All other columns (customer_name, email, phone, address\u2026) are not touched at all</li><li>I/O savings: if table has 50 columns and you need 3, you read 6% of the data</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Read column files from disk with compression</div><div class=\"step-desc\">Each column is stored as a separate compressed file on disk.\n      <ul><li>Because all values in a column have the same type, compression is extremely effective</li><li>A column of integers like revenue compresses 10\u201320\u00d7 (run-length encoding, delta encoding)</li><li>A column of low-cardinality strings like city compresses 30\u201350\u00d7 (dictionary encoding: map \"Bangalore\"\u21921, \"London\"\u21922, store integers)</li><li>ClickHouse achieves 5\u201320\u00d7 compression vs PostgreSQL on the same data</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Apply vectorised execution (SIMD)</div><div class=\"step-desc\">Modern CPUs have SIMD instructions (Single Instruction Multiple Data) that process multiple values in a single clock cycle.\n      <ul><li>Row stores process one row at a time: read name, read email, read age, move to next row</li><li>Column stores process 16 or 32 integers simultaneously: compute 32 revenue additions in one CPU instruction</li><li>ClickHouse processes 8\u201332 values per CPU instruction via AVX2/AVX-512 \u2014 this is the real reason ClickHouse query throughput is extraordinary</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Aggregate and return results</div><div class=\"step-desc\">GROUP BY, SUM, COUNT, window functions operate on dense arrays of same-typed data \u2014 no pointer chasing, no row parsing.\n      <ul><li>ClickHouse: GROUP BY on 100M rows in 200\u2013500ms</li><li>PostgreSQL row store: same query in 30\u2013120 seconds (sequential scan + per-row processing)</li><li>The columnar advantage is not just I/O \u2014 it's CPU cache efficiency: dense arrays fit in CPU L1/L2 cache, enabling near-memory-speed processing</li></ul></div></div></li>\n  </ol>\n</section>\n\n<section id=\"engines\">\n  <div class=\"sec-tag\">03 \u00b7 The Four Engines</div>\n  <h2>Core identity of each</h2>\n  <div class=\"eng-grid\">\n    <div class=\"eng-card ch\">\n      <div class=\"eng-name\">ClickHouse</div><div class=\"eng-role\">Columnar \u00b7 Write-heavy OLAP \u00b7 Self-hosted</div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Best for</span><span class=\"eng-v\">Real-time analytics at high ingest rate</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ingest speed</span><span class=\"eng-v g\">500K\u20131M rows/sec per node</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Query latency</span><span class=\"eng-v g\">&lt;1s on 100B rows</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Compression</span><span class=\"eng-v g\">10\u201320\u00d7 columnar</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ops</span><span class=\"eng-v a\">Self-hosted, moderate ops</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">FAANG use</span><span class=\"eng-v\">Yandex (built it), Cloudflare, Uber, ByteDance</span></div>\n    </div>\n    <div class=\"eng-card dr\">\n      <div class=\"eng-name\">Apache Druid</div><div class=\"eng-role\">Pre-aggregation \u00b7 Sub-second \u00b7 Self-hosted</div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Best for</span><span class=\"eng-v\">Sub-second interactive dashboard queries</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ingest speed</span><span class=\"eng-v g\">Real-time streaming + batch</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Query latency</span><span class=\"eng-v g\">&lt;500ms interactive</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Compression</span><span class=\"eng-v g\">Bitmap indexes + rollup</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ops</span><span class=\"eng-v r\">Complex \u2014 multiple node types</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">FAANG use</span><span class=\"eng-v\">Pinterest, Twitter, Airbnb, Netflix</span></div>\n    </div>\n    <div class=\"eng-card bq\">\n      <div class=\"eng-name\">BigQuery</div><div class=\"eng-role\">Serverless \u00b7 Managed \u00b7 Google Cloud</div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Best for</span><span class=\"eng-v\">Ad-hoc queries, ML, no-ops analytics</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ingest speed</span><span class=\"eng-v a\">Batch + streaming (higher cost)</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Query latency</span><span class=\"eng-v a\">2\u201330s (slots-dependent)</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Cost model</span><span class=\"eng-v r\">Per TB scanned \u2014 can spike</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ops</span><span class=\"eng-v g\">Zero \u2014 fully serverless</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">FAANG use</span><span class=\"eng-v\">Google (built it), Spotify, Twitter analytics</span></div>\n    </div>\n    <div class=\"eng-card rs\">\n      <div class=\"eng-name\">Redshift</div><div class=\"eng-role\">Columnar \u00b7 Managed \u00b7 AWS ecosystem</div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Best for</span><span class=\"eng-v\">AWS-native BI, data warehouse, SQL analytics</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ingest speed</span><span class=\"eng-v a\">COPY command batch; Kinesis streaming</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Query latency</span><span class=\"eng-v a\">2\u201315s typical</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Cost model</span><span class=\"eng-v a\">Node-based or Serverless</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">Ops</span><span class=\"eng-v g\">Managed by AWS</span></div>\n      <div class=\"eng-row\"><span class=\"eng-k\">FAANG use</span><span class=\"eng-v\">Amazon internal, Nasdaq, GE Analytics</span></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"internals\">\n  <div class=\"sec-tag\">04 \u00b7 How They Actually Work Inside</div>\n  <h2>Internals that interviewers probe</h2>\n\n  <h3>ClickHouse \u2014 MergeTree Engine</h3>\n  <p>ClickHouse's core storage engine. Understanding MergeTree is what separates a good answer from a great one.</p>\n  <ol class=\"steps\">\n    <li><div><div class=\"step-title\">Writes go to a MemTable (in-memory buffer)</div><div class=\"step-desc\">Incoming rows accumulate in memory. ClickHouse periodically flushes them to disk as a <em>data part</em> \u2014 a sorted, compressed block of rows.\n      <ul><li>Each data part is immutable once written \u2014 no in-place updates</li><li>This is why ClickHouse can ingest 500K rows/sec: writes are sequential appends, never random</li><li>Updates in ClickHouse are actually: mark old rows as deleted + insert new rows. Mutations run asynchronously.</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Background compaction \u2014 MergeTree's magic</div><div class=\"step-desc\">Over time, many small data parts accumulate. Background merge process combines small parts into larger ones, sorting and re-compressing.\n      <ul><li>Queries during merge: read from both old parts and new merged part \u2014 transparent to the query</li><li>Merge reduces number of files to scan on query, improving query speed over time</li><li>This is the same LSM-tree concept as Cassandra but optimised for reads (column-oriented) rather than just writes</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Primary index (sparse) enables fast range scans</div><div class=\"step-desc\">ClickHouse stores a <em>sparse index</em> \u2014 one index entry per 8192 rows (configurable). Tiny index, fits in RAM.\n      <ul><li>For <code>WHERE event_date = '2026-03-20'</code>: index skips to the right range in milliseconds</li><li>Not row-level index \u2014 ClickHouse skips 8192 rows at a time. Within the range, it scans linearly.</li><li>Order by matters: if you ORDER BY (tenant_id, event_date), queries filtering by tenant_id are fast. Queries filtering only by event_date must scan everything.</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">AggregatingMergeTree \u2014 for pre-aggregated counts</div><div class=\"step-desc\">Specialised MergeTree variant that merges rows with the same key, combining their aggregate state.\n      <ul><li>Example: two rows (ad_id=123, count=500) and (ad_id=123, count=300) merge to (ad_id=123, count=800)</li><li>ClickHouse does this merging in background without any explicit trigger</li><li>This is how the Top-K system works: Flink writes partial counts to ClickHouse, ClickHouse merges them continuously</li></ul></div></div></li>\n  </ol>\n\n  <h3>Apache Druid \u2014 Pre-aggregation at ingest (Rollup)</h3>\n  <ol class=\"steps\">\n    <li><div><div class=\"step-title\">Ingest-time rollup \u2014 aggregate before storing</div><div class=\"step-desc\">Druid's key differentiator: it aggregates data as it ingests.\n      <ul><li>Raw event: {user_id: \"u1\", video_id: \"v42\", region: \"IN\", timestamp: 14:32:47, count: 1}</li><li>Druid rolls up to 1-minute granularity: {video_id: \"v42\", region: \"IN\", minute: \"14:32\", count: 547}</li><li>Many individual events collapse into one row \u2014 potentially 100\u20131000\u00d7 data reduction</li><li>Trade-off: you lose individual event detail. You cannot answer \"did user u1 watch video v42?\" after rollup.</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Segments \u2014 immutable, pre-sorted, pre-compressed time slices</div><div class=\"step-desc\">Druid divides data into time-based segments (e.g., one segment per hour per datasource).\n      <ul><li>Each segment is immutable \u2014 like ClickHouse parts</li><li>Segments are distributed across Historical nodes, with deep storage (S3) as source of truth</li><li>Query: Broker routes to relevant Historical nodes, merges results</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Bitmap indexes enable sub-second filter performance</div><div class=\"step-desc\">Druid automatically creates bitmap indexes on all dimensions (region, device, etc.).\n      <ul><li>Bitmap index: for each value of \"region\" (IN, US, UK\u2026), store a bitset of which rows match</li><li>Filtering \"region = IN\" = bitwise AND of the IN bitmap with other filters \u2014 extremely fast</li><li>This is why Druid excels at dashboard queries with many filters: each filter is a bitwise operation</li></ul></div></div></li>\n  </ol>\n\n  <h3>BigQuery \u2014 Dremel columnar tree</h3>\n  <ol class=\"steps\">\n    <li><div><div class=\"step-title\">Dremel execution model \u2014 distributed tree of workers</div><div class=\"step-desc\">BigQuery uses Google's Dremel engine. A query fans out to thousands of workers in milliseconds.\n      <ul><li>Root server receives query, distributes to intermediate servers, which distribute to leaf servers</li><li>Leaf servers read Colossus (Google's distributed file system) directly \u2014 no data movement</li><li>Results aggregate back up the tree</li><li>A query that scans 1 TB can use 2,000 workers simultaneously \u2014 each worker reads 0.5 GB</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Slots \u2014 units of compute</div><div class=\"step-desc\">BigQuery measures compute in \"slots\" \u2014 a virtual CPU.\n      <ul><li>On-demand pricing: you don't manage slots \u2014 BigQuery allocates automatically, charges per TB scanned</li><li>Reservations pricing: buy a fixed number of slots (e.g., 500 slots) \u2014 predictable cost, consistent performance</li><li>A complex query might use 2,000 slots for 3 seconds \u2014 that's 6,000 slot-seconds of compute</li></ul></div></div></li>\n    <li><div><div class=\"step-title\">Partitioned and clustered tables for cost control</div><div class=\"step-desc\">Critical for production BigQuery usage:\n      <ul><li><strong>Partition by date:</strong> Query <code>WHERE date = '2026-03-20'</code> reads only that date's partition \u2014 1/365 of the data</li><li><strong>Cluster by column:</strong> Within a partition, data is co-located by cluster column. Filter on cluster column skips most blocks.</li><li>Without partitioning: a query always scans the entire table. At $5/TB, a 1 PB table = $5,000 per query. Always partition.</li></ul></div></div></li>\n  </ol>\n</section>\n\n<section id=\"dimensions\">\n  <div class=\"sec-tag\">05 \u00b7 Every Dimension That Matters</div>\n  <h2>The full comparison matrix</h2>\n  <table class=\"matrix\">\n    <thead><tr><th>Dimension</th><th>ClickHouse</th><th>Apache Druid</th><th>BigQuery</th><th>Redshift</th></tr></thead>\n    <tbody>\n      <tr><td class=\"rh\">Storage model</td><td>Columnar MergeTree. Each column in separate compressed file. Sparse primary index.</td><td>Columnar segments with bitmap indexes. Pre-aggregated rollup at ingest.</td><td>Capacitor columnar format on Colossus (Google's GFS). Dremel execution.</td><td>Columnar, zone maps (min/max per 1MB block). Sorted by SORTKEY for fast range scans.</td></tr>\n      <tr><td class=\"rh\">Ingest speed</td><td><span class=\"dot g\"></span>500K\u20131M rows/sec via Kafka engine or HTTP insert. Native Kafka consumer built in.</td><td><span class=\"dot g\"></span>Real-time streaming via Kafka (Middle Manager). Native streaming + batch.</td><td><span class=\"dot a\"></span>Batch (load jobs) preferred. Streaming inserts: 1 GB/s but 10\u00d7 more expensive.</td><td><span class=\"dot a\"></span>COPY command from S3 is fast (batch). Kinesis Firehose for streaming (ingestion lag).</td></tr>\n      <tr><td class=\"rh\">Query latency</td><td><span class=\"dot g\"></span>&lt;1s on 100B rows for simple aggregations. Vectorised SIMD execution. Sub-100ms for pre-aggregated data.</td><td><span class=\"dot g\"></span>&lt;500ms interactive \u2014 fastest for dashboard queries. Pre-aggregation makes queries fast even at petabyte scale.</td><td><span class=\"dot a\"></span>2\u201330s depending on data scanned, slot availability, and query complexity.</td><td><span class=\"dot a\"></span>2\u201315s for well-tuned queries. Requires SORTKEY and DISTKEY design \u2014 wrong keys = slow.</td></tr>\n      <tr><td class=\"rh\">Cost model</td><td><span class=\"dot g\"></span>Instance-based (EC2/bare metal). Predictable. Very cheap per TB at scale. ClickHouse Cloud also available.</td><td><span class=\"dot a\"></span>Instance-based. Multiple node types (Historical, Broker, Coordinator) \u2014 complex sizing.</td><td><span class=\"dot r\"></span>$5/TB scanned (on-demand). Predictable with reservations ($1,800\u2013$2,400/slot/month). Partitioning is critical for cost control.</td><td><span class=\"dot a\"></span>Node-based (RA3 nodes decouple compute/storage). Serverless option. Generally less expensive than BigQuery for steady workloads.</td></tr>\n      <tr><td class=\"rh\">Ops complexity</td><td><span class=\"dot a\"></span>Self-managed. Single binary \u2014 simple deployment. Replication, sharding need configuration. ClickHouse Cloud option.</td><td><span class=\"dot r\"></span>High. Multiple node types (Coordinator, Overlord, Broker, Historical, MiddleManager) \u2014 complex cluster management.</td><td><span class=\"dot g\"></span>Zero \u2014 fully serverless. No capacity planning, no patching. Just query.</td><td><span class=\"dot g\"></span>Managed by AWS. Less ops than self-hosted, but requires SORTKEY/DISTKEY tuning.</td></tr>\n      <tr><td class=\"rh\">SQL support</td><td>SQL with extensions (ARRAY, Map, AggregateFunction types). Missing: full joins on large tables, UPDATES.</td><td>SQL (Druid SQL) or native JSON-based API. Limited SQL compared to standard \u2014 no joins across datasources.</td><td>Standard SQL (ANSI). Best SQL support of the four. Window functions, ML via BQML, geospatial, JSON.</td><td>PostgreSQL-compatible SQL. Full ANSI SQL. Joins work well if DISTKEY matches join key.</td></tr>\n      <tr><td class=\"rh\">Updates / deletes</td><td>Mutations (async ALTER TABLE UPDATE). Expensive \u2014 avoid frequent updates. Design for append-only.</td><td>Not supported natively. To update: reindex the segment. Druid is designed for immutable time-series.</td><td>DML updates/deletes supported but scan the whole partition \u2014 expensive. Use MERGE for upserts.</td><td>UPDATE/DELETE supported. Tombstone-based \u2014 old rows remain until VACUUM. Similar to Postgres.</td></tr>\n      <tr><td class=\"rh\">Real-time capability</td><td>Near real-time via Kafka engine \u2014 data visible in 1\u20132 seconds. ReplacingMergeTree for deduplication.</td><td>True real-time via streaming ingestion. Data queryable in &lt;1 second. This is Druid's strongest differentiator.</td><td>Streaming inserts visible in seconds but 10\u00d7 more expensive than batch loads. Most teams batch-load hourly.</td><td>Not designed for real-time. Typically batch-loaded every 5\u201360 minutes from S3.</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"when-to-use\">\n  <div class=\"sec-tag\">06 \u00b7 When to Use Each</div>\n  <h2>Real system design examples</h2>\n  <h3>ClickHouse \u2014 high-frequency writes + fast aggregation</h3>\n  <ul class=\"blist\">\n    <li><strong>Top-K trending (our system):</strong> Flink writes 50K aggregated count rows/sec. ClickHouse ingests via Kafka engine natively. Query \"top 10 videos in India last hour\" = 200ms on 100B rows. No other OLAP engine matches this ingest+query combination.</li>\n    <li><strong>Ad click analytics:</strong> 10K clicks/sec, each click is one row event. ClickHouse ingests via Kafka, aggregates by ad_id and time window. Advertisers query \"my ad performance last 24 hours\" \u2014 sub-second response.</li>\n    <li><strong>Observability / APM:</strong> Cloudflare processes 30M DNS queries/sec \u2014 all logged to ClickHouse. Engineers query \"how many 5xx errors from IP range X in last 5 minutes\" \u2014 answers in &lt;1 second.</li>\n    <li><strong>User behaviour analytics:</strong> ByteDance (TikTok) uses ClickHouse for product analytics. Every user action (swipe, play, like, skip) is one row. A/B test analysis, funnel queries, retention cohorts \u2014 all ClickHouse.</li>\n  </ul>\n  <h3>Apache Druid \u2014 sub-second interactive dashboards</h3>\n  <ul class=\"blist\">\n    <li><strong>Business intelligence dashboards:</strong> Operations team needs a dashboard that responds in &lt;500ms to every filter change (date range, region, device type). Druid pre-aggregates at ingest \u2014 filter changes just flip bitmap indexes. No other OLAP engine is this fast for interactive exploration.</li>\n    <li><strong>Real-time anomaly detection:</strong> Data is visible in Druid in &lt;1 second. Dashboard shows \"current minute revenue vs expected\" \u2014 Druid handles both the real-time ingest and the historical baseline query in the same system.</li>\n    <li><strong>Pinterest Ads analytics:</strong> Advertisers need to see their campaign performance update in real time as users interact with pins. Druid's streaming ingestion + rollup makes this possible at Pinterest's scale.</li>\n    <li><strong>When NOT to use Druid:</strong> Complex multi-join queries across large datasets; when you need to retain raw event granularity; when ops complexity is a concern (Druid clusters are hard to manage).</li>\n  </ul>\n  <h3>BigQuery \u2014 ad-hoc exploration, ML, no-ops</h3>\n  <ul class=\"blist\">\n    <li><strong>Data science exploration:</strong> A data scientist needs to run 20 different exploratory queries on last year's data. They don't know the queries in advance. BigQuery: spin up, run queries, pay only for what you scan. No infrastructure to manage, no index to design.</li>\n    <li><strong>ML training data:</strong> BigQuery ML (BQML) lets you train models directly in SQL without moving data. Spotify uses BigQuery to train their recommendation models on listening history \u2014 petabytes of data, no data pipeline needed.</li>\n    <li><strong>Cross-team analytics at Google scale:</strong> Multiple teams query the same data. BigQuery handles concurrency automatically \u2014 2,000 concurrent queries with automatic slot allocation.</li>\n    <li><strong>When NOT to use BigQuery:</strong> When you need &lt;1 second query latency consistently; when you have very high-frequency streaming ingest; when you're not on GCP and don't want cloud vendor lock-in.</li>\n  </ul>\n  <h3>Redshift \u2014 AWS-native data warehouse</h3>\n  <ul class=\"blist\">\n    <li><strong>AWS-native workloads:</strong> You're already heavily on AWS (S3, Kinesis, Glue). Redshift Spectrum can query S3 directly without loading. Glue automatically catalogs your data. The ecosystem integration is seamless.</li>\n    <li><strong>Traditional BI with standard SQL:</strong> Teams familiar with PostgreSQL SQL, using Tableau or Looker. Redshift's PostgreSQL-compatible SQL and JDBC/ODBC connectors work with every BI tool out of the box.</li>\n    <li><strong>When NOT to use Redshift:</strong> High-frequency writes (Redshift is batch-oriented); when you need Druid-style sub-second interactive queries; when you're on GCP (BigQuery is the obvious choice).</li>\n  </ul>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">07 \u00b7 Decision Tree</div>\n  <h2>Pick your OLAP engine in 60 seconds</h2>\n  <div class=\"dtree\">\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Do you need high-frequency streaming ingest (&gt;100K rows/sec) AND fast aggregation queries? (ad clicks, event tracking, Top-K)</div><div class=\"dtree-a ch\">\u2192 ClickHouse</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Do you need sub-second interactive dashboard queries with many filters changing in real time? (ops dashboards, ad analytics)</div><div class=\"dtree-a dr\">\u2192 Apache Druid</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Do you want zero infrastructure ops, ad-hoc exploration, ML integration, and you're on GCP?</div><div class=\"dtree-a bq\">\u2192 BigQuery</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Are you AWS-native with existing S3/Glue/Kinesis setup, and need a managed columnar warehouse?</div><div class=\"dtree-a rs\">\u2192 Redshift</div></div>\n    <div class=\"dtree-node\"><div class=\"dtree-q\">Already on AWS, want serverless with simpler pricing than on-demand BigQuery?</div><div class=\"dtree-a rs\">\u2192 Redshift Serverless</div></div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">08 \u00b7 Every Hard Follow-up</div>\n  <h2>Questions interviewers always ask</h2>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">Why not use PostgreSQL for analytics? It has window functions and GROUP BY.<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>PostgreSQL can handle analytics on small datasets. The problem emerges at scale:</p>\n    <ul>\n      <li><strong>Row storage is fundamentally wrong for column scans:</strong> <code>SELECT COUNT(*) FROM events WHERE date = today()</code> on 100M rows \u2014 PostgreSQL reads every column of every row (even unused ones) due to row-oriented storage. ClickHouse reads only the date column \u2014 50\u00d7 less I/O on a table with 50 columns.</li>\n      <li><strong>MVCC overhead on analytical queries:</strong> PostgreSQL must check visibility for every row it scans (is this row visible to my transaction?). On 100M rows, this adds 10\u201330% CPU overhead. ClickHouse has no MVCC.</li>\n      <li><strong>No vectorised execution:</strong> PostgreSQL processes one row at a time through a tree of plan nodes. ClickHouse processes 8,192 rows per batch using SIMD instructions \u2014 50\u2013100\u00d7 more CPU-efficient for aggregations.</li>\n      <li><strong>Competing with live workload:</strong> Running a long analytical query on the OLTP PostgreSQL blocks autovacuum, consumes I/O, and spikes p99 latency for real users. Always separate OLAP from OLTP.</li>\n    </ul>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">ClickHouse claims 500K rows/sec ingest. How does that work with Kafka?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>ClickHouse has a native <strong>Kafka Table Engine</strong> that acts as a built-in Kafka consumer.</p>\n    <ol>\n      <li>You create a Kafka table pointing at your Kafka topic (broker address, topic name, consumer group, format).</li>\n      <li>You create a destination MergeTree table where data will be stored.</li>\n      <li>You create a Materialised View that connects the Kafka table to the MergeTree table \u2014 this is the insert trigger.</li>\n      <li>ClickHouse continuously polls Kafka, batches messages (default: 65,536 rows or 1 second, whichever comes first), and inserts into MergeTree atomically.</li>\n    </ol>\n    <p style=\"margin-top:8px;\"><strong>Why this is fast:</strong> Batched inserts write entire sorted data parts to disk sequentially \u2014 no random I/O. Each batch is one atomic disk write per column. With 500K rows/sec at ~100 bytes per row = 50 MB/sec sequential write \u2014 well within NVMe SSD capacity.</p>\n    <p style=\"margin-top:8px;\"><strong>Exactly-once guarantee:</strong> ClickHouse commits the Kafka offset only after the insert succeeds. If ClickHouse crashes mid-insert, it re-reads from the last committed offset \u2014 at-least-once semantics. Use ReplacingMergeTree with deduplication key to handle duplicate inserts.</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is Druid rollup and how is it different from ClickHouse AggregatingMergeTree?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>Both pre-aggregate data, but at different stages and with different trade-offs:</p>\n    <ul>\n      <li><strong>Druid rollup \u2014 at ingest time:</strong> Data is aggregated as it enters Druid. Raw events are combined into coarser time buckets (e.g., 1-minute granularity) before being stored. You configure rollup granularity upfront \u2014 you lose raw event detail permanently. 1B raw clicks become 10M rolled-up rows. Storage is 100\u00d7 smaller, queries are 100\u00d7 faster. But you can never answer \"what did user_id X do at 14:32:47\" after rollup.</li>\n      <li><strong>ClickHouse AggregatingMergeTree \u2014 at background merge time:</strong> Raw data is stored initially. Background merge process combines rows with identical keys, merging their aggregate state (SUM, MAX, HyperLogLog sketch). Raw data exists temporarily \u2014 row-level queries work until merged. After merge, rows with same key are combined. More flexible than Druid rollup \u2014 you can always query raw data before it's merged.</li>\n    </ul>\n    <p style=\"margin-top:8px;\"><strong>Which to choose:</strong> Druid rollup is more aggressive \u2014 better for when you know your query granularity in advance and want maximum compression. ClickHouse AggregatingMergeTree is more flexible \u2014 data is stored raw initially, merged asynchronously, and you can query at different granularities.</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">BigQuery charges per TB scanned. How do you control costs in production?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>BigQuery cost control is a real engineering concern. The four levers:</p>\n    <ul>\n      <li><strong>Partition pruning:</strong> Always add <code>WHERE _PARTITIONDATE = '2026-03-20'</code> or use partition columns in filters. Without this, every query scans the entire table. A 1 PB table with daily partitions: filtering one day = 1/365 of cost.</li>\n      <li><strong>Clustering:</strong> <code>CLUSTER BY user_id</code> co-locates rows with the same user_id in the same blocks. A query filtering by user_id skips 90%+ of blocks. Combined with partitioning, you can reduce scan to &lt;1% of total data.</li>\n      <li><strong>BI Engine / materialised views:</strong> Pre-compute common aggregations as materialised views. Dashboard queries hit the view (tiny) not the raw table (huge). BI Engine caches frequently-run query results in RAM \u2014 subsequent identical queries cost nothing.</li>\n      <li><strong>Reservations:</strong> Switch from on-demand to flat-rate reservations once you have predictable query volume. $1,800\u2013$2,400/slot/month with 500 slots is predictable vs unpredictable per-TB charges. Break-even is roughly when you scan 400+ TB/month.</li>\n    </ul>\n    <p style=\"margin-top:8px;\"><strong>Common interview answer:</strong> \"In production, all BigQuery tables are partitioned by date and clustered by the most common filter dimension. We use materialised views for dashboard queries. Monthly cost monitoring with alerts when a query scans &gt;10 TB unexpectedly.\"</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">In the Top-K system, why use ClickHouse instead of Cassandra for analytics?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>They serve completely different query contracts \u2014 this is a crucial distinction:</p>\n    <ul>\n      <li><strong>Cassandra serves the operational read path:</strong> \"Give me all hourly counts for entity X in region IN over the last 7 days\" = partition key lookup + range scan on clustering key. Fast, pre-defined access pattern. Cannot do GROUP BY, cannot scan all entities to find top ones, cannot do complex aggregations.</li>\n      <li><strong>ClickHouse serves the analytical read path:</strong> \"What were the top 10 videos in India last Tuesday between 6\u20138pm, broken down by device type, and how does that compare to the same period last week?\" \u2014 this requires full columnar scan + GROUP BY + window functions + join across time periods. ClickHouse handles this in 2\u20133 seconds on 100B rows. Cassandra would timeout or require 10+ minutes of scatter-gather across all partitions.</li>\n    </ul>\n    <p style=\"margin-top:8px;\">The same event stream (Kafka) feeds both. Flink writes to Cassandra (for operational real-time reads) AND to a Kafka output topic that ClickHouse consumes (for analytics). They receive the same data but answer different questions at different time horizons.</p>\n    <p style=\"margin-top:8px;\"><strong>Summary:</strong> Cassandra = fast, narrow, pre-planned queries on current data. ClickHouse = flexible, deep, analytical queries on historical data. Both necessary; neither can replace the other.</p>\n  </div></div>\n\n  <div class=\"faq\"><div class=\"faq-q\" onclick=\"toggle(this)\">ClickHouse vs Druid \u2014 when does Druid's sub-second speed matter more than ClickHouse's ingest speed?<span class=\"faq-tog\">+</span></div><div class=\"faq-a\">\n    <p>The decision comes down to the latency requirement and whether you need raw events:</p>\n    <ul>\n      <li><strong>Choose Druid when:</strong> You need &lt;500ms guaranteed for interactive dashboards with arbitrary filter combinations. A business user changes the date range slider and expects the chart to update instantly. Druid's bitmap indexes on every dimension make this possible. ClickHouse's &lt;1s is often good enough, but not always.</li>\n      <li><strong>Choose ClickHouse when:</strong> You have high-frequency ingest (&gt;100K rows/sec), need to retain raw event granularity (user-level queries), need flexible ad-hoc SQL, or want simpler operational management. ClickHouse's single binary vs Druid's 5-node-type cluster is a significant ops advantage.</li>\n      <li><strong>The Druid tax:</strong> Druid's rollup destroys raw event granularity. If you ever need \"did this specific user see this specific ad?\", Druid after rollup cannot answer this. ClickHouse retains raw events until they're merged.</li>\n    </ul>\n    <p style=\"margin-top:8px;\"><strong>Real-world trend:</strong> Many teams that previously used Druid are migrating to ClickHouse + pre-aggregated materialised views \u2014 they get 95% of Druid's query speed with ClickHouse's simpler ops and better SQL support.</p>\n  </div></div>\n\n</section>\n\n<div class=\"oneliner\">\n  <div class=\"lbl\">The one rule to remember</div>\n  <blockquote>\"ClickHouse: extreme ingest + fast aggregation, self-hosted. Druid: sub-second interactive dashboards, pre-aggregates at ingest. BigQuery: serverless analytics, pay per TB, zero ops. Redshift: AWS-native data warehouse. All four are columnar \u2014 the difference is when they aggregate, how they manage ops, and what they cost.\"</blockquote>\n</div>\n</div>\n<footer>OLAP \u00b7 CLICKHOUSE \u00b7 DRUID \u00b7 BIGQUERY \u00b7 REDSHIFT \u00b7 MANISH-ALMANAC</footer>\n\u003cscript>function toggle(el){var item=el.parentElement;var isOpen=item.classList.contains('open');document.querySelectorAll('.faq.open').forEach(function(f){f.classList.remove('open');});if(!isOpen)item.classList.add('open');}<\/script>\n</body></html>\n<section id=\"concepts-olap\">\n  <div class=\"sec-tag\">08 \u00b7 Core Concepts</div>\n  <h2>OLAP internals every interviewer tests</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Columnar Storage</div><div class=\"concept-def\"><strong>OLAP stores data column-by-column, not row-by-row. This is the single most important architectural difference from OLTP.</strong><br>\n      Row store: <code>[id=1, name=Alice, age=30, country=IN] | [id=2, ...]</code> \u2014 all columns for one row are adjacent.<br>\n      Column store: <code>[age: 30,25,41,28...] [country: IN,US,IN,UK...]</code> \u2014 all values for one column are adjacent.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Analytics queries read 2\u20133 columns from 100M rows. Column store reads only those 2\u20133 columns from disk. Row store must read all columns even if only 2 are needed \u2014 50x more I/O. Compression ratio also dramatically better: a column of country codes compresses 100:1 (dict encoding).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Vectorised Execution</div><div class=\"concept-def\"><strong>ClickHouse processes data in vectors (batches of 1,024 values) rather than row-by-row.</strong><br>\n      Traditional row-by-row: per-row function call overhead, poor CPU cache utilisation. Vectorised: load 1,024 values into SIMD registers, apply operation to all 1,024 simultaneously using CPU vector instructions.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 10\u2013100x faster for aggregations (SUM, AVG, COUNT) compared to row-by-row execution. ClickHouse benchmarks: 1 billion row aggregation in &lt;1 second on a single node. DuckDB also uses vectorised execution for embedded analytics.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pre-Aggregation<br>(Rollup / Materialization)</div><div class=\"concept-def\"><strong>Pre-compute aggregations at ingest time so queries read pre-rolled-up data instead of raw events.</strong><br>\n      Apache Druid: at ingest, rolls up <code>(timestamp, country, device) \u2192 count</code>. If 10,000 events have the same (minute, country, device) tuple, they become 1 row. Query on pre-aggregated data is 10,000x smaller.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Dramatic query speedup and storage reduction. Perfect for: dashboard metrics (DAU, event counts, revenue). Trade-off: cannot reconstruct individual events \u2014 only aggregated data is stored.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Must define aggregation dimensions at ingest time. Changing dimensions later requires full reingestion.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Partitioning &amp;<br>Pruning</div><div class=\"concept-def\"><strong>Partition data by time (day/month). Queries with time filters only scan relevant partitions.</strong><br>\n      ClickHouse: <code>PARTITION BY toYYYYMM(timestamp)</code>. Query for March 2026: reads only the March partition. Other months never touched.<br>\n      BigQuery: partition by date column. A query for last 7 days scans only 7 partitions regardless of total table size. Billing is based on bytes scanned \u2014 partitioning directly reduces query cost.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Always partition OLAP tables by time. Most analytics queries have a time filter \u2014 partition pruning turns full-table scans into partition scans. 100x reduction in data scanned is typical.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Dremel / BigQuery<br>Execution Model</div><div class=\"concept-def\"><strong>BigQuery uses a distributed execution engine (Dremel) that dynamically allocates thousands of workers for a single query.</strong><br>\n      A query on 10TB of data: BigQuery spins up 10,000 workers, each reading 1GB of Parquet from Colossus (Google's distributed filesystem). Workers aggregate in a shuffle step. Result returned in seconds.<br>\n      No indexes \u2014 BigQuery relies entirely on columnar scan parallelism. Works because: fast network (100Gbps), columnar compression (read only needed columns), massive parallelism.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">You pay per query (bytes scanned). Use partitioning + column selection to minimise scan cost. Clustering (sorting by commonly filtered columns) further reduces bytes scanned.</span></div></div>\n  </div>\n\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>OLAP Engine Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need sub-second query latency on fresh data (&lt;1 minute old)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (real-time OLAP) \u2192</span><span class=\"opt-text\"><strong>ClickHouse or Apache Druid.</strong> ClickHouse: best raw query speed, MergeTree + vectorised execution. Druid: better for pre-aggregated time-series with real-time ingestion from Kafka. Both handle seconds-fresh data at billions of rows.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (batch / hourly OK) \u2192</span><span class=\"opt-text\">Go to Step 2. Cloud DW may suffice.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your cloud provider and ops preference?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">AWS + zero ops \u2192</span><span class=\"opt-text\"><strong>Redshift.</strong> Fully managed. RA3 nodes: separate compute and storage \u2014 scale independently. Spectrum: query S3 data lakes directly without loading. Best for: AWS-native orgs, existing BI tooling (Tableau, Looker), mixed OLAP + ETL workloads.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">GCP or multi-cloud \u2192</span><span class=\"opt-text\"><strong>BigQuery.</strong> Serverless \u2014 no cluster to manage, pay per query. External tables query GCS/S3 directly. Best for: ad-hoc analytics, variable query patterns, orgs that cannot predict query volume.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Self-managed, cost-sensitive \u2192</span><span class=\"opt-text\"><strong>ClickHouse.</strong> 10x cheaper than BigQuery at high query volume. Self-hosted or ClickHouse Cloud. Requires ops knowledge but delivers best price/performance.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Is your primary use case time-series event analytics with known dimensions?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Apache Druid.</strong> Pre-aggregation at ingest compresses data dramatically. Perfect for: product analytics (DAU, event funnels), monitoring metrics, ad-tech impression counting. Real-time ingestion from Kafka with sub-second freshness.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (ad-hoc, exploratory) \u2192</span><span class=\"opt-text\"><strong>ClickHouse or BigQuery.</strong> No pre-aggregation needed. Full raw data retained, any aggregation computed at query time. Better for: data science exploration, complex multi-dimensional queries.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Uber \u2014 Real-Time Surge Pricing Analytics</div><span class=\"sd-example-tag\">REAL-TIME OLAP \u00b7 DRUID</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PROBLEM</div><div class=\"choice-val\">Surge pricing requires knowing demand (ride requests) vs supply (available drivers) per geo-cell, per minute, globally. Must be fresh (&lt;30s), queryable by city/zone/time, and handle millions of events per second.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ARCHITECTURE</div><div class=\"choice-val\">Ride request events \u2192 Kafka \u2192 Druid ingestion with 30-second rollup: (minute, city, zone, type) \u2192 count. Pre-aggregation reduces 1M events/min to ~10K rows/min. Druid real-time nodes answer \"requests in zone X last 5 minutes\" in &lt;50ms.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">QUERY</div><div class=\"choice-val\"><code>SELECT SUM(request_count) FROM ride_events WHERE zone='BLR-3' AND time > NOW()-5m</code> \u2014 Druid executes this on pre-aggregated data. Result: 2ms. Same query on raw events in PostgreSQL: minutes. This is the entire value proposition of pre-aggregating OLAP.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">HISTORICAL</div><div class=\"choice-val\">Historical data (>7 days) automatically tiered to deep storage (S3). Druid historical nodes load segments from S3 on demand. Dashboard queries for \"surge patterns last 90 days by city\" answered from S3-backed segments in &lt;2 seconds.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Shopify \u2014 Merchant Analytics Dashboard</div><span class=\"sd-example-tag\">BIGQUERY \u00b7 MULTI-TENANT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">SCALE</div><div class=\"choice-val\">100K+ merchants. Each merchant has their own analytics (sales by product, conversion rates, geographic breakdown). 50M+ orders/day across all merchants. Each merchant's dashboard must load in &lt;2 seconds.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">BIGQUERY</div><div class=\"choice-val\">One BigQuery dataset per merchant (logical isolation). Partitioned by order_date, clustered by product_id. Merchant dashboard query: scans only their partitions, &lt;5 seconds for 3 years of data. BigQuery's serverless model: Shopify pays per query scanned bytes, not for reserved cluster capacity.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">CACHING</div><div class=\"choice-val\">Dashboard common queries (today's revenue, top 10 products this week) pre-computed nightly by a Spark job \u2192 results stored in Redis with 1-hour TTL. Dashboard loads from Redis for common views (&lt;50ms). \"Custom\" queries (arbitrary date range, filter combinations) go to BigQuery (&lt;5 seconds).</div></div>\n    </div>\n  </div>\n  <div class=\"concept-grid\" style=\"margin-top:16px;\">\n    <div class=\"concept-row\"><div class=\"concept-term\">ClickHouse<br>MergeTree</div><div class=\"concept-def\"><strong>ClickHouse's primary table engine. Data is written in \"parts\" and merged in the background \u2014 like LSM trees but for columnar OLAP.</strong><br>\n      Insert: data written as a new sorted part (like an SSTable). Background merge: parts are periodically merged and sorted. Query: reads only relevant parts (primary key pruning) + relevant columns.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Extremely fast inserts (sequential writes). Background merge keeps reads fast. Variants: SummingMergeTree (aggregates on merge), ReplacingMergeTree (deduplicates on merge), AggregatingMergeTree (stores pre-aggregated state).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redshift Spectrum</div><div class=\"concept-def\"><strong>Query S3 data directly from Redshift without loading it into Redshift storage first.</strong><br>\n      Create an external table pointing to S3 Parquet files. JOIN it with internal Redshift tables. Spectrum pushes predicates and column selection to the S3 layer \u2014 only relevant data is transferred.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Hot data in Redshift (fast). Cold/archive data in S3 (cheap). Query both in one SQL statement. Ideal for: historical analysis where only recent data needs Redshift's full speed.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">BigQuery Slots</div><div class=\"concept-def\"><strong>BigQuery allocates \"slots\" (units of compute) to each query dynamically from a shared pool.</strong><br>\n      On-demand pricing: up to 2,000 slots per project. Pay per TB scanned. Flat-rate: buy reserved slots (500 minimum) for predictable cost at high query volume. At Shopify/Airbnb scale, flat-rate is dramatically cheaper.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Slot contention: if your project runs many concurrent queries, they compete for slots. One very large query can starve smaller dashboard queries. Use workload management (reservations + assignments) to allocate slots per team or use case.</span></div></div>\n  </div>\n</section>\n\n<section id=\"faq-olap\">\n  <div class=\"sec-tag\">09 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">When should you use ClickHouse instead of Redshift or BigQuery?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>ClickHouse wins on raw query speed and cost at high query volume. Cloud DWs win on zero ops and ecosystem integration.</strong><br><br>\n  <strong>Choose ClickHouse when:</strong> (1) Query latency matters at millisecond level (dashboards updating every few seconds). (2) You run high query volume \u2014 BigQuery/Redshift charge per byte scanned, which gets expensive. (3) You want to self-host and have ops capacity. (4) You need real-time ingestion with seconds-fresh query results. Uber, Cloudflare, ByteDance all use ClickHouse for exactly these reasons.<br><br>\n  <strong>Stay with BigQuery/Redshift when:</strong> (1) You prioritise zero infrastructure management. (2) Your queries are infrequent and ad-hoc \u2014 BigQuery's serverless model is perfect. (3) You need tight integration with the cloud provider's ecosystem (Redshift + S3 + Glue + QuickSight). (4) Your team lacks the expertise to tune ClickHouse (MergeTree configuration, shard keys, tiered storage).</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle schema changes in a live OLAP system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Schema evolution in OLAP is harder than OLTP because of partitioned, compressed, column-oriented storage.</strong><br><br>\n  <strong>Adding a new column</strong>: safe in ClickHouse (ALTER TABLE ADD COLUMN \u2014 metadata change only, new column is NULL/default for existing rows). Safe in BigQuery (ADD COLUMN via schema update). Safe in Redshift (ALTER TABLE ADD COLUMN \u2014 fast metadata operation).<br><br>\n  <strong>Changing column type or removing a column</strong>: dangerous. Options: (1) Add new column with new type, backfill from old column, update application to use new column, eventually drop old column. (2) Create a new table with correct schema, backfill from old, swap via view or DNS change. Never modify column types in place on petabyte tables \u2014 it requires a full rewrite.<br><br>\n  <strong>Changing partition key</strong>: requires full reingestion. There is no shortcut. Plan partition keys carefully before launch \u2014 they are permanent.<br><br>\n  <strong>Druid</strong>: schema changes require re-ingesting affected time intervals from the source (Kafka or S3). Druid's immutable segment model means in-place schema migration is not possible.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you design a real-time dashboard showing metrics with sub-second freshness?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Three-layer architecture: streaming ingestion \u2192 real-time OLAP \u2192 query cache.</strong><br><br>\n  Layer 1 \u2014 Ingestion: events from your application \u2192 Kafka topic \u2192 Flink aggregation (1-minute tumbling windows) \u2192 ClickHouse or Druid sink. Flink reduces event volume by 100x before hitting OLAP (10K events/sec \u2192 100 pre-aggregated rows/sec per dimension).<br><br>\n  Layer 2 \u2014 OLAP: ClickHouse table partitioned by hour, clustered by (date, metric_name, dimensions). Pre-computed rollups for common queries. Queries return in &lt;50ms even at billions of rows because they hit pre-aggregated data.<br><br>\n  Layer 3 \u2014 Query cache: dashboard queries for the same time range and dimensions are cached in Redis for 10 seconds. 100 concurrent users viewing the same dashboard = 1 ClickHouse query per 10 seconds (not 100). Cache-aside with short TTL matches the sub-second freshness requirement.<br><br>\n  <strong>The trap to avoid</strong>: querying raw events in ClickHouse from a dashboard with 100 concurrent users. Even fast OLAP becomes slow under that load. Pre-aggregate + cache is always the answer for dashboard use cases.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between a data warehouse and a data lake?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Schema-on-write (warehouse) vs schema-on-read (lake) \u2014 and the modern \"lakehouse\" that combines both.</strong><br><br>\n  <strong>Data Warehouse</strong> (Redshift, BigQuery, Snowflake): structured, schema defined before loading, data cleaned and transformed at ingest (ETL). Fast queries because structure is known. Cannot store unstructured data (images, raw logs, JSON blobs).<br><br>\n  <strong>Data Lake</strong> (S3 + Parquet): store raw data in any format first, define schema when reading (schema-on-read). Flexible, cheap, can store anything. Slow queries without proper partitioning and file format discipline.<br><br>\n  <strong>Data Lakehouse</strong> (Databricks Delta Lake, Apache Iceberg on S3): combine both. S3/GCS storage cost + columnar Parquet performance + ACID transactions from Delta/Iceberg metadata layer. Query directly from S3 with warehouse-like performance. This is the modern standard \u2014 most new data platform designs use the lakehouse pattern.<br><br>\n  <strong>Interview answer</strong>: \"I'd start with a data lake on S3 using Parquet + Delta Lake for ACID. Query with Athena for ad-hoc, Spark for batch processing, and ClickHouse for dashboard queries. This gives warehouse performance at lake economics.\"</div></div>\n</section>", tag: 'Analytics DB' },
  streaming:   { title: 'Stream Processing Decoded',     srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Stream Processing Showdown: Kafka vs Flink vs Kinesis vs Spark Streaming</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Sora:wght@300;400;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#080c14;--page:#f2f4f8;--surface:#e6eaf2;--surface2:#d8dcec;--border:#c8cdd8;--muted:#6870880;\n--kf:#000000;--kf-bg:#f0f0f0;--fl:#e35400;--fl-bg:#fff4ef;--ki:#ff9900;--ki-bg:#fff8ee;--ss:#e25100;--ss-bg:#fff3ee;\n--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--teal:#0a7070;--teal-bg:#edf6f6;\n--mono:'JetBrains Mono',monospace;--sans:'Sora',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#dde0ec;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent,transparent 80px,rgba(255,255,255,.008) 80px,rgba(255,255,255,.008) 81px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#3a3e50;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--sans);font-size:clamp(30px,5vw,56px);font-weight:800;line-height:1.05;letter-spacing:-1.5px;margin-bottom:20px;color:#eef0f8;}\nh1 em{color:#f77f3a;font-style:normal;}\n.hero-sub{font-size:15px;color:#5a5e70;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-kf{border-color:#666;color:#666;background:rgba(0,0,0,.05);}\n.pill-fl{border-color:#e35400;color:#c04400;background:rgba(227,84,0,.06);}\n.pill-ki{border-color:#ff9900;color:#cc7000;background:rgba(255,153,0,.06);}\n.pill-ss{border-color:#e25100;color:#b04000;background:rgba(226,81,0,.06);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #101420;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#2a2e40;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#f77f3a;border-color:#f77f3a;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:#7a7e90;margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--sans);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;letter-spacing:-.5px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3d50;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.kf::before{background:#333;}.db-card.fl::before{background:var(--fl);}.db-card.ki::before{background:var(--ki);}.db-card.ss::before{background:var(--ss);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--sans);font-size:17px;font-weight:700;letter-spacing:-.3px;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#7a7e90;margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5e70;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:#7a7e90;margin-top:8px;}\n.role-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:24px 0;}\n.role-card{border-radius:8px;padding:20px;border:1px solid var(--border);}\n.role-card.transport{background:#f8f0e8;border-color:#d8b88a;}\n.role-card.processing{background:#e8f4f0;border-color:#8ac8b0;}\n.role-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;font-weight:600;}\n.role-body{font-size:13.5px;color:#3a3d50;line-height:1.65;}\n.analogy{background:var(--ink);color:#c8ccd8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#3a3e50;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d0d4e0;}\n.analogy-text strong{color:#f77f3a;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-teal{background:var(--teal-bg);border-color:var(--teal);color:#0a2a2a;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8ccd8;border:1px solid #101420;}\n.codeblock .c{color:#2a2e40;}.codeblock .k{color:#f77f3a;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8a06a;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}.codeblock .t{color:#7ab8e0;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:#7a7e90;}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3d50;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--sans);font-size:16px;font-weight:700;color:#eef0f8;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#3a3e50;border:1px solid #1a1e30;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#7a7e90;width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3d50;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-kf{background:#f0f0f0;border-color:#999;color:#444;}.b-fl{background:var(--fl-bg);border-color:var(--fl);color:#c04400;}.b-ki{background:var(--ki-bg);border-color:var(--ki);color:#cc7000;}.b-ss{background:var(--ss-bg);border-color:var(--ss);color:#b04000;}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#f77f3a;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3d50;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4e60;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#1a1e30;letter-spacing:2px;}\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 Stream Processing \u00b7 Manish-Almanac</div>\n    <h1>Stream Processing<br><em>Decoded</em></h1>\n    <p class=\"hero-sub\">Kafka vs Apache Flink vs Amazon Kinesis vs Spark Streaming \u2014 understand the roles, the differences, and exactly how to use each in a FAANG-level system design interview. With real examples and every follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-kf\">Apache Kafka</span>\n      <span class=\"db-pill pill-fl\">Apache Flink</span>\n      <span class=\"db-pill pill-ki\">Amazon Kinesis</span>\n      <span class=\"db-pill pill-ss\">Spark Streaming</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#roles\">Transport vs Processing</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#kafka-deep\">Kafka Deep</a>\n  <a href=\"#processing\">Processing Engines</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"roles\">\n  <div class=\"sec-tag\">00 \u00b7 The Critical Distinction</div>\n  <h2>Transport vs Processing \u2014 they're not the same thing</h2>\n  <p>The biggest mistake candidates make is treating Kafka, Flink, Kinesis, and Spark Streaming as competing alternatives. <strong>They're not.</strong> They play fundamentally different roles in a streaming architecture.</p>\n  <div class=\"role-grid\">\n    <div class=\"role-card transport\">\n      <div class=\"role-title\" style=\"color:#8a6020\">\ud83d\ude8c Transport / Message Bus</div>\n      <div class=\"role-body\"><strong>Kafka, Kinesis, Pulsar</strong><br><br>Like a highway \u2014 vehicles (messages) enter, travel through, and exit. The highway stores vehicles temporarily so producers don't have to wait for consumers to be ready. It decouples producers from consumers.<br><br>Key properties: durable storage, ordered delivery within partition, multiple consumers reading the same message independently, replay old messages.</div>\n    </div>\n    <div class=\"role-card processing\">\n      <div class=\"role-title\" style=\"color:#1a6a4a\">\u2699\ufe0f Stream Processor</div>\n      <div class=\"role-body\"><strong>Flink, Spark Streaming, Kafka Streams</strong><br><br>Like a factory that processes vehicles as they pass through \u2014 counting them, sorting them, combining them with data from other sources, detecting anomalies. The processor does the actual computation.<br><br>Key properties: stateful computation, windowing (tumbling, sliding, session), joins across streams, exactly-once semantics, fault tolerance with checkpoints.</div>\n    </div>\n  </div>\n  <div class=\"callout cl-teal\">\n    <div class=\"cl-lbl\">The correct mental model for Top-K</div>\n    <p><strong>Kafka</strong> = the highway. Events from users flow in, get durably stored, and multiple consumers can read them independently and at their own pace.</p>\n    <p><strong>Flink</strong> = the factory. Consumes from Kafka, applies the Count-Min Sketch, maintains the local heap, and every 30 seconds flushes the Top-K results to Redis and Cassandra.</p>\n    <p>You <strong>always use a transport layer AND a processing layer</strong> together. They're complementary, not competitive.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four Technologies</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card kf\">\n      <div class=\"db-logo\">\u2b1b</div>\n      <div class=\"db-name\">Apache Kafka</div>\n      <div class=\"db-type\">Distributed Message Bus</div>\n      <div class=\"db-tagline\">The gold standard for event streaming. Durable, ordered, replayable. Processes trillions of events/day at LinkedIn, Netflix, Uber. The backbone of nearly every modern data platform.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 LinkedIn \u2192 Apache \u00b7 Log-structured storage</div>\n    </div>\n    <div class=\"db-card fl\">\n      <div class=\"db-logo\">\ud83d\udd36</div>\n      <div class=\"db-name\">Apache Flink</div>\n      <div class=\"db-type\">Stateful Stream Processor</div>\n      <div class=\"db-tagline\">The stream processing heavyweight. True streaming (not micro-batch), exactly-once semantics, millisecond latency, complex windowing, stateful operations. Used by Uber, Alibaba, Apple for real-time pipelines.</div>\n      <div class=\"db-born\">Born 2014 \u00b7 TU Berlin \u2192 Apache \u00b7 Dataflow model</div>\n    </div>\n    <div class=\"db-card ki\">\n      <div class=\"db-logo\">\ud83d\udfe0</div>\n      <div class=\"db-name\">Amazon Kinesis</div>\n      <div class=\"db-type\">Managed Event Streaming (AWS)</div>\n      <div class=\"db-tagline\">Kafka's managed AWS alternative. Zero ops, auto-scaling shards, deep AWS integration (Lambda, S3, Redshift). Perfect if you're all-in AWS and don't want to manage a Kafka cluster.</div>\n      <div class=\"db-born\">Born 2013 \u00b7 Amazon AWS \u00b7 Shard-based partitioning</div>\n    </div>\n    <div class=\"db-card ss\">\n      <div class=\"db-logo\">\u2726</div>\n      <div class=\"db-name\">Spark Streaming</div>\n      <div class=\"db-type\">Micro-Batch Stream Processor</div>\n      <div class=\"db-tagline\">Streaming built on Spark's batch engine. Uses micro-batches (seconds) rather than true streaming. Best when you already use Spark for batch ETL and want a unified pipeline. Not ideal for millisecond-latency requirements.</div>\n      <div class=\"db-born\">Born 2013 \u00b7 UC Berkeley \u2192 Apache \u00b7 Micro-batch model</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"kafka-deep\">\n  <div class=\"sec-tag\">02 \u00b7 Transport Layer Deep Dive</div>\n  <h2>Kafka \u2014 Understanding It at Interview Depth</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Kafka explained for a complete layman</div>\n    <div class=\"analogy-text\">\n      Imagine a newspaper printing plant. Every morning, thousands of reporters (producers) submit stories. The plant prints millions of copies (events) and distributes them to hundreds of newsstands (partitions). Each newsstand keeps its newspapers for 7 days (retention).<br><br>\n      Any reader (consumer) can pick up a paper from any newsstand, and two readers picking up the same paper both get the full content \u2014 the paper isn't destroyed when read. A reader can also go back and re-read papers from last Tuesday (replay).<br><br>\n      <strong>The magic:</strong> Reporters don't wait for readers. Readers don't wait for reporters. The newsstand (Kafka) acts as a durable buffer between them.\n    </div>\n  </div>\n\n  <h3>The Core Kafka Concepts Every Interviewer Expects</h3>\n  <div class=\"codeblock\">\n<span class=\"c\">// Kafka architecture \u2014 say these terms correctly in interviews</span>\n\n<span class=\"k\">Topic:</span>       A named stream of events. Like a table in a database.\n              e.g. \"user-clicks\", \"video-views\", \"payment-events\"\n\n<span class=\"k\">Partition:</span>   A topic is split into N partitions for parallelism.\n              Events with the same partition key always go to the same partition.\n              <span class=\"t\">entity_id \u2192 hash(entity_id) % N \u2192 partition number</span>\n              Within a partition, order is GUARANTEED.\n              Across partitions, order is NOT guaranteed.\n\n<span class=\"k\">Offset:</span>      A sequential ID for each event within a partition.\n              Consumers track their offset \u2014 \"I've read up to #12,847\"\n              This enables replay: \"re-read from offset 0\"\n\n<span class=\"k\">Consumer Group:</span> A set of consumers that share the work of reading a topic.\n              Each partition is consumed by exactly ONE consumer in a group.\n              Multiple groups can read the same topic independently.\n              <span class=\"g\">\u2192 This is how Flink, ClickHouse, and S3 sink can all read the same Kafka topic</span>\n\n<span class=\"k\">Broker:</span>      A Kafka server node. Usually 3\u20135 brokers in production.\n              Each partition is replicated across brokers (replication factor = 3).\n              Leader broker accepts writes; followers replicate.\n\n<span class=\"k\">Retention:</span>   How long Kafka keeps events before deleting.\n              Default: 7 days. Can be extended to forever (like a database).\n              <span class=\"g\">This enables replay: Flink crashed? Resume from last committed offset.</span>\n  </div>\n\n  <h3>Kafka vs Kinesis \u2014 The Managed vs Self-Managed Decision</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Apache Kafka \u2b1b</th><th>Amazon Kinesis \ud83d\udfe0</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Throughput</td><td><span class=\"good\">Millions/sec</span> per cluster</td><td><span class=\"warn\">1MB/sec or 1000 records/sec</span> per shard</td></tr>\n      <tr><td class=\"row-head\">Latency</td><td><span class=\"good\">Sub-millisecond</span></td><td><span class=\"warn\">70\u2013200ms</span> typical</td></tr>\n      <tr><td class=\"row-head\">Retention</td><td><span class=\"good\">Configurable</span> \u2014 days to forever</td><td><span class=\"warn\">24h default</span>, max 7 days (Kinesis Firehose: unlimited)</td></tr>\n      <tr><td class=\"row-head\">Replay</td><td><span class=\"good\">Any offset, any time</span></td><td><span class=\"warn\">Within retention window</span> only</td></tr>\n      <tr><td class=\"row-head\">Partitioning</td><td>Topics \u2192 Partitions (flexible count)</td><td>Streams \u2192 Shards (auto-scaling available)</td></tr>\n      <tr><td class=\"row-head\">Consumer Groups</td><td><span class=\"good\">Unlimited</span> independent consumer groups</td><td><span class=\"warn\">Limited</span> \u2014 5 consumers per shard by default</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"bad\">High</span> \u2014 manage brokers, ZK/KRaft, rebalancing</td><td><span class=\"good\">Zero</span> \u2014 fully managed</td></tr>\n      <tr><td class=\"row-head\">Cost Model</td><td>Fixed infra cost (predictable at scale)</td><td>Pay per shard-hour + data volume</td></tr>\n      <tr><td class=\"row-head\">Cloud Lock-in</td><td><span class=\"good\">None</span> \u2014 open source, any cloud</td><td><span class=\"bad\">AWS only</span></td></tr>\n      <tr><td class=\"row-head\">AWS Integration</td><td>Manual connectors</td><td><span class=\"good\">Native</span> Lambda triggers, S3 Firehose, Redshift</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"processing\">\n  <div class=\"sec-tag\">03 \u00b7 Processing Layer Deep Dive</div>\n  <h2>Flink vs Spark Streaming \u2014 True Streaming vs Micro-Batch</h2>\n\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The Core Difference</div>\n    <p><strong>Apache Flink:</strong> True streaming. Processes each event as it arrives. State is maintained in memory/RocksDB between events. Latency: milliseconds. Results are continuously updated.</p>\n    <p><strong>Spark Streaming (Structured Streaming):</strong> Micro-batch. Collects events for X seconds (e.g., 5s), then processes the batch. Latency: minimum is the batch interval. Simpler programming model, reuses Spark's batch optimisations.</p>\n  </div>\n\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">True streaming vs micro-batch \u2014 the toll booth analogy</div>\n    <div class=\"analogy-text\">\n      <strong>True streaming (Flink):</strong> Each car approaches the toll booth and is processed individually as it arrives. The attendant collects, processes, and lets through each car without waiting. Immediate, real-time.<br><br>\n      <strong>Micro-batch (Spark Streaming):</strong> Cars are held at a red light for 5 seconds. Then the light turns green, all cars are processed together as a batch, then the light turns red again. Slightly delayed but can be more efficient for high volumes.\n    </div>\n  </div>\n\n  <h3>Flink's Key Capabilities \u2014 What Makes It the FAANG Choice</h3>\n  <div class=\"codeblock\">\n<span class=\"c\">// Flink's three superpowers for system design interviews</span>\n\n<span class=\"c\">// 1. WINDOWING \u2014 aggregate events over time</span>\n<span class=\"k\">Tumbling Window</span> (30 seconds):\n  Events from t=0 to t=30 form one window.\n  Window closes at t=30, results emitted, new window starts.\n  <span class=\"g\">Used in Top-K: flush Top-K every 30 seconds to Redis/Cassandra</span>\n\n<span class=\"k\">Sliding Window</span> (1 hour, slides every 5 min):\n  12 overlapping windows active simultaneously.\n  Smoother results but 12x memory and compute.\n  <span class=\"g\">Used for: \"trending over last hour\" with smooth updates</span>\n\n<span class=\"k\">Session Window</span> (gap timeout: 30 min):\n  Window stays open while user is active, closes after 30min idle.\n  <span class=\"g\">Used for: user session analytics, funnel analysis</span>\n\n<span class=\"c\">// 2. EXACTLY-ONCE SEMANTICS</span>\n<span class=\"k\">The problem:</span>  Flink crashes mid-window. How do you avoid double-counting?\n<span class=\"k\">The solution:</span> Kafka offsets + Flink checkpoints (saved to S3/HDFS)\n  - Every 60 seconds, Flink saves: current state + last Kafka offset consumed\n  - On crash recovery: restore state from checkpoint, re-read Kafka from saved offset\n  - Some events processed twice (between last checkpoint and crash)\n  - Two-phase commit: Flink only commits offset to Kafka AFTER state is checkpointed\n  <span class=\"g\">\u2192 Guaranteed: each event counted exactly once, even after crash</span>\n\n<span class=\"c\">// 3. STATEFUL OPERATIONS \u2014 memory across events</span>\n<span class=\"k\">Without state:</span> Each event processed independently (like a stateless function)\n<span class=\"k\">With state:</span>    Flink remembers the running count for entity_id=123 across events\n  State stored in: memory (fast) or RocksDB (durable, larger than RAM)\n  State checkpointed to S3 for fault tolerance\n  <span class=\"g\">Used in Top-K: the Count-Min Sketch and local heap ARE Flink state</span>\n  </div>\n\n  <h3>When to Use Each Processing Engine</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Apache Flink \ud83d\udd36</th><th>Spark Streaming \u2726</th><th>Kafka Streams</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Processing Model</td><td><span class=\"good\">True streaming</span></td><td><span class=\"warn\">Micro-batch</span> (1\u201310s)</td><td><span class=\"good\">True streaming</span></td></tr>\n      <tr><td class=\"row-head\">Latency</td><td><span class=\"good\">Milliseconds</span></td><td><span class=\"warn\">Seconds</span> (batch interval)</td><td><span class=\"good\">Milliseconds</span></td></tr>\n      <tr><td class=\"row-head\">Exactly-Once</td><td><span class=\"good\">Yes</span> \u2014 native</td><td><span class=\"warn\">Yes</span> \u2014 with idempotent sinks</td><td><span class=\"good\">Yes</span> \u2014 within Kafka</td></tr>\n      <tr><td class=\"row-head\">Complexity</td><td><span class=\"warn\">High</span> \u2014 dedicated cluster</td><td><span class=\"warn\">Medium</span> \u2014 reuses Spark</td><td><span class=\"good\">Low</span> \u2014 library, no cluster</td></tr>\n      <tr><td class=\"row-head\">State Management</td><td><span class=\"good\">RocksDB</span>, large state ok</td><td><span class=\"warn\">In-memory</span> \u2014 limited state</td><td><span class=\"good\">RocksDB</span> local to app</td></tr>\n      <tr><td class=\"row-head\">Best For</td><td>Complex stateful streaming, low latency</td><td>Already using Spark batch; simple streaming</td><td>Lightweight per-service streaming</td></tr>\n      <tr><td class=\"row-head\">Throughput</td><td>Millions events/sec</td><td>Millions events/sec (in batch)</td><td>Hundreds K/sec per app</td></tr>\n      <tr><td class=\"row-head\">Used By</td><td>Uber, Alibaba, Apple, Netflix</td><td>Databricks customers, Spark shops</td><td>Microservice architectures</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">04 \u00b7 The Full Stack</div>\n  <h2>How They Combine in a Real Architecture</h2>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The standard streaming stack pattern</div>\n    <p><strong>Layer 1 \u2014 Producers:</strong> Applications, services, IoT sensors emit events.</p>\n    <p><strong>Layer 2 \u2014 Transport (Kafka / Kinesis):</strong> Events are durably stored, decoupling producers from consumers. Multiple downstream consumers read independently.</p>\n    <p><strong>Layer 3 \u2014 Stream Processor (Flink / Spark):</strong> Consumes from transport layer, applies business logic (windowing, aggregation, enrichment, filtering), outputs results.</p>\n    <p><strong>Layer 4 \u2014 Sinks:</strong> Results written to Redis (hot), Cassandra (warm), ClickHouse (analytics), S3 (cold/archive).</p>\n  </div>\n\n  <div class=\"codeblock\">\n<span class=\"c\">// The Top-K streaming stack \u2014 visualised</span>\n\n<span class=\"n\">Mobile/Web Apps</span>\n      \u2502  (HTTP POST /event)\n      \u25bc\n<span class=\"k\">Event Service</span>  \u2500\u2500(async fire-and-forget)\u2500\u2500\u25ba  <span class=\"t\">Apache Kafka</span>\n                                                   \u2502\n                              \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n                              \u2502                    \u2502                      \u2502\n                              \u25bc                    \u25bc                      \u25bc\n                     <span class=\"k\">Flink Cluster</span>     <span class=\"t\">ClickHouse</span>          <span class=\"t\">S3 Sink</span>\n                   (Count-Min + Heap)   (Kafka Engine)      (Parquet archive)\n                              \u2502\n              \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n              \u25bc               \u25bc               \u25bc\n         <span class=\"n\">Redis ZSET</span>    <span class=\"n\">Cassandra</span>    <span class=\"n\">Kafka Output Topic</span>\n         (hot ranking)  (warm counts)  (\u2192 ClickHouse)\n              \u2502\n              \u25bc\n         <span class=\"k\">Read API</span>  \u2500\u2500\u25ba  CDN  \u2500\u2500\u25ba  Client (&lt;50ms)\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 Applied to Real Systems</div>\n  <h2>System Design Examples</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending \u2014 Complete Stream Stack</div>\n      <span class=\"sd-example-tag\">500K EVENTS/SEC</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TRANSPORT</div><div class=\"choice-val\"><span class=\"badge b-kf\">Kafka \u2713</span> Partitioned by entity_id \u2014 all events for video_123 go to the same partition and same Flink worker. No cross-worker coordination needed for local aggregation. 7-day retention enables Flink to replay on crash without data loss.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PROCESSING</div><div class=\"choice-val\"><span class=\"badge b-fl\">Flink \u2713</span> 30-second tumbling windows. Count-Min Sketch per worker (6KB fixed memory). Local min-heap of top-K=1000. Bloom filter for deduplication. Exactly-once via Kafka offset + S3 checkpoint. Flushes ZINCRBY to Redis + rows to Cassandra every 30s.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT KINESIS</div><div class=\"choice-val\"><span class=\"badge b-a\">Kinesis \u26a0</span> Could work in AWS but: 1MB/sec per shard limit means 500K events/sec needs 500 shards minimum. At $0.015/shard-hour \u00d7 500 shards \u00d7 24h = $180/day just for the shard cost. Kafka on 10 nodes handles same volume for ~$50/day.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT SPARK</div><div class=\"choice-val\"><span class=\"badge b-a\">Spark \u26a0</span> Micro-batch model means Top-K results update every 5\u201310 seconds minimum (batch interval). Flink's true streaming updates the Count-Min Sketch per-event with millisecond latency. For a trending feature, Flink's freshness is materially better.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Fraud Detection (Payment System)</div>\n      <span class=\"sd-example-tag\">MILLISECOND DECISIONS</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TRANSPORT</div><div class=\"choice-val\"><span class=\"badge b-kf\">Kafka \u2713</span> Payment events partitioned by user_id. Ensures all transactions for a given user go to the same Flink worker \u2014 enabling per-user velocity checks without cross-partition joins.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PROCESSING</div><div class=\"choice-val\"><span class=\"badge b-fl\">Flink \u2713</span> Session windows detect: \"more than 3 transactions in 60 seconds\" or \"transaction amount 10x higher than 30-day average.\" Per-user state (running totals, recent transaction history) stored in RocksDB \u2014 survives restarts.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY FLINK NOT SPARK</div><div class=\"choice-val\">Fraud decisions need sub-100ms latency \u2014 the payment is in flight waiting for approval. Spark's 5-second micro-batch interval means a fraudulent transaction would be approved before detection. Flink processes each event in ~10ms.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">ETL Pipeline (Data Warehouse Loading)</div>\n      <span class=\"sd-example-tag\">BATCH-FRIENDLY</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">CHOICE</div><div class=\"choice-val\"><span class=\"badge b-kf\">Kafka</span> + <span class=\"badge\" style=\"background:#f0f4fc;border-color:#888;color:#444\">Spark Streaming \u2713</span> ETL to data warehouse: Kafka \u2192 Spark Structured Streaming \u2192 Redshift/BigQuery. Spark's micro-batch is fine here \u2014 loading data every 5 minutes into a data warehouse is perfectly acceptable. Reuses existing Spark infrastructure. Spark's DataFrame API makes transformations, schema enforcement, and deduplication easy.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">AWS VERSION</div><div class=\"choice-val\"><span class=\"badge b-ki\">Kinesis Firehose \u2713</span> Kinesis Data Firehose auto-delivers to S3, Redshift, OpenSearch. Zero-code ETL for simple pipelines. For AWS shops building data lakes, Firehose + Glue is the zero-ops path.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 The Decision Framework</div>\n  <h2>How to Pick in an Interview</h2>\n  <div class=\"codeblock\">\n<span class=\"c\">// Streaming technology decision tree</span>\n\n<span class=\"k\">Step 1:</span> What is your latency requirement?\n  <span class=\"g\">Sub-second (fraud detection, real-time alerts)</span>\n    \u2192 Kafka + Flink (true streaming)\n  <span class=\"n\">A few seconds is fine (dashboards, aggregations)</span>\n    \u2192 Kafka + Flink or Kafka + Spark Streaming\n  <span class=\"r\">Minutes ok (ETL, data warehouse)</span>\n    \u2192 Kafka/Kinesis + Spark Structured Streaming\n\n<span class=\"k\">Step 2:</span> Do you need stateful computation?\n  <span class=\"g\">YES (running aggregations, windowed counts, ML scoring)</span>\n    \u2192 Flink (best state management: RocksDB + checkpoints)\n  <span class=\"n\">NO (simple filter, transform, route)</span>\n    \u2192 Kafka Streams or Kinesis Data Analytics\n\n<span class=\"k\">Step 3:</span> Transport: managed or self-hosted?\n  <span class=\"g\">AWS-first, zero ops</span>         \u2192 Kinesis Data Streams\n  <span class=\"n\">Cost-sensitive, high throughput</span> \u2192 Apache Kafka\n  <span class=\"r\">Pulsar features needed</span>         \u2192 Apache Pulsar\n\n<span class=\"k\">Step 4:</span> Processing: team expertise?\n  <span class=\"g\">Already use Spark for batch ETL</span> \u2192 Spark Structured Streaming\n  <span class=\"n\">Need low-latency, complex state</span>  \u2192 Apache Flink\n  <span class=\"r\">Simple per-service streaming</span>    \u2192 Kafka Streams (library, no cluster)\n\n<span class=\"k\">Always combine transport + processing:</span>\n  Kafka + Flink     = FAANG standard for complex real-time pipelines\n  Kinesis + Lambda  = AWS serverless, simple event-driven\n  Kafka + Spark     = Unified batch + streaming on Databricks/Spark shops\n  </div>\n\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#444\">\u2b1b Use Kafka when\u2026</div>\n      <ul><li>High throughput (&gt;100K/sec per topic)</li><li>Long retention / replay needed</li><li>Multiple independent consumers</li><li>Not locked into AWS</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#c04400\">\ud83d\udd36 Use Flink when\u2026</div>\n      <ul><li>Sub-second latency needed</li><li>Complex stateful operations</li><li>Windowed aggregations</li><li>Exactly-once critical (fraud, billing)</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc7000\">\ud83d\udfe0 Use Kinesis when\u2026</div>\n      <ul><li>AWS-native, zero ops priority</li><li>Moderate throughput</li><li>Lambda integration needed</li><li>Firehose delivery to S3/Redshift</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#b04000\">\u2726 Use Spark Streaming when\u2026</div>\n      <ul><li>Already have Spark infrastructure</li><li>ETL/data warehouse loading</li><li>Unified batch + streaming code</li><li>Seconds latency is acceptable</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Kafka guarantees at-most-once, at-least-once, or exactly-once?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>All three \u2014 depending on how you configure it.</strong><br><br><strong>At-most-once:</strong> Consumer reads message, immediately commits offset, then processes. If processing crashes, the message is lost (offset already advanced).<br><br><strong>At-least-once:</strong> Consumer reads, processes, then commits offset. If processing crashes before commit, message is reprocessed on restart. May be processed twice.<br><br><strong>Exactly-once (EOS):</strong> Requires both idempotent producers (enable.idempotence=true) AND transactional producers + consumers. Kafka ensures each message is written exactly once even with retries. Combined with Flink's two-phase commit, this gives exactly-once end-to-end. Performance overhead: ~20% throughput reduction.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What happens to in-flight Flink state when a node crashes?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Flink recovers from its last checkpoint.</strong><br><br>Every 60 seconds (configurable), Flink performs a distributed snapshot: all operator states (Count-Min Sketch, local heap, Bloom filter) are saved to S3. The corresponding Kafka offset consumed up to that point is also saved.<br><br>On crash: Flink restarts from the last successful checkpoint. It resumes reading Kafka from the saved offset. Events between the checkpoint and the crash are replayed from Kafka (this is why Kafka retention matters). State is restored from S3.<br><br>If Flink uses exactly-once mode (two-phase commit), the output (writes to Redis/Cassandra) is also rolled back if the checkpoint was not completed. This prevents double-counting even across crashes.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle late-arriving events in Flink?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Watermarks and allowed lateness.</strong><br><br><strong>The problem:</strong> Events arrive out of order. An event with timestamp t=14:23:45 might arrive at t=14:24:10 (25 seconds late) due to network delays. If the 30-second window for 14:23 already closed and was flushed, what do you do?<br><br><strong>Watermarks:</strong> Flink maintains a \"watermark\" \u2014 its best guess of the current event time. A watermark of t=14:24:00 means \"all events with timestamp &lt; 14:24:00 have probably arrived.\" Windows only close when the watermark passes the window end time.<br><br><strong>Allowed lateness:</strong> Even after a window closes, Flink can wait for late events up to X seconds. Late events trigger a window update (re-emit corrected results). Events arriving after the allowed lateness are either dropped or sent to a side output for separate handling.<br><br>In Top-K, we use a 5-second watermark lag \u2014 accepting that our Top-K results may be 5 seconds stale in exchange for near-complete accuracy.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why does Kafka partitioning by entity_id matter so much for Top-K?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>It eliminates cross-worker coordination \u2014 the fundamental scalability trick.</strong><br><br>If all events for video_123 go to the same Kafka partition, they're consumed by the same Flink worker. That worker maintains the local count for video_123 in its own Count-Min Sketch, entirely in local memory. No network calls needed to coordinate with other workers.<br><br>If video_123's events were spread across multiple partitions, three things would go wrong: (1) Multiple Flink workers would each have a partial count for video_123. (2) To merge them, every worker would need to communicate with every other worker after each event. (3) At 500K events/sec, this coordination traffic would overwhelm the cluster.<br><br>Partitioning by entity_id makes the problem embarrassingly parallel \u2014 each worker handles a disjoint subset of entities, does all its computation locally, and the only cross-worker step is the final merge of top-K lists at flush time.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Can you replace Kafka with a database in the streaming pipeline?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Technically yes, practically no \u2014 and interviewers will probe this.</strong><br><br>You could write events to a PostgreSQL table and have Flink poll it. This is called \"Change Data Capture\" (CDC) and it works for low-throughput pipelines. But it fails at 500K events/sec because:<br><br>1. Each INSERT is a full row write with WAL logging \u2014 massive I/O overhead at scale.<br>2. Polling introduces latency: Flink polls every X seconds, creating inherent lag.<br>3. Ordering guarantees are weak: multiple writers can write with slightly different timestamps.<br>4. Backpressure handling: if Flink falls behind, the database table grows unbounded (no TTL like Kafka retention).<br>5. Multiple consumers: each consumer needs its own polling mechanism and state tracking.<br><br>Kafka is purpose-built for this. Its log-structured storage makes sequential writes extremely fast. Consumers maintain their own offset. Backpressure is handled naturally \u2014 consumers just read slower while Kafka buffers the data within retention limits.</div>\n  </div>\n</section>\n\n</div>\n\n<section id=\"concepts-streaming\">\n  <div class=\"sec-tag\">07 \u00b7 Core Concepts Deep Dive</div>\n  <h2>Kafka internals every FAANG interviewer tests</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Consumer Group<br>Rebalancing</div><div class=\"concept-def\"><strong>When a consumer joins or leaves a group, Kafka reassigns partition ownership \u2014 this is a rebalance.</strong><br>\n      During rebalance: all consumption stops (stop-the-world). Duration: seconds to minutes for large groups. All consumers in the group coordinate via the group coordinator broker.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Frequent rebalances (pod restarts, rolling deploys) cause processing gaps. Fix: incremental cooperative rebalancing (Kafka 2.4+) \u2014 only reassigns affected partitions, others keep processing. Also: set session.timeout.ms appropriately (not too short).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Exactly-Once<br>Semantics (EOS)</div><div class=\"concept-def\"><strong>Kafka guarantees at-least-once by default. Exactly-once requires explicit configuration.</strong><br>\n      Producer side: <code>enable.idempotence=true</code> + <code>transactional.id</code>. Prevents duplicate messages on retries.<br>\n      Consumer side: <code>isolation.level=read_committed</code>. Only reads messages from committed transactions.<br>\n      Flink + Kafka: two-phase commit checkpoint. Flink checkpoints aligned with Kafka offsets \u2014 exactly-once end-to-end.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 EOS adds ~10\u201320% throughput overhead. Use for: financial event streams, inventory updates. Skip for: metrics, logs, analytics where duplicates are tolerable.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Log Compaction</div><div class=\"concept-def\"><strong>Instead of deleting old messages by time, keep only the latest value per key.</strong><br>\n      Compacted topic: Kafka runs a background compaction thread that removes old records for the same key, retaining only the most recent. Result: the topic always contains the current state of every key \u2014 like a changelog.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Used for: materialising database changelogs (Debezium \u2192 Kafka compacted topic = current DB state). New consumers can bootstrap from the compacted topic to get current state without reading the full history. Used by: Kafka Connect, ksqlDB state stores.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Backpressure in<br>Flink</div><div class=\"concept-def\"><strong>Flink propagates backpressure upstream through its credit-based flow control.</strong><br>\n      If a sink (Cassandra write) is slow \u2192 output buffer fills \u2192 upstream operators slow down \u2192 eventually the Kafka consumer slows its poll rate \u2192 Kafka consumer lag grows \u2192 natural backpressure signal.<br>\n      Monitor: Flink Web UI shows backpressure ratio per operator. High backpressure (red) = that operator is the bottleneck. Fix: increase parallelism for that operator, or optimise the slow operation.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Flink's backpressure propagation is automatic and zero-copy \u2014 no application code needed. It prevents out-of-memory failures when sinks are overwhelmed.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Watermarks &amp;<br>Late Data</div><div class=\"concept-def\"><strong>Event time vs processing time: events arrive out of order. Watermarks tell Flink when a time window is \"complete enough\" to compute.</strong><br>\n      Watermark = current_event_time - allowed_lateness. When watermark passes window end time, Flink triggers the window computation.<br>\n      Example: 1-minute tumbling window with 5-second allowed lateness. Window closes at 14:01:00. Flink waits until it sees events with timestamps \u2265 14:01:05 before computing. Events up to 5 seconds late are included.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Handles network delays and out-of-order mobile events gracefully. Later events (beyond allowed lateness) go to a side output for separate handling.</span></div></div>\n  </div>\n\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Streaming System Decision Tree</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need stateful stream processing (joins, aggregations, windows)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (stateful) \u2192</span><span class=\"opt-text\"><strong>Flink or Spark Structured Streaming.</strong> Flink: lower latency (milliseconds), better backpressure, exactly-once. Spark: better for micro-batch (seconds), familiar SQL API, better for ML pipelines. Both handle joins across streams and windows.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (simple routing/filtering) \u2192</span><span class=\"opt-text\"><strong>Kafka Streams or simple consumer app.</strong> Filter, transform, route messages without a separate processing cluster. Runs inside your application. Zero additional infrastructure.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your latency requirement?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">&lt;100ms (real-time) \u2192</span><span class=\"opt-text\"><strong>Flink in streaming mode.</strong> Processes each event as it arrives. Checkpointing every 30s for fault tolerance. State in RocksDB (on-disk) for large state or JVM heap for small state.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Seconds (near real-time) \u2192</span><span class=\"opt-text\"><strong>Spark Structured Streaming micro-batch or Flink mini-batch.</strong> Trigger every 5\u201330 seconds. More efficient for high-throughput aggregations. Better SQL support.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Minutes (batch-ish) \u2192</span><span class=\"opt-text\"><strong>Spark batch on incremental data or Flink batch mode.</strong> Read new S3 partitions every N minutes. Simplest operational model \u2014 no streaming state to manage.</span></div>\n        </div>\n      </div></div>\n    </di\n  <div class=\"concept-grid\" style=\"margin-top:16px;\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Kafka Consumer<br>Lag</div><div class=\"concept-def\"><strong>Consumer lag = the difference between the latest offset in a partition and the consumer's current offset. The most important Kafka operational metric.</strong><br>\n      Lag = 0: consumer is keeping up with producers in real time.<br>\n      Lag growing: consumer is falling behind. Causes: slow processing logic, insufficient consumer parallelism, downstream bottleneck (DB writes too slow).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">Monitor with: Kafka's consumer-groups.sh, Burrow (LinkedIn's open-source lag monitor), or CloudWatch (MSK). Alert when lag &gt; N minutes worth of events \u2014 this defines your data staleness SLO.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Flink State<br>Backends</div><div class=\"concept-def\"><strong>Flink's stateful operations (aggregations, joins, windows) store state in a configurable backend.</strong><br>\n      <strong>HashMap (in-memory)</strong>: fastest, state in JVM heap. Limited by available RAM. Use for: small state (&lt;1GB), latency-sensitive operations.<br>\n      <strong>RocksDB (on-disk)</strong>: state on local SSD, spills to disk. Handles terabytes of state. Slightly slower than HashMap. Use for: large state (user session data, 30-day aggregations).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">RocksDB is the production default for most Flink jobs. RAM is the bottleneck in streaming systems \u2014 RocksDB removes that constraint at the cost of ~2x latency (SSD read vs RAM read).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Kinesis vs Kafka</div><div class=\"concept-def\"><strong>Both are event streaming systems \u2014 the choice is almost always cloud commitment and ops budget.</strong><br>\n      <strong>Kinesis</strong>: fully managed, AWS-native, limited to 7-day retention, max 1MB/record, shard-based scaling (manual). Simple, zero ops. Best for: AWS-native orgs, moderate throughput (&lt;1GB/sec per stream).<br>\n      <strong>Kafka (MSK or self-managed)</strong>: configurable retention (unlimited), higher throughput, richer ecosystem (Kafka Connect, Kafka Streams, ksqlDB, Flink). Best for: complex streaming pipelines, multi-cloud, high throughput, need replay.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">At FAANG scale: Kafka. For simple AWS pipelines at moderate scale: Kinesis. For new systems with limited ops capacity: consider Confluent Cloud (managed Kafka without the operational burden).</span></div></div>\n  </div>\nv>\n  </div>\n</section>\n<div class=\"footer\">STREAMING \u00b7 KAFKA \u00b7 FLINK \u00b7 KINESIS \u00b7 SPARK \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Streaming' },
  protocols:   { title: 'API Protocols Decoded',           srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>API Protocols: REST vs gRPC vs GraphQL vs WebSocket vs SSE vs Long Polling</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;\n  --rest:#1a4f8a;--rest-bg:#edf2fb;\n  --grpc:#1a7a4a;--grpc-bg:#edf8f2;\n  --gql:#a0208a;--gql-bg:#faedf8;\n  --ws:#b8720a;--ws-bg:#fdf6e8;\n  --sse:#1287b1;--sse-bg:#eaf6fb;\n  --lp:#6040a0;--lp-bg:#f2eefb;\n  --red:#c0392b;--red-bg:#fdf0ee;\n  --green:#1a7a4a;--green-bg:#edf8f2;\n  --amber:#b8720a;--amber-bg:#fdf6e8;\n  --blue:#1a4f8a;--blue-bg:#edf2fb;\n  --mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;\n}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-rest{border-color:var(--rest);color:var(--rest);background:rgba(26,79,138,.08);}\n.pill-grpc{border-color:var(--grpc);color:var(--grpc);background:rgba(26,122,74,.08);}\n.pill-gql{border-color:var(--gql);color:var(--gql);background:rgba(160,32,138,.08);}\n.pill-ws{border-color:var(--ws);color:var(--ws);background:rgba(184,114,10,.08);}\n.pill-sse{border-color:var(--sse);color:var(--sse);background:rgba(18,135,177,.08);}\n.pill-lp{border-color:var(--lp);color:var(--lp);background:rgba(96,64,160,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;max-width:820px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n/* Protocol identity cards */\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.rest::before{background:var(--rest);}\n.db-card.grpc::before{background:var(--grpc);}\n.db-card.gql::before{background:var(--gql);}\n.db-card.ws::before{background:var(--ws);}\n.db-card.sse::before{background:var(--sse);}\n.db-card.lp::before{background:var(--lp);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n/* Analogy block */\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n/* Callouts */\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n/* Comparison table */\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n/* System design examples */\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:130px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n/* Badges */\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-rest{background:var(--rest-bg);border-color:var(--rest);color:var(--rest);}\n.b-grpc{background:var(--grpc-bg);border-color:var(--grpc);color:var(--grpc);}\n.b-gql{background:var(--gql-bg);border-color:var(--gql);color:var(--gql);}\n.b-ws{background:var(--ws-bg);border-color:var(--ws);color:var(--ws);}\n.b-sse{background:var(--sse-bg);border-color:var(--sse);color:var(--sse);}\n.b-lp{background:var(--lp-bg);border-color:var(--lp);color:var(--lp);}\n.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}\n.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}\n.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n/* FAQ */\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.faq-a ul{padding-left:18px;margin:8px 0;}.faq-a li{margin-bottom:6px;}\n/* Concept grid */\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n/* Step block */\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:130px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n/* Use-card grid */\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n/* Combo pattern cards */\n.combo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:20px 0;}\n.combo-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;}\n.combo-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;border-radius:8px 8px 0 0;}\n.combo-card.c1::before{background:linear-gradient(90deg,var(--rest),var(--ws));}\n.combo-card.c2::before{background:linear-gradient(90deg,var(--rest),var(--sse));}\n.combo-card.c3::before{background:linear-gradient(90deg,var(--grpc),var(--grpc));}\n.combo-card.c4::before{background:linear-gradient(90deg,var(--gql),var(--ws));}\n.combo-card.c5::before{background:linear-gradient(90deg,var(--rest),var(--lp));}\n.combo-card.c6::before{background:linear-gradient(90deg,var(--rest),var(--grpc));}\n.combo-title{font-family:var(--serif);font-size:15px;font-weight:700;margin-bottom:6px;color:var(--ink);}\n.combo-formula{font-family:var(--mono);font-size:11px;color:var(--muted);margin-bottom:12px;letter-spacing:.5px;}\n.combo-body{font-size:13px;color:#5a5848;line-height:1.65;margin-bottom:10px;}\n.combo-used{font-family:var(--mono);font-size:10px;color:var(--muted);}\n/* Footer */\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n/* Responsive */\n@media(max-width:560px){\n  .concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}\n  .opt-arrow{min-width:80px;}.choice-label{width:80px;}\n}\n</style>\n</head>\n<body>\n\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 API Design \u00b7 Manish-Almanac</div>\n    <h1>API Protocols<br><em>Decoded</em></h1>\n    <p class=\"hero-sub\">REST vs gRPC vs GraphQL vs WebSocket vs SSE vs Long Polling \u2014 every dimension that matters in a FAANG interview, explained from first principles. Includes when they complement each other, real system design examples, and every follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-rest\">REST</span>\n      <span class=\"db-pill pill-grpc\">gRPC</span>\n      <span class=\"db-pill pill-gql\">GraphQL</span>\n      <span class=\"db-pill pill-ws\">WebSocket</span>\n      <span class=\"db-pill pill-sse\">SSE</span>\n      <span class=\"db-pill pill-lp\">Long Polling</span>\n    </div>\n  </div>\n</div>\n\n<nav class=\"nav\">\n  <a href=\"#mental-model\">Mental Model</a>\n  <a href=\"#request-response\">Request-Response</a>\n  <a href=\"#realtime\">Real-Time</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#combos\">Combos</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n\n<div class=\"wrap\">\n\n<!-- \u2550\u2550 00 MENTAL MODEL \u2550\u2550 -->\n<section id=\"mental-model\">\n  <div class=\"sec-tag\">00 \u00b7 Start Here</div>\n  <h2>The mental model before memorising anything</h2>\n\n  <p>Most candidates treat REST, WebSocket, gRPC, and GraphQL as competing options. They're not \u2014 they solve <strong>different communication problems</strong>. Before picking any protocol, answer one question:</p>\n\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The single question that matters</div>\n    <p><strong>Who initiates communication, and how often does data change?</strong></p>\n    <p>Client asks once, server replies once \u2192 <strong>Request-Response</strong> (REST, gRPC, GraphQL)</p>\n    <p>Server needs to push data to client without the client asking \u2192 <strong>Server Push</strong> (SSE, WebSocket, Long Polling)</p>\n    <p>Client and server need to talk simultaneously, continuously \u2192 <strong>Bidirectional</strong> (WebSocket, gRPC streaming)</p>\n  </div>\n\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The restaurant analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      <strong>REST</strong> is a waiter who takes your order, goes to the kitchen, and comes back with exactly what you asked for. Simple, stateless, everyone knows the rules.<br><br>\n      <strong>gRPC</strong> is a waiter using a walkie-talkie with the kitchen using a shared codebook. Faster, more efficient, but both sides need the same codebook (Protobuf schema).<br><br>\n      <strong>GraphQL</strong> is a waiter who lets you design your own plate. \"I want 3 items from dish A and 2 from dish B, in one trip.\" You get exactly what you asked for \u2014 nothing more, nothing less.<br><br>\n      <strong>WebSocket</strong> is a phone call \u2014 once connected, both sides can speak at any moment without hanging up and redialling.<br><br>\n      <strong>SSE</strong> is a radio broadcast \u2014 the server talks continuously to all listeners, but listeners can't transmit back on the same channel.<br><br>\n      <strong>Long Polling</strong> is repeatedly calling the kitchen and asking \"is my order ready yet?\" \u2014 the kitchen keeps you on hold until it is, then hangs up. You immediately call back.\n    </div>\n  </div>\n\n  <h3>The Two Families</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Request-Response</div>\n      <div class=\"concept-def\"><strong>Client sends a request, server replies, connection closes.</strong> Each interaction is independent. The server has no memory of previous requests unless you send a session token.<br><span style=\"color:#5a5848;font-size:12.5px;\">Members: REST, gRPC (unary), GraphQL Query/Mutation. HTTP/1.1, HTTP/2, HTTP/3 are the transports.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Persistent / Push</div>\n      <div class=\"concept-def\"><strong>Connection stays open. Server can push data without the client asking.</strong> Crucial for real-time features: live feeds, notifications, chat, collaborative editing.<br><span style=\"color:#5a5848;font-size:12.5px;\">Members: WebSocket (bidirectional), SSE (server\u2192client only), Long Polling (simulated push), gRPC streaming.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 01 REQUEST-RESPONSE PROTOCOLS \u2550\u2550 -->\n<section id=\"request-response\">\n  <div class=\"sec-tag\">01 \u00b7 Request-Response Family</div>\n  <h2>REST, gRPC, and GraphQL \u2014 the three ways to ask</h2>\n\n  <div class=\"db-grid\">\n    <div class=\"db-card rest\">\n      <div class=\"db-logo\">\ud83c\udf10</div>\n      <div class=\"db-name\">REST</div>\n      <div class=\"db-type\">HTTP \u00b7 Stateless \u00b7 Resource-Oriented</div>\n      <div class=\"db-tagline\">The universal default. Every HTTP client speaks it. Resources are nouns (URLs), actions are verbs (GET/POST/PUT/DELETE). No special tooling needed. The right choice until it isn't.</div>\n      <div class=\"db-born\">Born 2000 \u00b7 Roy Fielding's PhD thesis \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n    <div class=\"db-card grpc\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">gRPC</div>\n      <div class=\"db-type\">HTTP/2 \u00b7 Binary \u00b7 Contract-First</div>\n      <div class=\"db-tagline\">Google's internal RPC framework. Define your API in a .proto file \u2014 both sides generate code from it. Binary encoding (Protobuf) makes it 5\u201310x smaller and faster than JSON REST. Built for internal service-to-service calls.</div>\n      <div class=\"db-born\">Born 2015 \u00b7 Google \u00b7 HTTP/2 + Protobuf</div>\n    </div>\n    <div class=\"db-card gql\">\n      <div class=\"db-logo\">\u25c8</div>\n      <div class=\"db-name\">GraphQL</div>\n      <div class=\"db-type\">HTTP \u00b7 Query Language \u00b7 Client-Driven</div>\n      <div class=\"db-tagline\">Facebook's answer to REST's over-fetching problem. The client describes exactly what data it needs in a typed query. One endpoint, infinite flexibility. Ideal when different clients (mobile/web/partner) need different shapes of the same data.</div>\n      <div class=\"db-born\">Born 2015 \u00b7 Facebook \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n  </div>\n\n  <h3>REST \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Resources & Verbs</div>\n      <div class=\"concept-def\"><strong>REST maps actions to HTTP methods and nouns to URLs.</strong><br>\n        <code>GET /users/123</code> \u2192 fetch user<br>\n        <code>POST /users</code> \u2192 create user<br>\n        <code>PUT /users/123</code> \u2192 replace user<br>\n        <code>PATCH /users/123</code> \u2192 partial update<br>\n        <code>DELETE /users/123</code> \u2192 delete user<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">The URL is the resource (noun). The HTTP method is the action (verb). This separation is REST's core design principle.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Stateless</div>\n      <div class=\"concept-def\"><strong>Every request must contain everything the server needs to process it.</strong> The server stores no session between requests. Identity always comes from a token in the header \u2014 never assumed from context.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Statelessness makes REST trivially horizontally scalable \u2014 any server can handle any request. No sticky sessions needed.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP Caching</div>\n      <div class=\"concept-def\"><strong>GET requests are cacheable by default</strong> \u2014 CDNs, browsers, and proxies can cache them. This is one of REST's biggest advantages over gRPC and GraphQL.<br><code>Cache-Control: max-age=3600</code> tells every layer to cache for 1 hour.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A public REST API with GET responses cached at Cloudflare reduces origin traffic by 95%+. gRPC and GraphQL cannot use HTTP caching natively.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Status Codes</div>\n      <div class=\"concept-def\"><strong>HTTP status codes carry semantic meaning every client understands natively:</strong><br>\n        <code>200</code> OK \u00b7 <code>201</code> Created \u00b7 <code>204</code> No Content<br>\n        <code>400</code> Bad Request \u00b7 <code>401</code> Unauthorised \u00b7 <code>403</code> Forbidden \u00b7 <code>404</code> Not Found<br>\n        <code>429</code> Rate Limited \u00b7 <code>500</code> Server Error \u00b7 <code>503</code> Unavailable<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Every HTTP client, load balancer, and monitoring tool understands these codes. GraphQL always returns 200 \u2014 errors are in the response body, invisible to infrastructure.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Over-Fetching</div>\n      <div class=\"concept-def\"><strong>REST's biggest weakness: you get what the endpoint returns, not what you need.</strong><br><code>GET /users/123</code> returns all 40 fields. Your mobile app only needed name and avatar.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f On mobile with limited bandwidth, over-fetching wastes data and slows rendering. This is exactly why Facebook invented GraphQL.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Under-Fetching</div>\n      <div class=\"concept-def\"><strong>REST's second weakness: one endpoint rarely returns all the data you need.</strong><br>To show a user's profile with their posts and followers: <code>GET /users/123</code> + <code>GET /users/123/posts</code> + <code>GET /users/123/followers</code> \u2014 3 round trips.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f On mobile, each extra round trip adds 50\u2013200ms. Waterfall requests add up fast. GraphQL solves this with a single query.</span></div>\n    </div>\n  </div>\n\n  <h3>gRPC \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Protocol Buffers</div>\n      <div class=\"concept-def\"><strong>gRPC uses Protobuf \u2014 a binary serialisation format \u2014 instead of JSON.</strong> You define your data schema in a <code>.proto</code> file. Both client and server generate code from it automatically.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Binary is 5\u201310x smaller than equivalent JSON. Parsing binary is 5\u201310x faster than parsing JSON text. At 1M requests/sec, this matters enormously.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP/2 Multiplexing</div>\n      <div class=\"concept-def\"><strong>gRPC runs on HTTP/2, which multiplexes multiple requests over a single TCP connection.</strong> With HTTP/1.1 REST, each request needs its own connection (or connection pooling). HTTP/2 sends hundreds of requests simultaneously over one connection.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Huge advantage for service-to-service calls where you're making thousands of RPCs per second between the same two services.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Streaming Modes</div>\n      <div class=\"concept-def\"><strong>gRPC supports 4 modes \u2014 REST only supports request-response:</strong><br>\n        <strong>Unary</strong> \u2014 one request, one response (like REST)<br>\n        <strong>Server streaming</strong> \u2014 one request, stream of responses (like SSE)<br>\n        <strong>Client streaming</strong> \u2014 stream of requests, one response (uploading chunks)<br>\n        <strong>Bidirectional streaming</strong> \u2014 both sides stream simultaneously (like WebSocket)<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Real example: Google Maps sends your location as a client stream, receives route updates as a server stream \u2014 all over one gRPC bidirectional connection.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Schema Contract</div>\n      <div class=\"concept-def\"><strong>The .proto file is a strict API contract between client and server.</strong> Both sides must use the same schema. Adding a field is backwards-compatible; removing one breaks older clients.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f gRPC requires code generation on every schema change. REST and GraphQL don't. This is operational overhead \u2014 significant for teams with many services.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Browser Support</div>\n      <div class=\"concept-def\"><strong>Browsers cannot call gRPC directly.</strong> HTTP/2 trailers (which gRPC uses) are not exposed by browser APIs. You need gRPC-Web (a proxy layer) or gRPC-Gateway (which translates to REST).<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f This is why gRPC is almost exclusively used for internal service-to-service communication, not for public-facing APIs.</span></div>\n    </div>\n  </div>\n\n  <h3>GraphQL \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Single Endpoint</div>\n      <div class=\"concept-def\"><strong>GraphQL has one endpoint: <code>POST /graphql</code>.</strong> The query in the request body describes exactly what data to return. No URL routing, no versioning headaches \u2014 the schema evolves by adding fields (never removing).<br><span style=\"color:#5a5848;font-size:12.5px;\">This is how Facebook, GitHub, Shopify, and Twitter serve data to their apps \u2014 one endpoint, infinite flexibility.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Query vs Mutation</div>\n      <div class=\"concept-def\"><strong>Query</strong> = read (like GET). <strong>Mutation</strong> = write (like POST/PUT/DELETE). <strong>Subscription</strong> = real-time push (like WebSocket).<br>\n        <code>query { user(id:\"123\") { name, avatar, followerCount } }</code><br>\n        <code>mutation { createPost(input:{...}) { id, createdAt } }</code><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Subscriptions use WebSocket under the hood \u2014 GraphQL is a query language on top of a transport, not a transport itself.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">N+1 Problem</div>\n      <div class=\"concept-def\"><strong>GraphQL's biggest pitfall: a single query can trigger hundreds of database calls.</strong><br>Query for 100 posts, each needing its author \u2192 1 query for posts + 100 queries for authors = 101 DB calls.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Fix: DataLoader (batches and deduplicates database calls). Every GraphQL implementation needs it or performance degrades to unusable.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Introspection</div>\n      <div class=\"concept-def\"><strong>GraphQL APIs are self-documenting.</strong> Clients can query the schema itself to discover all available types, fields, and operations \u2014 no separate Swagger/OpenAPI needed.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Tools like GraphiQL and Apollo Studio give developers interactive playgrounds. New team members explore the API without reading docs.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Disable introspection in production \u2014 it exposes your entire data model to attackers.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Caching Problem</div>\n      <div class=\"concept-def\"><strong>GraphQL uses POST for queries \u2014 HTTP caching doesn't work natively.</strong> CDNs only cache GET requests. Every GraphQL query hits your origin.<br><span style=\"color:#5a5848;font-size:12.5px;\">Workarounds: Persisted Queries (assign each query a hash, send hash as GET), Apollo CDN caching, or Cloudflare Workers. More complexity than REST's built-in GET caching.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 02 REAL-TIME PROTOCOLS \u2550\u2550 -->\n<section id=\"realtime\">\n  <div class=\"sec-tag\">02 \u00b7 Real-Time Family</div>\n  <h2>WebSocket, SSE, and Long Polling \u2014 the three ways to push</h2>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">Why REST can't do real-time</div>\n    <p>REST is pull-only: <strong>the client must ask</strong> before the server can respond. For a chat app, polling every second means thousands of empty responses. For a live dashboard, you'd poll 60 times/minute per user. At 100K users, that's 6M requests/minute for mostly empty data.</p>\n    <p><strong>Real-time protocols invert this: the server pushes data the moment it's available.</strong> No polling, no wasted requests, no latency from the polling interval.</p>\n  </div>\n\n  <div class=\"db-grid\">\n    <div class=\"db-card ws\">\n      <div class=\"db-logo\">\ud83d\udd0c</div>\n      <div class=\"db-name\">WebSocket</div>\n      <div class=\"db-type\">Full-Duplex \u00b7 Persistent \u00b7 TCP</div>\n      <div class=\"db-tagline\">A persistent bidirectional connection over a single TCP socket. Once the HTTP handshake upgrades to WS, both client and server can send messages at any time, simultaneously. The gold standard for true real-time: chat, multiplayer games, collaborative editing.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 RFC 6455 \u00b7 HTTP Upgrade handshake</div>\n    </div>\n    <div class=\"db-card sse\">\n      <div class=\"db-logo\">\ud83d\udce1</div>\n      <div class=\"db-name\">Server-Sent Events</div>\n      <div class=\"db-type\">Server\u2192Client Only \u00b7 HTTP \u00b7 Auto-Reconnect</div>\n      <div class=\"db-tagline\">A simple HTTP connection that stays open. The server pushes text events whenever it wants. The client cannot send data back on this connection. Simpler than WebSocket, works with HTTP/2 multiplexing, and auto-reconnects on disconnect.</div>\n      <div class=\"db-born\">Born 2006 \u00b7 W3C Standard \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n    <div class=\"db-card lp\">\n      <div class=\"db-logo\">\ud83d\udd04</div>\n      <div class=\"db-name\">Long Polling</div>\n      <div class=\"db-type\">Simulated Push \u00b7 HTTP \u00b7 Request-Response</div>\n      <div class=\"db-tagline\">Client sends a request. Server holds it open until data is available or a timeout occurs. Client immediately sends a new request. Simulates real-time over plain HTTP \u2014 no special protocol needed. The legacy fallback when WebSocket isn't available.</div>\n      <div class=\"db-born\">Born ~2000s \u00b7 No official standard \u00b7 Plain HTTP</div>\n    </div>\n  </div>\n\n  <h3>WebSocket \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Upgrade Handshake</div>\n      <div class=\"concept-def\"><strong>WebSocket starts as an HTTP request, then upgrades to a persistent TCP connection.</strong><br>\n        Client sends: <code>GET /ws HTTP/1.1, Upgrade: websocket</code><br>\n        Server responds: <code>101 Switching Protocols</code><br>\n        Now: raw TCP frames flow in both directions \u2014 no HTTP overhead per message.<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Why HTTP start? Firewalls and proxies block arbitrary TCP but allow HTTP port 80/443. The upgrade trick bypasses firewall restrictions.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Full-Duplex</div>\n      <div class=\"concept-def\"><strong>Both client and server can send messages at any moment, simultaneously, over the same connection.</strong> No waiting for the other side. No request-response cycle.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This is why WebSocket is used for chat (user sends and receives simultaneously), multiplayer games (constant position updates both directions), and collaborative editing (every keystroke sent immediately).</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Framing</div>\n      <div class=\"concept-def\"><strong>WebSocket sends data as frames, not HTTP requests.</strong> Each frame has a tiny 2\u201310 byte header (opcode, mask, length) vs HTTP's 200\u2013800 byte headers per request.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A chat message sent via WebSocket costs ~10 bytes overhead. Via HTTP polling: 300\u2013800 bytes of headers per poll even when empty. At 1M active users, this difference is measured in gigabits per second.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">State & Scaling</div>\n      <div class=\"concept-def\"><strong>WebSocket connections are stateful and sticky \u2014 the connection lives on a specific server.</strong> If that server dies, all its connections drop. Clients must reconnect.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f You cannot load-balance WebSocket with standard round-robin. You need sticky sessions (by user_id) or a pub/sub broker (Redis, Kafka) so any server can push to any user regardless of which server they're connected to.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Heartbeats</div>\n      <div class=\"concept-def\"><strong>Idle WebSocket connections get killed by proxies and NAT gateways after 30\u201390 seconds.</strong> Solution: ping/pong heartbeat every 20\u201330 seconds. Server sends a ping frame, client echoes a pong. No pong = connection dead, clean up and notify.<br><span style=\"color:#5a5848;font-size:12.5px;\">Every production WebSocket implementation needs heartbeat logic. Without it, you get ghost connections \u2014 the server thinks the client is connected but the client is gone.</span></div>\n    </div>\n  </div>\n\n  <h3>SSE \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Wire Format</div>\n      <div class=\"concept-def\"><strong>SSE is a plain HTTP response that never ends.</strong> Content-Type is <code>text/event-stream</code>. The server sends newline-delimited text events:<br>\n        <code>data: {\"type\":\"view\",\"count\":1247}\\n\\n</code><br>\n        <code>data: {\"type\":\"view\",\"count\":1248}\\n\\n</code><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Two consecutive newlines signal the end of one event. The browser's EventSource API parses this automatically and fires events at your JavaScript handler.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Auto-Reconnect</div>\n      <div class=\"concept-def\"><strong>The browser's EventSource automatically reconnects after a disconnect.</strong> The server sends an event ID with each event. On reconnect, the browser sends <code>Last-Event-ID</code> header \u2014 the server can replay missed events.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This makes SSE dramatically simpler to operate than WebSocket. No custom reconnect logic needed on the client. Works out of the box.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP/2 Multiplexing</div>\n      <div class=\"concept-def\"><strong>Over HTTP/2, multiple SSE streams share one TCP connection.</strong> With HTTP/1.1, browsers limit connections per domain (typically 6). If you have 6 SSE streams, you've used all connections. HTTP/2 multiplexes hundreds over one connection.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Use HTTP/2 for SSE at scale. HTTP/1.1 SSE has a hard limit of ~6 concurrent streams per browser per domain.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">One Direction Only</div>\n      <div class=\"concept-def\"><strong>SSE is server-to-client only.</strong> The client cannot send data back on the same connection. For any client action (user sends a message, acknowledges a notification), you make a separate REST/HTTP POST call.<br><span style=\"color:#5a5848;font-size:12.5px;\">This is the key difference from WebSocket. In most notification/feed systems this is fine \u2014 client-to-server actions are already REST calls.</span></div>\n    </div>\n  </div>\n\n  <h3>Long Polling \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Mechanism</div>\n      <div class=\"concept-def\"><strong>Step by step:</strong><br>\n        1. Client sends <code>GET /messages?since=1234</code><br>\n        2. Server checks if new messages exist. If yes \u2192 respond immediately. If no \u2192 <strong>hold the connection open</strong><br>\n        3. When a message arrives, server responds with it<br>\n        4. Client receives response, <strong>immediately sends a new request</strong><br>\n        5. Repeat forever<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Timeout: if no data after 30 seconds, server responds with 204 No Content. Client retries. This prevents proxy timeouts.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">vs Regular Polling</div>\n      <div class=\"concept-def\"><strong>Regular polling</strong>: client asks every N seconds regardless. Empty responses waste bandwidth and add N seconds of latency.<br><strong>Long polling</strong>: client asks once, server responds only when there's data. Near-zero latency, zero empty responses.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Long polling is near-real-time with standard HTTP. No WebSocket, no special protocol. Works everywhere HTTP works.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Scalability Challenge</div>\n      <div class=\"concept-def\"><strong>Long polling holds server threads/connections open while waiting.</strong> With 100K concurrent users each holding a long poll connection, you need 100K open connections on your servers \u2014 consuming file descriptors and memory even when idle.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Mitigate with async event loops (Node.js, Go goroutines, Nginx) that handle thousands of open connections on a single thread. Traditional thread-per-request servers (Java/Rails) cannot scale long polling.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">When Still Used</div>\n      <div class=\"concept-def\"><strong>Long polling is the fallback when WebSocket is unavailable</strong> (corporate firewalls blocking WS) or for systems where you need guaranteed delivery with replay.<br><span style=\"color:#5a5848;font-size:12.5px;\">Real usage: Slack originally used long polling before WebSocket. Some mobile apps in restricted networks still use it. XMPP Bosh protocol is long polling. Most modern systems use WebSocket or SSE instead.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 03 FULL COMPARISON \u2550\u2550 -->\n<section id=\"comparison\">\n  <div class=\"sec-tag\">03 \u00b7 Side by Side</div>\n  <h2>Every dimension that matters in an interview</h2>\n\n  <table class=\"comp-table\">\n    <thead>\n      <tr>\n        <th>Dimension</th>\n        <th>REST \ud83c\udf10</th>\n        <th>gRPC \u26a1</th>\n        <th>GraphQL \u25c8</th>\n        <th>WebSocket \ud83d\udd0c</th>\n        <th>SSE \ud83d\udce1</th>\n        <th>Long Poll \ud83d\udd04</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td class=\"row-head\">Communication</td>\n        <td>Request-Response</td>\n        <td>RPC + Streaming</td>\n        <td>Request-Response</td>\n        <td>Bidirectional</td>\n        <td>Server\u2192Client</td>\n        <td>Simulated Push</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Transport</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>HTTP/2 only</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>TCP (after upgrade)</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>HTTP/1.1, HTTP/2</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Data Format</td>\n        <td>JSON, XML, anything</td>\n        <td>Protobuf (binary)</td>\n        <td>JSON</td>\n        <td>Any (text or binary)</td>\n        <td>Text (UTF-8)</td>\n        <td>JSON, anything</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Latency</td>\n        <td><span class=\"warn\">1 RTT per request</span></td>\n        <td><span class=\"good\">~1 RTT, multiplexed</span></td>\n        <td><span class=\"warn\">1 RTT per query</span></td>\n        <td><span class=\"good\">Sub-ms after connect</span></td>\n        <td><span class=\"good\">Sub-ms after connect</span></td>\n        <td><span class=\"warn\">~1 RTT when data ready</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Payload Size</td>\n        <td><span class=\"warn\">Large (JSON + HTTP headers)</span></td>\n        <td><span class=\"good\">5\u201310x smaller than REST</span></td>\n        <td><span class=\"warn\">Similar to REST</span></td>\n        <td><span class=\"good\">Tiny frame headers</span></td>\n        <td><span class=\"good\">Small (text events)</span></td>\n        <td><span class=\"warn\">HTTP headers per request</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">HTTP Caching</td>\n        <td><span class=\"good\">Full support (GET)</span></td>\n        <td><span class=\"bad\">None</span></td>\n        <td><span class=\"bad\">None natively</span></td>\n        <td><span class=\"bad\">None</span></td>\n        <td><span class=\"warn\">Limited</span></td>\n        <td><span class=\"bad\">None effectively</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Browser Support</td>\n        <td><span class=\"good\">Universal</span></td>\n        <td><span class=\"bad\">Needs gRPC-Web proxy</span></td>\n        <td><span class=\"good\">Universal (HTTP)</span></td>\n        <td><span class=\"good\">All modern browsers</span></td>\n        <td><span class=\"good\">All modern browsers</span></td>\n        <td><span class=\"good\">Universal</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Stateful?</td>\n        <td><span class=\"good\">Stateless</span></td>\n        <td><span class=\"warn\">Stream is stateful</span></td>\n        <td><span class=\"good\">Stateless (queries)</span></td>\n        <td><span class=\"bad\">Stateful connection</span></td>\n        <td><span class=\"bad\">Stateful connection</span></td>\n        <td><span class=\"warn\">Quasi-stateful</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Load Balancing</td>\n        <td><span class=\"good\">Trivial</span></td>\n        <td><span class=\"good\">L7 with gRPC-aware LB</span></td>\n        <td><span class=\"good\">Trivial</span></td>\n        <td><span class=\"bad\">Sticky sessions needed</span></td>\n        <td><span class=\"bad\">Sticky sessions needed</span></td>\n        <td><span class=\"warn\">Manageable</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Schema / Contract</td>\n        <td><span class=\"warn\">Optional (OpenAPI)</span></td>\n        <td><span class=\"good\">Mandatory .proto</span></td>\n        <td><span class=\"good\">Typed schema</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Tooling / Ecosystem</td>\n        <td><span class=\"good\">Massive</span></td>\n        <td><span class=\"warn\">Good, growing</span></td>\n        <td><span class=\"good\">Rich (Apollo, Relay)</span></td>\n        <td><span class=\"warn\">Good</span></td>\n        <td><span class=\"warn\">Lightweight</span></td>\n        <td><span class=\"warn\">Basic</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Best For</td>\n        <td>Public APIs, CRUD</td>\n        <td>Internal services</td>\n        <td>Multi-client APIs</td>\n        <td>Chat, games, collab</td>\n        <td>Feeds, notifications</td>\n        <td>Legacy/fallback</td>\n      </tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- \u2550\u2550 04 COMBOS \u2550\u2550 -->\n<section id=\"combos\">\n  <div class=\"sec-tag\">04 \u00b7 Where They Complement Each Other</div>\n  <h2>Protocols that work together \u2014 not against each other</h2>\n\n  <p>The biggest interview insight: <strong>real systems use multiple protocols simultaneously</strong>. The request-response and real-time families solve different problems and are designed to be combined. Here are the six most common patterns you'll see and need to justify in interviews.</p>\n\n  <div class=\"combo-grid\">\n\n    <div class=\"combo-card c1\">\n      <div class=\"combo-title\">REST + WebSocket</div>\n      <div class=\"combo-formula\">REST for actions \u00b7 WebSocket for events</div>\n      <div class=\"combo-body\">REST handles all mutations (send message, create post, update status). WebSocket delivers the real-time events (new message received, presence change, typing indicator). The REST call triggers the server-side change; WebSocket broadcasts the result to affected users.</div>\n      <div class=\"combo-used\">Used by: Slack, Discord, WhatsApp Web, Notion</div>\n    </div>\n\n    <div class=\"combo-card c2\">\n      <div class=\"combo-title\">REST + SSE</div>\n      <div class=\"combo-formula\">REST for writes \u00b7 SSE for live updates</div>\n      <div class=\"combo-body\">User submits actions via REST (POST /start-analysis). Server acknowledges immediately with a job ID. SSE stream delivers progress updates as the job runs. Simpler than WebSocket because the client never needs to send mid-stream. Classic for progress bars, live dashboards, AI streaming responses.</div>\n      <div class=\"combo-used\">Used by: GitHub Actions, Vercel deployments, OpenAI API (streaming tokens), monitoring dashboards</div>\n    </div>\n\n    <div class=\"combo-card c3\">\n      <div class=\"combo-title\">REST (external) + gRPC (internal)</div>\n      <div class=\"combo-formula\">REST at the edge \u00b7 gRPC between services</div>\n      <div class=\"combo-body\">Public API exposed as REST \u2014 universal browser support, HTTP caching, familiar to all clients. Internal microservice calls use gRPC \u2014 5\u201310x smaller payloads, strict typed contracts, HTTP/2 multiplexing. An API Gateway (like Envoy or Kong) translates REST\u2192gRPC at the boundary.</div>\n      <div class=\"combo-used\">Used by: Google, Uber, Netflix, most FAANG internal architectures</div>\n    </div>\n\n    <div class=\"combo-card c4\">\n      <div class=\"combo-title\">GraphQL + WebSocket</div>\n      <div class=\"combo-formula\">GraphQL Queries/Mutations + GraphQL Subscriptions</div>\n      <div class=\"combo-body\">GraphQL queries and mutations travel over HTTP for reads and writes. GraphQL Subscriptions use WebSocket under the hood for real-time updates. One unified schema \u2014 the client uses the same GraphQL types and vocabulary for both. Apollo Client handles both transports automatically.</div>\n      <div class=\"combo-used\">Used by: GitHub (GraphQL API + subscriptions), Hasura, Shopify Storefront API</div>\n    </div>\n\n    <div class=\"combo-card c5\">\n      <div class=\"combo-title\">REST + Long Polling (legacy)</div>\n      <div class=\"combo-formula\">REST everywhere \u00b7 Long polling as fallback</div>\n      <div class=\"combo-body\">When WebSocket or SSE is blocked by corporate firewalls or unsupported by old clients, long polling bridges the gap. Standard REST for all actions; long polling for the notification channel. Socket.io does exactly this \u2014 it tries WebSocket first, falls back to long polling automatically.</div>\n      <div class=\"combo-used\">Used by: Socket.io fallback, legacy enterprise apps, restricted network environments</div>\n    </div>\n\n    <div class=\"combo-card c6\">\n      <div class=\"combo-title\">gRPC Bidirectional Streaming</div>\n      <div class=\"combo-formula\">One protocol, four modes</div>\n      <div class=\"combo-body\">For pure service-to-service real-time, gRPC bidirectional streaming replaces both REST and WebSocket. Both sides stream simultaneously over a single HTTP/2 connection. Used for location tracking (client streams GPS, server streams route), audio/video processing, real-time ML inference pipelines.</div>\n      <div class=\"combo-used\">Used by: Google Maps, real-time ML pipelines, internal FAANG service meshes</div>\n    </div>\n\n  </div>\n\n  <div class=\"callout cl-green\">\n    <div class=\"cl-lbl\">The Interview Sound Bite</div>\n    <p><strong>\"In most production systems I would use REST for the request-response layer and pair it with either SSE or WebSocket for the real-time layer \u2014 depending on whether the client needs to send data back on the same connection. REST handles mutations; the real-time channel delivers server-initiated events. gRPC replaces REST for internal service-to-service calls where latency and throughput matter.\"</strong></p>\n  </div>\n</section>\n\n<!-- \u2550\u2550 05 SYSTEM DESIGN EXAMPLES \u2550\u2550 -->\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 Applied to Real Systems</div>\n  <h2>Which protocol wins in which system?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Chat App (Slack / WhatsApp)</div>\n      <span class=\"sd-example-tag\">BIDIRECTIONAL \u00b7 REAL-TIME</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">SEND MESSAGE</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> <code>POST /messages</code> \u2014 client sends message, server persists it, returns message ID + timestamp. REST because: idempotency key prevents duplicates on retry, HTTP status codes signal delivery failure clearly, easy to rate-limit with standard middleware.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">RECEIVE MESSAGES</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Server pushes new messages to all room members the moment they arrive. Bidirectional needed: client also sends typing indicators and read receipts back on the same connection. Sub-10ms delivery vs 1\u20135 second polling lag.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">PRESENCE / TYPING</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> \"Alice is typing\u2026\" \u2014 client sends typing events over the WebSocket every keystroke. Server fans out to all members via pub/sub (Redis). Low-overhead frames, no HTTP headers per event.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INTERNAL SERVICES</div>\n        <div class=\"choice-val\"><span class=\"badge b-grpc\">gRPC \u2713</span> Message Service \u2192 Notification Service \u2192 Presence Service: all internal. Protobuf contracts prevent schema drift. HTTP/2 multiplexing handles thousands of RPCs/sec between services without connection explosion.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT ALL WS</div>\n        <div class=\"choice-val\"><span class=\"badge b-a\">Tradeoff \u26a0</span> WebSocket for everything seems elegant but: WS mutations can't use HTTP caching, rate limiting is harder, retry logic needs custom implementation, and load balancing requires sticky sessions. REST for writes + WS for events is the industry standard split.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending Dashboard (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">SERVER PUSH \u00b7 READ-HEAVY</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">LIVE RANKINGS</div>\n        <div class=\"choice-val\"><span class=\"badge b-sse\">SSE \u2713</span> Dashboard shows top 10 videos updating every 30 seconds. SSE stream pushes updates from Flink flush events. Client never sends data back \u2014 perfect SSE fit. Auto-reconnect handles network hiccups transparently. HTTP/2 multiplexes thousands of concurrent dashboard viewers.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INITIAL DATA LOAD</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> <code>GET /top-k?window=1h&region=IN</code> loads the initial ranked list. Cacheable at CDN edge (60s TTL). 95% of requests served from cache \u2014 SSE stream only delivers delta updates after the initial load.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT WEBSOCKET</div>\n        <div class=\"choice-val\"><span class=\"badge b-a\">Overkill \u26a0</span> The dashboard is read-only \u2014 users never push data back. WebSocket's bidirectional capability is wasted. SSE is simpler: no handshake upgrade, works through HTTP/2 proxies without special configuration, auto-reconnects, and uses standard HTTP connections that load balancers understand natively.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT POLLING</div>\n        <div class=\"choice-val\"><span class=\"badge b-r\">Inefficient \u2717</span> At 30s poll interval and 100K concurrent users: 100K requests every 30s = 3,333 requests/sec, most returning the same data. SSE uses a persistent connection per user \u2014 0 requests until data changes. Orders of magnitude less origin traffic.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Mobile App API (Instagram / Uber)</div>\n      <span class=\"sd-example-tag\">MULTI-CLIENT \u00b7 BANDWIDTH-SENSITIVE</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WEB APP API</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Desktop browser with good connectivity. REST with HTTP/2 is fast, cacheable, and familiar. No over-fetching problem at this scale \u2014 one REST response per screen is acceptable.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">MOBILE APP API</div>\n        <div class=\"choice-val\"><span class=\"badge b-gql\">GraphQL \u2713</span> Mobile on 4G/5G with limited bandwidth. GraphQL lets the app fetch exactly the fields it needs \u2014 no wasted data. One query fetches feed + stories + story counts instead of 3 REST calls. Instagram's move to GraphQL reduced API response sizes by 30\u201350%.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">PARTNER API</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Third-party developer integrations use REST. Universal support, simple to understand, extensive documentation. GraphQL's flexibility is a liability here \u2014 partners need a stable, versioned contract, not an evolving schema.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">DRIVER LOCATION (Uber)</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Driver app streams GPS location every 2 seconds. Rider app receives driver position updates in real-time. Both directions active simultaneously \u2014 classic WebSocket scenario. gRPC bidirectional streaming works equally well for this internal use case.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Notification System (Apple Push / Firebase)</div>\n      <span class=\"sd-example-tag\">FAN-OUT \u00b7 MOBILE PUSH</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WEB NOTIFICATIONS</div>\n        <div class=\"choice-val\"><span class=\"badge b-sse\">SSE \u2713</span> Browser tab receives notifications via SSE stream. User doesn't send acknowledgements in the same connection \u2014 REST POST for \"mark as read\". Simple, reconnects automatically, works with HTTP/2.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">MOBILE PUSH</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Your server calls APNs (Apple) or FCM (Firebase) REST APIs to push notifications to iOS/Android. The OS maintains its own persistent connection to Apple/Google \u2014 you just trigger it via REST. Your app never holds a WebSocket open in the background.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INTERNAL FAN-OUT</div>\n        <div class=\"choice-val\"><span class=\"badge b-grpc\">gRPC \u2713</span> Notification Service fans out to User Service, Device Service, and APNs Gateway all via gRPC. Hundreds of millions of notifications/day means every millisecond and byte of payload overhead compounds. Protobuf binary encoding + HTTP/2 multiplexing handles the load.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Collaborative Editing (Google Docs / Notion)</div>\n      <span class=\"sd-example-tag\">CRDT \u00b7 REAL-TIME \u00b7 MULTI-USER</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">EDITS</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Every keystroke is an operation (insert/delete + position). Operations are sent over WebSocket immediately. Server applies OT (Operational Transformation) or CRDT to merge concurrent edits from multiple users. The merged result is broadcast back to all connected users via the same WebSocket.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">CURSOR POSITIONS</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> \"Alice is editing paragraph 3\" \u2014 cursor broadcast via WebSocket at ~10 events/sec. Ephemeral \u2014 not persisted. WebSocket's low per-frame overhead makes this affordable even for documents with 50 simultaneous editors.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">DOCUMENT SAVE</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Periodic snapshot of document state sent via REST POST. Idempotent, retryable, separate from the real-time stream. REST for durability; WebSocket for real-time sync.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 06 DECISION TREE \u2550\u2550 -->\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 The Decision Framework</div>\n  <h2>How to pick in an interview \u2014 in 60 seconds</h2>\n\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Protocol Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the server need to push data to the client without the client asking?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\">You need a real-time protocol. Go to Step 2. REST alone cannot solve this.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Request-Response is sufficient. Go to Step 4 to pick between REST, gRPC, and GraphQL.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the client also need to send data back on the same real-time connection?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>WebSocket.</strong> Chat messages, cursor positions, game inputs, collaborative edits \u2014 bidirectional continuous communication. Pair with REST for mutations that need HTTP semantics (retries, idempotency).</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>SSE</strong> (preferred) or <strong>Long Polling</strong> (fallback). Live feeds, notifications, progress bars, dashboards \u2014 server pushes, client only reads. SSE is simpler and HTTP/2-native. Long Polling if SSE is unavailable.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this for browser clients or internal service-to-service?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Browser \u2192</span><span class=\"opt-text\"><strong>WebSocket or SSE.</strong> Both have native browser APIs (WebSocket API, EventSource API). No proxy needed.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Service-to-Service \u2192</span><span class=\"opt-text\"><strong>gRPC bidirectional streaming</strong> \u2014 all the benefits of gRPC (binary, typed, multiplexed) plus both sides can stream. Google Maps, real-time ML inference pipelines.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this a public API, internal service, or multi-client API?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Public API \u2192</span><span class=\"opt-text\"><strong>REST.</strong> Universal support, HTTP caching, familiar to all developers, simple to rate limit and monitor. Default until you have a specific reason to deviate.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Internal services \u2192</span><span class=\"opt-text\"><strong>gRPC.</strong> Binary Protobuf (5\u201310x smaller), HTTP/2 multiplexing, strict typed contracts. Ideal for service meshes where latency and throughput compound across hundreds of microservices.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Multi-client (web + mobile + partners) \u2192</span><span class=\"opt-text\"><strong>GraphQL.</strong> Different clients need different data shapes. One schema, client-driven queries, no over-fetching on mobile bandwidth. Requires DataLoader to avoid N+1.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you have strict performance or bandwidth requirements?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Performance critical \u2192</span><span class=\"opt-text\"><strong>gRPC over REST</strong> for service-to-service. Binary vs JSON: 5\u201310x payload reduction. At 1M RPC/sec between services, the difference is measurable in infra costs and latency percentiles.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Standard requirements \u2192</span><span class=\"opt-text\"><strong>REST is fine.</strong> With HTTP/2 and proper JSON compression (gzip/brotli), REST performance is excellent for the vast majority of systems. Don't optimise prematurely.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <h3>The Rules You Must Know</h3>\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--rest)\">\ud83c\udf10 Always use REST when\u2026</div>\n      <ul>\n        <li>Building a public-facing API</li>\n        <li>Need HTTP caching (GET responses)</li>\n        <li>Clients are diverse (browsers, mobile, partners)</li>\n        <li>Team is small, simplicity matters</li>\n        <li>CRUD operations with standard semantics</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--grpc)\">\u26a1 Always use gRPC when\u2026</div>\n      <ul>\n        <li>Service-to-service internal calls</li>\n        <li>High-throughput, latency-sensitive RPCs</li>\n        <li>Need strong schema contract between teams</li>\n        <li>Polyglot microservices (code gen handles language)</li>\n        <li>Streaming between services (bidirectional)</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--gql)\">\u25c8 Always use GraphQL when\u2026</div>\n      <ul>\n        <li>Multiple client types with different data needs</li>\n        <li>Mobile bandwidth is constrained</li>\n        <li>Rapidly evolving product with frequent data shape changes</li>\n        <li>BFF (Backend-for-Frontend) pattern</li>\n        <li>Developer experience is a priority</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--ws)\">\ud83d\udd0c Always use WebSocket when\u2026</div>\n      <ul>\n        <li>Chat or messaging (bidirectional)</li>\n        <li>Multiplayer games or real-time collaboration</li>\n        <li>Both client AND server need to push continuously</li>\n        <li>Sub-100ms latency for every event</li>\n        <li>Persistent session with many small messages</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--sse)\">\ud83d\udce1 Always use SSE when\u2026</div>\n      <ul>\n        <li>Server pushes, client only reads</li>\n        <li>Live dashboards, feeds, notifications</li>\n        <li>AI streaming responses (token-by-token)</li>\n        <li>Progress bars for long-running jobs</li>\n        <li>Simpler alternative to WebSocket</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--lp)\">\ud83d\udd04 Long Polling only when\u2026</div>\n      <ul>\n        <li>WebSocket and SSE are unavailable (firewalls)</li>\n        <li>Legacy client support required</li>\n        <li>Using Socket.io (handles fallback automatically)</li>\n        <li>Low update frequency (&lt;1/min) where polling gap is fine</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 07 FOLLOW-UPS \u2550\u2550 -->\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every hard follow-up, answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you scale WebSocket to millions of concurrent connections?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>The core challenge:</strong> WebSocket connections are stateful and live on a specific server. Standard round-robin load balancing breaks \u2014 if user A is connected to server 1 and sends a message to user B connected to server 3, server 1 can't directly push to user B.<br><br>\n      <strong>The solution \u2014 pub/sub message bus:</strong>\n      <ul>\n        <li>Every server subscribes to a Redis Pub/Sub channel or Kafka topic</li>\n        <li>When server 1 needs to push to user B (connected to server 3), it publishes to the shared channel</li>\n        <li>Server 3 is subscribed, receives the message, and pushes it to user B's WebSocket connection</li>\n        <li>Any server can reach any user \u2014 no sticky sessions required for message delivery</li>\n      </ul>\n      <strong>Connection count:</strong> A single server with an async event loop (Node.js, Go, Nginx) can handle 100K\u20131M concurrent WebSocket connections. C10M is achievable with tuned Linux kernel settings (file descriptor limits, socket buffer sizes).<br><br>\n      <strong>Load balancing:</strong> Use sticky sessions (consistent hash by user_id) so a user's connection always routes to the same server \u2014 reduces pub/sub overhead. Failover: client reconnects to any available server on disconnect.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">REST vs gRPC \u2014 which is faster and by how much?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>In benchmarks, gRPC is typically 5\u201310x faster than JSON REST for equivalent payloads.</strong><br><br>\n      <strong>Why Protobuf is faster than JSON:</strong>\n      <ul>\n        <li><strong>Size:</strong> JSON is human-readable text. \"created_at\": \"2026-03-20T14:23:45Z\" is 37 bytes. Protobuf field 5 = timestamp = 8 bytes. 4\u20135x smaller is typical.</li>\n        <li><strong>Parsing:</strong> JSON parsing is string scanning and Unicode handling. Protobuf parsing is integer-indexed field lookup. 5\u201310x faster deserialization.</li>\n        <li><strong>HTTP/2 multiplexing:</strong> gRPC reuses one TCP connection for all RPCs between two services. HTTP/1.1 REST requires a connection per request or connection pooling.</li>\n      </ul>\n      <strong>Real-world numbers (Google's internal benchmarks):</strong> gRPC serialization is ~7x faster than JSON, payloads are ~3.5x smaller, leading to ~2\u20134x fewer CPU cycles per RPC.<br><br>\n      <strong>When the difference matters:</strong> At 10K RPC/sec between services, the CPU savings from Protobuf are measurable in infra cost. At 100 RPC/sec, use REST \u2014 the operational simplicity outweighs any performance gain.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">GraphQL solves over-fetching \u2014 but doesn't it create its own performance problems?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Yes \u2014 GraphQL solves bandwidth but creates three new challenges:</strong><br><br>\n      <strong>1. N+1 queries (the biggest one):</strong> A query for 100 posts each needing their author resolves by calling getAuthor() 100 times. Without DataLoader, this is 101 database calls instead of 2.<br>\n      Fix: DataLoader batches all getAuthor() calls that occur in the same tick into one <code>SELECT * FROM users WHERE id IN (1,2,3...100)</code>.<br><br>\n      <strong>2. Query complexity attacks:</strong> A malicious client sends a deeply nested query: posts \u2192 comments \u2192 authors \u2192 posts \u2192 comments \u2192 authors \u2192 (\u221e). Without depth limiting, this triggers exponential resolver calls.<br>\n      Fix: Query depth limit (max 10 levels), query complexity scoring (each field costs points, reject queries over a budget), query whitelisting in production (only allow known queries).<br><br>\n      <strong>3. No HTTP caching:</strong> GraphQL uses POST \u2014 CDNs don't cache POST. Every query hits your origin.<br>\n      Fix: Persisted Queries \u2014 hash each known query, send the hash as a GET parameter. CDN caches the response. Only novel/uncached queries reach the origin.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">SSE vs WebSocket \u2014 when exactly do you pick SSE?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Pick SSE when the data flow is one-directional and you want HTTP-native simplicity.</strong><br><br>\n      <strong>SSE wins over WebSocket when:</strong>\n      <ul>\n        <li>Client only reads \u2014 never sends data on the real-time channel (notifications, feeds, dashboards, AI token streaming)</li>\n        <li>You need automatic reconnection with event replay \u2014 SSE's <code>Last-Event-ID</code> mechanism gives you this for free; WebSocket requires custom client logic</li>\n        <li>HTTP/2 is available \u2014 SSE over HTTP/2 multiplexes thousands of streams over one TCP connection, solving HTTP/1.1's 6-connection limit</li>\n        <li>Your infrastructure doesn't support WebSocket upgrades (some corporate proxies block it)</li>\n        <li>You want standard HTTP monitoring, logging, and load balancing without special WebSocket-aware tooling</li>\n      </ul>\n      <strong>WebSocket wins when:</strong>\n      <ul>\n        <li>Client sends data frequently on the real-time channel (chat, collaborative editing, games, cursor positions)</li>\n        <li>Sub-frame latency matters \u2014 WebSocket frames are slightly lower overhead than SSE's HTTP text envelope</li>\n        <li>You need binary data (WebSocket supports binary frames natively; SSE is text-only)</li>\n      </ul>\n      <strong>The practical test:</strong> Draw an arrow for your data flow. If the arrow points server\u2192client only, use SSE. If arrows go both directions, use WebSocket.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How does gRPC handle versioning when you change your .proto schema?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Protobuf has designed-in backwards compatibility rules \u2014 but you must follow them religiously.</strong><br><br>\n      <strong>Safe changes (backwards and forwards compatible):</strong>\n      <ul>\n        <li>Adding a new field \u2014 old clients ignore it, new clients read it</li>\n        <li>Changing a field name \u2014 field numbers are what Protobuf uses on the wire, not names</li>\n        <li>Adding a new RPC method \u2014 old clients don't call it</li>\n      </ul>\n      <strong>Breaking changes (never do these in production):</strong>\n      <ul>\n        <li>Changing a field's number (field number = wire identity; changing it means old clients misread your data)</li>\n        <li>Changing a field's type (int32 \u2192 string will corrupt data in-flight)</li>\n        <li>Removing a required field (old clients still send it; new server rejects it)</li>\n        <li>Removing an RPC method that clients are calling</li>\n      </ul>\n      <strong>The strategy for major changes:</strong> Create a new package version (<code>package myapi.v2</code>). Run v1 and v2 in parallel. Migrate clients to v2 gradually. Retire v1 only after all clients have migrated. This is identical to REST's <code>/v1/</code> vs <code>/v2/</code> URL versioning.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between REST idempotency and GraphQL mutation safety?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Idempotency means: calling the operation multiple times has the same effect as calling it once.</strong><br><br>\n      <strong>REST's HTTP methods have defined idempotency semantics:</strong>\n      <ul>\n        <li><code>GET, HEAD, OPTIONS</code> \u2014 safe (no side effects) and idempotent</li>\n        <li><code>PUT, DELETE</code> \u2014 idempotent (doing it twice = same result as once)</li>\n        <li><code>POST</code> \u2014 neither safe nor idempotent (creates a new resource each call)</li>\n        <li><code>PATCH</code> \u2014 not inherently idempotent (depends on implementation)</li>\n      </ul>\n      <strong>For POST idempotency:</strong> Use an Idempotency-Key header (unique UUID per request). Server stores the key \u2192 result mapping. If same key arrives twice, return the stored result instead of executing again. Stripe, Stripe, and most payment APIs require this.<br><br>\n      <strong>GraphQL mutations:</strong> All mutations use POST \u2014 no built-in idempotency. You must implement idempotency keys manually in your mutation resolvers if needed (e.g., payment mutations). This is GraphQL's operational weakness vs REST's verb semantics.<br><br>\n      <strong>Why it matters in interviews:</strong> Payment processing, order creation, and any mutation where double-execution has real consequences needs explicit idempotency handling regardless of protocol.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you secure WebSocket connections?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>WebSocket has no built-in authentication \u2014 you must implement it explicitly.</strong><br><br>\n      <strong>Step 1 \u2014 Use WSS (WebSocket Secure):</strong> Always use <code>wss://</code> (TLS), never <code>ws://</code>. Same as HTTPS vs HTTP. Your certificate covers both.<br><br>\n      <strong>Step 2 \u2014 Authenticate at connection time:</strong> The HTTP Upgrade request is a standard HTTP request \u2014 you can read headers and cookies. Send a JWT or session token in the <code>Authorization</code> header or as a query parameter on the initial <code>wss://</code> URL. Validate before accepting the upgrade.<br><br>\n      <strong>Step 3 \u2014 Authorise at message time:</strong> Validate that the connected user has permission for every message they send. Don't assume that because they connected legitimately, all their subsequent messages are authorised.<br><br>\n      <strong>Step 4 \u2014 Rate limit messages:</strong> Unlike HTTP where rate limiting is standard middleware, WebSocket bypasses your HTTP layer. Implement per-connection message rate limiting at the WebSocket handler level. Without it, one client can flood your server with messages.<br><br>\n      <strong>Step 5 \u2014 Handle token expiry:</strong> JWTs expire. If a user's token expires mid-session, the server needs to close the WebSocket and force re-authentication. Implement token refresh via a REST call; send the new token over the WebSocket or reconnect with the new token.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">In the Uber system design, why use both REST and WebSocket \u2014 why not just WebSocket for everything?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Using WebSocket for everything seems elegant but creates real problems:</strong><br><br>\n      <strong>1. HTTP semantics matter:</strong> REST gives you status codes (400 bad request, 402 payment required, 409 conflict) that load balancers, monitoring tools, and clients all understand natively. Over WebSocket, you'd invent custom error codes \u2014 invisible to your infrastructure.<br><br>\n      <strong>2. Idempotency and retries:</strong> When a user books a ride, you need idempotency guarantees. REST POST with an Idempotency-Key is standardised. WebSocket message delivery is at-most-once by default \u2014 you'd need to build your own ack/retry layer.<br><br>\n      <strong>3. Caching:</strong> Fare estimates, driver profiles, and static data are cacheable. REST GET responses are cached at CDN and browser level automatically. WebSocket has no caching layer.<br><br>\n      <strong>4. Load balancing:</strong> REST requests are stateless \u2014 any server handles any request. WebSocket connections are stateful \u2014 they need sticky sessions or a message bus. Running everything over WebSocket means every service needs WebSocket-aware infrastructure.<br><br>\n      <strong>5. Operational tooling:</strong> HTTP logs, traces, and metrics are supported by every monitoring tool out of the box. WebSocket message-level observability requires custom instrumentation.<br><br>\n      <strong>The correct split:</strong> WebSocket for what genuinely needs real-time bidirectional communication (location, status updates). REST for everything transactional (booking, payment, profile). The complexity-to-benefit ratio is much better.\n    </div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">PROTOCOLS \u00b7 REST \u00b7 GRPC \u00b7 GRAPHQL \u00b7 WEBSOCKET \u00b7 SSE \u00b7 LONG POLLING \u00b7 MANISH-ALMANAC</div>\n\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Protocols' },
  caching: { title: 'Caching Deep Dive', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Caching: Redis, Memcached & CDN</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n\n\n.tier-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.tier-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.tier-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.tier-card.hot::before{background:var(--red);}\n.tier-card.warm::before{background:var(--amber);}\n.tier-card.cold::before{background:var(--blue);}\n.tier-card.cdn::before{background:var(--green);}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n    <h1>Caching<br><em>Redis, Memcached & CDN</em></h1>\n    <p class=\"hero-sub\">Every caching strategy, eviction policy, Redis data structure, and invalidation pattern \u2014 explained from first principles with real system design examples.</p>\n    <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">Redis</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Memcached</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">Cache-Aside</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Write-Through</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:rgba(96,64,160,.08)\">Eviction</span><span class=\"db-pill\" style=\"border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08)\">CDN</span></div>\n  </div>\n</div>\n<nav class=\"nav\"><a href=\"#why\">Why Cache</a><a href=\"#hierarchy\">Hierarchy</a><a href=\"#strategies\">Write Strategies</a><a href=\"#eviction\">Eviction</a><a href=\"#redis\">Redis Deep Dive</a><a href=\"#examples\">System Design</a><a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n\n<section id=\"why\">\n  <div class=\"sec-tag\">00 \u00b7 Why Caching Exists</div>\n  <h2>The single reason every system needs a cache</h2>\n  <p>A database read on a cold system takes 1\u201310ms. A cache hit takes 0.1\u20131ms. At 100K requests/sec, that difference is the line between a system that works and one that collapses. But caching is not just about speed \u2014 it is about <strong>protecting your database from traffic it was never designed to handle</strong>.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The library analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      A library (database) has every book ever written. But fetching any book takes a librarian 10 minutes. So you keep the 100 most popular books on a desk beside you (cache). When someone asks for a book, you check your desk first. 99% of the time it's there \u2014 instant. Only 1% of requests require the 10-minute librarian trip.<br><br>\n      <strong>The cache hit rate is everything.</strong> A 99% hit rate means your database handles 1% of original traffic. A 90% hit rate means 10% \u2014 still 10x less. A 50% hit rate barely helps at all.\n    </div>\n  </div>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The interview framing</div>\n    <p>Never say \"I'll add a cache\" without answering: <strong>(1) What exactly gets cached?</strong> (2) What is the cache key? (3) When does it get invalidated? (4) What is the consistency trade-off? Interviewers give no credit for \"add Redis\" \u2014 they want the strategy.</p>\n  </div>\n</section>\n\n<section id=\"hierarchy\">\n  <div class=\"sec-tag\">01 \u00b7 Cache Hierarchy</div>\n  <h2>The four layers \u2014 where caching lives</h2>\n  <div class=\"tier-grid\">\n    <div class=\"tier-card cdn\">\n      <div class=\"db-logo\">\ud83c\udf0d</div>\n      <div class=\"db-name\">CDN Edge Cache</div>\n      <div class=\"db-type\">Nearest PoP \u00b7 HTTP \u00b7 Global</div>\n      <div class=\"db-tagline\">Caches static assets and cacheable API responses at 200+ edge nodes worldwide. Serves from &lt;10ms anywhere. Absorbs 90\u201399% of static traffic before it touches your servers.</div>\n      <div class=\"db-born\">Cloudflare \u00b7 Fastly \u00b7 Akamai \u00b7 AWS CloudFront</div>\n    </div>\n    <div class=\"tier-card hot\">\n      <div class=\"db-logo\">\ud83d\udd25</div>\n      <div class=\"db-name\">Application Cache</div>\n      <div class=\"db-type\">In-Process \u00b7 RAM \u00b7 Single Node</div>\n      <div class=\"db-tagline\">In-memory cache inside the application process (Guava Cache, Caffeine, Python dict). Sub-microsecond access. No network hop. Limited to one server's RAM. Not shared across instances.</div>\n      <div class=\"db-born\">Caffeine (Java) \u00b7 Guava \u00b7 Python functools.lru_cache</div>\n    </div>\n    <div class=\"tier-card warm\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">Distributed Cache</div>\n      <div class=\"db-type\">Shared \u00b7 Network \u00b7 Multi-Node</div>\n      <div class=\"db-tagline\">Shared cache accessible by all app servers. Sub-millisecond over LAN. Survives server restarts. The default choice for any horizontally-scaled system \u2014 all app instances share the same view.</div>\n      <div class=\"db-born\">Redis \u00b7 Memcached \u00b7 AWS ElastiCache \u00b7 Aerospike</div>\n    </div>\n    <div class=\"tier-card cold\">\n      <div class=\"db-logo\">\ud83d\uddc4\ufe0f</div>\n      <div class=\"db-name\">Database Buffer Pool</div>\n      <div class=\"db-type\">Internal \u00b7 OS Page Cache \u00b7 Transparent</div>\n      <div class=\"db-tagline\">PostgreSQL/MySQL's internal page cache. Frequently accessed pages stay in RAM automatically. You don't control it directly \u2014 but proper indexing ensures hot data stays cached here.</div>\n      <div class=\"db-born\">PostgreSQL shared_buffers \u00b7 InnoDB buffer pool \u00b7 OS page cache</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"strategies\">\n  <div class=\"sec-tag\">02 \u00b7 Write Strategies</div>\n  <h2>The four write patterns \u2014 this is what interviewers test</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Cache-Aside<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Lazy Loading)</span></div>\n      <div class=\"concept-def\"><strong>Application manages the cache explicitly. Most common pattern.</strong><br>\n        Read: check cache \u2192 if miss, read DB \u2192 write result to cache \u2192 return.<br>\n        Write: write to DB \u2192 <em>invalidate or update</em> cache entry.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Only caches data that is actually requested. Cache can survive a restart (just misses until warmed). Resilient \u2014 cache failure doesn't break reads.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cache miss penalty: 3 operations instead of 1. Race condition: two threads can miss simultaneously, both read DB, both write cache (use distributed lock or short TTL).</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: most read-heavy systems \u2014 social feeds, product pages, user profiles.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Write-Through</div>\n      <div class=\"concept-def\"><strong>Every write goes to cache AND database synchronously before returning.</strong><br>\n        Write: write cache \u2192 write DB \u2192 return success.<br>\n        Read: always hits cache (always fresh).<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cache is always consistent with DB. No stale reads. No cache miss on subsequent reads.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Write latency = cache write + DB write (two hops). Caches data that may never be read (write-heavy systems waste cache space).</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: systems where reads must be fresh \u2014 financial dashboards, inventory systems.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Write-Behind<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Write-Back)</span></div>\n      <div class=\"concept-def\"><strong>Write to cache immediately, persist to DB asynchronously in the background.</strong><br>\n        Write: write cache \u2192 return success \u2192 background job flushes to DB.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Fastest write latency \u2014 single cache write. Batches DB writes (10x fewer DB operations). Great for high-write-frequency data (view counters, like counts).</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Data loss risk: if cache crashes before flush, writes are lost. Not safe for financial data. Complex recovery logic needed.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: counters, analytics, non-critical state. Redis itself uses write-back for AOF persistence.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Refresh-Ahead<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Read-Through)</span></div>\n      <div class=\"concept-def\"><strong>Cache automatically refreshes hot entries before they expire, predicting future reads.</strong><br>\n        Cache layer intercepts reads. On miss: fetches from DB, caches, returns. Proactively re-fetches keys nearing expiry if they were recently accessed.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No cache miss latency for hot data. Application code never touches DB directly \u2014 clean separation.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 May cache stale data if prediction is wrong. Requires a separate refresh thread/process.</span><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Used by: read-through cache libraries (Ehcache, Spring Cache), Redis with background refresh logic.</span>\n      </div>\n    </div>\n  </div>\n\n  <h3>Cache Invalidation \u2014 The Hardest Problem in Caching</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">TTL (Time-to-Live)</div>\n      <div class=\"concept-def\"><strong>Every cache entry expires after N seconds.</strong> Simplest approach. After expiry, next read re-fetches from DB.<br>\n        <code>SET user:123 {json} EX 3600</code> \u2014 expires in 1 hour.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No invalidation logic needed. Self-healing \u2014 stale data auto-purges.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Data is stale for up to TTL seconds after an update. TTL too short = many misses. TTL too long = stale data shown to users.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Event-Driven<br>Invalidation</div>\n      <div class=\"concept-def\"><strong>When data changes, explicitly delete or update the cache entry.</strong><br>\n        User updates profile \u2192 <code>DEL user:123</code> in Redis \u2192 next read re-fetches fresh data.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Immediately consistent. No stale window.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cache and DB writes must be atomic \u2014 if cache delete succeeds but DB write fails (or vice versa), you have inconsistency. Use transactional outbox pattern or delete-after-DB-commit.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Cache Stampede<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">(Thundering Herd)</span></div>\n      <div class=\"concept-def\"><strong>A popular key expires \u2192 thousands of simultaneous requests all miss \u2192 all hit the DB simultaneously \u2192 DB falls over.</strong><br>\n        Scenario: trending video cached with 10-minute TTL. At expiry, 50K requests/sec all miss simultaneously.<br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 The cache that was protecting your DB is now the reason your DB dies.</span><br>\n        <strong>Fixes:</strong><br>\n        \u2022 <strong>Mutex lock</strong>: first thread to miss acquires a lock, fetches DB, populates cache. Others wait, then read from cache.<br>\n        \u2022 <strong>Probabilistic early expiry</strong>: slightly before TTL, a fraction of requests proactively refresh.<br>\n        \u2022 <strong>Jitter</strong>: randomise TTL (\u00b110%) so not all keys expire simultaneously.<br>\n        \u2022 <strong>Stale-while-revalidate</strong>: return stale value immediately, refresh in background.\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"eviction\">\n  <div class=\"sec-tag\">03 \u00b7 Eviction Policies</div>\n  <h2>What gets removed when the cache is full</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">LRU<br>(Least Recently Used)</div><div class=\"concept-def\"><strong>Evict the entry that was accessed longest ago.</strong> Implemented as a doubly-linked list + hashmap. O(1) get and put. Most common default.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Works well when recency correlates with future access. A user just viewed their profile \u2014 it should stay cached.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0 A single large sequential scan (backup job reading all users) pollutes the cache with one-time data, evicting actually-hot entries.</span><br><span style=\"color:#5a5848;font-size:12.5px;\">Redis default policy: allkeys-lru. Used by: most web application caches.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">LFU<br>(Least Frequently Used)</div><div class=\"concept-def\"><strong>Evict the entry accessed fewest times total.</strong> Tracks a frequency counter per key. O(1) with a min-heap + frequency buckets (complex implementation).<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Better for workloads with stable hot keys (celebrity user profiles, popular products). Resists cache pollution from one-time scans.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0 New keys start with frequency=1 \u2014 they get evicted immediately even if they'll be accessed 1M times tomorrow. Requires frequency decay to handle shifting popularity.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">TTL-Based</div><div class=\"concept-def\"><strong>Evict entries whose TTL has expired.</strong> Passive expiry (evict on access if expired) + active expiry (background sweep). Redis uses both.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Natural fit for session caches, API response caches where staleness has a defined bound.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis Policies</div><div class=\"concept-def\"><strong>Redis has 8 eviction policies. The most important:</strong><br>\n      <code>noeviction</code> \u2014 return error when full (safest, but breaks writes)<br>\n      <code>allkeys-lru</code> \u2014 LRU across all keys (most common)<br>\n      <code>volatile-lru</code> \u2014 LRU only among keys with TTL set<br>\n      <code>allkeys-lfu</code> \u2014 LFU across all keys (Redis 4+)<br>\n      <code>allkeys-random</code> \u2014 random eviction (surprisingly effective for uniform workloads)<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Set via <code>maxmemory-policy</code> config. Always set <code>maxmemory</code> or Redis will consume all available RAM.</span>\n    </div></div>\n  </div>\n</section>\n\n<section id=\"redis\">\n  <div class=\"sec-tag\">04 \u00b7 Redis Deep Dive</div>\n  <h2>Redis data structures \u2014 the right tool for each problem</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">String</div><div class=\"concept-def\"><strong>Binary-safe value up to 512MB. The catch-all type.</strong><br>\n      Use for: JSON blobs, HTML fragments, counters, session tokens.<br>\n      <code>SET user:123 \"{name:Alice}\" EX 3600</code><br>\n      <code>INCR pageview:home</code> \u2014 atomic counter, no race condition.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">INCR/DECR are atomic \u2014 the only safe way to do distributed counters without locks.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Hash</div><div class=\"concept-def\"><strong>Field-value map within one key. Ideal for objects.</strong><br>\n      <code>HSET user:123 name Alice age 30 city Bangalore</code><br>\n      <code>HGET user:123 name</code> \u2014 fetch one field without deserializing the whole object.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 More memory-efficient than separate string keys per field. Update one field without reading/writing the entire object. Used by: user profiles, shopping carts.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Sorted Set (ZSET)</div><div class=\"concept-def\"><strong>Set of unique members, each with a float score. Ordered by score. O(log N) operations.</strong><br>\n      <code>ZADD leaderboard 9241038 user:alice</code><br>\n      <code>ZREVRANGE leaderboard 0 9 WITHSCORES</code> \u2014 top 10 with scores.<br>\n      <code>ZINCRBY leaderboard 847 vid:abc</code> \u2014 atomic increment.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 The backbone of Top-K, leaderboards, rate limiting windows, priority queues. Used by: Top-K system, gaming leaderboards, Twitter trending.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Set</div><div class=\"concept-def\"><strong>Unordered collection of unique strings. O(1) add/remove/lookup.</strong><br>\n      <code>SADD online:users user:123 user:456</code><br>\n      <code>SISMEMBER online:users user:123</code> \u2014 is user online?<br>\n      <code>SUNION followers:alice followers:bob</code> \u2014 union of sets.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used for: online presence, unique visitors per day, tag systems, friend intersections (SINTER).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">List</div><div class=\"concept-def\"><strong>Doubly-linked list. O(1) push/pop from both ends.</strong><br>\n      <code>LPUSH feed:user:123 post:789</code> \u2014 prepend to feed.<br>\n      <code>LRANGE feed:user:123 0 19</code> \u2014 fetch first 20 items.<br>\n      <code>BRPOP queue:emails 30</code> \u2014 blocking pop (simple message queue).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used for: activity feeds, simple task queues, recent items lists. BRPOP pattern = lightweight job queue without Kafka overhead.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">HyperLogLog</div><div class=\"concept-def\"><strong>Probabilistic cardinality estimator. Counts unique items using ~12KB regardless of cardinality.</strong><br>\n      <code>PFADD unique:visitors:2026-03-21 user:123 user:456</code><br>\n      <code>PFCOUNT unique:visitors:2026-03-21</code> \u2014 returns ~100M unique visitors using 12KB RAM. Error rate: \u00b10.81%.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Count 1 billion unique visitors using 12KB. A HashSet for the same would need ~8GB. Used by: DAU metrics, unique video views, distinct IP counting.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pub/Sub &amp; Streams</div><div class=\"concept-def\"><strong>Pub/Sub: fire-and-forget broadcasting. Streams: persistent, replayable event log (mini Kafka).</strong><br>\n      <code>PUBLISH notifications:user:123 \"New message from Alice\"</code><br>\n      <code>XADD events * type view entity_id vid_abc</code> \u2014 append to stream.<br>\n      <code>XREAD COUNT 100 STREAMS events 0</code> \u2014 read from stream.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Pub/Sub: real-time notifications between app servers. Streams: durable event log for small-scale streaming (not a Kafka replacement at scale).</span></div></div>\n  </div>\n\n  <h3>Redis Cluster vs Sentinel \u2014 When to Use Each</h3>\n  <div class=\"comp-table-wrap\">\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Redis Sentinel</th><th>Redis Cluster</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Purpose</td><td>High availability (HA) \u2014 automatic failover</td><td>Horizontal scaling + HA</td></tr>\n      <tr><td class=\"row-head\">Data distribution</td><td>All data on primary + replicas (full copy)</td><td>Sharded across 16,384 hash slots</td></tr>\n      <tr><td class=\"row-head\">Scaling</td><td>Scale reads via replicas; writes on one primary</td><td>Scale writes across multiple primaries</td></tr>\n      <tr><td class=\"row-head\">Max data</td><td>Single primary's RAM (~100s GB)</td><td>Sum of all primaries' RAM (TBs)</td></tr>\n      <tr><td class=\"row-head\">Multi-key ops</td><td><span class=\"good\">All supported</span></td><td><span class=\"warn\">Only if keys on same slot (use hash tags)</span></td></tr>\n      <tr><td class=\"row-head\">Complexity</td><td>Simple \u2014 just 3 sentinel nodes</td><td>Complex \u2014 resharding, gossip protocol</td></tr>\n      <tr><td class=\"row-head\">Use when</td><td>Dataset fits in one server's RAM</td><td>Dataset exceeds one server's RAM or need write scale-out</td></tr>\n    </tbody>\n  </table>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 System Design Examples</div>\n  <h2>Caching decisions in real systems</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Twitter / X \u2014 Social Feed</div><span class=\"sd-example-tag\">READ-HEAVY \u00b7 FAN-OUT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">FEED CACHE</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis List \u2713</span> Each user's pre-computed feed stored as a Redis List (LPUSH on new tweet, LRANGE for reads). Cache-aside with TTL=24h. 99% of feed reads are cache hits \u2014 the DB never sees them. Key: <code>feed:user:{id}</code>.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TWEET CONTENT</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis String \u2713</span> Individual tweet JSON cached as a String with TTL=1h. Celebrity tweets get longer TTL (>24h) because they're read millions of times. Key: <code>tweet:{id}</code>.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TRENDING</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis ZSET \u2713</span> Hashtag counts in a sorted set. <code>ZINCRBY trending:1h #WorldCup 1</code> per event. <code>ZREVRANGE trending:1h 0 9</code> returns top 10. Sub-millisecond at any scale.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">INVALIDATION</div><div class=\"choice-val\">User deletes a tweet \u2192 <code>DEL tweet:{id}</code> + rebuild affected feeds. TTL as safety net for stale data. Eventual consistency is acceptable \u2014 seeing a deleted tweet for 1 minute is tolerable for Twitter's use case.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">E-Commerce \u2014 Product Catalog</div><span class=\"sd-example-tag\">WRITE-RARE \u00b7 READ-HEAVY</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PRODUCT PAGE</div><div class=\"choice-val\"><span class=\"badge b-g\">CDN + Redis \u2713</span> Static product HTML cached at CDN edge (TTL=10min). Inventory count cached in Redis String with TTL=30s. CDN handles 95% of product page traffic. Redis handles inventory checks without hitting DB.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">INVENTORY</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis DECR \u2713</span> <code>DECRBY inventory:{sku} {qty}</code> \u2014 atomic decrement. If result &lt; 0, rollback: <code>INCRBY inventory:{sku} {qty}</code> and reject order. No DB needed for inventory check during purchase flow.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FLASH SALE</div><div class=\"choice-val\">During a flash sale (10K requests/sec for one SKU), cache stampede risk is extreme. Solution: Redis lock (<code>SET lock:{sku} 1 NX EX 5</code>) + pre-warm cache 5 minutes before sale. Only the lock-holder refreshes the cache; others read stale value briefly.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 Decision Framework</div>\n  <h2>How to talk about caching in an interview</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Caching Strategy \u2014 Answer These in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the read-to-write ratio?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Read-heavy (&gt;10:1) \u2192</span><span class=\"opt-text\"><strong>Cache aggressively.</strong> Cache-aside or read-through. High cache hit rate justifies complexity. Most social, e-commerce, and media systems fall here.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Write-heavy \u2192</span><span class=\"opt-text\"><strong>Cache carefully.</strong> Write-behind for non-critical counters. Cache invalidation complexity may outweigh benefit. Consider whether caching actually helps.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Can you tolerate stale data? For how long?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Yes (seconds/minutes OK) \u2192</span><span class=\"opt-text\"><strong>TTL-based invalidation.</strong> Simple, no code coupling. Social feed, product descriptions, user profiles \u2014 all tolerate seconds of staleness.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">No (must be fresh) \u2192</span><span class=\"opt-text\"><strong>Event-driven invalidation + write-through.</strong> Financial balances, inventory counts, seat availability \u2014 must be consistent. Use shorter TTL as safety net too.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your data structure need?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Simple key-value \u2192</span><span class=\"opt-text\"><strong>Memcached</strong> (simpler, multi-threaded, pure LRU) or <strong>Redis String</strong>. Memcached is faster for simple string caching with multiple CPU cores.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Rich structures (sorted sets, counters, lists) \u2192</span><span class=\"opt-text\"><strong>Redis.</strong> No contest. Sorted sets for leaderboards, atomic INCR for counters, Lists for queues, HyperLogLog for cardinality.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Persistence needed \u2192</span><span class=\"opt-text\"><strong>Redis with AOF/RDB.</strong> Memcached is pure in-memory \u2014 no persistence. Redis can persist to disk and survive restarts.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the data size and access pattern?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Small hot dataset (&lt;100GB) \u2192</span><span class=\"opt-text\"><strong>Redis Sentinel.</strong> All data fits on one primary. Simple HA with automatic failover. No sharding complexity.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Large dataset or high write throughput \u2192</span><span class=\"opt-text\"><strong>Redis Cluster.</strong> Horizontal sharding across multiple primaries. Scale both data size and write throughput. More operational complexity.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Redis is single-threaded \u2014 how does it handle 1M requests/sec?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Redis's event loop is single-threaded for command processing, but that is actually its strength, not its weakness.</strong><br><br>Since commands execute serially, there are no lock contention or deadlock issues. Redis commands are in-memory operations taking microseconds \u2014 the bottleneck is never CPU, it is always network I/O. Redis 6+ added multithreaded I/O for reading/writing the network buffers, while keeping command execution single-threaded. Result: 1\u201310M operations/sec on a single instance depending on command complexity and payload size.<br><br>When you need more throughput: Redis Cluster shards load across multiple independent single-threaded instances. 10 nodes = ~10M ops/sec aggregate throughput.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle cache consistency in a microservices architecture?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>This is one of the hardest distributed systems problems. Three patterns, in order of complexity:</strong><br><br><strong>1. TTL + eventual consistency</strong>: Each service caches with a short TTL (30s\u20135min). Stale data is guaranteed to expire. Simple, no coordination. Works for most social/media use cases where slight staleness is acceptable.<br><br><strong>2. Event-driven invalidation</strong>: When Service A updates user data, it publishes a <code>UserUpdated</code> event to Kafka. Service B consumes the event and deletes/updates its cache. Consistent eventually. Risk: if the event is lost, cache stays stale indefinitely \u2014 mitigate with TTL as backup.<br><br><strong>3. Cache ownership</strong>: Each data domain is owned by one service. Other services must call that service's API to read data \u2014 they cannot cache it themselves. Eliminates invalidation problem entirely at the cost of added latency on every cross-service read.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between Redis and Memcached? When do you pick each?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Memcached is a simpler, faster, multi-threaded string cache. Redis is a full data structure server.</strong><br><br><strong>Pick Memcached when:</strong> You need pure key-value string caching, you have a multi-core server and want to saturate all cores (Memcached is truly multi-threaded), you do not need persistence or replication, and you want the absolute simplest operational footprint.<br><br><strong>Pick Redis when:</strong> You need any data structure beyond strings (sorted sets, lists, hashes), you need atomic operations (INCR, LPUSH), you need persistence (AOF/RDB for crash recovery), you need Pub/Sub or Streams, or you need built-in replication and cluster mode.<br><br><strong>In practice at FAANG:</strong> Redis has won. The operational overhead of maintaining two different cache systems (Redis for rich structures, Memcached for simple caching) is rarely worth the marginal performance difference. Most teams standardize on Redis for everything.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does Redis persistence work \u2014 RDB vs AOF?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Redis has two persistence mechanisms that can be used independently or together.</strong><br><br><strong>RDB (Redis Database Backup)</strong>: Point-in-time snapshot written to disk periodically (every N seconds if M keys changed). Fast to restore \u2014 single compact binary file. Risk: data since last snapshot is lost on crash. Used for: disaster recovery, backups, cache warm-up after restart.<br><br><strong>AOF (Append-Only File)</strong>: Every write command is appended to a log file. On restart, Redis replays the log. Three fsync options: always (safest, slowest), every second (good balance \u2014 max 1 second data loss), never (OS decides, fastest). AOF rewrite periodically compacts the log. Used for: when you cannot afford data loss.<br><br><strong>Recommendation</strong>: Use both for critical data \u2014 RDB for fast restarts + AOF for durability. For pure cache use cases where data can be reconstructed from the DB, disable persistence entirely for maximum performance.</div></div>\n</section>\n\n</div>\n<div class=\"footer\">CACHING \u00b7 REDIS \u00b7 MEMCACHED \u00b7 EVICTION \u00b7 INVALIDATION \u00b7 CDN \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>", tag: 'Caching' },
  consistent_hashing: { title: 'Consistent Hashing', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Consistent Hashing: Partitioning at Scale</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Consistent Hashing<br><em>Partitioning at Scale</em></h1>\n  <p class=\"hero-sub\">Why naive hashing breaks, the ring explained step by step, virtual nodes, hot spot mitigation, and how Cassandra, Redis Cluster and DynamoDB actually implement it.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">Hash Ring</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Virtual Nodes</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Hash Slots</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Hot Spots</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">Rendezvous Hashing</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#problem\">The Problem</a><a href=\"#ring\">The Ring</a><a href=\"#partitioning\">Strategies</a><a href=\"#hotspot\">Hot Spots</a><a href=\"#real\">Real Systems</a><a href=\"#rendezvous\">Rendezvous</a><a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"problem\">\n  <div class=\"sec-tag\">00 \u00b7 The Problem With Naive Hashing</div>\n  <h2>Why key % N destroys your cache on every topology change</h2>\n  <p>You have 3 servers. A request for <code>user:123</code> maps to <code>hash(\"user:123\") % 3 = 1</code> \u2192 Server 1. Your cache is warm, hit rate 98%. You add a 4th server to handle load. Now <code>hash(\"user:123\") % 4 = 3</code> \u2192 Server 3. <strong>Every single key remaps to a different server.</strong> Your entire cache is cold simultaneously. Your database receives 100x normal traffic and falls over.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The seating chart analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      A wedding has 100 guests and 10 tables. Each guest is assigned <code>hash(name) % 10</code>. The seating works perfectly.<br><br>\n      One table collapses mid-event \u2014 now 9 tables. Recompute <code>hash(name) % 9</code> for every guest. Nearly <em>everyone</em> moves to a different table. Chaos.<br><br>\n      <strong>Consistent hashing</strong> arranges all tables in a circle. Remove one table \u2014 only that table's guests move to the next table clockwise. Everyone else stays exactly where they were. Only 1/N guests are disrupted.\n    </div>\n  </div>\n  <div class=\"callout cl-red\">\n    <div class=\"cl-lbl\">The interview setup</div>\n    <p>Interviewers introduce consistent hashing with: \"Your caching layer has 10 nodes. Traffic doubles \u2014 you need to add 5 more nodes. What happens to your cache?\" The wrong answer: \"Cache invalidation.\" The right answer: walk through consistent hashing, virtual nodes, and the fraction of keys that need to migrate.</p>\n  </div>\n</section>\n\n<section id=\"ring\">\n  <div class=\"sec-tag\">01 \u00b7 The Ring \u2014 Step by Step</div>\n  <h2>How consistent hashing actually works</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">The Hash Space</div><div class=\"concept-def\"><strong>Imagine a circle representing all possible hash values \u2014 0 to 2\u00b3\u00b2 (about 4.3 billion positions).</strong> Both servers and keys are placed on this circle by hashing their identifiers with the same function (MurmurHash3 in production).<br>\n      Servers: <code>hash(\"server-A\") \u2192 120M</code>, <code>hash(\"server-B\") \u2192 1.8B</code>, <code>hash(\"server-C\") \u2192 3.1B</code><br>\n      Key assignment rule: <strong>walk clockwise from the key's position until you hit a server.</strong> That server owns the key.<br>\n      <code>hash(\"user:123\") \u2192 900M</code> \u2192 walk clockwise \u2192 hit Server-B at 1.8B \u2192 Server-B owns this key.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Adding a Server</div><div class=\"concept-def\"><strong>New Server-D hashes to position 1.2B \u2014 between Server-A (120M) and Server-B (1.8B).</strong><br>\n      Before D: keys between 120M and 1.8B \u2192 Server-B.<br>\n      After D: keys between 120M and 1.2B \u2192 Server-D. Keys between 1.2B and 1.8B \u2192 still Server-B.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Only keys previously on Server-B (in that arc) move to Server-D. All keys on Server-A and Server-C are completely unaffected. Exactly 1/N of keys move when adding the Nth server.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Removing a Server</div><div class=\"concept-def\"><strong>Server-B crashes. Its keys now walk clockwise to Server-C.</strong><br>\n      Before crash: keys between 1.2B and 1.8B \u2192 Server-B.<br>\n      After crash: keys between 1.2B and 1.8B \u2192 Server-C (next clockwise).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Only 1/N of keys experience a cache miss (the ones that were on Server-B). Every other server's keys are completely unaffected. Compare to naive hashing: 100% of keys remapped.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">The database only absorbs 1/N of normal traffic from cold cache misses \u2014 not a complete collapse.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Virtual Nodes (Vnodes)</div><div class=\"concept-def\"><strong>Problem: with 3 physical servers, one might own 60% of the ring. Uneven load.</strong><br>\n      Solution: each physical server gets 100\u2013300 positions on the ring by hashing variations of its ID:<br>\n      <code>hash(\"server-A#1\"), hash(\"server-A#2\"), ..., hash(\"server-A#150\")</code><br>\n      Server-A now has 150 small arcs scattered across the ring instead of one large arc.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Load distributes much more evenly \u2014 law of large numbers applies. Larger servers get more vnodes. Cassandra default: 256 vnodes. Redis Cluster: 16,384 fixed slots.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 More vnodes = larger routing table (must store all vnode\u2192server mappings). 1000 servers \u00d7 256 vnodes = 256,000 entries. Still small enough to fit in memory easily.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Replication on the Ring</div><div class=\"concept-def\"><strong>Store each key on the next N servers clockwise \u2014 replication factor N gives N-way redundancy.</strong><br>\n      Replication factor 3: <code>hash(\"user:123\") \u2192 900M</code> \u2192 primary Server-B (1.8B) \u2192 replica Server-C (3.1B) \u2192 replica Server-A (120M + wraparound).<br>\n      Writes go to all 3. Reads can come from any of 3.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 If Server-B crashes, Server-C and Server-A still have the data \u2014 zero data loss for RF=3. Used by: Cassandra (RF typically 3), DynamoDB (transparently behind the scenes).</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">The ring simultaneously handles partitioning (which nodes own which keys) and replication (which N nodes store each key). One data structure, two concerns.</span></div></div>\n  </div>\n</section>\n\n<section id=\"partitioning\">\n  <div class=\"sec-tag\">02 \u00b7 Partitioning Strategies</div>\n  <h2>Four ways to shard \u2014 and when each breaks in production</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Strategy</th><th>Mechanism</th><th>Strength</th><th>Failure Mode</th><th>Used By</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Hash mod N<br><code>key % N</code></td><td>Hash key, modulo server count</td><td>Simple, zero overhead</td><td class=\"bad\">100% key remapping on any topology change</td><td>Single-node only</td></tr>\n      <tr><td class=\"row-head\">Range Sharding</td><td>A\u2013F \u2192 shard 1, G\u2013M \u2192 shard 2</td><td>Range queries efficient; predictable data locality</td><td class=\"warn\">Hot spots: users with names starting \"S\" dominate one shard; time-series data concentrates on newest shard</td><td>HBase, BigTable, CockroachDB</td></tr>\n      <tr><td class=\"row-head\">Consistent Hash Ring</td><td>Ring: key \u2192 nearest server clockwise</td><td>Only 1/N keys disrupted on topology change; works without coordination</td><td class=\"warn\">Non-uniform without vnodes; popular keys still hot (hash distributes keys, not traffic)</td><td>Cassandra, DynamoDB, Memcached, Akamai</td></tr>\n      <tr><td class=\"row-head\">Hash Slots<br>(Redis Cluster)</td><td>16,384 fixed slots; key \u2192 CRC16 % 16384 \u2192 server</td><td>Deterministic; explicit slot assignment; easy resharding; <code>{hashtag}</code> for colocation</td><td class=\"warn\">Cross-slot multi-key ops require hash tags; resharding needs careful orchestration</td><td>Redis Cluster</td></tr>\n      <tr><td class=\"row-head\">Directory-Based</td><td>Metadata service maps each shard to a server</td><td>Maximum flexibility; any mapping possible; supports non-uniform shards</td><td class=\"bad\">Metadata service is a single point of failure and performance bottleneck</td><td>MongoDB mongos, HDFS NameNode</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"hotspot\">\n  <div class=\"sec-tag\">03 \u00b7 Hot Spots</div>\n  <h2>Consistent hashing distributes keys \u2014 not traffic. These are different problems.</h2>\n  <div class=\"callout cl-red\">\n    <div class=\"cl-lbl\">\u26a0 The interview trap that catches most candidates</div>\n    <p>\"I'll use consistent hashing to distribute load evenly.\" Interviewer: \"Beyonc\u00e9 posts a new album. Her account receives 10 million writes per minute \u2014 all hashing to the same server. How does consistent hashing help?\" <strong>Answer: it doesn't.</strong> Consistent hashing distributes the keyspace evenly. A celebrity key is still a single key on a single node \u2014 it just happens to be consistently routed to that node.</p>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Key Salting</div><div class=\"concept-def\"><strong>Distribute one logical key across multiple physical keys with a random or deterministic suffix.</strong><br>\n      Instead of writing to <code>celebrity:456:post_count</code>, write to one of <code>celebrity:456:post_count#0</code> through <code>celebrity:456:post_count#15</code> (16 shards, chosen randomly).<br>\n      Reads: scatter-gather all 16 shards, sum the counts.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 16x write throughput for that key. Distributes across 16 different servers. Used for: view counters, like counts, follower counts on celebrities.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Reads require 16 parallel requests + aggregation \u2014 adds latency. Tradeoff: write scale vs read complexity.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Fan-Out on Write</div><div class=\"concept-def\"><strong>Push content to every follower's personal shard at write time \u2014 so reads are O(1) per user.</strong><br>\n      Celebrity posts: instead of one write + 50M lazy reads, pre-write the post to each follower's feed. Each follower's feed is stored on their own shard \u2014 reads are local.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Feed reads are sub-millisecond. Twitter uses fan-out on write for most users.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Celebrity with 50M followers = 50M writes per post. Hybrid approach: fan-out for regular users, fan-out on read (lazy) for celebrities. Twitter's actual system uses this hybrid.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">In-Process Local Cache</div><div class=\"concept-def\"><strong>Cache hot keys on every app server in-memory \u2014 zero network hop for reads.</strong><br>\n      Celebrity profile read 10M times/minute: Caffeine (Java) or dict (Python) on each of 1,000 app servers. Each serves from local RAM. Total: 1M reads/sec per app server absorbed locally.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Eliminates hot spot on the distributed cache entirely for pure reads. Used for: config data, feature flags, celebrity profiles, reference data.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Each server has its own copy \u2192 inconsistency across servers. Short TTL (10\u201360s) + push invalidation on write. Acceptable for eventually-consistent data only.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Adaptive Routing</div><div class=\"concept-def\"><strong>Detect hot keys in real time and replicate them to additional nodes dynamically.</strong><br>\n      DynamoDB's adaptive capacity: automatically provides additional read/write capacity to hot partitions by splitting them. The partition that is hot gets a larger slice of the underlying capacity automatically, with no manual intervention.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Transparent to the application. No manual key salting needed. Used by: DynamoDB (built-in), Google Spanner (automatic split on hot ranges).</span></div></div>\n  </div>\n</section>\n\n<section id=\"real\">\n  <div class=\"sec-tag\">04 \u00b7 Real Implementations</div>\n  <h2>How Cassandra, Redis Cluster, and DynamoDB actually do it</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Cassandra \u2014 Murmur3 Token Ring</div><span class=\"sd-example-tag\">CONSISTENT HASHING \u00b7 RF=3</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TOKEN RING</div><div class=\"choice-val\">Murmur3 hash maps partition keys to tokens in range -2\u2076\u00b3 to +2\u2076\u00b3. Each node gets 256 vnodes by default, each with a random token. The ring has 256 \u00d7 N tokens for an N-node cluster.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">REPLICATION</div><div class=\"choice-val\">RF=3: partition key hashes to a token \u2192 first node clockwise is primary \u2192 next 2 clockwise nodes are replicas. Data lives on exactly 3 nodes. NetworkTopologyStrategy ensures replicas span different racks/DCs.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">COORDINATOR</div><div class=\"choice-val\">Any node can be coordinator. Client connects to any node \u2192 coordinator hashes the key \u2192 identifies the 3 replica nodes \u2192 routes request \u2192 returns result. No central routing service needed. Gossip protocol keeps topology consistent across all nodes.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ADDING A NODE</div><div class=\"choice-val\">New node announces itself via gossip. Cassandra assigns 256 new tokens scattered across the ring. Each existing node streams a portion of its data to the new node for exactly the token ranges the new node now owns. No downtime. No manual resharding.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Redis Cluster \u2014 16,384 Hash Slots</div><span class=\"sd-example-tag\">HASH SLOTS \u00b7 CLUSTER BUS</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">SLOT ASSIGNMENT</div><div class=\"choice-val\">Every key \u2192 <code>CRC16(key) % 16384</code> \u2192 slot number 0\u201316383. Slots are assigned to master nodes: node-A owns 0\u20135460, node-B owns 5461\u201310922, node-C owns 10923\u201316383. Each node stores a 2KB bitmap of its slots, propagated via gossip.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">MOVED REDIRECT</div><div class=\"choice-val\">Client sends GET to wrong node \u2192 node responds <code>MOVED 7892 192.168.1.2:6380</code> \u2192 client redirects to correct node. Smart clients (jedis, redis-py) cache the slot\u2192node map and go direct after first lookup. One extra hop max.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">HASH TAGS</div><div class=\"choice-val\">Multi-key operations require co-location: <code>{user:123}.profile</code> and <code>{user:123}.sessions</code> \u2014 only the content inside <code>{}</code> determines the slot. Both land on same node, enabling MGET, MULTI/EXEC across these keys.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">RESHARDING</div><div class=\"choice-val\"><code>redis-cli --cluster reshard</code> migrates slots between nodes using <code>MIGRATE</code> command. Each key is migrated atomically. During migration, ASKING redirects handle requests for keys mid-migration. Online resharding with zero downtime.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">DynamoDB \u2014 Adaptive Capacity + Auto-Sharding</div><span class=\"sd-example-tag\">MANAGED \u00b7 TRANSPARENT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PARTITION KEY DESIGN</div><div class=\"choice-val\">DynamoDB uses your partition key as the hash input. Good partition keys have high cardinality and uniform access: <code>user_id</code> (millions of users, random access). Bad: <code>status</code> (3 values, \"active\" gets 99% of traffic \u2192 hot partition).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WRITE SHARDING PATTERN</div><div class=\"choice-val\">For hot keys: add a random suffix 1\u2013N to partition key at write time. At read time, scatter-gather N partitions. Example: <code>game:chess#{random(1,10)}</code> distributes writes across 10 partitions. DynamoDB documentation calls this \"write sharding.\"</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ADAPTIVE CAPACITY</div><div class=\"choice-val\">DynamoDB automatically detects hot partitions and splits them, providing additional throughput capacity. This is transparent \u2014 no application changes. Works for read-heavy hot spots; for write-heavy you still need write sharding.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"rendezvous\">\n  <div class=\"sec-tag\">05 \u00b7 Rendezvous Hashing</div>\n  <h2>The alternative to consistent hashing \u2014 and when it wins</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">HRW Algorithm</div><div class=\"concept-def\"><strong>Highest Random Weight (HRW): to assign key K, compute hash(K, server_i) for every server. Pick the server with the highest score.</strong><br>\n      For key \"user:123\" with 3 servers:<br>\n      hash(\"user:123\", \"server-A\") = 0.72 \u2190 winner<br>\n      hash(\"user:123\", \"server-B\") = 0.45<br>\n      hash(\"user:123\", \"server-C\") = 0.61<br>\n      \u2192 Server-A owns \"user:123\". If Server-A is removed, each key independently recomputes and picks the next-highest server.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">vs Consistent Hashing</div><div class=\"concept-def\"><strong>Rendezvous achieves the same minimal disruption property (1/N keys move on server removal) without a ring data structure.</strong><br>\n      Advantages: No ring, no vnodes, perfect load distribution by default, any client can compute independently without shared state.<br>\n      Disadvantage: O(N) computation per key (hash against every server). With 1,000 servers and 1M requests/sec, this becomes expensive.<br>\n      Consistent hashing with a sorted ring: O(log N) lookup.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used by: Akamai CDN (original design), some load balancers. Not common in databases where consistent hashing dominates.</span></div></div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 Interview Decision Framework</div>\n  <h2>How to structure your answer in a sharding conversation</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Sharding Strategy \u2014 The 5 Questions to Answer</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your access pattern \u2014 random key lookups or range scans?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Random lookups \u2192</span><span class=\"opt-text\"><strong>Hash-based partitioning (consistent hashing or hash slots).</strong> Distributes load evenly. O(1) point lookups. Used for: cache, user profiles, session data, key-value stores.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Range scans \u2192</span><span class=\"opt-text\"><strong>Range-based partitioning.</strong> Time-series data, leaderboards, ordered IDs. All records in a range are co-located on one shard \u2192 efficient range reads. Used by: HBase, BigTable, InfluxDB, CockroachDB.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Is your data distribution uniform or skewed?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Uniform (user_id, session_id) \u2192</span><span class=\"opt-text\"><strong>Simple consistent hashing works well.</strong> Random distribution means no shard will be disproportionately hot.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Skewed (celebrity users, trending events) \u2192</span><span class=\"opt-text\"><strong>Consistent hashing + hot spot mitigation.</strong> Key salting, fan-out on write, or in-process caching for the hot keys. Consistent hashing alone is not sufficient.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need cross-shard transactions or multi-key operations?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Yes \u2014 need ACID across shards \u2192</span><span class=\"opt-text\"><strong>Use co-location strategy.</strong> Hash tags (Redis) or entity grouping (DynamoDB: user + all their posts in same partition). Design schema so related data lands on the same shard, eliminating cross-shard ops.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">No \u2014 operations are single-key \u2192</span><span class=\"opt-text\"><strong>Pure consistent hashing.</strong> Each key routes independently. Most cache workloads and many NoSQL workloads fall here.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you own the infrastructure or use a managed service?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Managed (DynamoDB, Cosmos) \u2192</span><span class=\"opt-text\"><strong>Focus on partition key design.</strong> The sharding mechanism is transparent. Your job: choose a partition key with high cardinality and uniform access. Let the service handle sharding.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Self-managed (Cassandra, Redis Cluster) \u2192</span><span class=\"opt-text\"><strong>Choose vnode count, replication factor, and topology strategy upfront.</strong> Changing these later requires costly resharding. Plan for 5x current data size minimum.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Why does Redis Cluster use 16,384 slots specifically \u2014 why not 65,536 or 1,024?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>16,384 was chosen as a balance between cluster heartbeat message size and practical flexibility.</strong><br><br>Every Redis node sends heartbeat messages to all other nodes containing a bitmap of which slots it owns. 16,384 slots = 16,384 bits = exactly 2KB per bitmap. This fits comfortably in a single network packet and keeps gossip overhead trivial even in large clusters.<br><br>Why not more? 65,536 slots would make the bitmap 8KB \u2014 4x larger gossip overhead for no practical benefit. Redis's creator Antirez noted that even with 1,000 nodes, 16 slots per node gives ample granularity for resharding. In practice most clusters have 10\u201330 nodes, giving 500\u20131,600 slots per node \u2014 plenty of flexibility.<br><br>Why not fewer? With 1,024 slots and 100 nodes, you only have 10 slots per node. Resharding granularity becomes coarse \u2014 you'd need to move large chunks of data at once.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does consistent hashing handle data replication across failure domains (racks, AZs)?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Topology-aware replication strategies ensure replicas land on different failure domains, not just different nodes.</strong><br><br>Cassandra's NetworkTopologyStrategy: for each replica beyond the first, skip over nodes in the same rack when walking clockwise. This guarantees that for RF=3 with 3 racks, each rack holds exactly one replica.<br><br>Example: key hashes to node-A1 (rack 1 \u2192 primary). Walk clockwise for first replica: node-B1 (rack 1, same rack) \u2192 skip \u2192 node-A2 (rack 2) \u2192 first replica. Walk for second replica: node-A2 was just assigned, continue \u2192 node-B2 (rack 2, same rack as A2) \u2192 skip \u2192 node-A3 (rack 3) \u2192 second replica.<br><br>Result: replicas span 3 different racks. If rack 1 loses power, 2 of 3 replicas are still available. Reads continue at quorum.<br><br>AWS DynamoDB does this transparently across AZs \u2014 every partition always has 3 replicas across 3 different AZs. You don't configure it; it's the default.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What happens during a network partition \u2014 can consistent hashing nodes disagree about who owns what?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Yes, and this is where the CAP theorem intersects with consistent hashing.</strong><br><br>If a network partition separates a 6-node Cassandra cluster into two groups of 3, both groups continue operating \u2014 AP choice. Each group believes the other's nodes are down and tries to serve all keys. When the partition heals, Cassandra uses read repair and anti-entropy to reconcile divergent writes using \"last write wins\" (LWW) based on timestamps, or vector clocks for conflict detection.<br><br>Redis Cluster makes a different choice: during a partition, the minority partition (fewer than N/2+1 nodes) stops accepting writes \u2014 CP choice. The majority partition continues serving. When the partition heals, the minority replicas catch up from the majority. This prevents split-brain writes but means the minority partition is unavailable during the network outage.<br><br>This is a fundamental design decision you must make when designing sharded systems: do you want availability or consistency during partitions?</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How would you design a globally distributed sharding scheme across 3 data centres?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Geo-distributed sharding combines consistent hashing with geo-routing and topology-aware replication.</strong><br><br>Approach 1 \u2014 Single global ring with DC-aware placement: one ring, vnodes spread across all 3 DCs. NetworkTopologyStrategy ensures each DC holds its share of replicas. Cassandra supports this natively. Write to LOCAL_QUORUM (majority within one DC), replicate asynchronously to other DCs.<br><br>Approach 2 \u2014 Regional sharding + global routing: each DC is an independent cluster owning its regional data. A global routing layer (DNS geo-routing + application-level user-to-DC affinity) routes each user to their home DC. Cross-DC reads are forwarded to the owning DC. Used by: Shopify (data residency), WhatsApp (region-based data sovereignty).<br><br>Approach 3 \u2014 Active-active multi-master: data is replicated to all DCs, any DC can serve any user. CRDTs or LWW handle conflicts. Used by: DynamoDB Global Tables, Cassandra multi-DC active-active. Highest availability, most complex conflict handling.</div></div>\n</section></div>\n<div class=\"footer\">CONSISTENT HASHING \u00b7 PARTITIONING \u00b7 VNODES \u00b7 REDIS CLUSTER \u00b7 CASSANDRA \u00b7 HOT SPOTS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Partitioning' },
  rate_limiting: { title: 'Rate Limiting & Throttling', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Rate Limiting & Throttling</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Rate Limiting & Throttling<br><em>Every algorithm from token bucket to sliding window counter, distributed implementation with Redis, multi-layer enforcement, and production system design examples.</em></h1>\n  <p class=\"hero-sub\">Every algorithm from token bucket to sliding window counter, distributed implementation with Redis, multi-layer enforcement, and production system design examples.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">Token Bucket</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Sliding Window</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Redis INCR/Lua</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Leaky Bucket</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">Circuit Breaker</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#why\">Why Rate Limit</a><a href=\"#algorithms\">Algorithms</a><a href=\"#distributed\">Distributed</a><a href=\"#layers\">Layers</a><a href=\"#examples\">System Design</a><a href=\"#decision\">Decision Tree</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"why\">\n  <div class=\"sec-tag\">00 \u00b7 Why Rate Limiting</div>\n  <h2>What collapses without it \u2014 the three failure modes</h2>\n  <p>A single misbehaving client, a buggy retry loop, or a credential-stuffing bot can send 100,000 requests per second to your API. Without rate limiting, your database absorbs all of it until it falls over \u2014 and every other user is impacted. Rate limiting is the contract between your API and the outside world.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Three failure modes you are actually defending against</div>\n    <div class=\"analogy-text\">\n      <strong>1. Accidental overload</strong>: A customer's backend has a bug \u2014 their retry loop goes infinite. They go from 10 req/sec to 100,000 req/sec. Without rate limiting: your API goes down for all customers. With it: their requests get 429s, your other customers are unaffected.<br><br>\n      <strong>2. Abuse / scraping</strong>: A competitor scrapes your entire product catalogue. Without limits: they steal your data and you pay the egress bill. With it: they hit limits at 1,000 requests/minute and give up.<br><br>\n      <strong>3. Brute force</strong>: An attacker tries 10M password combinations against your login endpoint. Without limits: they eventually succeed. With per-IP limits (5 attempts/minute): they'd need 32 years to try 10M passwords.\n    </div>\n  </div>\n</section>\n\n<section id=\"algorithms\">\n  <div class=\"sec-tag\">01 \u00b7 The Five Algorithms</div>\n  <h2>Token bucket, leaky bucket, fixed window, sliding window log, sliding window counter</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Token Bucket<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">Industry Standard</span></div>\n      <div class=\"concept-def\"><strong>A bucket holds up to N tokens. Tokens refill at rate R per second. Each request consumes 1 token. Empty bucket = rejected request.</strong><br>\n        Example: capacity=100 tokens, refill=10/sec. A burst of 100 requests is served immediately (empties the bucket). Then max 10/sec sustained.<br>\n        Implementation: store <code>(token_count, last_refill_time)</code>. On each request: <code>tokens = min(capacity, stored_tokens + (now - last_refill) \u00d7 rate)</code>. If tokens \u2265 1: decrement and allow. Else: reject.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Allows legitimate burst traffic. O(1) memory per user. Smooth average enforcement. The AWS API Gateway, Stripe, and Twilio algorithm.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Two users can both exhaust their buckets at the same moment and both immediately refill \u2014 two full bursts back-to-back at window boundaries.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Leaky Bucket</div>\n      <div class=\"concept-def\"><strong>Requests enter a fixed-size queue (the bucket). They drain at a fixed rate (the leak). Queue full = requests dropped.</strong><br>\n        Enforces exactly R requests/second regardless of arrival rate. A burst of 100 arrives \u2014 100 enter the queue, they drain at 10/sec, all served over 10 seconds.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Perfectly smooth outbound rate. Protects downstream services that can only handle a fixed rate (DB connection pool, third-party API with strict QPS). No traffic spikes ever reach the downstream.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Burst requests experience queuing latency, not fast rejection. A slow legitimate request queues behind a burst attacker's requests. If queue fills, the most recent requests (possibly legitimate) are dropped.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Fixed Window</div>\n      <div class=\"concept-def\"><strong>Count requests per fixed time window. Reset counter at the boundary.</strong><br>\n        Example: 100 req/minute. Counter for window \"14:03\" resets at \"14:04:00.000\".<br>\n        Redis: <code>INCR ratelimit:user:123:14:03</code> \u2192 <code>EXPIRE key 60</code> \u2192 check count \u2264 100.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Simplest implementation. Single Redis INCR per request. Minimal memory.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 <strong>Boundary attack:</strong> 100 requests at 14:03:59 + 100 requests at 14:04:01 = 200 requests in 2 seconds \u2014 both within their respective windows. Set your limit 50% conservatively to compensate, or use sliding window.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Sliding Window Log</div>\n      <div class=\"concept-def\"><strong>Store a timestamp for every request in a sorted set. Count entries in the last N seconds. Reject if over limit.</strong><br>\n        Redis: <code>ZADD log:user:123 {now_ms} {now_ms}</code> \u2192 <code>ZREMRANGEBYSCORE log 0 {now_ms - window_ms}</code> \u2192 <code>ZCARD log</code> \u2192 compare to limit.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Perfectly accurate. No boundary attack possible. True rolling window at all times.</span><br>\n        <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Memory: O(requests per window) per user. At 1,000 req/min and 1M users: 1 billion sorted set entries. Only viable for low-rate, high-value endpoints: login, payment, account creation.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Sliding Window Counter<br><span style=\"font-size:10px;font-weight:400;color:#6a6458\">Production Choice</span></div>\n      <div class=\"concept-def\"><strong>Interpolate between current and previous fixed window counts to approximate a rolling window. O(1) memory, ~0.003% error rate.</strong><br>\n        <code>count = prev_window_count \u00d7 (1 - elapsed/window_size) + curr_window_count</code><br>\n        Example: window=1min, 40% through current minute. prev_window had 80 requests, current has 30.<br>\n        Estimated rolling count: <code>80 \u00d7 0.6 + 30 = 78</code>. Compare to limit.<br>\n        <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 O(1) memory (two counters per user). Accurate enough: Cloudflare uses this and measured &lt;0.003% incorrect rate limiting decisions. The practical production algorithm at scale.</span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"distributed\">\n  <div class=\"sec-tag\">02 \u00b7 Distributed Rate Limiting</div>\n  <h2>How to enforce limits correctly across 100 app servers</h2>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The core problem</div>\n    <p>Each app server sees only 1/100th of total traffic. If you rate-limit locally at 100 req/min per server with 100 servers, your effective global limit is 10,000 req/min \u2014 100x too permissive. You need a shared counter that all servers update atomically.</p>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis INCR<br>with Lua Script</div><div class=\"concept-def\"><strong>Atomic increment + check in a single Redis round trip using Lua.</strong><br>\n      <pre style=\"background:#f0ede6;padding:12px;border-radius:4px;font-size:11.5px;overflow-x:auto\">local key = KEYS[1]\nlocal limit = tonumber(ARGV[1])\nlocal window = tonumber(ARGV[2])\nlocal current = redis.call('INCR', key)\nif current == 1 then\n  redis.call('EXPIRE', key, window)\nend\nif current > limit then\n  return 0  -- rejected\nelse\n  return 1  -- allowed\nend</pre>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Lua executes atomically in Redis \u2014 no race between check and increment. One network round trip. Works correctly under any concurrency.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Token Bucket in Redis</div><div class=\"concept-def\"><strong>Atomic token bucket using Lua: refill tokens based on elapsed time, check, consume.</strong><br>\n      Key stores <code>[token_count, last_refill_timestamp]</code> as a hash.<br>\n      Lua script: (1) read current tokens and last refill time, (2) compute new tokens = min(capacity, stored + elapsed \u00d7 rate), (3) if tokens \u2265 1: set tokens\u22121, allow; else: reject.<br>\n      All in one atomic operation. Libraries: <code>redis-rate-limiter</code>, <code>redis-cell</code> (native Redis module).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Handles burst correctly in distributed context. Two servers both try to consume simultaneously \u2192 Lua serialises them \u2192 correct token count maintained.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Local Approximation<br>+ Async Sync</div><div class=\"concept-def\"><strong>Each server maintains a local counter. Sync to Redis every 100ms. Reduces Redis calls by 100x.</strong><br>\n      Each server allows up to <code>limit / server_count</code> requests locally before checking Redis. Every 100ms, flush local count to Redis, refresh local quota.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Reduces Redis round trips 100x at cost of slight inaccuracy. Burst of 200ms can exceed limit by up to <code>limit \u00d7 (100ms / window)</code>. Acceptable for most APIs.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Not suitable for strict financial or security rate limiting where brief overages could be exploited.</span></div></div>\n  </div>\n</section>\n\n<section id=\"layers\">\n  <div class=\"sec-tag\">03 \u00b7 Rate Limiting Layers</div>\n  <h2>Where to enforce \u2014 gateway vs application vs service mesh</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Layer</th><th>Where</th><th>Enforces On</th><th>Best For</th><th>Examples</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">API Gateway</td><td>Before any service code runs</td><td>IP, API key, user</td><td>External API protection, global limits per API plan, DDoS mitigation</td><td>AWS API Gateway, Kong, Apigee</td></tr>\n      <tr><td class=\"row-head\">Reverse Proxy / CDN</td><td>At edge, before origin</td><td>IP, ASN, geo</td><td>Absorbing DDoS before it hits your infra at all; IP-level throttling</td><td>Cloudflare, Nginx rate_limit module</td></tr>\n      <tr><td class=\"row-head\">Application</td><td>Inside your service</td><td>User ID, plan tier, feature</td><td>Business logic rate limits: plan-based (free/pro), per-feature, per-resource</td><td>Custom Redis middleware</td></tr>\n      <tr><td class=\"row-head\">Service Mesh</td><td>Sidecar proxy (Envoy)</td><td>Service-to-service</td><td>Protecting internal services from runaway microservices; circuit breaking</td><td>Istio, Envoy local rate limit</td></tr>\n      <tr><td class=\"row-head\">Database</td><td>DB connection pool</td><td>Connections, queries/sec</td><td>Preventing connection exhaustion; protecting DB from spike traffic</td><td>PgBouncer max_client_conn, HikariCP</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 System Design Examples</div>\n  <h2>Rate limiting in production systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Stripe \u2014 Multi-Dimensional API Rate Limiting</div><span class=\"sd-example-tag\">PAYMENTS \u00b7 TIERED</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">DIMENSIONS</div><div class=\"choice-val\">Stripe enforces rate limits on 3 independent dimensions simultaneously: per API key (100 req/sec), per endpoint (POST /charges: 25/sec separate from GET /customers), and per live/test mode (separate limits for test keys so testing doesn't consume production quota).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ALGORITHM</div><div class=\"choice-val\"><span class=\"badge b-g\">Token Bucket \u2713</span> Allows burst traffic from legitimate API integrations (a customer's batch job), while enforcing sustained average limits. Idempotency keys work with rate limiting \u2014 duplicate requests use the cached response without consuming a new token.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">HEADERS</div><div class=\"choice-val\"><code>Ratelimit-Limit: 100</code>, <code>Ratelimit-Remaining: 73</code>, <code>Ratelimit-Reset: 1742383260</code>. On 429: <code>Retry-After: 1</code> (seconds until next token available). Clients use these to implement exponential backoff + jitter before retrying.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TIERED LIMITS</div><div class=\"choice-val\">API key's plan tier stored in JWT or Redis hash. Free: 25/sec, Pro: 100/sec, Enterprise: custom. Tier checked once per request from JWT claim \u2014 zero extra Redis lookup for tier. Only limit counter needs Redis.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Login Endpoint \u2014 Security Rate Limiting</div><span class=\"sd-example-tag\">BRUTE FORCE \u00b7 AUTH</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">LAYERED DEFENCE</div><div class=\"choice-val\">3 independent limits: (1) per-IP: 10 login attempts / 10 minutes \u2014 stops distributed credential stuffing from one location. (2) per-username: 5 attempts / 15 minutes \u2014 stops password spraying on one account from many IPs. (3) global: 10K login attempts / minute \u2014 circuit breaker for the entire auth service.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ALGORITHM</div><div class=\"choice-val\"><span class=\"badge b-g\">Sliding Window Log \u2713</span> Exactly the right choice here. Login endpoint handles 10K/sec globally but the per-user limit is 5/15min \u2014 very small cardinality of allowed requests per user. Memory cost is acceptable. Accuracy matters \u2014 an attacker cannot exploit boundary timing.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PROGRESSIVE DELAYS</div><div class=\"choice-val\">After 3 failed attempts: add 1-second delay. After 5: add 5-second delay. After 10: lock account, require email verification. This is orthogonal to rate limiting \u2014 slows automated tools even within rate limits.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Notification Service \u2014 Outbound Rate Limiting</div><span class=\"sd-example-tag\">THIRD-PARTY API \u00b7 QUOTA</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PROVIDER LIMITS</div><div class=\"choice-val\">SendGrid allows 100K emails/hour. Twilio allows 1 SMS/sec per phone number. These are outbound limits \u2014 you rate-limit your own send rate to avoid hitting provider quotas that result in drops, not 429s you can handle.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ALGORITHM</div><div class=\"choice-val\"><span class=\"badge b-g\">Leaky Bucket \u2713</span> Queue all outbound notifications. Drain at exactly provider-allowed rate. Excess is buffered (queue), not dropped. For SendGrid: fill 100K tokens/hour (27 tokens/sec), drain 1 token per email sent. If queue grows: auto-scale workers within token availability.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">USER ANTI-SPAM</div><div class=\"choice-val\">Separate per-user limits: max 2 SMS per user per 10 minutes, max 5 emails per user per hour. Prevents notification spam to individual users from rogue internal services. Independent from the global send-rate limits.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">05 \u00b7 Decision Framework</div>\n  <h2>Choose the right algorithm for your use case</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Rate Limiting Algorithm Selection</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need to allow legitimate burst traffic?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (bursts OK) \u2192</span><span class=\"opt-text\"><strong>Token Bucket.</strong> Accumulates tokens during quiet periods. Allows burst up to bucket capacity. Standard choice for REST APIs, SDKs, and developer-facing APIs.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (strict smooth rate) \u2192</span><span class=\"opt-text\"><strong>Leaky Bucket.</strong> Enforces exactly R/sec regardless of arrival pattern. Use when protecting a downstream that cannot handle any spike: DB connection pool, third-party API, CPU-bound service.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">How important is boundary-attack resistance?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Critical (auth/payment) \u2192</span><span class=\"opt-text\"><strong>Sliding Window Log.</strong> Perfectly accurate. Immune to boundary timing attacks. Acceptable because rate limits are small (5 logins/15min) so memory cost is low.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">High scale, OK with ~0.003% error \u2192</span><span class=\"opt-text\"><strong>Sliding Window Counter.</strong> Cloudflare's production choice. O(1) memory. Handles billions of requests. Not perfectly accurate but close enough for all practical purposes.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Low stakes, simplicity first \u2192</span><span class=\"opt-text\"><strong>Fixed Window.</strong> Single Redis INCR. Set limit 50% conservatively to compensate for boundary doubling. Simple to implement, debug, and monitor.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the enforcement layer?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">External API traffic \u2192</span><span class=\"opt-text\"><strong>API Gateway layer.</strong> Kong, AWS API Gateway, or Nginx. Centralised enforcement before any application code runs. Language and framework agnostic.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Business logic limits (plan tiers) \u2192</span><span class=\"opt-text\"><strong>Application middleware.</strong> Redis-backed. Access to business context (user plan, feature flags). Apply different limits per tier.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Service-to-service internal \u2192</span><span class=\"opt-text\"><strong>Service mesh (Istio/Envoy).</strong> Circuit breaking + local rate limiting per sidecar. Prevents a runaway microservice from overwhelming its dependencies.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">06 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you implement tiered rate limits for free/pro/enterprise plans?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Embed the tier in the JWT, map to limits in config, use tier in the Redis key.</strong><br><br>JWT payload includes <code>\"plan\": \"pro\"</code> \u2014 decoded at the rate limit middleware with zero extra lookups. A config map translates plan to limit: <code>{\"free\": 25, \"pro\": 100, \"enterprise\": 10000}</code>. The Redis key includes the plan: <code>ratelimit:pro:user:123:minute</code>.<br><br>Why include plan in the key: if a user upgrades from free to pro mid-window, their free-plan counter simply stops being checked. The pro counter starts fresh. No need to invalidate or reset anything.<br><br>For enterprise customers with custom limits: store the custom limit in Redis itself (<code>ratelimit:config:user:123 = 50000</code>) with fallback to the plan default if not set. Check this config key on each request (cached in-process for 60 seconds to avoid per-request Redis lookups).</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What happens if your Redis rate limit store goes down?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>You must decide: fail open (allow all traffic) or fail closed (reject all traffic). There is no free lunch.</strong><br><br><strong>Fail open</strong>: if Redis is unreachable, allow all requests. Users see no degradation. Abuse is possible during the outage window. Acceptable for: consumer APIs where rate limits are about fairness, not security. Google's approach for most rate limiting.<br><br><strong>Fail closed</strong>: if Redis is unreachable, return 429 or 503. Zero abuse possible. Legitimate users are blocked. Acceptable for: payment APIs, authentication endpoints, anything where abuse has direct financial or security cost.<br><br><strong>Hybrid (recommended)</strong>: fall back to local in-process counters. Each app server tracks its own count. If Redis is down, enforce <code>limit / server_count</code> locally. This is slightly over-permissive (multiple servers don't coordinate) but functional. As soon as Redis recovers, switch back to shared counters. Redis Sentinel or Cluster ensures Redis outages are brief (&lt;30 seconds for automatic failover).</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you rate-limit on distributed clients \u2014 a user calling from multiple IPs or devices?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Rate limit on authenticated user identity, not on IP. IP-based limiting is supplementary only.</strong><br><br>The user's <code>user_id</code> extracted from their JWT is the primary rate limit key: <code>ratelimit:user:{user_id}:{window}</code>. This accumulates across all their devices, IPs, and sessions. A user signing in from phone + laptop + tablet all share the same quota. Prevents circumventing limits by rotating devices.<br><br>IP-based limiting runs in parallel as a separate independent limit \u2014 specifically for unauthenticated endpoints (login, signup, password reset) where you don't yet have a user_id. For these: <code>ratelimit:ip:{hashed_ip}:{window}</code>. Hash the IP (SHA-256 first 8 bytes) \u2014 prevents storing raw PII, harder to reverse than plain IP storage.<br><br>Never use IP as the sole mechanism for authenticated APIs \u2014 enterprise customers may have thousands of users behind a single NAT IP (corporate proxy, VPN). A per-IP limit of 1,000/min would mean 1 request per user per minute for a 1,000-person company behind one IP.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle the circuit breaker pattern as it relates to rate limiting?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Rate limiting and circuit breaking are complementary but solve different problems.</strong><br><br><strong>Rate limiting</strong>: \"You are sending too many requests \u2014 slow down.\" Applied at the entry point to protect your service from external or internal overload. Proactive.<br><br><strong>Circuit breaking</strong>: \"The downstream service is failing \u2014 stop sending requests to protect it and yourself.\" Applied at the exit point (your outbound calls to dependencies). Reactive to failure.<br><br>Circuit breaker states: Closed (normal, all requests pass through) \u2192 Open (downstream is failing, immediately return error without calling downstream) \u2192 Half-Open (probe with one request \u2014 if success, close; if failure, stay open).<br><br>They work together: rate limiting prevents your service from being overwhelmed. Circuit breaking prevents your service from overwhelming a failing dependency. In Envoy/Istio: configure both \u2014 rate limiting on the ingress side, circuit breaking on the egress side for each service call.</div></div>\n</section></div>\n<div class=\"footer\">RATE LIMITING \u00b7 TOKEN BUCKET \u00b7 SLIDING WINDOW \u00b7 REDIS \u00b7 CIRCUIT BREAKER \u00b7 TIERED PLANS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Rate Limiting' },
  distributed_systems: { title: 'Distributed Systems Fundamentals', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Distributed Systems: Fundamentals</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Distributed Systems<br><em>Fundamentals</em></h1>\n  <p class=\"hero-sub\">CAP theorem, PACELC, quorum reads/writes, Raft consensus, 2PC vs Saga, distributed locking with fencing tokens, vector clocks, CRDTs \u2014 from first principles to production patterns.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">CAP / PACELC</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">Raft Consensus</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Saga / 2PC</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Redlock / Fencing</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">CRDTs</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#cap\">CAP Theorem</a><a href=\"#consensus\">Raft Consensus</a><a href=\"#transactions\">Distributed Tx</a><a href=\"#locks\">Distributed Locks</a><a href=\"#clocks\">Clocks & CRDTs</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"cap\">\n  <div class=\"sec-tag\">00 \u00b7 CAP Theorem</div>\n  <h2>The fundamental constraint every distributed system lives with</h2>\n  <p>CAP theorem states that a distributed system can guarantee at most two of: Consistency, Availability, and Partition Tolerance. Since network partitions are inevitable in any real distributed system, the practical choice is always <strong>CP vs AP</strong> \u2014 you are choosing what to sacrifice during a network partition.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">CAP as a bank branch analogy</div>\n    <div class=\"analogy-text\">\n      Two bank branches connected by a telephone line. The line goes down (partition).<br><br>\n      <strong>CP \u2014 Consistency + Partition Tolerance:</strong> Both branches close to customers until the line is restored. No one gets incorrect balance info, but service is unavailable during the outage.<br><br>\n      <strong>AP \u2014 Availability + Partition Tolerance:</strong> Both branches stay open, serving customers independently. Service stays up. But when the line is restored, one branch shows \u20b950,000 and the other \u20b972,000 for the same account \u2014 they need to reconcile.<br><br>\n      <strong>The question is: would you rather return an error, or return potentially stale data?</strong> Both are wrong \u2014 the choice is about which kind of wrong is less harmful to your users.\n    </div>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">PACELC Extension</div><div class=\"concept-def\"><strong>CAP only describes partition behaviour. PACELC adds the normal-operation trade-off.</strong><br>\n      P \u2192 A vs C (partition: choose availability or consistency)<br>\n      E \u2192 L vs C (else: choose latency or consistency)<br>\n      Even without partitions, you must decide: serve reads from the nearest replica (low latency, possibly stale) or always read from primary (consistent, higher latency).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">DynamoDB: PA/EL \u2014 available during partition, low latency normally (reads from local region).<br>HBase: PC/EC \u2014 consistent during partition (stops accepting writes), consistent normally (always read from primary).<br>Cassandra: PA/EL by default \u2014 configurable per operation via consistency level.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Linearisability</div><div class=\"concept-def\"><strong>The strongest consistency model. Every operation appears to happen instantaneously at a single point in time, visible to all nodes simultaneously.</strong><br>\n      If write(X=1) completes before read(X) starts, read must return 1 \u2014 not a previous value, even from a stale replica.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 System behaves as if running on a single machine. No surprises. Required for: distributed locks, financial transactions, leader election, inventory decrement.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires consensus (Raft/Paxos round trip) on every write. High latency. Cannot scale across geographies without extremely high write latency (speed of light constraints).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Eventual Consistency</div><div class=\"concept-def\"><strong>If no new updates are made, all replicas will eventually converge to the same value. Reads during convergence may return stale data.</strong><br>\n      Convergence window: typically milliseconds to seconds in practice (not hours as the name might imply).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Highest availability and lowest latency. Scales globally with no cross-region coordination. Used by: DNS, CDN caches, social feed reads, product descriptions, shopping carts.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Applications must handle stale reads gracefully. Concurrent writes to the same key create conflicts \u2014 need resolution strategy: Last Write Wins (LWW), CRDTs, or application-level merge.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Quorum Reads/Writes</div><div class=\"concept-def\"><strong>Configurable consistency between linearisable and eventual: require acknowledgement from W of N write replicas, and read from R of N read replicas.</strong><br>\n      Strong consistency condition: W + R &gt; N (read and write quorums overlap).<br>\n      Example: N=3, W=2, R=2 \u2192 W+R=4 &gt; 3 \u2192 any read will see the latest write.<br>\n      Example: N=3, W=1, R=1 \u2192 W+R=2 \u2264 3 \u2192 eventual consistency (reads may miss latest write).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Cassandra: <code>QUORUM</code> = ceiling(N/2)+1. <code>LOCAL_QUORUM</code> = quorum within one DC only (lower latency). <code>ALL</code> = all N replicas (linearisable but fails if any replica is down).</span></div></div>\n  </div>\n</section>\n\n<section id=\"consensus\">\n  <div class=\"sec-tag\">01 \u00b7 Consensus \u2014 Raft</div>\n  <h2>How distributed systems agree on a single truth without a central coordinator</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">The Problem</div><div class=\"concept-def\"><strong>5 nodes must agree on the value of X despite any 2 nodes being down or sending wrong values.</strong><br>\n      Without consensus: node A believes X=1, node B believes X=2, node C is unreachable. What is the correct answer? Who breaks the tie? How do you ensure a decision made today is honoured after a crash and restart?<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Consensus is what makes etcd, ZooKeeper, Kafka (KRaft), and CockroachDB reliable \u2014 it is the foundation every distributed database is built on.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Raft \u2014 Leader Election</div><div class=\"concept-def\"><strong>Raft elects exactly one leader at a time. All writes go through the leader. Followers only accept log entries from the current leader.</strong><br>\n      Startup: all nodes start as followers with a random election timeout (150\u2013300ms). First node to time out becomes a candidate, increments term counter, requests votes from all nodes. First to receive majority (N/2+1) becomes leader \u2014 sends heartbeats to suppress new elections.<br>\n      Leader failure: followers stop receiving heartbeats \u2192 timeout \u2192 new election \u2192 new leader. Takes 150\u2013600ms in practice.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 At most one leader per term. Clear authority. Simple mental model. Used by: etcd (Kubernetes), CockroachDB, TiKV, Kafka (KRaft), Consul.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Raft \u2014 Log Replication</div><div class=\"concept-def\"><strong>Every write is appended to the leader's log as an entry. Leader replicates to all followers. Entry is committed when a majority acknowledges it.</strong><br>\n      Flow: client write \u2192 leader appends entry \u2192 sends AppendEntries RPC to all followers \u2192 majority acknowledge \u2192 leader commits \u2192 applies to state machine \u2192 responds to client \u2192 followers commit on next AppendEntries.<br>\n      Committed = durable. Even if the leader immediately crashes, the entry will be present on a majority of nodes and any new leader will have it.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Exactly how Kafka replication works (ISR). How etcd stores Kubernetes cluster state. How CockroachDB achieves ACID transactions across nodes.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Raft vs Paxos</div><div class=\"concept-def\"><strong>Paxos is theoretically equivalent but notoriously difficult to understand and implement correctly.</strong><br>\n      Raft was designed explicitly for understandability \u2014 the original paper's subtitle is \"In Search of an Understandable Consensus Algorithm.\" Raft makes stronger design choices (single strong leader, log matching) that simplify implementation at the cost of some theoretical flexibility.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">In interviews: always say Raft. You can explain it end-to-end. Paxos is of historical significance but Raft has replaced it in essentially all new distributed systems. Multi-Paxos (used in Chubby) is even more complex.</span></div></div>\n  </div>\n</section>\n\n<section id=\"transactions\">\n  <div class=\"sec-tag\">02 \u00b7 Distributed Transactions</div>\n  <h2>2PC, Saga pattern, and when to use each</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Two-Phase Commit<br>(2PC)</div><div class=\"concept-def\"><strong>A coordinator asks all participants to prepare, then commits only if all vote yes.</strong><br>\n      Phase 1 (Prepare): Coordinator sends \"can you commit?\" to all participants. Each participant: locks resources, writes prepare record to WAL, votes yes/no.<br>\n      Phase 2 (Commit/Abort): If all voted yes \u2192 send commit to all. Any voted no \u2192 send abort to all. Participants release locks.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 True ACID atomicity across multiple databases. All commit or none do.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 <strong>Blocking protocol:</strong> if coordinator crashes after Phase 1, participants hold locks indefinitely. Tight coupling \u2014 all participants must be available. 2 round trips minimum. Used in: PostgreSQL distributed (XA), Oracle, MySQL XA. <strong>Never use across microservice boundaries.</strong></span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Saga Pattern</div><div class=\"concept-def\"><strong>Decompose a distributed transaction into local transactions, each with a compensating transaction to undo on failure.</strong><br>\n      Order saga: (1) Reserve inventory \u2192 (2) Charge payment \u2192 (3) Create shipment \u2192 (4) Send confirmation.<br>\n      If step 3 fails: compensating transactions run in reverse \u2014 cancel shipment (no-op) \u2192 refund payment \u2192 release inventory.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No distributed locks. Services remain autonomous. Failures handled by compensation. The correct pattern for microservices. Eventually consistent \u2014 other services may see intermediate states.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Compensation logic must be idempotent and durable. Other services see partially-committed state during execution. Complex to reason about ordering. Requires careful saga state management.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Choreography vs<br>Orchestration Saga</div><div class=\"concept-def\"><strong>Two implementation styles for Saga \u2014 fundamentally different operational characteristics.</strong><br>\n      <strong>Choreography:</strong> each service publishes an event after completing its step. The next service listens for the event and acts. No central coordinator. Services communicate through events (Kafka).<br>\n      <em>Problem: hard to debug. \"Where is my order?\" requires tracing events across multiple services and queues.</em><br><br>\n      <strong>Orchestration:</strong> a saga orchestrator (Temporal, AWS Step Functions, a dedicated service) explicitly calls each step and decides what to do on failure.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Orchestration is easier to monitor, debug, and reason about. The orchestrator maintains full saga state. Temporal.io is the modern standard for saga orchestration.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Idempotency</div><div class=\"concept-def\"><strong>An operation that produces the same result whether executed once or many times.</strong><br>\n      Critical because: network failures cause retries, message queues deliver at-least-once, and saga compensation steps may run multiple times if they fail mid-way.<br>\n      Implementation: client includes a unique <code>idempotency_key</code> per operation. Server stores <code>(idempotency_key \u2192 result)</code> in DB. On duplicate: return stored result without re-executing.<br>\n      Database pattern: <code>INSERT INTO orders ... ON CONFLICT (idempotency_key) DO NOTHING</code> \u2014 atomic, no need for an explicit lookup first.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Safe retries under any failure scenario. Stripe, PayPal, Twilio all require idempotency keys on mutating API calls.</span></div></div>\n  </div>\n</section>\n\n<section id=\"locks\">\n  <div class=\"sec-tag\">03 \u00b7 Distributed Locking</div>\n  <h2>Redlock, etcd, and the fencing token pattern</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis SETNX Lock</div><div class=\"concept-def\"><strong>Simple distributed lock: SET key value NX EX ttl.</strong><br>\n      Acquire: <code>SET lock:resource unique_id NX EX 30</code> \u2014 NX = only if not exists, EX 30 = auto-expire in 30s.<br>\n      Release (atomic via Lua): check owner then delete: <code>if GET(key) == unique_id then DEL(key)</code>.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Works correctly with a single Redis instance. Simple, fast (&lt;1ms). Adequate for most use cases where brief lock loss on Redis failure is acceptable.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Single Redis node = single point of failure. If Redis crashes between SETNX and EXPIRE (in older implementations): lock held forever. Use the atomic <code>SET NX EX</code> single command to avoid this.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redlock Algorithm</div><div class=\"concept-def\"><strong>Acquire lock on majority (3 of 5) independent Redis nodes.</strong><br>\n      Steps: (1) Record start time. (2) Sequentially try to acquire lock on all 5 independent Redis nodes with small timeout (5ms each). (3) Lock acquired if: \u22653 nodes succeeded AND total elapsed time &lt; lock TTL minus clock drift margin. (4) On failure: release lock on all nodes.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Survives failure of 2 of 5 Redis nodes. No single point of failure.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Martin Kleppmann published a critique: GC pauses and clock skew can cause two clients to both believe they hold the lock. For truly critical systems (financial, coordination): use etcd/ZooKeeper with fencing tokens.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Fencing Tokens</div><div class=\"concept-def\"><strong>Every time a lock is granted, issue a monotonically increasing fencing token. The protected resource rejects writes with older tokens.</strong><br>\n      Client A acquires lock, gets token=33. Client A pauses (GC). Lock expires. Client B acquires lock, gets token=34. Client A resumes, sends write with token=33. Storage rejects it: \"I've already seen token=34.\"<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Correct under all failure scenarios including GC pauses, clock skew, and slow networks. The only fully safe distributed locking pattern.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">etcd provides this natively: each lease has a revision number. Store systems like S3 conditionally (ETag + If-Match) and databases with optimistic locking implement the same pattern.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">etcd / ZooKeeper</div><div class=\"concept-def\"><strong>CP systems built on Raft consensus \u2014 correct distributed locking under all failure scenarios.</strong><br>\n      etcd: <code>PUT /locks/resource?prevExist=false</code> with a lease TTL. Raft ensures only one leader can grant the lock cluster-wide. Linearisable reads guarantee no stale state.<br>\n      ZooKeeper: ephemeral znodes \u2014 the lock is an ephemeral node. If the lock holder's session expires (crash), ZooKeeper automatically deletes the ephemeral node, releasing the lock.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Correct under all scenarios. Used by: Kubernetes leader election (etcd), distributed job schedulers, Kafka broker coordination (ZooKeeper historically, now KRaft).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Higher latency than Redis (Raft round trip = 5\u201310ms). Operational complexity of running a Raft cluster.</span></div></div>\n  </div>\n</section>\n\n<section id=\"clocks\">\n  <div class=\"sec-tag\">04 \u00b7 Clocks & Ordering</div>\n  <h2>Why you cannot trust wall-clock timestamps in distributed systems</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Clock Skew</div><div class=\"concept-def\"><strong>Servers in different data centres have different clocks, even with NTP. Typical skew: 1\u2013100ms. Worst case: seconds.</strong><br>\n      Server A timestamps event at 14:00:01.000. Server B timestamps its event at 14:00:00.998. B appears to have happened first \u2014 but it actually happened after A's event.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Never use wall-clock timestamps for causal ordering. \"Last Write Wins\" based on timestamps will silently discard correct writes when clocks are skewed. Cassandra's LWW uses this \u2014 it works in practice because NTP skew is usually small, but it is theoretically unsound.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Lamport Clocks</div><div class=\"concept-def\"><strong>Logical clock: a counter that captures \"happened-before\" relationships without requiring synchronised clocks.</strong><br>\n      Rules: (1) Increment counter on every local event. (2) When sending a message, include current counter. (3) On receiving a message with counter C: set local counter to max(local, C) + 1.<br>\n      Guarantee: if event A happened-before event B (causally), then Lamport(A) &lt; Lamport(B). But the converse is not true \u2014 two events with comparable Lamport times might not be causally related.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used by: Cassandra timestamps (wall clock + client-side Lamport), logical replication in PostgreSQL.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Vector Clocks</div><div class=\"concept-def\"><strong>One Lamport counter per node. Captures causality and detects concurrent events precisely.</strong><br>\n      Node A: [A:2, B:1, C:0]. A sends message to B. B updates to [A:2, B:2, C:0].<br>\n      Compare two events: if every element of clock1 \u2264 clock2 and any element is strictly less, clock1 happened-before clock2. If neither dominates the other: they are concurrent (a conflict).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Detects concurrent writes precisely. Amazon Dynamo original paper used vector clocks for shopping cart conflict detection. Riak database uses them.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Vector size grows with number of nodes. Conflict resolution still needs application logic (merge, user choice, or CRDT).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">CRDTs</div><div class=\"concept-def\"><strong>Conflict-free Replicated Data Types: data structures that can be merged from any two replicas without conflict, by design.</strong><br>\n      G-Counter (grow-only): each node has its own counter. Merge = take max of each node's counter. Sum = total across all nodes. Concurrent increments on different nodes are automatically merged correctly.<br>\n      PN-Counter (positive-negative): two G-counters. Supports increment and decrement. Used for: like counts, view counts, inventory.<br>\n      OR-Set: add-wins set. Can add and remove elements concurrently \u2014 add wins on conflict.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No coordination needed for merging. Perfect for: shared documents (Google Docs uses CRDT-like structures), distributed counters, real-time collaboration. Used by: Riak, Redis (some data types), Apple Notes.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 System Design Examples</div>\n  <h2>Distributed systems patterns in real production systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Kubernetes \u2014 etcd as the Brain</div><span class=\"sd-example-tag\">CP \u00b7 RAFT \u00b7 LINEARISABLE</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WHAT etcd STORES</div><div class=\"choice-val\">All cluster state: which pods are running on which nodes, service definitions, config maps, secrets, RBAC rules. etcd is a CP system \u2014 during a partition, it stops accepting writes rather than risk divergent cluster state.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LEADER ELECTION</div><div class=\"choice-val\">Only one API server writes to etcd at a time (via Raft). kube-controller-manager and kube-scheduler use etcd-backed leases for leader election \u2014 only the leader instance processes changes. etcd's fencing token (revision number) prevents stale leaders from writing.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT AP</div><div class=\"choice-val\">If Kubernetes used an AP datastore and two controller-manager replicas disagreed about cluster state during a partition, they'd both try to schedule pods \u2014 creating duplicate deployments, split-brain scheduling, or conflicting resource allocation. CP is the only safe choice for infrastructure coordination.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Food Delivery App \u2014 Order Saga</div><span class=\"sd-example-tag\">SAGA PATTERN \u00b7 TEMPORAL</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">SAGA STEPS</div><div class=\"choice-val\">(1) Create order record \u2192 (2) Reserve restaurant slot \u2192 (3) Charge customer \u2192 (4) Assign delivery partner \u2192 (5) Notify customer. Each step is a local transaction. Each has a compensating transaction.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FAILURE AT STEP 3</div><div class=\"choice-val\">Payment fails. Compensating transactions: cancel restaurant reservation (step 2 compensation) \u2192 mark order as failed (step 1 compensation). Customer sees \"payment failed\" immediately. No money was charged. Restaurant slot is freed. Delivery partner was never assigned \u2014 no compensation needed.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ORCHESTRATION</div><div class=\"choice-val\">Temporal workflow manages the saga state durably. Each step is a Temporal activity. If the Temporal worker crashes mid-saga, it resumes from the last completed step on restart. The saga state is stored in Temporal's backend database. No lost orders, no orphaned state.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">EVENTUAL CONSISTENCY</div><div class=\"choice-val\">Between step 2 (restaurant reserved) and step 3 (payment charged), the restaurant service sees a reservation that might get cancelled. This intermediate state is visible. The restaurant app must handle \"pending\" states gracefully \u2014 not assume all reservations become confirmed orders.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Google Spanner \u2014 Globally Linearisable</div><span class=\"sd-example-tag\">CP \u00b7 TRUETIME \u00b7 GLOBAL</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TRUETIME</div><div class=\"choice-val\">GPS + atomic clocks provide bounded time uncertainty: current time is somewhere in interval [earliest, latest]. Uncertainty typically 7ms. Spanner waits out this uncertainty window before committing \u2014 ensures all nodes agree on transaction ordering without a Raft round trip per write.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LINEARISABLE GLOBALLY</div><div class=\"choice-val\">A transaction committed in Singapore is immediately visible to a read in Frankfurt \u2014 even though those data centres are separated by 150ms of latency. Spanner achieves this by assigning commit timestamps from TrueTime and delaying reads until their timestamp is safely in the past.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">REPLICATION</div><div class=\"choice-label\">WHY UNIQUE</div><div class=\"choice-val\">You cannot replicate Spanner without GPS/atomic clock hardware. CockroachDB approximates it with NTP (larger uncertainty window, uses Raft where Spanner uses TrueTime). For your system design: use Spanner for truly global ACID at the cost of 7ms commit latency. Use CockroachDB as an open-source alternative.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">06 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does split-brain happen and how do you prevent it?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Split-brain: a network partition causes two groups of nodes to both believe they are the active primary, leading to divergent writes and data corruption.</strong><br><br>Example: 6-node cluster, partition splits into group of 4 and group of 2. Both groups try to elect a leader. Both succeed (within their own group). Both accept writes. When partition heals: two divergent histories, conflicting data.<br><br><strong>Prevention:</strong><br>1. <strong>Quorum writes</strong>: require majority (N/2+1) acknowledgement. The minority partition (2 nodes) cannot achieve quorum and stops accepting writes. Only the majority (4 nodes) proceeds. Raft enforces this automatically.<br><br>2. <strong>Fencing tokens</strong>: new leader gets a higher epoch/term number. Old leader's writes are rejected by storage systems that have seen the higher epoch.<br><br>3. <strong>Witness nodes</strong>: a lightweight tiebreaker node with no data \u2014 only votes. 2-node cluster \u2192 add a 3rd witness. Split 1+1+witness: majority requires 2 votes. Used by: SQL Server Availability Groups, some Cassandra configurations.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between linearisability and serializability?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>They solve different problems at different granularities \u2014 commonly confused in interviews.</strong><br><br><strong>Linearisability</strong>: applies to single operations on individual keys. Every read/write appears to happen atomically at a single point in time, globally visible. \"If you write X=1 and then I read X, I must see 1.\" A property of the key's operation history.<br><br><strong>Serializability</strong>: applies to transactions (groups of operations across potentially many keys). The result of concurrent transactions is equivalent to some serial execution order. \"My multi-step bank transfer looks as if no other transaction interleaved with it.\" A property of the database's transaction isolation.<br><br><strong>Strict Serializability</strong> (= Linearisable + Serializable): transactions are both serialised AND appear instantaneous. The gold standard. Spanner and CockroachDB provide this globally. Most expensive guarantee, but the one you want for financial systems.<br><br>Common systems: PostgreSQL SERIALIZABLE isolation is serializable but not linearisable (a replica read can be stale). Spanner is strictly serializable. Cassandra with QUORUM is neither (it provides tunable consistency, not transactions).</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle the compensating transaction failing in a Saga?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Compensating transactions must be idempotent and retried with exponential backoff until they succeed. They should never be allowed to permanently fail.</strong><br><br>Make compensating transactions idempotent: \"cancel reservation for order X\" executed twice should have the same effect as once (the second execution finds the reservation already cancelled \u2014 this is success, not an error).<br><br>Retry strategy: persistent retry queue (Kafka DLQ or dedicated retry table in DB). Each failed compensation attempt is re-enqueued with exponential backoff (1s, 2s, 4s, 8s...) and a max retry count.<br><br>What if compensation is permanently impossible? Example: payment refund fails because customer's card is closed. This is a \"business exception\" \u2014 not a technical failure. Route to a manual operations queue. Ops team handles it (alternative refund method, store credit, etc.). This is expected in production at large scale \u2014 Saga frameworks like Temporal provide a UI for exactly this: paused sagas requiring human intervention.<br><br>Design principle: compensation must always eventually succeed or escalate to human handling. Never silently drop a failed compensation \u2014 that leaves orphaned state in your system.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does Cassandra handle concurrent writes to the same key?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Cassandra uses Last Write Wins (LWW) \u2014 the write with the highest timestamp wins. This is correct most of the time but has known edge cases.</strong><br><br>Two concurrent writes to the same key from different nodes: write A has timestamp 14:00:01.000, write B has timestamp 14:00:00.998 (clock skewed). Write A wins \u2014 it has the higher timestamp. Write B is silently discarded, even though B might have been the \"correct\" or \"intended\" final value from the application's perspective.<br><br>Why Cassandra accepts this tradeoff: NTP clock skew is typically &lt;1ms on modern hardware. The probability of two writes in the same millisecond to the same key is very low for most workloads. And Cassandra is optimised for write-heavy, high-scale workloads where this tradeoff (very rare silent overwrites vs guaranteed write availability) is acceptable.<br><br>When it is not acceptable: financial data, counters (use Cassandra counters with conditional updates), any data where silent overwrites are unacceptable. For these: use CAS (Compare-And-Set with Lightweight Transactions) which uses Paxos for coordination \u2014 but at 4x the latency cost.</div></div>\n</section></div>\n\n  <h3>Consistency Model Decision Tree</h3>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Which Consistency Model for Your System?</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Can your users tolerate seeing stale data (even briefly)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2014 must be fresh \u2192</span><span class=\"opt-text\"><strong>Strong consistency (CP).</strong> Every read reflects the latest write. Use: financial balances, inventory counts, seat reservations. Tools: PostgreSQL, CockroachDB, Spanner. Accept higher latency and reduced availability during partitions.</span></div>\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2014 staleness OK \u2192</span><span class=\"opt-text\">Go to Step 2. Eventual consistency is viable.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the acceptable staleness window?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Seconds OK \u2192</span><span class=\"opt-text\"><strong>Eventual consistency with read-your-own-writes.</strong> Social feeds, product pages, user profiles. DynamoDB (eventually consistent reads), Cassandra (ONE consistency). Add read-your-own-writes: route user's reads to primary for 5s after any write they made.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Minutes OK \u2192</span><span class=\"opt-text\"><strong>Pure eventual consistency.</strong> Analytics dashboards, recommendation engines, search indexes. Cassandra ONE, DynamoDB eventuallyConsistent. Maximum availability and lowest latency.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need cross-shard / cross-service transactions?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">YES \u2014 multi-entity atomic \u2192</span><span class=\"opt-text\"><strong>Saga pattern</strong> for microservices. Each step is a local transaction with a compensating transaction on failure. <strong>Never use 2PC in microservices</strong> \u2014 it creates distributed locks that block on coordinator failure.</span></div>\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">NO \u2014 single entity \u2192</span><span class=\"opt-text\"><strong>Single-node transaction or single-shard operation.</strong> Design your data model so related data lives on the same shard. Avoid cross-shard operations in the hot path.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n<div class=\"footer\">DISTRIBUTED SYSTEMS \u00b7 CAP \u00b7 RAFT \u00b7 SAGA \u00b7 IDEMPOTENCY \u00b7 VECTOR CLOCKS \u00b7 CRDTs \u00b7 FENCING \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Distributed Sys' },
  load_balancing: { title: 'Load Balancing & Proxies', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Load Balancing: Proxies & Gateways</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Load Balancing<br><em>Proxies & Gateways</em></h1>\n  <p class=\"hero-sub\">L4 vs L7, load balancing algorithms, circuit breakers, API Gateway vs service mesh, and zero-downtime deployments \u2014 every concept needed for system design interviews.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:rgba(26,79,138,.08)\">L4 / L7</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:rgba(26,122,74,.08)\">Nginx</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:rgba(184,114,10,.08)\">Envoy</span><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:rgba(192,57,43,.08)\">Circuit Breaker</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:rgba(96,64,160,.08)\">Service Mesh</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#why\">Why LB</a><a href=\"#l4vsl7\">L4 vs L7</a><a href=\"#algorithms\">Algorithms</a><a href=\"#patterns\">Advanced Patterns</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"why\">\n  <div class=\"sec-tag\">00 \u00b7 Why Load Balancing</div>\n  <h2>The first component in every system diagram</h2>\n  <p>A single server handling all traffic is a single point of failure and a performance ceiling. Load balancers distribute traffic across a fleet of servers, enabling horizontal scaling and eliminating single points of failure. In every FAANG system design diagram, the first arrow after \"Client\" points to a load balancer.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The supermarket checkout analogy</div>\n    <div class=\"analogy-text\">\n      A supermarket has 10 checkout lanes. A greeter (load balancer) at the entrance directs each customer to the shortest queue. Without the greeter, everyone crowds into lane 1 while lanes 2\u201310 sit empty.<br><br>\n      <strong>L4 load balancer</strong> = greeter who only looks at which lane is least busy (doesn't care what's in your cart).<br>\n      <strong>L7 load balancer</strong> = greeter who reads your items and sends produce-only carts to lane 3 (express), bulk items to lane 7 (large cart), etc.\n    </div>\n  </div>\n</section>\n\n<section id=\"l4vsl7\">\n  <div class=\"sec-tag\">01 \u00b7 L4 vs L7</div>\n  <h2>The most important distinction in load balancing</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">L4 (Transport Layer)</div><div class=\"concept-def\"><strong>Routes based on IP address and TCP/UDP port only. Does not inspect packet contents.</strong><br>\n      Decision: \"This TCP connection from 1.2.3.4 goes to server B.\"<br>\n      One TCP connection between client and server \u2014 the LB just forwards packets.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Extremely fast \u2014 no parsing overhead. Works for any protocol (TCP, UDP, SMTP, MySQL). Lower latency. Used for high-throughput, low-overhead routing.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cannot make routing decisions based on URL, headers, cookies, or content. Cannot terminate SSL. Cannot implement application-level health checks.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: AWS NLB (Network Load Balancer), HAProxy in TCP mode, Linux IPVS.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">L7 (Application Layer)</div><div class=\"concept-def\"><strong>Inspects HTTP headers, URL paths, cookies, and body to make routing decisions. Terminates the client connection and opens a new one to the backend.</strong><br>\n      Decision: \"This POST /api/payments request goes to the payments service. This GET /images/ request goes to the static content service.\"<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 URL-based routing (path-based or host-based). SSL termination (decrypts once at LB, unencrypted to backends). A/B testing and canary deploys. Rate limiting. Request/response transformation. Advanced health checks (HTTP 200 check, not just TCP connect).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Higher CPU overhead (parses every HTTP request). Slightly higher latency. Cannot handle raw TCP/UDP workloads.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: AWS ALB, Nginx, Envoy, Traefik, HAProxy in HTTP mode.</span></div></div>\n  </div>\n</section>\n\n<section id=\"algorithms\">\n  <div class=\"sec-tag\">02 \u00b7 Algorithms</div>\n  <h2>How the LB decides which server gets the request</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Round Robin</div><div class=\"concept-def\"><strong>Distribute requests evenly in rotation: server 1, 2, 3, 1, 2, 3...</strong><br>\n      Simple and fair for homogeneous servers with similar request costs.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Fails when servers have different capacities or when request cost varies (a 10ms request and a 5-second request are treated identically).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Weighted Round Robin</div><div class=\"concept-def\"><strong>Servers get traffic proportional to their weight.</strong> Server A (32 cores) gets 2x traffic of Server B (16 cores).<br>\n      Useful during rolling deploys: new servers start with weight=0, gradually increased.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Handles heterogeneous fleets. Natural fit for canary deployments (weight new version at 5%).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Least Connections</div><div class=\"concept-def\"><strong>Route to the server with fewest active connections currently.</strong><br>\n      Ideal for long-lived connections or variable request duration (WebSocket, video streaming, large file uploads).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Naturally load-balances when request durations vary. A slow server accumulates connections and receives fewer new ones.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires the LB to track active connections per server \u2014 state overhead.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Consistent Hash</div><div class=\"concept-def\"><strong>Route requests from the same source (IP or user ID) to the same server consistently.</strong><br>\n      Required for: WebSocket connections (must reach the same server), stateful sessions without a shared cache, server-side caching (cache warm on one server).<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Can create hot spots if one user generates disproportionate traffic. Server removal disrupts affected users.</span></div></div>\n  </div>\n</section>\n\n<section id=\"patterns\">\n  <div class=\"sec-tag\">03 \u00b7 Advanced Patterns</div>\n  <h2>Circuit breaker, health checks, and service mesh</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Health Checks</div><div class=\"concept-def\"><strong>LB continuously probes backends. Unhealthy servers are removed from rotation.</strong><br>\n      Passive: track error rate and latency from real traffic. Remove servers exceeding threshold.<br>\n      Active: LB sends <code>GET /health</code> every 10s. If 3 consecutive failures \u2192 mark unhealthy \u2192 remove from pool.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Automatic removal of crashed instances without human intervention. Required for zero-downtime deployments.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Return 200 only when truly healthy: DB connected, dependencies up, startup complete. Not just \"process is running.\"</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Circuit Breaker</div><div class=\"concept-def\"><strong>Stop sending requests to a failing service instead of letting failures cascade.</strong><br>\n      Three states: Closed (normal) \u2192 Open (failures exceed threshold, stop sending) \u2192 Half-Open (send probe requests to check recovery).<br>\n      Example: Payment service is down. Without circuit breaker: all requests queue up, threads exhaust, your entire API times out. With circuit breaker: immediately return \"payment service unavailable\" and redirect to fallback.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Prevents cascade failures. Fast failure response. Used by: Netflix Hystrix, Envoy, Istio, Spring Cloud Circuit Breaker.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">API Gateway vs<br>Reverse Proxy vs<br>Service Mesh</div><div class=\"concept-def\"><strong>Three different things that are often confused:</strong><br>\n      <strong>Reverse Proxy</strong>: Sits in front of servers, forwards requests. Handles SSL, caching, compression. Example: Nginx.<br>\n      <strong>API Gateway</strong>: Smart reverse proxy with auth, rate limiting, request routing by path, API versioning, request/response transformation. Example: Kong, AWS API Gateway.<br>\n      <strong>Service Mesh</strong>: Sidecar proxies (Envoy) injected next to every service. Handles service-to-service communication: mTLS, circuit breaking, load balancing, distributed tracing \u2014 all without changing application code. Example: Istio, Linkerd.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Use API Gateway for external traffic (public API). Use service mesh for internal service-to-service traffic at large scale.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 System Design Examples</div>\n  <h2>Load balancing decisions in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Uber \u2014 Multi-Tier Load Balancing</div><span class=\"sd-example-tag\">GLOBAL SCALE</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">GLOBAL DNS</div><div class=\"choice-val\">AWS Route 53 with latency-based routing directs users to nearest region (Bangalore \u2192 Mumbai region, New York \u2192 us-east). Geo-routing at DNS layer before any L4/L7 balancer is involved.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">EDGE (L4)</div><div class=\"choice-val\">AWS NLB handles raw TCP traffic at the edge of each region. Terminates TCP efficiently. Routes to L7 cluster. Handles DDoS mitigation via AWS Shield.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">APPLICATION (L7)</div><div class=\"choice-val\"><span class=\"badge b-g\">Envoy \u2713</span> Path-based routing: <code>/api/rides</code> \u2192 Ride Service, <code>/api/payments</code> \u2192 Payment Service. Handles auth (JWT validation), rate limiting, circuit breaking to downstream services.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WEBSOCKET</div><div class=\"choice-val\">Driver location WebSocket connections use consistent hash by driver_id \u2192 always reach same WebSocket server. Redis pub/sub propagates location updates to other servers if rider is on a different server.</div></div>\n    </div>\n  </div>\n</section>\n\n\n<section id=\"deploy-strategies\">\n  <div class=\"sec-tag\">04 \u00b7 Deployment Strategies</div>\n  <h2>Blue-green, canary, and rolling \u2014 how the LB enables zero-downtime deploys</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Blue-Green Deploy</div><div class=\"concept-def\"><strong>Run two identical production environments (blue = current, green = new). Switch traffic instantly by updating the LB.</strong><br>\n      Blue = v1.0 serving 100% traffic. Deploy v1.1 to green (idle). Run smoke tests on green. Switch LB: 0% \u2192 blue, 100% \u2192 green. Instant cutover. Rollback: flip LB back to blue in seconds.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Zero downtime. Instant rollback. Full production test on idle environment before cutover. Used for: high-stakes deploys where any version mixing is unacceptable.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires double infrastructure temporarily. DB schema changes must be backwards-compatible (both blue and green must work with same schema during transition).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Canary Deploy</div><div class=\"concept-def\"><strong>Route a small percentage of real traffic to the new version. Gradually increase if metrics look good.</strong><br>\n      Week 1: 1% \u2192 new version. Week 2: 10%. Week 3: 50%. Week 4: 100%. At each stage, monitor error rates, latency, and business metrics. Automated rollback if anomaly detected.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Real user validation before full rollout. Limits blast radius of bugs to 1% of users initially. Used by: Google, Netflix, Amazon for all feature releases.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Implementation: Nginx <code>split_clients</code>, Envoy weighted clusters, AWS ALB weighted target groups. Route by: random (statistical), user ID hash (consistent experience), header flag (beta testers).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Rolling Deploy</div><div class=\"concept-def\"><strong>Replace instances one at a time. At any point, some instances run old version, some run new.</strong><br>\n      10 instances: replace 1 \u2192 2 \u2192 3... until all 10 run new version. LB automatically routes to healthy instances (health checks remove in-progress instances from rotation).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No extra infrastructure. Gradual. Works with any LB.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Both versions run simultaneously \u2014 APIs must be backwards-compatible. Rollback requires rolling back all instances (slow). Default strategy for Kubernetes Deployments.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Connection Draining</div><div class=\"concept-def\"><strong>Before removing a server from rotation, wait for in-flight requests to complete.</strong><br>\n      1. Mark server as \"draining\" in LB \u2014 no new connections routed to it.<br>\n      2. Wait for existing connections to finish (or timeout after 30 seconds).<br>\n      3. Server reports zero active connections \u2192 safely terminate/redeploy.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Zero dropped requests. Users in the middle of a long operation (file upload, ML inference) are not interrupted. AWS ALB calls this \"deregistration delay\" (default 300s).</span></div></div>\n  </div>\n</section>\n\n<section id=\"nginx-envoy\">\n  <div class=\"sec-tag\">05 \u00b7 Nginx vs Envoy vs HAProxy</div>\n  <h2>Choosing the right proxy for each layer</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Nginx</th><th>Envoy</th><th>HAProxy</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Primary role</td><td>Web server + reverse proxy</td><td>Service mesh sidecar + edge proxy</td><td>High-performance TCP/HTTP LB</td></tr>\n      <tr><td class=\"row-head\">Configuration</td><td>Declarative config files</td><td>xDS dynamic API (no reload needed)</td><td>Declarative config, hot reload</td></tr>\n      <tr><td class=\"row-head\">Dynamic config</td><td><span class=\"warn\">Requires reload (brief pause)</span></td><td><span class=\"good\">Real-time via xDS \u2014 zero downtime</span></td><td><span class=\"warn\">Requires reload</span></td></tr>\n      <tr><td class=\"row-head\">Observability</td><td>Access logs, basic metrics</td><td><span class=\"good\">Built-in tracing, rich metrics, access logs</span></td><td>Good stats, logs</td></tr>\n      <tr><td class=\"row-head\">Service mesh</td><td><span class=\"bad\">Not designed for it</span></td><td><span class=\"good\">Built for it \u2014 Istio uses Envoy</span></td><td><span class=\"bad\">Not designed for it</span></td></tr>\n      <tr><td class=\"row-head\">L4 performance</td><td>Good</td><td>Good</td><td><span class=\"good\">Excellent \u2014 purpose-built for throughput</span></td></tr>\n      <tr><td class=\"row-head\">Ops simplicity</td><td><span class=\"good\">Simple \u2014 widely understood</span></td><td><span class=\"warn\">Complex xDS, steep learning curve</span></td><td><span class=\"good\">Simple</span></td></tr>\n      <tr><td class=\"row-head\">Use at</td><td>Web server, simple edge proxy, static serving</td><td>Service mesh sidecar, complex routing, microservices</td><td>High-throughput TCP LB, database proxies</td></tr>\n    </tbody>\n  </table>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">How Envoy's xDS works \u2014 interviewers love this</div>\n    <p><strong>Traditional proxies require a reload to pick up config changes.</strong> During reload, there's a brief pause. With 1000 Envoy sidecars, reloading all of them for every config change is impractical.</p>\n    <p><strong>xDS (Discovery Service):</strong> Envoy maintains a persistent gRPC connection to a control plane (Istio Pilot). The control plane pushes config updates in real time. Envoy applies them instantly with zero connection drops. Adding a new backend node? Control plane updates all Envoy instances in seconds \u2014 no reload, no downtime, no deployment needed.</p>\n  </div>\n</section>\n\n<section id=\"more-sd-lb\">\n  <div class=\"sec-tag\">06 \u00b7 More System Design Examples</div>\n  <h2>Load balancing in complex real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Netflix \u2014 Multi-Tier Global LB</div><span class=\"sd-example-tag\">GLOBAL \u00b7 VIDEO STREAMING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">DNS / GLOBAL</div><div class=\"choice-val\">AWS Route 53 latency-based routing \u2192 nearest AWS region. Anycast via CloudFront for video segments. User in Singapore \u2192 Singapore edge, never touches US origin for cached video.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">EDGE (L7)</div><div class=\"choice-val\">AWS ALB in each region. Path-based routing: <code>/api/*</code> \u2192 microservices, <code>/video/*</code> \u2192 streaming service. SSL termination at ALB. mTLS to internal services via Envoy service mesh.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">INTERNAL</div><div class=\"choice-val\">Envoy sidecars on every microservice (Zuul 2 at the edge, Envoy internally). Circuit breaking: if Recommendation Service fails, Envoy automatically falls back to cached recommendations. Zero code changes \u2014 configured in Istio control plane.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">CANARY</div><div class=\"choice-val\">New recommendation algorithm deployed to 1% of users via weighted routing in Envoy. A/B test measured on play rate and watch time metrics. Full rollout only after statistically significant improvement confirmed.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Database Proxy \u2014 PgBouncer for PostgreSQL</div><span class=\"sd-example-tag\">CONNECTION POOLING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">THE PROBLEM</div><div class=\"choice-val\">PostgreSQL supports ~100\u2013400 concurrent connections before performance degrades (each connection is a process). A web app with 50 servers \u00d7 20 threads each = 1,000 connections. Postgres falls over.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PGBOUNCER</div><div class=\"choice-val\">PgBouncer sits between app servers and PostgreSQL. App servers open connections to PgBouncer (thousands of connections OK). PgBouncer maintains a pool of 50\u2013100 real connections to PostgreSQL. Transaction-mode pooling: a real connection is only needed during an active transaction \u2014 idle app connections share the real connection pool.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LB FOR DB</div><div class=\"choice-val\">HAProxy in front of PostgreSQL read replicas: <code>balance leastconn</code> routes read queries to the least-loaded replica. Primary write goes direct. This is an L4 LB \u2014 HAProxy does not inspect SQL, just routes TCP connections.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you achieve zero-downtime deployments with a load balancer?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Rolling deployment with connection draining.</strong><br><br>\n  1. Take server-1 out of rotation: set its weight to 0 in the LB. New requests stop going to it.<br>\n  2. <strong>Connection draining</strong>: wait for existing connections on server-1 to complete naturally (or timeout after 30s). During this period, server-1 still serves in-flight requests but receives no new ones.<br>\n  3. Deploy new version to server-1. Wait for health check to pass.<br>\n  4. Add server-1 back to rotation. Repeat for server-2, etc.<br><br>\n  For databases: <strong>blue-green deployment</strong> \u2014 spin up a complete new fleet, promote when ready. Instant cutover with instant rollback. Requires double infrastructure temporarily.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Is the load balancer itself a single point of failure?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Yes \u2014 and the mitigation is to run multiple LBs with automatic failover.</strong><br><br>\n  For managed cloud LBs (AWS ALB/NLB): AWS runs them as a managed service across multiple AZs automatically. Not your problem.<br><br>\n  For self-managed LBs: run two Nginx/HAProxy instances in active-passive with keepalived. keepalived uses VRRP (Virtual Router Redundancy Protocol) \u2014 a virtual IP floats to whichever Nginx is healthy. If primary dies, virtual IP moves to secondary in &lt;1 second. DNS points to the virtual IP, not to either specific host.<br><br>\n  At Google/Netflix scale: use anycast routing \u2014 the same IP address is announced from multiple data centers. BGP routing automatically sends users to the nearest available one. Individual LB failures are invisible to users.</div></div>\n\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does a load balancer handle sticky sessions without storing state?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Sticky sessions route the same user to the same server, but the LB itself should not store per-user state (that would make the LB stateful and harder to scale).</strong><br><br>\n  <strong>Cookie-based stickiness (L7)</strong>: LB injects a cookie (AWSALB, JSESSIONID) containing a hashed identifier for the target server. On subsequent requests, LB reads the cookie and routes to the indicated server. LB is stateless \u2014 the routing information lives in the client's cookie.<br><br>\n  <strong>Consistent hash by IP/User-ID (L4)</strong>: hash the source IP (or a user ID from headers) to deterministically select the same server. No state stored anywhere. Downside: if server counts change, the hash remaps \u2014 consistent hashing mitigates this.<br><br>\n  <strong>When to avoid sticky sessions</strong>: sticky sessions make scaling and rolling deploys harder (you must drain a server of its sticky sessions before removing it). If your application needs stickiness, consider moving the stateful data to a shared store (Redis) instead, so any server can handle any request.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between a load balancer and an API gateway?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>All API gateways are load balancers, but not all load balancers are API gateways.</strong><br><br>\n  A <strong>load balancer</strong> distributes traffic across servers. It may be L4 (TCP-level) or L7 (HTTP-level). Its primary concern is traffic distribution and availability.<br><br>\n  An <strong>API gateway</strong> is a superset: it also load balances, but adds: authentication (JWT validation), authorisation (RBAC checks), rate limiting (per-user quotas), request transformation (add/remove headers, transform body), API versioning (route /v1/ and /v2/ to different backend versions), observability (per-endpoint metrics and logging), and developer portal integration.<br><br>\n  <strong>Rule of thumb for interviews</strong>: if the component needs to understand your business logic (who is this user? what plan are they on? is this request authorised?), it is an API gateway. If it just needs to distribute traffic reliably, it is a load balancer. In production, you typically have both: an L4 NLB at the outer edge (raw throughput), an L7 API gateway behind it (business logic), and internal load balancers between services.</div></div>\n</section></div>\n\n<section id=\"decision-lb\">\n  <div class=\"sec-tag\">07 \u00b7 Decision Framework</div>\n  <h2>Choosing the right load balancing layer</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Load Balancer Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need to inspect HTTP headers, URLs, or cookies to route?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>L7 (Application Layer) LB.</strong> AWS ALB, Nginx, Envoy, HAProxy HTTP mode. Path-based routing (/api/* vs /static/*), host-based routing, header-based A/B testing, SSL termination. Required for any URL-aware routing.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (pure TCP/UDP) \u2192</span><span class=\"opt-text\"><strong>L4 (Transport Layer) LB.</strong> AWS NLB, HAProxy TCP mode. Raw TCP routing \u2014 faster, lower overhead, works for any protocol (MySQL, SMTP, game servers). Use when you don't need HTTP awareness.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Are request durations variable (some fast, some very slow)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (variable duration) \u2192</span><span class=\"opt-text\"><strong>Least Connections.</strong> Routes to server with fewest active connections. A slow server accumulates connections and receives fewer new ones automatically. Best for: WebSocket, video streaming, large uploads, ML inference endpoints.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (uniform fast requests) \u2192</span><span class=\"opt-text\"><strong>Round Robin or Weighted Round Robin.</strong> Distributes evenly. Simple, low overhead. Best for: homogeneous stateless API servers with uniform request cost.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Do clients need to always reach the same backend (stateful)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (stateful) \u2192</span><span class=\"opt-text\"><strong>Sticky sessions.</strong> Cookie-based (LB injects AWSALB cookie) or consistent hash by user ID. Required for: WebSocket connections, legacy session-based apps. Prefer moving state to Redis so any server can handle any request.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (stateless) \u2192</span><span class=\"opt-text\"><strong>Any algorithm \u2014 no stickiness needed.</strong> Stateless is always preferred. Store session state in Redis, not in-process. Enables free horizontal scaling and zero-downtime rolling deploys.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">Internal microservice traffic or public edge traffic?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Internal (service mesh) \u2192</span><span class=\"opt-text\"><strong>Envoy sidecar proxies + Istio.</strong> mTLS between services, circuit breaking, distributed tracing, dynamic config via xDS \u2014 all without changing application code. Overkill for small systems; essential at 50+ microservices.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Public edge \u2192</span><span class=\"opt-text\"><strong>API Gateway (Kong/AWS API GW) + L7 LB.</strong> Auth, rate limiting, request transformation at the gateway. L7 LB (Nginx/ALB) distributes to backend fleet. Two layers: gateway handles business rules, LB handles distribution.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n<div class=\"footer\">LOAD BALANCING \u00b7 L4 \u00b7 L7 \u00b7 NGINX \u00b7 ENVOY \u00b7 CIRCUIT BREAKER \u00b7 API GATEWAY \u00b7 SERVICE MESH \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Infra' },
  search: { title: 'Search & Elasticsearch', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Search: Elasticsearch & Inverted Index</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Search<br><em>Elasticsearch & Inverted Index</em></h1>\n  <p class=\"hero-sub\">How search works from first principles \u2014 inverted index, BM25 relevance, Elasticsearch architecture, typeahead design, and vector search.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Elasticsearch</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Inverted Index</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">BM25</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Typeahead</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">Vector Search</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#intuition\">Why Search</a><a href=\"#inverted\">Inverted Index</a><a href=\"#elasticsearch\">ES Architecture</a><a href=\"#typeahead\">Typeahead</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"intuition\">\n  <div class=\"sec-tag\">00 \u00b7 Core Intuition</div>\n  <h2>Why a database cannot do what a search engine does</h2>\n  <p>A SQL database index finds exact values fast: <code>WHERE user_id = 123</code>. But <code>WHERE body LIKE '%distributed systems%'</code> requires a full table scan \u2014 every row, every time. At 1 billion documents, that takes minutes. A search engine can answer this in milliseconds because it inverts the problem entirely.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The book index analogy</div>\n    <div class=\"analogy-text\">\n      A database is a book read cover-to-cover to find a word. Slow.<br><br>\n      A search engine is a book with an index at the back: \"distributed systems \u2192 pages 12, 47, 203, 891.\" You go directly to those pages. That back-of-book index is an <strong>inverted index</strong> \u2014 and it is the entire secret of how search works.\n    </div>\n  </div>\n</section>\n\n<section id=\"inverted\">\n  <div class=\"sec-tag\">01 \u00b7 Inverted Index</div>\n  <h2>The data structure that powers every search engine</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">How It Works</div><div class=\"concept-def\"><strong>An inverted index maps each unique term to the list of documents containing it.</strong><br>\n      Documents: Doc1=\"Redis is fast\", Doc2=\"Redis scales well\", Doc3=\"Kafka is fast\"<br>\n      Inverted index:<br>\n      <code>redis   \u2192 [Doc1, Doc2]</code><br>\n      <code>fast    \u2192 [Doc1, Doc3]</code><br>\n      <code>is      \u2192 [Doc1, Doc3]</code><br>\n      <code>scales  \u2192 [Doc2]</code><br>\n      Query \"redis fast\" \u2192 intersection of [Doc1,Doc2] and [Doc1,Doc3] \u2192 <strong>Doc1</strong> (contains both terms)</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Posting List</div><div class=\"concept-def\"><strong>For each term, the index stores not just document IDs but positions and frequencies.</strong><br>\n      <code>redis \u2192 [(Doc1, freq:1, pos:[0]), (Doc2, freq:1, pos:[0])]</code><br>\n      Position enables phrase queries: \"redis cluster\" requires \"redis\" and \"cluster\" to be adjacent.<br>\n      Frequency enables relevance scoring \u2014 a document mentioning \"redis\" 20 times ranks higher than one mentioning it once.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Text Analysis Pipeline</div><div class=\"concept-def\"><strong>Before indexing, text passes through an analysis pipeline that normalises it.</strong><br>\n      1. <strong>Tokenization</strong>: \"Redis is Fast!\" \u2192 [\"Redis\", \"is\", \"Fast\"]<br>\n      2. <strong>Lowercasing</strong>: \u2192 [\"redis\", \"is\", \"fast\"]<br>\n      3. <strong>Stop word removal</strong>: \u2192 [\"redis\", \"fast\"] (removes \"is\")<br>\n      4. <strong>Stemming/Lemmatization</strong>: \"running\" \u2192 \"run\", \"faster\" \u2192 \"fast\"<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">The same pipeline must run at query time. \"Running Redis\" \u2192 [\"run\", \"redis\"] \u2192 matches documents containing \"run\" or \"redis\" in any form.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">TF-IDF / BM25</div><div class=\"concept-def\"><strong>Relevance scoring: not all matches are equal.</strong><br>\n      <strong>TF (Term Frequency)</strong>: how often does the term appear in this document? More occurrences = more relevant.<br>\n      <strong>IDF (Inverse Document Frequency)</strong>: how rare is the term across all documents? \"the\" appears everywhere \u2014 low IDF, low importance. \"Kafka\" appears rarely \u2014 high IDF, high importance.<br>\n      <strong>BM25</strong>: modern improvement over TF-IDF used by Elasticsearch. Prevents very long documents from dominating just because they mention a term more times.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Elasticsearch uses BM25 by default. You can boost specific fields (title matches worth 3x body matches).</span></div></div>\n  </div>\n</section>\n\n<section id=\"elasticsearch\">\n  <div class=\"sec-tag\">02 \u00b7 Elasticsearch Architecture</div>\n  <h2>How ES scales to billions of documents</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Index \u2192 Shards</div><div class=\"concept-def\"><strong>An Elasticsearch index is split into N primary shards. Each shard is a complete, independent Lucene index.</strong><br>\n      Index \"tweets\" with 5 shards: each shard holds ~20% of documents. Queries fan out to all 5 shards in parallel, results merged by the coordinator.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Shard count is set at creation and cannot be changed (except via reindex). Over-sharding (too many small shards) is as harmful as under-sharding (too few large ones). Rule of thumb: aim for 10\u201350GB per shard.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Replication</div><div class=\"concept-def\"><strong>Each primary shard has N replica shards on different nodes.</strong><br>\n      Writes: go to primary, primary replicates to replicas.<br>\n      Reads: can be served by primary or any replica \u2014 distributes read load.<br>\n      Node failure: replica promoted to primary automatically.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Replicas both provide HA and increase read throughput. 5 shards \u00d7 2 replicas = 15 Lucene indexes total across the cluster.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Near Real-Time<br>(NRT) Search</div><div class=\"concept-def\"><strong>Newly indexed documents are searchable within ~1 second, not immediately.</strong><br>\n      Lucene writes to an in-memory buffer \u2192 every 1 second, refreshed to a new segment (searchable) \u2192 eventually merged into larger segments.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">This is why Elasticsearch is \"near real-time\" not \"real-time.\" To force immediate visibility: <code>?refresh=true</code> on indexing \u2014 forces a refresh but hurts write throughput. Only use for critical flows.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Lucene Segments</div><div class=\"concept-def\"><strong>Lucene (the underlying library) writes data in immutable segments.</strong><br>\n      New documents \u2192 write buffer \u2192 periodic flush \u2192 new immutable segment. Background merges combine small segments into larger ones (like Cassandra SSTables, like ClickHouse parts).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Deletes are soft-deletes (marked, not removed) until a merge happens. This is why delete-heavy workloads require periodic forced merges to reclaim space.</span></div></div>\n  </div>\n</section>\n\n<section id=\"typeahead\">\n  <div class=\"sec-tag\">03 \u00b7 Typeahead / Autocomplete</div>\n  <h2>Design: search-as-you-type at FAANG scale</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Prefix Trie</div><div class=\"concept-def\"><strong>A tree where each node is a character. Every path from root to leaf is a word. O(L) lookup for a prefix of length L \u2014 regardless of vocabulary size.</strong><br>\n      To find all words starting with \"redis\": traverse to node 'r'\u2192'e'\u2192'd'\u2192'i'\u2192's', return all words in subtree.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Fast prefix lookup. Memory-efficient with shared prefixes. Used by: Google Suggest backend, IDE autocomplete.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Storing popularity scores in a trie and returning top-K results requires augmenting each node with a max-heap \u2014 complex. Sharding a trie across machines is non-trivial.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Elasticsearch<br>Completion Suggester</div><div class=\"concept-def\"><strong>Built-in completion suggester using an in-memory FST (Finite State Transducer) \u2014 more memory-efficient than a trie.</strong><br>\n      Index time: store completion field with weight (popularity score).<br>\n      Query: <code>suggest: {prefix: \"red\", field: \"title.completion\", size: 5}</code><br>\n      Returns top-5 completions by weight instantly.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Easy to implement on top of existing ES infrastructure. Handles millions of suggestions in milliseconds.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Redis ZSET Approach</div><div class=\"concept-def\"><strong>Store all prefixes as ZSET members scored by popularity. For \"redis\", store \"r\", \"re\", \"red\", \"redi\", \"redis\" all pointing to the suggestion with its popularity score.</strong><br>\n      <code>ZRANGEBYLEX suggestions \"[redis\" \"[redis\u00ff\" LIMIT 0 5</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Extremely fast (sub-ms). Works well for known vocabulary (hashtags, product names). Easy to update popularity in real time with ZINCRBY.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Storage: O(L \u00d7 V) where L is avg word length and V is vocabulary size. For a 10M-word vocabulary, this becomes large.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 System Design Examples</div>\n  <h2>Search in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Twitter Search</div><span class=\"sd-example-tag\">500M TWEETS/DAY</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WRITE PATH</div><div class=\"choice-val\">New tweet \u2192 Kafka \u2192 Indexing Service \u2192 Elasticsearch. The Kafka buffer decouples tweet volume from ES indexing rate. ES indexes ~6K tweets/sec sustained. NRT lag: ~1 second before searchable.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SEARCH</div><div class=\"choice-val\"><span class=\"badge b-g\">Elasticsearch \u2713</span> Full-text BM25 scoring + recency boost + engagement boost. Query rewriting: \"from:elonmusk\" \u2192 field-specific filter. Hashtag search: exact term match on the hashtag field (no tokenization).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TRENDING</div><div class=\"choice-val\">Trending hashtags NOT from ES \u2014 from a streaming Count-Min Sketch pipeline (Kafka + Flink + Redis ZSET). ES is too slow for trending (requires aggregation queries). The two systems complement each other.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT SQL</div><div class=\"choice-val\"><code>LIKE '%distributed%'</code> on 500M tweets = full table scan = minutes. Elasticsearch full-text search on same data = milliseconds. Not even close.</div></div>\n    </div>\n  </div>\n</section>\n\n\n<section id=\"ranking\">\n  <div class=\"sec-tag\">04 \u00b7 Search Ranking</div>\n  <h2>How search results are ordered \u2014 beyond BM25</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Multi-Stage Ranking</div><div class=\"concept-def\"><strong>Modern search uses a pipeline: cheap retrieval first, expensive re-ranking after.</strong><br>\n      Stage 1 \u2014 <strong>Recall</strong>: BM25/inverted index retrieves top 10,000 candidates. Fast, cheap.<br>\n      Stage 2 \u2014 <strong>Re-rank</strong>: ML model (LambdaMART, BERT-based) scores the top 1,000. Considers personalisation, freshness, engagement signals.<br>\n      Stage 3 \u2014 <strong>Business rules</strong>: Apply boosts (promoted listings), filters (safety), and diversity rules (not all results from same author).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Why multi-stage: running a BERT model on 10M documents per query is too slow. Run it on 1,000 pre-filtered candidates \u2192 acceptable latency.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Relevance Signals</div><div class=\"concept-def\"><strong>Beyond term frequency, production search incorporates:</strong><br>\n      <strong>Query-document signals</strong>: BM25 score, field match (title match worth 3x body match), exact phrase match bonus.<br>\n      <strong>Document-level signals</strong>: freshness (newer content boosted), authority (PageRank-style link graph), engagement (CTR, dwell time, shares).<br>\n      <strong>Personalisation</strong>: user's past clicks, location, language, search history.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Elasticsearch Rescore API: retrieve top 10K by BM25, rescore top 500 with a more expensive function. Balances speed and quality.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Faceted Search</div><div class=\"concept-def\"><strong>Filter and aggregate search results by multiple dimensions simultaneously \u2014 the e-commerce standard.</strong><br>\n      Query: \"laptop\" \u2192 results filtered by brand (Apple/Dell/HP), RAM (8GB/16GB/32GB), price range. Counts shown per facet: \"Apple (234), Dell (189)...\"<br>\n      Elasticsearch implementation: use <code>aggregations</code> alongside the query. One request returns both the matched documents AND the facet counts. No separate aggregation query needed.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Helps users narrow results without reformulating queries. Amazon, Flipkart, Zalando \u2014 all use faceted search as the primary product discovery interface.</span></div></div>\n  </div>\n</section>\n\n<section id=\"more-sd-search\">\n  <div class=\"sec-tag\">05 \u00b7 More System Design Examples</div>\n  <h2>Search architecture in Uber, LinkedIn, and GitHub</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Uber \u2014 Driver and Restaurant Search</div><span class=\"sd-example-tag\">GEO-SPATIAL \u00b7 REAL-TIME</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">GEO INDEX</div><div class=\"choice-val\">Uber stores driver locations in a geospatial index. S2 cells (Google's geo library) divide the world into hierarchical cells. Finding drivers within 2km of a rider = find all occupied S2 cells at the appropriate level within radius. Elasticsearch's geo_point field type with <code>geo_distance</code> query handles this natively.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">REAL-TIME UPDATE</div><div class=\"choice-val\">Driver positions update every 4 seconds via WebSocket. Writes go to a Redis Geo hash (GEOADD) for the hot, live view. Elasticsearch index updated async for the search layer. Two stores: Redis for real-time dispatch, Elasticsearch for search/analytics.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">RESTAURANT SEARCH</div><div class=\"choice-val\">Uber Eats: full-text BM25 on restaurant name + cuisine tags + menu items. Geo filter applied first (only restaurants within delivery range). Ranked by: rating, estimated delivery time, sponsored placement (business rules layer), and personalisation (user's order history).</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">LinkedIn \u2014 People and Job Search</div><span class=\"sd-example-tag\">PERSONALISED \u00b7 SOCIAL GRAPH</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PEOPLE SEARCH</div><div class=\"choice-val\">LinkedIn's Galene search engine (Elasticsearch-based): indexes 900M+ member profiles. Query \"data scientist in Bangalore\" \u2192 BM25 retrieval \u2192 ML re-ranking using network distance (1st/2nd degree connections ranked higher), engagement prediction, and profile completeness score.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">JOB SEARCH</div><div class=\"choice-val\">Semantic matching: your profile embedding (skills, title, experience) is compared to job embedding using cosine similarity (vector search). Keyword match + semantic similarity combined (hybrid search). Jobs at companies where you have connections get a boost.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TYPEAHEAD</div><div class=\"choice-val\">Job title suggestions: Redis ZSET with ~50K common job titles, scored by global frequency. Prefix query on typed characters returns top 5 suggestions in &lt;5ms. Personalised layer re-ranks suggestions based on user's profile and connections.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">05 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you keep Elasticsearch in sync with your primary database?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Two patterns, with very different trade-offs:</strong><br><br><strong>1. Dual write</strong>: Application writes to DB AND ES in the same request. Simple but dangerous \u2014 if ES write fails, you have inconsistency with no way to detect it. Acceptable only for non-critical search.<br><br><strong>2. Change Data Capture (CDC)</strong>: Debezium (or similar) reads the PostgreSQL WAL (Write-Ahead Log) and publishes every change to Kafka. An ES indexing consumer reads from Kafka and keeps ES in sync. This is the production approach:<br>\u2014 Source of truth is always the DB<br>\u2014 ES is an eventually consistent read replica<br>\u2014 On ES failure, reindex from DB<br>\u2014 Typical lag: 100ms\u20132s<br><br>Tools: Debezium + Kafka + Elasticsearch Kafka Connector. Used by: LinkedIn, Airbnb, Shopify.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is vector search and when do you need it?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Vector search finds documents semantically similar to a query, not just exact keyword matches.</strong><br><br>Classic inverted index search for \"fast database\" would not return a document about \"high-performance data store\" \u2014 different words, even if same meaning. Vector search uses ML embeddings (e.g., OpenAI text-embedding-ada-002) to convert both query and documents to dense vectors in the same semantic space. Documents near the query vector in that space are semantically similar.<br><br><strong>Implementation</strong>: index document embeddings in a vector database (Pinecone, Weaviate, Milvus, or Elasticsearch with kNN). Query: embed the query text \u2192 find K nearest neighbours using approximate nearest neighbour (HNSW algorithm).<br><br><strong>When to use</strong>: semantic search (\"show me articles about making databases fast\"), recommendation (\"more content like this\"), Q&A (RAG \u2014 Retrieval Augmented Generation for LLMs).<br><br><strong>Hybrid search</strong>: combine keyword BM25 + vector KNN scores (Reciprocal Rank Fusion). Best of both worlds \u2014 used by production AI search systems.</div></div>\n\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do search engines handle spelling mistakes \u2014 \"gogle\" instead of \"google\"?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Three techniques, typically combined:</strong><br><br>\n  <strong>1. Edit distance (Levenshtein)</strong>: for each query term, find indexed terms within edit distance 2 (2 character insertions/deletions/substitutions). \"gogle\" is distance 1 from \"google.\" Return results for the nearest match. Elasticsearch has a <code>fuzziness</code> parameter that does this automatically.<br><br>\n  <strong>2. N-gram index</strong>: at index time, break \"google\" into trigrams: [goo, oog, ogl, gle]. Index each trigram. At query time, break \"gogle\" into [gog, ogl, gle]. Overlap of 2 trigrams \u2192 likely a match. Faster than edit distance for large indexes.<br><br>\n  <strong>3. Query rewriting with spell checker</strong>: maintain a dictionary of correct terms with frequencies. For each query term not in dictionary, suggest the closest term. \"Did you mean: google?\" Google famously implemented this with a neural spell checker trained on query logs \u2014 \"what users typed \u2192 what they actually meant.\"<br><br>\n  <strong>Production approach</strong>: use Elasticsearch's built-in fuzzy matching for simple cases. For high-traffic queries, maintain a learned correction model trained on click-through data (if users click the 2nd result for query X, X was likely a misspelling of result 2's title).</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you keep search results fresh when new content is added every second?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Elasticsearch's NRT (Near Real-Time) makes documents searchable within ~1 second of indexing \u2014 usually sufficient. For truly real-time requirements, different approaches are needed.</strong><br><br>\n  <strong>Standard NRT path</strong>: write to ES \u2192 in-memory buffer \u2192 refresh every 1s \u2192 new segment \u2192 searchable. For most use cases (news articles, tweets), 1-second lag is imperceptible.<br><br>\n  <strong>For sub-second freshness</strong> (stock prices, live sports scores): do not use ES for the hot data. Use Redis Sorted Sets or a dedicated real-time index (Druid) for the last few minutes. ES handles historical data. The search UI blends real-time results (from Redis) with historical results (from ES).<br><br>\n  <strong>Index update strategy</strong>: full reindex (expensive, for schema changes), partial update via Update API (efficient for changing specific fields), delete + reindex (for major changes to a document). Avoid full reindexes for high-traffic indexes during peak hours \u2014 they consume significant I/O.</div></div>\n</section></div>\n\n<section id=\"decision-search\">\n  <div class=\"sec-tag\">06 \u00b7 Decision Framework</div>\n  <h2>Search architecture decisions</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Search System Design \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this full-text search (keyword matching across documents)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Elasticsearch / OpenSearch.</strong> Inverted index + BM25 scoring. Handles: full-text on articles/tweets/product descriptions, fuzzy matching, multi-field boosts. Scale: billions of documents. Never use SQL LIKE for this.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (exact match / geo / structured) \u2192</span><span class=\"opt-text\">Go to Step 2. SQL or Redis may suffice.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Is the primary dimension geospatial (find things near me)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (geo) \u2192</span><span class=\"opt-text\"><strong>Elasticsearch geo_distance queries or PostGIS.</strong> ES: geo_point field + distance query \u2014 returns results within N km. PostGIS: spatial indexes for complex polygon queries. Redis GEO commands for simple \"nearby\" lookups (Uber driver locations).</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Go to Step 3.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Is it semantic search (meaning-based, not keyword)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Vector search.</strong> Embed documents + queries with an embedding model (OpenAI, Cohere). Store vectors in Pinecone / Weaviate / pgvector. KNN search finds semantically similar content. Use hybrid search (BM25 + vector) for best precision + recall.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Both keyword + semantic \u2192</span><span class=\"opt-text\"><strong>Hybrid search.</strong> Elasticsearch 8+ supports kNN + BM25 in one query with Reciprocal Rank Fusion. Best of both worlds. Production choice for modern AI-powered search (LinkedIn, Spotify).</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">Typeahead / autocomplete needed?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Small vocabulary (&lt;1M terms) \u2192</span><span class=\"opt-text\"><strong>Redis ZSET prefix trick.</strong> Store all prefixes with popularity score. ZRANGEBYLEX for instant prefix lookup. &lt;1ms. Easy to update in real time with ZINCRBY.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Large vocabulary \u2192</span><span class=\"opt-text\"><strong>ES Completion Suggester.</strong> In-memory FST (finite state transducer). Handles millions of suggestions. Returns top-N by weight instantly. Best for: product search, job title autocomplete.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n<div class=\"footer\">SEARCH \u00b7 ELASTICSEARCH \u00b7 INVERTED INDEX \u00b7 BM25 \u00b7 TYPEAHEAD \u00b7 VECTOR SEARCH \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Search' },
  object_storage: { title: 'Object Storage: S3 & Blob Store', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Object Storage: S3 & Blob Store</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Object Storage<br><em>S3 & Blob Store</em></h1>\n  <p class=\"hero-sub\">S3 vs block vs file storage, multipart uploads, pre-signed URLs, storage classes, and CDN integration \u2014 everything for media and data lake system designs.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">S3 / GCS</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Multipart Upload</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">Pre-Signed URLs</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Storage Classes</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">CDN Origin</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#what\">Storage Types</a><a href=\"#internals\">S3 Internals</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"what\">\n  <div class=\"sec-tag\">00 \u00b7 What Is Object Storage</div>\n  <h2>S3 vs Block Storage vs File Storage</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Object Storage (S3)</div><div class=\"concept-def\"><strong>Stores data as flat objects \u2014 each object is a file with a key (path), value (bytes), and metadata.</strong> No directory hierarchy (though keys can have slashes to simulate it).<br>\n      Access: HTTP GET/PUT. Each object immutable after write. Unlimited scale. Cheap ($0.023/GB/month).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Unlimited scale. Cheap. HTTP accessible from anywhere. Perfect for: images, videos, logs, backups, data lakes. Used by: Netflix (video), Instagram (photos), Dropbox (files).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 High latency for small random reads (~50\u2013200ms). No in-place updates. No filesystem semantics (no rename, no locking).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Block Storage (EBS)</div><div class=\"concept-def\"><strong>Raw storage volumes attached to a VM. The OS sees it as a disk \u2014 format with any filesystem.</strong><br>\n      Sub-millisecond latency. Random reads/writes. Required for databases (PostgreSQL, MySQL need a filesystem).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Low latency. Random access. Required for any software that needs a real filesystem (databases, OS volumes).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Attached to one instance at a time. Fixed capacity (must resize manually). Expensive ($0.10/GB/month vs S3's $0.023).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">File Storage (EFS/NFS)</div><div class=\"concept-def\"><strong>Shared filesystem mounted by multiple instances simultaneously. Files, directories, locking semantics.</strong><br>\n      Multiple EC2 instances can read/write the same files concurrently.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Shared access across instances. POSIX filesystem. No refactoring of existing code that uses files.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Higher latency than block storage. More expensive. Rarely needed in modern cloud-native designs (S3 has replaced most file storage use cases).</span></div></div>\n  </div>\n</section>\n\n<section id=\"internals\">\n  <div class=\"sec-tag\">01 \u00b7 S3 Internals</div>\n  <h2>How S3 actually works under the hood</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Consistency Model</div><div class=\"concept-def\"><strong>S3 provides strong read-after-write consistency for all operations (since December 2020).</strong><br>\n      After a successful PUT, subsequent GET will return the new object. After DELETE, subsequent GET returns 404. No more \"eventually consistent\" surprises.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 You can safely read immediately after writing. No need for artificial delays or consistency workarounds.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Multipart Upload</div><div class=\"concept-def\"><strong>For files &gt;100MB: upload in parallel chunks, then assemble.</strong><br>\n      1. Initiate: <code>POST /object?uploads</code> \u2192 returns uploadId<br>\n      2. Upload parts: <code>PUT /object?partNumber=1&uploadId=X</code> (each part \u22655MB)<br>\n      3. Complete: <code>POST /object?uploadId=X</code> with list of part ETags<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Parallel uploads (5\u201310x faster for large files). Resume interrupted uploads. Each part is independently verified with MD5. Required for files &gt;5GB (single PUT limit).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pre-Signed URLs</div><div class=\"concept-def\"><strong>Temporarily grant a user direct access to an S3 object without exposing your credentials.</strong><br>\n      Server generates a signed URL valid for N seconds: <code>aws s3 presign s3://bucket/video.mp4 --expires-in 3600</code><br>\n      User uses URL directly to upload or download \u2014 bypasses your server entirely.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Client uploads directly to S3 \u2014 your server never sees the bytes. Offloads bandwidth and CPU. Standard pattern for all file upload systems (Instagram, Dropbox, Google Drive).</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Flow: Client \u2192 GET /upload-url \u2192 Server \u2192 Pre-signed URL \u2192 Client PUT directly to S3 \u2192 Client notifies Server of completion.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Storage Classes</div><div class=\"concept-def\"><strong>Different cost/access speed tiers for different data lifecycle stages:</strong><br>\n      <code>Standard</code>: frequently accessed, ~$0.023/GB/month, &lt;100ms access<br>\n      <code>Standard-IA</code>: infrequent access, ~$0.0125/GB/month, retrieval fee per GB<br>\n      <code>Glacier Instant</code>: archive, ~$0.004/GB/month, millisecond retrieval<br>\n      <code>Glacier Deep Archive</code>: long-term archive, ~$0.00099/GB/month, 12-hour retrieval<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Use Lifecycle Policies to automatically transition objects: new uploads \u2192 Standard \u2192 after 30 days \u2192 IA \u2192 after 1 year \u2192 Glacier. Common for log files and video archives.</span></div></div>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">02 \u00b7 System Design Examples</div>\n  <h2>Object storage in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Instagram \u2014 Photo Upload Flow</div><span class=\"sd-example-tag\">MEDIA UPLOAD</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">UPLOAD</div><div class=\"choice-val\">Client requests pre-signed URL from API server. API server generates URL scoped to that user's bucket path, valid for 5 minutes. Client uploads directly to S3 \u2014 API server never receives image bytes. Reduces server bandwidth by 100%.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PROCESSING</div><div class=\"choice-val\">S3 PUT triggers a Lambda (or SQS notification \u2192 EC2 worker). Worker: resize to 3 resolutions (thumbnail/feed/full), apply filters, extract EXIF metadata, write processed versions back to S3, update DB with S3 keys.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DELIVERY</div><div class=\"choice-val\">All S3 objects served through CloudFront CDN. CDN caches at 200+ edge locations. User in Tokyo gets the image from Tokyo edge, not from S3 in us-east-1. ~10ms delivery globally vs ~200ms from origin.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LIFECYCLE</div><div class=\"choice-val\">Stories expire after 24h: S3 Object expiry policy automatically deletes after 24h. Old posts after 1 year \u2192 transition to S3 Infrequent Access (saves ~45% storage cost). Deleted posts \u2192 immediate Object Delete + CDN invalidation.</div></div>\n    </div>\n  </div>\n</section>\n\n\n<section id=\"data-lake\">\n  <div class=\"sec-tag\">02 \u00b7 Data Lake Architecture</div>\n  <h2>S3 as the foundation of every modern data platform</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">What Is a Data Lake</div><div class=\"concept-def\"><strong>Store ALL your data in S3 in raw format first. Process later, for different purposes.</strong><br>\n      Raw events \u2192 S3 in Parquet/JSON. Same S3 data is read by: Spark (ML training), Athena (ad-hoc SQL), Redshift Spectrum (BI reports), Flink (stream processing via S3 checkpoints).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Schema-on-read: no predefined schema. Add new data sources without refactoring. Multiple compute engines on same data. Extremely cheap storage ($0.023/GB vs $0.10/GB for block storage).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 No ACID transactions on raw S3. Small file problem: millions of 1KB files are much slower to query than thousands of 100MB files. Use Parquet + Snappy compression + file compaction jobs.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Delta Lake / Iceberg</div><div class=\"concept-def\"><strong>Table formats that add ACID transactions, schema evolution, and time-travel to S3.</strong><br>\n      Delta Lake (Databricks) / Apache Iceberg (Netflix, Apple): store metadata files alongside Parquet data in S3 that track which files constitute the current table version.<br>\n      ACID on S3: each transaction writes new Parquet files + updates metadata atomically. Readers see consistent snapshots.<br>\n      Time travel: <code>SELECT * FROM events TIMESTAMP AS OF '2026-03-01'</code> \u2014 queries the state of the table on March 1st.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Fixes the S3 \"no transactions\" problem. Schema evolution without rewriting all data. Streaming + batch unified (Flink writes, Spark reads). Used by: Airbnb, Netflix, Apple for petabyte-scale data lakes.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">S3 Event Notifications</div><div class=\"concept-def\"><strong>S3 can trigger Lambda/SQS/SNS automatically when objects are created, deleted, or modified.</strong><br>\n      New photo uploaded to S3 \u2192 S3 event \u2192 Lambda triggered \u2192 resize image \u2192 write variants back to S3.<br>\n      Log file uploaded \u2192 S3 event \u2192 SQS message \u2192 EC2 worker processes log \u2192 writes structured data to Redshift.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Event-driven pipelines with zero polling. S3 becomes the trigger for the entire data processing pipeline. Latency: ~1 second from S3 write to Lambda invocation.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Intelligent Tiering</div><div class=\"concept-def\"><strong>S3 Intelligent-Tiering automatically moves objects between storage classes based on access patterns.</strong><br>\n      Objects not accessed for 30 days \u2192 moved to Infrequent Access automatically. Objects not accessed for 90 days \u2192 moved to Archive Instant. No retrieval fees for objects moved by Intelligent-Tiering.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Optimal cost without manual lifecycle management. Best for: data lakes where access patterns are unpredictable. Small management fee ($0.0025 per 1,000 objects) \u2014 worth it for large data lakes.</span></div></div>\n  </div>\n</section>\n\n<section id=\"more-sd-obj\">\n  <div class=\"sec-tag\">03 \u00b7 More System Design Examples</div>\n  <h2>Object storage decisions in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">YouTube \u2014 Video Storage & Delivery</div><span class=\"sd-example-tag\">PETABYTES \u00b7 ADAPTIVE STREAMING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">UPLOAD PATH</div><div class=\"choice-val\">Video uploaded directly to Google Cloud Storage (GCS) via resumable upload API (chunked 5MB parts). Upload service returns upload URL \u2192 client streams directly to GCS. Server never receives video bytes \u2014 saves enormous bandwidth.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TRANSCODING</div><div class=\"choice-val\">GCS PUT event triggers transcoding pipeline. Original video \u2192 encode at 360p/720p/1080p/4K (H.264 + VP9). HLS/DASH segmentation: split each quality into 10-second segments. All variants stored back in GCS under structured paths: <code>gs://videos/{id}/1080p/seg_{n}.ts</code>.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DELIVERY</div><div class=\"choice-val\">GCS \u2192 Cloud CDN serves video segments. Highly watched videos cached at 100+ PoPs globally. Long-tail videos served from GCS origin. Adaptive bitrate: player downloads manifest, picks quality based on bandwidth, fetches segments. CDN cache hit rate for popular videos: &gt;99%.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">STORAGE COST</div><div class=\"choice-val\">500 hours of video uploaded per minute. At 1GB/minute for 720p: 500GB/minute = 720TB/day. GCS Standard ($0.020/GB): ~$14,400/day storage cost. Lifecycle policy: videos with &lt;1000 views/month \u2192 GCS Nearline ($0.01/GB) after 30 days. Saves ~50% on long-tail storage.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Airbnb \u2014 Listing Photos & Data Lake</div><span class=\"sd-example-tag\">MEDIA + ANALYTICS</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">PHOTO UPLOAD</div><div class=\"choice-val\">Pre-signed URL flow: <code>GET /photos/upload-url \u2192 presigned S3 URL \u2192 client PUT directly to S3 \u2192 client notifies API of completion \u2192 API queues processing job</code>. Processing: detect faces, apply image enhancement, generate 5 resolutions, extract EXIF. Processed images back to S3, metadata to PostgreSQL.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DATA LAKE</div><div class=\"choice-val\">All business events (bookings, searches, clicks, page views) written to S3 in Parquet via Kafka \u2192 Flink \u2192 S3 sink. S3 is the \"source of truth\" for analytics. Spark clusters run on the S3 data for pricing ML, fraud detection model training, and business intelligence reports.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ICEBERG</div><div class=\"choice-val\">Apache Iceberg used for the booking events table. Enables: schema evolution when new fields are added (new booking metadata), time-travel queries (\"what was our booking rate on New Year's Eve 2024?\"), and ACID updates (correct a batch of mis-categorised listings without full rewrite).</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">03 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle large file uploads reliably over unreliable mobile connections?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Multipart upload with client-side resumable upload logic.</strong><br><br>\n  1. Client splits file into 5\u201310MB chunks before starting the upload.<br>\n  2. Client requests a multipart upload ID from your server. Server calls S3 to initiate and returns the uploadId.<br>\n  3. Client uploads chunks in parallel (3\u20135 simultaneous chunks for speed). Each chunk is independent \u2014 a failed chunk can be retried without restarting the whole upload.<br>\n  4. Client tracks which chunks succeeded locally (localStorage or a server-side record).<br>\n  5. If connection drops mid-upload, client resumes from the last successful chunk on reconnect.<br>\n  6. When all chunks are confirmed, client notifies your server, which calls S3's CompleteMultipartUpload.<br><br>\n  Tools: AWS SDK has built-in multipart upload with retry logic. tus.io is an open protocol for resumable uploads. Used by: Google Drive, Dropbox, YouTube for all video uploads.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you design a Dropbox-like file sync system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Core challenge: efficiently sync only changed parts of large files across devices.</strong><br><br>\n  <strong>Chunked storage</strong>: files are split into 4\u20138MB content-addressed chunks. Each chunk is identified by its SHA-256 hash. Only changed chunks need to be uploaded on modification.<br><br>\n  <strong>Delta sync</strong>: if you edit a 1GB file by changing one paragraph, only the 2\u20133 chunks containing that paragraph change. Only those chunks are uploaded. File metadata (which chunk IDs comprise the file) is updated. Other devices download only the new chunks.<br><br>\n  <strong>Deduplication</strong>: if two users upload identical files, the chunks are deduplicated \u2014 stored once, referenced by both. Dropbox saved ~2PB of storage via deduplication.<br><br>\n  <strong>Conflict handling</strong>: if two devices modify the same file while offline, both versions are kept \u2014 user sees \"conflicted copy\" and manually resolves. Alternatively: vector clocks to track causality and auto-merge text files (like Google Docs CRDT).</div></div>\n\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle eventual consistency in S3 for applications that require strong consistency?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Since December 2020, S3 provides strong read-after-write consistency for all operations \u2014 this is no longer a problem for new systems.</strong><br><br>\n  Historical context: before 2020, S3 had eventual consistency for LIST operations and overwrites of existing objects. This caused real bugs: upload a file, immediately list the bucket, the file might not appear. Developers had to add artificial delays or use DynamoDB to track object existence.<br><br>\n  Today: a successful PUT is immediately visible to all subsequent GET and LIST operations. No delays, no workarounds needed.<br><br>\n  <strong>Where consistency issues remain</strong>:<br>\n  1. <strong>Cross-region replication lag</strong>: if you enable S3 Cross-Region Replication (CRR), objects are eventually replicated to the destination region. Reads from the destination region might not see the latest version until replication completes (typically 15 minutes, but no SLA). For strong cross-region consistency, do not rely on S3 CRR alone \u2014 use a distributed database or accept the replication lag.<br>\n  2. <strong>Concurrent writes to the same key</strong>: if two clients simultaneously PUT the same S3 key, the \"last writer wins\" \u2014 but there is no atomic compare-and-swap (no \"write only if not modified\"). For concurrent update scenarios, use DynamoDB for metadata and version tracking alongside S3 for blob storage.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the \"small files problem\" in data lakes and how do you solve it?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Millions of small files in S3 make query engines (Spark, Athena, Redshift Spectrum) dramatically slower.</strong><br><br>\n  <strong>The problem</strong>: Flink flushes to S3 every 10 seconds. At 100 partitions \u00d7 6 flushes/minute \u00d7 60 minutes = 36,000 files/hour, each ~100KB. When Athena queries a day's data, it must open 864,000 files. S3 LIST + OPEN operations are expensive (~10ms each). 864,000 \u00d7 10ms = 2.4 hours of overhead before reading a single byte.<br><br>\n  <strong>Solutions</strong>:<br>\n  1. <strong>Compaction jobs</strong>: a daily Spark job reads all small files for each partition and rewrites them as a few large Parquet files (100\u2013500MB each). Athena now opens 10 files instead of 864,000. Requires a maintenance window or can run in the background during low-traffic hours.<br>\n  2. <strong>Increase flush interval</strong>: instead of flushing every 10 seconds, flush every 10 minutes. Fewer, larger files. Trade-off: longer lag before data is queryable.<br>\n  3. <strong>Delta Lake / Iceberg</strong>: these table formats include compaction operations (<code>OPTIMIZE</code> in Delta, <code>REWRITE_DATA_FILES</code> in Iceberg) that compact small files transactionally \u2014 no downtime, readers see consistent data throughout.</div></div>\n</section></div>\n\n<section id=\"decision-obj\">\n  <div class=\"sec-tag\">05 \u00b7 Decision Framework</div>\n  <h2>Storage type selection</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Object vs Block vs File Storage \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the software require a real filesystem (POSIX)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (databases, OS) \u2192</span><span class=\"opt-text\"><strong>Block storage (EBS, GCP PD).</strong> Attached as a disk. Sub-millisecond latency. Random read/write. Required for: PostgreSQL, MySQL, MongoDB \u2014 any database that writes WAL files and needs filesystem semantics. Cannot use S3 directly for a DB.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Go to Step 2.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Do multiple servers need to read/write the same files simultaneously?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (shared filesystem) \u2192</span><span class=\"opt-text\"><strong>File storage (EFS, NFS, Azure Files).</strong> POSIX filesystem mounted by multiple instances. Use for: shared config, legacy apps that read/write files and cannot be refactored, CMS media that multiple web servers access.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Go to Step 3.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">What is the access pattern \u2014 HTTP or programmatic?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">HTTP / URL-based access \u2192</span><span class=\"opt-text\"><strong>Object storage (S3/GCS) + CDN.</strong> Objects served via HTTP URLs. CDN caches at edge globally. Perfect for: images, videos, static files, any user-facing media. Pre-signed URLs for private access without exposing credentials.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Batch analytics / data lake \u2192</span><span class=\"opt-text\"><strong>Object storage (S3/GCS) with Parquet.</strong> Store raw data in Parquet format. Query with Athena/BigQuery/Redshift Spectrum. Lifecycle policies tier old data to Glacier automatically. Add Delta Lake/Iceberg for ACID transactions on top of S3.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <h3>S3 vs GCS vs Azure Blob \u2014 Quick Comparison</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">AWS S3</div><div class=\"concept-def\"><strong>The industry standard. Every major data tool integrates with S3 natively.</strong><br>\n      Unique features: S3 Select (query data inside objects with SQL without downloading), Intelligent-Tiering (auto cost optimisation), Object Lambda (transform objects on read), EventBridge integration.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Largest ecosystem. If you're on AWS, there's no reason to use anything else for object storage.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Google Cloud Storage</div><div class=\"concept-def\"><strong>Best integration with BigQuery and the GCP data ecosystem.</strong><br>\n      GCS \u2192 BigQuery: external tables query GCS Parquet files directly without loading. GCS \u2192 Dataflow: native integration for streaming pipelines. Multiregional storage for global CDN-like access.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">If your analytics runs on BigQuery, GCS is the natural companion.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Cost Optimisation</div><div class=\"concept-def\"><strong>Storage is cheap; data transfer OUT is expensive.</strong><br>\n      S3 storage: $0.023/GB/month (Standard). Data transfer OUT to internet: $0.09/GB. The CDN trick: CloudFront has a free tier for S3 origin transfers \u2014 route all user requests through CloudFront to eliminate S3 egress costs entirely.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 S3 \u2192 CloudFront transfer is free. CloudFront \u2192 users costs $0.085/GB. Net saving: significant at scale.</span></div></div>\n  </div>\n</section>\n<div class=\"footer\">OBJECT STORAGE \u00b7 S3 \u00b7 GCS \u00b7 MULTIPART UPLOAD \u00b7 PRE-SIGNED URLs \u00b7 CDN \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Storage' },
  message_queues: { title: 'Message Queues: SQS & RabbitMQ', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Message Queues: SQS, RabbitMQ vs Kafka</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Message Queues<br><em>SQS, RabbitMQ vs Kafka</em></h1>\n  <p class=\"hero-sub\">Queue vs stream, dead letter queues, fan-out, backpressure, exactly-once patterns \u2014 when to use each and how to make the right choice in system design interviews.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">SQS</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">RabbitMQ</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Fan-Out</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">DLQ</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">At-Least-Once</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#queues-vs-streams\">Queue vs Stream</a><a href=\"#patterns\">Patterns</a><a href=\"#sqs\">SQS vs RabbitMQ</a><a href=\"#examples\">System Design</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"queues-vs-streams\">\n  <div class=\"sec-tag\">00 \u00b7 The Critical Distinction</div>\n  <h2>Message Queue vs Event Stream \u2014 they are not the same</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Queue vs Stream \u2014 the post office analogy</div>\n    <div class=\"analogy-text\">\n      <strong>Message Queue (SQS/RabbitMQ)</strong> = a post office. A letter is delivered to one recipient and then destroyed. If you want two people to read it, send two letters. The post office's job is to deliver and confirm delivery.<br><br>\n      <strong>Event Stream (Kafka)</strong> = a newspaper printing plant. Every paper is kept on record for 7 days. Any subscriber can read any edition at any time. Multiple readers get the same paper independently.\n    </div>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Message Queue</div><div class=\"concept-def\"><strong>One consumer reads a message. Once consumed and acknowledged, it is deleted.</strong><br>\n      Point-to-point: one message \u2192 one consumer. Or fan-out: publish to topic \u2192 one copy per subscriber queue.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Ideal for task distribution: \"process this image resize job\" \u2014 you want exactly one worker to do it, not all of them. Built-in dead letter queues, retry logic, visibility timeout.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: SQS, RabbitMQ, ActiveMQ. Use for: email sending, image processing, order fulfillment tasks.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Event Stream</div><div class=\"concept-def\"><strong>Messages are retained. Multiple independent consumers can read all messages, each at their own pace.</strong><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Replay: Flink crashed? Replay from last offset. Multiple consumers: Flink, ClickHouse, and S3 all read the same stream independently.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Examples: Kafka, Kinesis, Pulsar. Use for: event sourcing, streaming analytics, audit logs, feeding multiple downstream systems.</span></div></div>\n  </div>\n</section>\n\n<section id=\"patterns\">\n  <div class=\"sec-tag\">01 \u00b7 Queue Patterns</div>\n  <h2>Dead letter queues, fan-out, priority, and backpressure</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Dead Letter Queue (DLQ)</div><div class=\"concept-def\"><strong>When a message fails processing N times, it moves to a DLQ instead of being silently dropped.</strong><br>\n      Flow: message enters queue \u2192 worker fails to process \u2192 message becomes visible again after visibility timeout \u2192 after 3 retries \u2192 moved to DLQ.<br>\n      DLQ stores failed messages for investigation and reprocessing.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No silent data loss. Failed messages are preserved and inspectable. Essential for production systems \u2014 without DLQ, a bad message can block a queue forever (poison pill).</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Visibility Timeout</div><div class=\"concept-def\"><strong>When a worker picks up a message, it becomes invisible to other workers for N seconds (the visibility timeout).</strong><br>\n      If the worker completes processing: explicitly deletes the message.<br>\n      If the worker crashes: timeout expires, message becomes visible again for another worker to pick up.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Automatic retry on worker failure. At-least-once delivery guarantee. Set timeout to 2x your expected processing time.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 At-least-once means duplicates are possible (worker completes but crashes before deleting). Make your consumers idempotent.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Fan-Out Pattern</div><div class=\"concept-def\"><strong>One message triggers multiple independent processing pipelines.</strong><br>\n      SNS (pub/sub topic) + multiple SQS queues: publish to SNS \u2192 SNS delivers a copy to each subscribed SQS queue \u2192 each queue has its own consumer processing independently.<br>\n      Example: new order event \u2192 (1) fulfillment queue, (2) analytics queue, (3) notification queue \u2014 all independent.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Decoupled services. New consumers added without touching the publisher. Each consumer has its own DLQ.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Backpressure</div><div class=\"concept-def\"><strong>When consumers cannot keep up with producers, the queue grows. Backpressure signals the producer to slow down.</strong><br>\n      Strategies:<br>\n      \u2022 <strong>Queue depth alarm</strong>: CloudWatch alarm when SQS depth &gt; 10K \u2192 auto-scale consumers.<br>\n      \u2022 <strong>Producer rate limiting</strong>: producer checks queue depth before sending; slows if deep.<br>\n      \u2022 <strong>Blocking send</strong>: Kafka producer blocks when buffer is full (internal backpressure).<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Without backpressure: queue grows unbounded \u2192 OOM or unbounded delay \u2192 cascading failure. Always monitor queue depth.</span></div></div>\n  </div>\n</section>\n\n<section id=\"sqs\">\n  <div class=\"sec-tag\">02 \u00b7 SQS vs RabbitMQ</div>\n  <h2>When to use each</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>AWS SQS</th><th>RabbitMQ</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Type</td><td>Fully managed, serverless</td><td>Self-managed broker</td></tr>\n      <tr><td class=\"row-head\">Ordering</td><td>Standard: best-effort. FIFO: guaranteed</td><td>Per-queue FIFO guaranteed</td></tr>\n      <tr><td class=\"row-head\">Throughput</td><td><span class=\"good\">Unlimited (auto-scales)</span></td><td><span class=\"warn\">~50K msg/sec per broker, cluster for more</span></td></tr>\n      <tr><td class=\"row-head\">Routing</td><td>Basic (queue per destination)</td><td><span class=\"good\">Rich exchanges: direct, fanout, topic, headers</span></td></tr>\n      <tr><td class=\"row-head\">Ops burden</td><td><span class=\"good\">Zero</span></td><td><span class=\"warn\">Medium \u2014 manage cluster, quorum, memory</span></td></tr>\n      <tr><td class=\"row-head\">Message retention</td><td>Up to 14 days (deleted on consume)</td><td>Configurable (deleted on consume)</td></tr>\n      <tr><td class=\"row-head\">Protocols</td><td>HTTP/SQS API only</td><td>AMQP, MQTT, STOMP, HTTP</td></tr>\n      <tr><td class=\"row-head\">Use when</td><td>AWS-native, variable load, zero ops</td><td>Complex routing, multi-protocol, existing AMQP</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">03 \u00b7 System Design Examples</div>\n  <h2>Message queues in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">E-Commerce Order Processing</div><span class=\"sd-example-tag\">ASYNC \u00b7 FAULT-TOLERANT</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDER PLACED</div><div class=\"choice-val\">User places order \u2192 API writes order to DB \u2192 publishes OrderPlaced event to SNS \u2192 SNS fans out to: (1) Fulfillment SQS Queue, (2) Notification SQS Queue, (3) Analytics SQS Queue. User gets immediate HTTP 200 \u2014 async processing happens independently.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FULFILLMENT</div><div class=\"choice-val\">Worker picks OrderPlaced from Fulfillment Queue \u2192 reserves inventory \u2192 creates shipment \u2192 publishes OrderFulfilled. Visibility timeout = 5 minutes (enough for fulfillment). DLQ captures failed orders after 3 retries \u2014 ops team investigates.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">VS KAFKA</div><div class=\"choice-val\">Why not Kafka here? Each order should be processed exactly once by fulfillment (point-to-point), not broadcast. SQS's delete-on-consume guarantees one fulfillment per order. Kafka would require consumer group management to achieve the same \u2014 more complex for this use case.</div></div>\n    </div>\n  </div>\n</section>\n\n\n<section id=\"ordering\">\n  <div class=\"sec-tag\">03 \u00b7 Message Ordering</div>\n  <h2>When order matters \u2014 and how to guarantee it</h2>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The interview gotcha</div>\n    <p>Candidates often assume message queues guarantee order. <strong>Most do not \u2014 or only guarantee order within a partition/group.</strong> Understanding the ordering semantics of each system is a senior-level expectation.</p>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">SQS Standard</div><div class=\"concept-def\"><strong>Best-effort ordering only.</strong> Messages may arrive out of order. May be delivered more than once.<br>\n      Why: SQS Standard routes messages across many redundant queues for maximum throughput. Order is not preserved across these internal queues.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Highest throughput (unlimited). Best for: tasks where order does not matter (image resizing, email sending, background jobs).</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 If you need order, use SQS FIFO \u2014 not Standard.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">SQS FIFO</div><div class=\"concept-def\"><strong>Strict first-in-first-out ordering AND exactly-once delivery within a message group.</strong><br>\n      Message Group ID: messages with the same group ID are processed in order. Different group IDs process in parallel.<br>\n      Example: all order events for order_123 share group_id=\"order_123\" \u2192 processed in sequence. Orders 123 and 456 processed in parallel.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Exactly-once processing (deduplication by message ID). Order guaranteed within group. Used for: order state machines, financial transactions, any workflow where step sequence matters.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Max 3,000 transactions/sec per queue (vs unlimited for Standard). If one message in a group fails and blocks, all subsequent messages in that group wait.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Kafka Ordering</div><div class=\"concept-def\"><strong>Strict ordering within a partition. No ordering guarantee across partitions.</strong><br>\n      All events for user_123 \u2192 same partition (keyed by user_id) \u2192 consumed in order by the same consumer thread. Events for user_456 \u2192 different partition \u2192 parallel, independent.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Per-entity ordering (all of one user's events are ordered) + high parallelism (different entities processed in parallel). The right model for most real-world ordering needs.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">RabbitMQ Ordering</div><div class=\"concept-def\"><strong>FIFO within a single queue with a single consumer. Multiple consumers break ordering.</strong><br>\n      With 3 consumers on one queue: message A \u2192 consumer 1 (slow, takes 5s), message B \u2192 consumer 2 (fast, takes 100ms). B is processed before A \u2014 out of order.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">To preserve order with RabbitMQ: use a single consumer. Or use one queue per \"entity\" (one queue per user) \u2014 but this doesn't scale to millions of users. RabbitMQ is a poor choice when strict per-entity ordering at scale matters \u2014 use Kafka instead.</span></div></div>\n  </div>\n</section>\n\n<section id=\"pubsub\">\n  <div class=\"sec-tag\">04 \u00b7 Pub/Sub vs Point-to-Point</div>\n  <h2>Two fundamentally different delivery models</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Point-to-Point<br>(Queue)</div><div class=\"concept-def\"><strong>One producer sends, one consumer receives. Message is deleted after consumption.</strong><br>\n      Multiple consumers on the same queue compete for messages \u2014 each message goes to exactly one consumer. This is task distribution: \"process this job\" should be done by one worker, not all workers.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Use for: task queues (image processing, email sending), work distribution, exactly-once processing. SQS, RabbitMQ queues.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Publish-Subscribe<br>(Topic)</div><div class=\"concept-def\"><strong>One producer publishes, ALL subscribers receive a copy. Message is not deleted after first consumption.</strong><br>\n      An OrderPlaced event published to SNS topic \u2192 Fulfillment Service gets a copy AND Notification Service gets a copy AND Analytics Service gets a copy. All three process independently.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Decoupled fan-out. Adding a new subscriber (e.g., new Fraud Detection service) requires zero changes to the publisher. Used for: event broadcasting, audit logging, feeding multiple downstream systems.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">SNS (pub/sub) + SQS (queue): the AWS pattern. SNS distributes to multiple SQS queues. Each queue has its own consumer group with independent retry logic and DLQ.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Kafka as Both</div><div class=\"concept-def\"><strong>Kafka supports both models via consumer groups.</strong><br>\n      <strong>Point-to-point</strong>: one consumer group, multiple consumers. Each partition assigned to one consumer. Messages load-balanced across consumers.<br>\n      <strong>Pub/sub</strong>: multiple independent consumer groups on the same topic. Each group gets all messages. Group A (Flink) and Group B (ClickHouse) both read the same events independently, at their own pace.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This flexibility is why Kafka replaced both SQS-style queues and SNS-style topics in many architectures. One transport layer serves all consumption patterns.</span></div></div>\n  </div>\n</section>\n\n<section id=\"more-sd-mq\">\n  <div class=\"sec-tag\">05 \u00b7 More System Design Examples</div>\n  <h2>Message queue decisions in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Notification System \u2014 Multi-Channel Fan-Out</div><span class=\"sd-example-tag\">FAN-OUT \u00b7 SLA \u00b7 ORDERING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TRIGGER</div><div class=\"choice-val\">NotificationRequested event published to SNS. SNS fans out to 4 SQS queues: Push Queue, Email Queue, SMS Queue, In-App Queue. Each queue has dedicated consumers with independent retry policies (push can retry every 5s, SMS retries every 30s due to cost).</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">RATE LIMITING</div><div class=\"choice-val\">Email provider (SendGrid) has send rate limits. SQS consumer reads from Email Queue at a controlled rate (Lambda with reserved concurrency = 10 \u2192 max 10 emails/second processed). Queue absorbs bursts \u2014 during flash sales, thousands of \"order confirmed\" emails queue up and drain at 10/sec.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDERING</div><div class=\"choice-val\">Notification ordering matters for chat (messages must arrive in order). Chat notifications use SQS FIFO with message group ID = conversation_id. All messages in one conversation processed sequentially. Different conversations process in parallel.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DLQ MONITORING</div><div class=\"choice-val\">Each channel's SQS queue has a DLQ. CloudWatch alarm: DLQ depth &gt; 0 \u2192 PagerDuty alert. Ops investigates every failed notification. DLQ messages inspected to find: malformed payloads, invalid phone numbers, email bounces, device tokens expired.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">04 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you guarantee exactly-once processing with SQS (which is at-least-once)?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>SQS Standard queues guarantee at-least-once delivery \u2014 duplicates are possible. Make your consumers idempotent.</strong><br><br>\n  <strong>Option 1 \u2014 SQS FIFO queues</strong>: exactly-once within a 5-minute deduplication window. Include a MessageDeduplicationId \u2014 if the same ID is submitted twice, SQS discards the duplicate. Cost: 3x price of Standard queues, lower throughput (3K msg/sec vs unlimited).<br><br>\n  <strong>Option 2 \u2014 Idempotent consumers</strong>: check if this messageId has been processed before. Store processed message IDs in Redis (SET with TTL=24h) or a DB dedup table. Before processing: <code>SET processed:{messageId} 1 NX EX 86400</code> \u2014 if NX succeeds (key did not exist), process. Otherwise, skip as duplicate. Delete SQS message either way.<br><br>\n  <strong>Option 3 \u2014 Idempotent operations</strong>: design your processing so that doing it twice has the same result as once. Example: <code>UPDATE orders SET status='fulfilled' WHERE id=X AND status='pending'</code> \u2014 running this twice only updates once (second run finds status is already 'fulfilled').</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">When should you use a message queue vs calling the downstream service directly?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Use a queue when temporal decoupling adds value. Use direct calls when it does not.</strong><br><br>\n  <strong>Use a message queue when:</strong><br>\n  \u2014 The downstream service might be slow, unavailable, or experiencing load spikes that you want to absorb<br>\n  \u2014 Processing can be deferred (email sends, video transcoding, report generation)<br>\n  \u2014 You need to fan out to multiple downstream systems<br>\n  \u2014 You need automatic retry on failure without complex retry logic in your code<br>\n  \u2014 Processing throughput is bursty (queue smooths it out)<br><br>\n  <strong>Use direct calls (synchronous) when:</strong><br>\n  \u2014 The caller needs the result to continue (payment confirmation, authentication check)<br>\n  \u2014 Latency SLA is tight (&lt;100ms \u2014 queue adds overhead)<br>\n  \u2014 The operation is simple and the downstream service is reliable<br>\n  \u2014 You need to return errors to the user immediately<br><br>\n  <strong>Rule of thumb</strong>: can the user proceed without waiting for this operation? If yes \u2192 queue. If no \u2192 synchronous call.</div></div>\n\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">When should you use Kafka instead of SQS for a task queue?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Use Kafka when you need replay, multiple independent consumers, or extremely high throughput. Use SQS when you need simple task distribution with zero ops overhead.</strong><br><br>\n  <strong>Choose Kafka when:</strong><br>\n  \u2014 You need to replay messages (Kafka retains for 7 days; SQS deletes on consumption)<br>\n  \u2014 Multiple independent consumers need the same data (Kafka consumer groups; SQS message goes to one consumer)<br>\n  \u2014 You process more than 50K messages/second (SQS FIFO caps at 3K/sec, Standard is unlimited but unordered)<br>\n  \u2014 You want the same transport to serve both streaming analytics (Flink) and task workers (application consumers)<br><br>\n  <strong>Choose SQS when:</strong><br>\n  \u2014 Simple \"do this job once\" semantics \u2014 no replay needed<br>\n  \u2014 Zero ops budget \u2014 SQS is fully managed, Kafka requires cluster management<br>\n  \u2014 AWS ecosystem \u2014 SQS integrates natively with Lambda, SNS, EventBridge<br>\n  \u2014 Moderate throughput (&lt;10K messages/sec for most task queues)<br>\n  \u2014 Need guaranteed FIFO with exactly-once semantics for low-to-moderate throughput<br><br>\n  <strong>The common mistake</strong>: using Kafka for simple task queues where SQS would suffice. Kafka's operational complexity (brokers, ZooKeeper/KRaft, partition management, consumer group rebalancing) is only justified when you genuinely need its streaming capabilities.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle a poison pill message \u2014 one that crashes your consumer every time?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>A poison pill is a malformed or unprocessable message that causes the consumer to crash or fail on every retry, blocking the queue.</strong><br><br>\n  <strong>SQS approach \u2014 maxReceiveCount + DLQ</strong>:<br>\n  Set <code>maxReceiveCount = 3</code> on your queue. After 3 failed deliveries, the message is automatically moved to the DLQ. The consumer continues processing other messages. DLQ alert fires \u2014 ops team investigates the specific message. Fix: either fix the consumer code to handle this message type, or discard the message from DLQ if it is genuinely malformed data.<br><br>\n  <strong>Kafka approach \u2014 skip and log</strong>:<br>\n  Kafka does not have a native DLQ. Options: (1) catch the exception, log the problematic message + offset to an error Kafka topic (manual DLQ pattern), then commit the offset and continue. (2) Use Spring Kafka's SeekToCurrentErrorHandler which retries N times then calls a recovery callback. (3) Use a dead-letter topic: on failure, produce to <code>topic.DLT</code> and commit the original offset.<br><br>\n  <strong>Prevention</strong>: validate message schema at ingest time. Reject malformed messages at the producer with an explicit schema (Avro + Schema Registry is the Kafka standard). Malformed messages never enter the queue in the first place.</div></div>\n</section></div>\n\n<section id=\"decision-mq\">\n  <div class=\"sec-tag\">06 \u00b7 Decision Framework</div>\n  <h2>Choosing your messaging system</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Message Queue vs Event Stream \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Do multiple independent consumers need to read the same messages?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (broadcast) \u2192</span><span class=\"opt-text\"><strong>Event stream (Kafka / Kinesis).</strong> Multiple consumer groups each get all messages independently. Flink, ClickHouse, S3 sink all read the same Kafka topic. Retention means replay is possible.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (one consumer per message) \u2192</span><span class=\"opt-text\">Go to Step 2. Queue semantics.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need strict FIFO ordering per entity?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>SQS FIFO</strong> (up to 3K msg/sec) or <strong>Kafka</strong> (partition by entity key). SQS FIFO: set MessageGroupId = entity ID. All messages for that entity are processed in order. Kafka: key by entity ID \u2192 same partition \u2192 same consumer thread \u2192 ordered.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (order doesn't matter) \u2192</span><span class=\"opt-text\"><strong>SQS Standard.</strong> Unlimited throughput. Best-effort ordering. Simplest, cheapest, fully managed. Perfect for: image resizing jobs, email sending, background tasks where order is irrelevant.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need message replay / audit trail?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Kafka.</strong> Configurable retention (hours to forever). Replay from any offset. Consumer crashed? Resume from last committed offset. New consumer added? Read from the beginning. SQS deletes on consumption \u2014 no replay possible.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>SQS</strong> (zero ops) or <strong>RabbitMQ</strong> (complex routing). Choose based on ops budget and routing needs, not replay.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your ops budget?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Zero ops (managed) \u2192</span><span class=\"opt-text\"><strong>SQS / SNS / EventBridge.</strong> No infrastructure to manage. Auto-scales. Integrates with Lambda. Pay per request. Best default for AWS-native systems.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Medium ops OK \u2192</span><span class=\"opt-text\"><strong>MSK (managed Kafka) or Confluent Cloud.</strong> Kafka without the operational burden. Handles broker management, replication, upgrades.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Full control needed \u2192</span><span class=\"opt-text\"><strong>Self-managed Kafka or RabbitMQ.</strong> Maximum flexibility, tuning, and cost efficiency at extreme scale. Requires dedicated platform team.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n<div class=\"footer\">MESSAGE QUEUES \u00b7 SQS \u00b7 RABBITMQ \u00b7 DLQ \u00b7 FAN-OUT \u00b7 AT-LEAST-ONCE \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Queues' },
  cdn_edge: { title: 'CDN & Edge Computing', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>CDN & Edge: Cloudflare, CloudFront, Fastly</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>CDN & Edge<br><em>Cloudflare, CloudFront, Fastly</em></h1>\n  <p class=\"hero-sub\">PoP architecture, pull vs push, cache invalidation, HLS video streaming, edge compute, DDoS mitigation \u2014 every CDN concept for system design interviews.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Cloudflare</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">CloudFront</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">HLS/DASH</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Edge Compute</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">DDoS</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#what\">What CDNs Do</a><a href=\"#how\">How They Work</a><a href=\"#video\">Video Streaming</a><a href=\"#edge-compute\">Edge Compute</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"what\">\n  <div class=\"sec-tag\">00 \u00b7 What a CDN Does</div>\n  <h2>Serving content from 200 cities instead of one data centre</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The warehouse vs corner shop analogy</div>\n    <div class=\"analogy-text\">\n      Your origin server is a central warehouse in Mumbai. A user in Tokyo requests a video.<br><br>\n      <strong>Without CDN</strong>: request travels Mumbai \u2192 Tokyo (~150ms round trip). At 10MB/s, a 1GB video takes 100 seconds to deliver from origin to the user.<br><br>\n      <strong>With CDN</strong>: A CDN edge node in Tokyo has a cached copy. Same video served at ~1ms latency from the nearby PoP (Point of Presence). The origin server is never involved.<br><br>\n      The CDN's job: be a corner shop stocking the 100 most popular items, so customers do not have to travel to the warehouse for common requests.\n    </div>\n  </div>\n</section>\n\n<section id=\"how\">\n  <div class=\"sec-tag\">01 \u00b7 How CDNs Work</div>\n  <h2>PoP architecture, pull vs push, and cache invalidation</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">PoP & Anycast</div><div class=\"concept-def\"><strong>CDNs have 200+ Points of Presence (PoPs) worldwide. Anycast routing sends users to the nearest PoP automatically.</strong><br>\n      Anycast: multiple PoPs announce the same IP address. BGP routing sends the user's packet to the geographically nearest PoP \u2014 no DNS lookup delay, no manual geo-routing config.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cloudflare: 200+ cities. Akamai: 4,000+ PoPs. Fastly: 50+ PoPs but higher bandwidth capacity. User latency: &lt;20ms to nearest PoP anywhere in the world.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Pull CDN (Lazy)</div><div class=\"concept-def\"><strong>CDN fetches content from origin on the first request (cache miss), then caches it.</strong><br>\n      First user in Tokyo requests <code>/images/photo.jpg</code> \u2192 CDN Tokyo misses \u2192 fetches from origin \u2192 caches \u2192 serves. All subsequent Tokyo users get it from cache.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 No management needed. Content is cached on demand. Automatically distributes popular content globally. Suitable for most web assets.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 First user in each region gets origin latency (cache miss penalty). Content that is never requested globally stays uncached.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Push CDN (Eager)</div><div class=\"concept-def\"><strong>You proactively upload content to all CDN PoPs before any user requests it.</strong><br>\n      Before a product launch: push all assets to 200+ PoPs. First user in Tokyo gets the asset from cache (zero miss).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Zero cache miss latency. Guaranteed availability. Ideal for: software releases, video premiere events, product launch assets.</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Management overhead. You pay for storage at all PoPs even if content is never requested there. Not suitable for dynamic or user-specific content.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Cache Invalidation</div><div class=\"concept-def\"><strong>When origin content changes, you need to tell CDN edge nodes to drop their cached copies.</strong><br>\n      <strong>TTL expiry</strong>: set a short <code>Cache-Control: max-age=300</code>. Stale for up to 5 minutes.<br>\n      <strong>Cache purge API</strong>: Cloudflare/CloudFront have APIs to immediately invalidate specific URLs or patterns. Used when you push a critical fix.<br>\n      <strong>Cache versioning</strong>: embed version in filename \u2014 <code>app.v2.3.js</code>. Old URL still cached (fine), new URL fetched fresh. Zero-downtime asset updates.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Best practice: use cache versioning for static assets (infinite TTL + version in URL). Use short TTL for semi-dynamic content. Use purge API for emergency fixes.</span></div></div>\n  </div>\n</section>\n\n<section id=\"video\">\n  <div class=\"sec-tag\">02 \u00b7 Video Streaming via CDN</div>\n  <h2>HLS, DASH, and adaptive bitrate \u2014 how Netflix/YouTube actually work</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Adaptive Bitrate (ABR)</div><div class=\"concept-def\"><strong>Video is encoded at multiple quality levels. The player automatically switches quality based on network speed.</strong><br>\n      A 2-hour movie is encoded at: 360p (1Mbps), 720p (4Mbps), 1080p (8Mbps), 4K (25Mbps).<br>\n      Player measures available bandwidth every few seconds and requests the appropriate quality.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Smooth playback despite varying network conditions. Starts at low quality (immediate playback) and upgrades as bandwidth permits.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">HLS Segmentation</div><div class=\"concept-def\"><strong>Video is split into 2\u201310 second segments stored as individual files. A manifest file (.m3u8) lists all segments.</strong><br>\n      Player downloads manifest \u2192 fetches segments sequentially \u2192 each segment is cached independently by CDN.<br>\n      <code>index.m3u8</code> \u2192 <code>segment001.ts, segment002.ts ...</code><br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 CDN caches each segment independently. Popular segments (the first 10 seconds every viewer watches) have extremely high cache hit rates. Seeks jump to the correct segment URL directly.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">CDN Role in Video</div><div class=\"concept-def\"><strong>Video segments are static files \u2192 perfect for CDN caching.</strong><br>\n      Netflix: 3 copies of each segment stored in S3 (origin). CloudFront caches hot segments at 200+ PoPs. Popular shows: 99%+ cache hit rate. Long-tail content: served from origin.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Netflix offloads ~95% of video bytes to CDN. Origin bandwidth savings: enormous. User experience: consistent quality regardless of Netflix's origin capacity.</span></div></div>\n  </div>\n</section>\n\n<section id=\"edge-compute\">\n  <div class=\"sec-tag\">03 \u00b7 Edge Compute</div>\n  <h2>Running code at the CDN edge</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">What Is Edge Compute</div><div class=\"concept-def\"><strong>Run serverless code at the CDN PoP, close to the user \u2014 before the request reaches your origin.</strong><br>\n      Examples: Cloudflare Workers, AWS Lambda@Edge, Fastly Compute@Edge.<br>\n      Use for: A/B testing (redirect 10% of users to new version at edge), auth token validation (validate JWT at edge, reject bad tokens before they hit origin), geo-based redirects, request transformation.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">CDN for DDoS</div><div class=\"concept-def\"><strong>CDN absorbs DDoS attacks at the edge \u2014 attack traffic never reaches your origin.</strong><br>\n      A 1Tbps DDoS attack is distributed across 200 PoPs. Each absorbs 5Gbps \u2014 trivial for a large PoP. Your 10Gbps origin link never sees the attack.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cloudflare's network capacity: 100+ Tbps. The largest DDoS attacks ever recorded were absorbed by Cloudflare without origin impact. Used by: every large web property (including FAANG).</span></div></div>\n  </div>\n</section>\n\n\n<section id=\"decision-cdn\">\n  <div class=\"sec-tag\">04 \u00b7 Decision Framework</div>\n  <h2>How to talk about CDN in a system design interview</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>CDN Strategy Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Is the content static (same for all users)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES (static) \u2192</span><span class=\"opt-text\"><strong>Definitely use CDN.</strong> Images, videos, JS/CSS bundles, compiled HTML. Cache at edge with long TTL (1 year for versioned assets). This is the highest-ROI CDN use case \u2014 zero origin load for cached content.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO (dynamic/personalised) \u2192</span><span class=\"opt-text\">Consider edge caching only for public, cacheable API responses. User-specific content cannot be cached at CDN without per-user cache keys (defeats the purpose). Go to Step 3.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">For static content: push or pull CDN?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Known ahead of time \u2192</span><span class=\"opt-text\"><strong>Push CDN.</strong> Proactively distribute to all PoPs before users request. Zero first-request miss. Use for: software releases, product launch assets, video premieres where you know demand will spike immediately.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Demand unpredictable \u2192</span><span class=\"opt-text\"><strong>Pull CDN (default).</strong> First request per PoP hits origin. Subsequent requests served from cache. Automatically distributes popular content globally. Works for 99% of use cases.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you need logic at the edge (auth, A/B testing, geo-routing)?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Edge Compute</strong> (Cloudflare Workers, Lambda@Edge). Validate JWTs at edge (reject invalid tokens before they hit origin), A/B test routing (redirect 10% to new version), geo-based content (show Indian prices to Indian users). Sub-ms overhead, no origin round-trip.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>Standard CDN caching.</strong> Just set appropriate Cache-Control headers on your origin responses. Cloudflare/CloudFront respects them automatically.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">What is your cache invalidation strategy?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Versioned filenames \u2192</span><span class=\"opt-text\"><strong>Best approach for static assets.</strong> <code>app.v2.3.7.js</code> \u2014 old URL stays cached forever, new URL fetched fresh. Zero-downtime deploy. Infinite TTL (Cache-Control: max-age=31536000, immutable).</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Purge API \u2192</span><span class=\"opt-text\"><strong>For emergencies.</strong> <code>POST api.cloudflare.com/cache/purge</code> with specific URLs. Propagates globally in &lt;150ms (Fastly) to ~30s (CloudFront). Use sparingly \u2014 not designed for high-frequency changes.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Short TTL \u2192</span><span class=\"opt-text\"><strong>For semi-dynamic content.</strong> <code>Cache-Control: max-age=300</code>. Stale for up to 5 minutes. Acceptable for: news articles, product prices, API responses that change infrequently.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"sd-examples-cdn\">\n  <div class=\"sec-tag\">05 \u00b7 System Design Examples</div>\n  <h2>CDN architecture in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Netflix \u2014 Global Video Delivery</div><span class=\"sd-example-tag\">PETABYTES \u00b7 ADAPTIVE STREAMING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">OPEN CONNECT</div><div class=\"choice-val\">Netflix runs its own CDN called Open Connect. Netflix appliances are co-located in ISP data centers worldwide (1,000+ locations). ISPs host these appliances for free in exchange for reduced peering costs. Result: ~95% of Netflix traffic served from inside the ISP's own network \u2014 no internet backbone traversal for the user's last mile.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PROACTIVE CACHING</div><div class=\"choice-val\">Netflix pre-loads popular content to Open Connect appliances during off-peak hours (2\u20134am local time). Trending shows are pushed to all regional appliances before peak viewing. Cache hit rate for popular titles: ~99%. Long-tail content served from S3 origin via CloudFront.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">HLS SEGMENTS</div><div class=\"choice-val\">Each 2-hour movie = ~720 \u00d7 10-second HLS segments per quality level \u00d7 5 quality levels = 3,600 cached files. The first 60 seconds (6 segments) of every show is pre-loaded to all major PoPs \u2014 zero wait time when users press play. Subsequent segments loaded as user watches.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY OWN CDN</div><div class=\"choice-val\">At Netflix's scale (~500Tbps peak bandwidth), commercial CDN costs would be $500M+/year. Open Connect amortises over company lifetime and gives Netflix full control over caching policy, health monitoring, and routing decisions.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">E-Commerce \u2014 Asset Pipeline & API Caching</div><span class=\"sd-example-tag\">MIXED STATIC + DYNAMIC</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">STATIC ASSETS</div><div class=\"choice-val\">Product images, CSS, JS bundled with content hash in filename (<code>main.3f2c9a.js</code>). Deployed to S3 \u2192 CloudFront. Cache-Control: max-age=31536000, immutable. Images CDN served from nearest PoP in &lt;10ms globally. Origin S3 never receives image requests after initial population.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PRODUCT API</div><div class=\"choice-val\"><code>GET /api/products/{id}</code> response: Cache-Control: public, max-age=300, s-maxage=3600. Browser caches 5 minutes, CDN caches 1 hour. Product catalog changes are infrequent \u2014 1-hour CDN TTL is acceptable. CloudFront serves ~80% of product API requests without touching origin.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PERSONALISED</div><div class=\"choice-val\"><code>GET /api/cart</code>, <code>GET /api/user</code>: Cache-Control: private, no-store. CDN never caches user-specific data. These requests always reach origin. Keep non-cacheable API calls minimal \u2014 design your API to maximise cacheable endpoints.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">FLASH SALE</div><div class=\"choice-val\">Flash sale landing page pre-pushed to all CDN PoPs 5 minutes before launch. Warm cache ensures zero origin load when 1M users hit the page simultaneously. Origin only handles the purchase API calls \u2014 which cannot be cached.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">04 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you cache personalised or authenticated content at the CDN?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>The standard CDN model caches public content. Personalised content requires one of three approaches:</strong><br><br>\n  <strong>1. Edge side includes (ESI)</strong>: The page has a public frame (cached) with placeholder tags for personalised sections. CDN fetches only the personalised fragment from origin (small request) and assembles the full page. Used by: Akamai ESI, Varnish.<br><br>\n  <strong>2. Split the response</strong>: API returns a public body + a personalised section. Public body cached at CDN (TTL=1h). Personalised section fetched fresh from origin on each request (bypass cache). Combine on the client.<br><br>\n  <strong>3. Cache by session/user segment</strong>: CDN can cache separate copies per cache key, including cookies or auth headers: <code>Vary: Authorization</code>. But this effectively defeats caching for large user populations (one cache entry per user). Only viable for small user pools or role-based segmentation (admin vs regular user).<br><br>\n  <strong>General rule</strong>: use CDN for the parts of your response that are genuinely the same for all users. Fetch personalised parts dynamically. The split between cacheable and dynamic is a key architectural decision.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">Cloudflare vs CloudFront vs Fastly \u2014 which should you use?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>All three are production-grade. The decision is usually driven by cloud commitment and specific feature needs.</strong><br><br>\n  <strong>CloudFront (AWS)</strong>: Best choice if you are already on AWS. Native integration with S3 (origin), ALB, API Gateway, Lambda@Edge. Pricing: per-GB transfer + per-request. Can get expensive at very high volume. Management via AWS Console/IaC (Terraform, CDK).<br><br>\n  <strong>Cloudflare</strong>: Independent of cloud provider. Largest network (200+ PoPs, 100+ Tbps). Best DDoS protection. Workers are the most capable edge compute. Generous free tier. Flat pricing at enterprise scale (often cheaper than CloudFront for high-volume). Best choice for: security-first setups, cloud-agnostic architectures, maximising CDN network size.<br><br>\n  <strong>Fastly</strong>: Fewer PoPs but very high capacity at each. Instant purge API (&lt;150ms globally) \u2014 critical for news sites and real-time content. Varnish-based \u2014 very developer-friendly cache configuration. Best choice for: media companies, news sites, any use case where sub-second cache invalidation is critical.</div></div>\n\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How does CDN handle HTTPS \u2014 does the CDN see your encrypted traffic?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Yes \u2014 the CDN terminates TLS on your behalf. The CDN can see the decrypted content.</strong><br><br>\n  When a user connects to your CDN (Cloudflare, CloudFront), TLS is terminated at the CDN edge. The CDN decrypts the request, makes a routing decision (cache hit or origin fetch), and re-encrypts for the origin if needed.<br><br>\n  <strong>End-to-end encryption</strong>: configure your CDN to also use HTTPS when fetching from origin (origin pull over HTTPS). This means: User \u2192 TLS \u2192 CDN edge \u2192 TLS \u2192 Origin. Two separate TLS sessions, both encrypted. The CDN can see the plaintext in the middle \u2014 this is a trust question, not a technical limitation.<br><br>\n  <strong>TLS certificates</strong>: CDNs provision and renew TLS certificates automatically (Cloudflare's Universal SSL, CloudFront ACM). You do not need to manage certificate rotation. The CDN's certificate covers your domain (<code>yourdomain.com</code>) via SNI (Server Name Indication) \u2014 one IP address serves HTTPS for thousands of domains on shared infrastructure.<br><br>\n  <strong>For regulated industries</strong> (healthcare, finance): check your compliance requirements. Some regulations require end-to-end encryption where only the final recipient can decrypt. In practice, most enterprises use CDNs for HTTPS with contractual data processing agreements (DPAs) with the CDN provider.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">What is the difference between a CDN and a reverse proxy \u2014 can Cloudflare Workers replace your backend?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>A CDN is a distributed reverse proxy network optimised for caching and delivery. Workers extend it to run arbitrary code at the edge.</strong><br><br>\n  <strong>CDN without Workers</strong>: caches and delivers static/cacheable content. Cannot make database queries, cannot run business logic, cannot access your internal APIs. Acts as a transparent pass-through for uncached requests.<br><br>\n  <strong>Cloudflare Workers</strong>: V8 JavaScript/WASM runtime at every PoP. Can: read/write KV store (Cloudflare KV, Durable Objects), make HTTP requests to external services, modify request/response on the fly, implement rate limiting logic, run ML inference (Workers AI).<br><br>\n  <strong>What Workers can replace</strong>: stateless edge functions (JWT validation, header manipulation, A/B testing, geo-routing, simple redirects), static API responses (config, feature flags), lightweight personalization.<br><br>\n  <strong>What Workers cannot replace</strong>: anything requiring your primary database (Cloudflare KV has ~50ms global read latency but limited querying capabilities), long-running computations (&gt;30ms CPU limit per request), streaming heavy media processing.<br><br>\n  <strong>The architecture</strong>: Workers as edge compute + your origin as the authority for dynamic data. Workers handle 90% of requests at the edge; only complex, personalised, or write requests reach your origin.</div></div>\n</section></div>\n<div class=\"footer\">CDN \u00b7 EDGE \u00b7 CLOUDFLARE \u00b7 CLOUDFRONT \u00b7 HLS \u00b7 ADAPTIVE BITRATE \u00b7 DDOS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'CDN' },
  observability: { title: 'Monitoring & Observability', srcdoc: "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Monitoring & Observability: The Three Pillars</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style></head><body>\n<div class=\"hero\"><div class=\"hero-inner\">\n  <div class=\"hero-tag\">System Design \u00b7 FAANG Interview Prep \u00b7 Manish-Almanac</div>\n  <h1>Monitoring & Observability<br><em>The Three Pillars</em></h1>\n  <p class=\"hero-sub\">Metrics, logs, traces \u2014 SLI/SLO/SLA, error budgets, four golden signals, Prometheus/Grafana, distributed tracing and alerting best practices.</p>\n  <div class=\"db-pills\"><span class=\"db-pill\" style=\"border-color:#c0392b;color:#c0392b;background:#c0392b18\">Prometheus</span><span class=\"db-pill\" style=\"border-color:#1a4f8a;color:#1a4f8a;background:#1a4f8a18\">Jaeger / OTEL</span><span class=\"db-pill\" style=\"border-color:#1a7a4a;color:#1a7a4a;background:#1a7a4a18\">SLO / SLA</span><span class=\"db-pill\" style=\"border-color:#b8720a;color:#b8720a;background:#b8720a18\">Golden Signals</span><span class=\"db-pill\" style=\"border-color:#6040a0;color:#6040a0;background:#6040a018\">Error Budget</span></div>\n</div></div>\n<nav class=\"nav\"><a href=\"#three-pillars\">Three Pillars</a><a href=\"#slo\">SLI/SLO/SLA</a><a href=\"#tools\">Tools & Signals</a><a href=\"#followups\">Follow-ups</a></nav>\n<div class=\"wrap\">\n<section id=\"three-pillars\">\n  <div class=\"sec-tag\">00 \u00b7 The Three Pillars</div>\n  <h2>Metrics, Logs, and Traces \u2014 why you need all three</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The hospital analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      Your system is a patient. Observability is how doctors understand what is happening inside.<br><br>\n      <strong>Metrics</strong> are the vital signs: heart rate 72bpm, blood pressure 120/80. Numbers over time. They tell you something is wrong but not why.<br><br>\n      <strong>Logs</strong> are the doctor's notes: \"14:23:01 \u2014 patient reported chest pain. 14:23:45 \u2014 administered aspirin.\" Text events at specific times. They tell you what happened, step by step.<br><br>\n      <strong>Traces</strong> are the MRI scan: shows exactly which organ is causing the problem, how blood flows through each one, and where the blockage is. For distributed systems: shows exactly which service caused the latency.\n    </div>\n  </div>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Metrics</div><div class=\"concept-def\"><strong>Numeric measurements over time. Aggregated, efficient, alertable.</strong><br>\n      Examples: requests/sec, p99 latency, error rate, CPU usage, DB connections.<br>\n      Storage: time-series databases (Prometheus, InfluxDB) designed for fast aggregation over time ranges.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Cheap to store (numbers, not text). Fast to query. Essential for dashboards and alerting. Answer: \"is something wrong?\"</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Cannot tell you why something is wrong. High cardinality metrics (one time series per user ID) explode storage costs.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Logs</div><div class=\"concept-def\"><strong>Text records of discrete events. Timestamped. Searchable.</strong><br>\n      Examples: \"ERROR: DB connection failed \u2014 timeout after 5000ms\", \"INFO: user:123 logged in from IP 1.2.3.4\"<br>\n      Storage: Elasticsearch (ELK stack) or Loki (cheaper, label-based).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Rich context. Exact error messages. Correlate events by user/session/request ID. Answer: \"what exactly happened?\"</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Expensive to store at high volume. Unstructured logs are hard to query \u2014 use structured JSON logging. Do not log sensitive data.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Traces</div><div class=\"concept-def\"><strong>Records the path of a single request through all microservices, with timing at each hop.</strong><br>\n      A user request spawns a trace with a unique trace_id. Each service call is a span. The trace shows: API Gateway (10ms) \u2192 Auth Service (5ms) \u2192 Product Service (200ms) \u2192 DB query (180ms of that 200ms).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Immediately identifies which service is slow. Essential for microservices. Answer: \"which service is causing the problem?\"</span><br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 Requires instrumentation in every service. Storage costs proportional to request volume \u00d7 service count. Use sampling (store 1% of traces, all error traces).</span></div></div>\n  </div>\n</section>\n\n<section id=\"slo\">\n  <div class=\"sec-tag\">01 \u00b7 SLI, SLO, SLA</div>\n  <h2>How to define and measure reliability \u2014 Director-level expected</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">SLI<br>(Service Level Indicator)</div><div class=\"concept-def\"><strong>A quantitative measure of service behaviour. The thing you actually measure.</strong><br>\n      Examples: request success rate (% of requests returning non-5xx), p99 latency (99th percentile response time), availability (% of time service is up).<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">SLIs are the raw measurements. Choose SLIs that directly reflect the user experience.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">SLO<br>(Service Level Objective)</div><div class=\"concept-def\"><strong>The target for your SLI. The internal goal your team commits to.</strong><br>\n      Examples: \"99.9% of requests complete successfully\" (three nines), \"p99 latency \u2264 200ms\", \"availability \u2265 99.95% per month\".<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 SLOs drive engineering decisions. If you are burning your error budget, prioritise reliability work. If you are comfortably meeting SLOs, invest in features.</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">99.9% availability = 8.7 hours downtime/year. 99.99% = 52 minutes. 99.999% = 5 minutes. Know these numbers.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">SLA<br>(Service Level Agreement)</div><div class=\"concept-def\"><strong>The contractual commitment to customers, with financial penalties for breach.</strong><br>\n      AWS EC2 SLA: 99.99% availability. If violated: customer gets service credits.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 SLA should be more conservative than your SLO. Your internal SLO is 99.95% so you have headroom before violating the 99.9% SLA you've contractually committed to customers.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Error Budget</div><div class=\"concept-def\"><strong>The amount of unreliability you are allowed per period before violating your SLO.</strong><br>\n      SLO: 99.9% success rate over 30 days. That is 0.1% allowed failures = 43.2 minutes of downtime allowed per month.<br>\n      If you deploy a bad release and burn 30 minutes of error budget, you have 13 minutes left that month.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Error budgets make reliability discussions data-driven. \"We cannot deploy this risky feature \u2014 we have only 5 minutes of error budget left this month.\"</span><br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Google SRE invented this concept. It is the key metric for Director-level reliability conversations.</span></div></div>\n  </div>\n</section>\n\n<section id=\"tools\">\n  <div class=\"sec-tag\">02 \u00b7 Tools & Golden Signals</div>\n  <h2>Prometheus, Grafana, Jaeger, and the four golden signals</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Four Golden Signals<br>(Google SRE Book)</div><div class=\"concept-def\"><strong>The four metrics that matter most for any service:</strong><br>\n      1. <strong>Latency</strong>: how long it takes to serve a request. Track p50, p95, p99 separately \u2014 averages hide outliers.<br>\n      2. <strong>Traffic</strong>: demand on your system (requests/sec, messages/sec, transactions/sec).<br>\n      3. <strong>Errors</strong>: rate of failed requests (5xx errors, exceptions, timeouts).<br>\n      4. <strong>Saturation</strong>: how \"full\" your service is (CPU %, memory %, DB connection pool utilisation, queue depth).<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 If you only monitor these four for every service, you will catch 90% of production incidents before users notice.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Prometheus + Grafana</div><div class=\"concept-def\"><strong>The standard open-source metrics stack.</strong><br>\n      Prometheus: pulls metrics from /metrics endpoints every 15s. Stores as time-series. PromQL query language for aggregations.<br>\n      Grafana: dashboards on top of Prometheus (and many other sources). Pre-built dashboards for Kubernetes, PostgreSQL, Redis, etc.<br>\n      <code>rate(http_requests_total{status=~\"5..\"}[5m])</code> \u2014 error rate over last 5 minutes.<br>\n      <span style=\"color:#5a5848;font-size:12.5px;\">Used by: Grafana Labs (obviously), Uber, DigitalOcean, dozens of FAANG-adjacent companies. Kubernetes ships Prometheus-compatible metrics by default.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Distributed Tracing<br>(Jaeger / Zipkin)</div><div class=\"concept-def\"><strong>OpenTelemetry is the emerging standard for instrumentation. One SDK, plugs into any backend (Jaeger, Zipkin, Tempo, Datadog).</strong><br>\n      Instrument your code once with OpenTelemetry SDK \u2192 export traces to Jaeger \u2192 visualise spans in the Jaeger UI.<br>\n      trace_id propagated in headers: <code>traceparent: 00-{trace_id}-{span_id}-01</code><br>\n      All services that receive this header add their span to the same trace.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 OpenTelemetry is vendor-neutral \u2014 switch backends without re-instrumenting. Used by: Google Cloud Trace, AWS X-Ray, Datadog, New Relic all accept OTLP format.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Structured Logging</div><div class=\"concept-def\"><strong>Log as JSON instead of plain text. Every field is queryable.</strong><br>\n      Bad: <code>\"ERROR: user 123 failed login from 1.2.3.4 at 14:23:01\"</code> \u2014 requires regex to parse.<br>\n      Good: <code>{\"level\":\"error\",\"event\":\"login_failed\",\"user_id\":123,\"ip\":\"1.2.3.4\",\"ts\":\"14:23:01\"}</code> \u2014 directly filterable in Elasticsearch or Loki.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Filter all errors for user:123 in seconds. Correlate across services by request_id. Aggregate error types. Essential for production debugging at scale.</span></div></div>\n  </div>\n</section>\n\n\n<section id=\"debugging\">\n  <div class=\"sec-tag\">03 \u00b7 Debugging a Production Incident</div>\n  <h2>The systematic approach \u2014 Director-level expected</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">The Incident Response Flow</div><div class=\"concept-def\"><strong>A structured approach to diagnosing production issues in real time:</strong><br>\n      1. <strong>What is broken?</strong> \u2192 Check golden signals dashboard. Which service is elevated on errors or latency?<br>\n      2. <strong>When did it start?</strong> \u2192 Correlate with recent deployments (deployment markers on Grafana). Was there a deploy 5 minutes before the spike?<br>\n      3. <strong>Which requests are affected?</strong> \u2192 Sample error traces in Jaeger. Is it all users or a specific cohort (specific region, device, API version)?<br>\n      4. <strong>Why is it failing?</strong> \u2192 Drill into traces to find the slow/failing span. Check logs for that service around that time.<br>\n      5. <strong>Fix or rollback?</strong> \u2192 If recent deploy is culprit: rollback first, diagnose later. Never debug a production incident with a new deployment in flight.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Cardinality Problem</div><div class=\"concept-def\"><strong>High-cardinality labels in metrics explode your time-series database cost and performance.</strong><br>\n      Bad: <code>http_requests_total{user_id=\"12345\", ...}</code> \u2014 if 1M users, this creates 1M time series. Prometheus stores each separately. Query performance degrades, storage costs explode.<br>\n      Good: <code>http_requests_total{status=\"200\", endpoint=\"/api/feed\"}</code> \u2014 low cardinality labels only. Use traces for per-user debugging, not metrics.<br>\n      <span style=\"color:#b83030;font-size:12.5px;\">\u26a0 The rule: metrics are for aggregates (rates, percentiles, counts by cohort). Traces are for individual requests. Never put high-cardinality identifiers (user_id, request_id) in metric labels.</span></div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Sampling Strategy</div><div class=\"concept-def\"><strong>Storing 100% of traces at high traffic is cost-prohibitive. Smart sampling is essential.</strong><br>\n      <strong>Head-based sampling</strong>: decide at trace start whether to sample. Simple (coin flip at 1%). Misses rare errors \u2014 a 0.01% error rate with 1% sampling = you only see 1 in 10,000 errors.<br>\n      <strong>Tail-based sampling</strong>: collect all spans, decide at trace completion. Always sample: all traces with errors, all traces over p99 latency, 1% of normal traces. Captures all interesting events.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Tail-based sampling is the production standard (Honeycomb, Datadog APM, OpenTelemetry Collector). Ensures no errors are missed while controlling storage costs.</span></div></div>\n  </div>\n</section>\n\n<section id=\"sd-examples-obs\">\n  <div class=\"sec-tag\">04 \u00b7 System Design Examples</div>\n  <h2>Observability architecture in real systems</h2>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Top-K System \u2014 End-to-End Observability</div><span class=\"sd-example-tag\">MULTI-LAYER MONITORING</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">METRICS</div><div class=\"choice-val\">Prometheus scrapes every 15s: Kafka consumer lag per topic/partition, Flink checkpointing duration, Redis ZSET operation latency (p50/p95/p99), ClickHouse query latency, API response time per endpoint. Grafana dashboard: one panel per layer, red/amber/green colour coding against SLO thresholds.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LOGS</div><div class=\"choice-val\">Structured JSON logs from all services \u2192 Filebeat \u2192 Logstash \u2192 Elasticsearch (ELK stack). Key log events: Flink checkpoint completed/failed (with duration), Redis ZINCRBY latency &gt;10ms (warning), ClickHouse query &gt;2s (slow query log). Kibana dashboard for ops team to search by trace_id, entity_id, window_time.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">TRACES</div><div class=\"choice-val\">OpenTelemetry SDK in API service. Every <code>GET /top-k</code> request creates a trace: API handler \u2192 Redis ZREVRANGE \u2192 (cache miss) \u2192 ClickHouse query \u2192 response. Jaeger shows: Redis hit rate over time, ClickHouse query breakdown (parse/execute/return), p99 end-to-end latency by region.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ALERTING</div><div class=\"choice-val\">Alert 1: Kafka consumer lag &gt;100K messages for &gt;5 minutes \u2192 Flink is falling behind, data staleness risk. Alert 2: Redis error rate &gt;0.1% \u2192 cache issues, requests falling through to ClickHouse. Alert 3: SLO burn rate alert \u2014 if error budget burning 10x faster than sustainable \u2192 PagerDuty page.</div></div>\n    </div>\n  </div>\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\"><div class=\"sd-example-title\">Payment Service \u2014 High-Stakes Observability</div><span class=\"sd-example-tag\">FINANCIAL \u00b7 COMPLIANCE</span></div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">TRANSACTION TRACING</div><div class=\"choice-val\">Every payment request carries a trace_id (in header and DB). Trace spans: API validation \u2192 idempotency check \u2192 bank API call \u2192 DB write \u2192 confirmation. For any disputed transaction, ops can reconstruct exact execution path, timing, and error messages from traces.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">AUDIT LOGS</div><div class=\"choice-val\">Immutable audit log: every state change (payment initiated, authorised, captured, refunded) written to append-only Kafka topic \u2192 S3. Logs cannot be deleted or modified. Required for PCI-DSS compliance. Separate from operational logs \u2014 different retention (7 years) and access controls.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ERROR BUDGET</div><div class=\"choice-val\">Payment success SLO: 99.99% (52 minutes downtime/year). Error budget dashboard updated in real time. Engineering team alerted when error budget &lt;20% remaining in current month \u2192 freeze all non-critical deployments, focus only on reliability improvements.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"alerting\">\n  <div class=\"sec-tag\">05 \u00b7 Alerting Best Practices</div>\n  <h2>Building alerts that are actionable, not noisy</h2>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\"><div class=\"concept-term\">Symptom vs Cause</div><div class=\"concept-def\"><strong>Alert on symptoms (user-visible problems), not causes (infrastructure metrics).</strong><br>\n      Bad: \"Alert when CPU &gt; 80%.\" CPU spikes happen constantly, usually resolve, rarely impact users.<br>\n      Good: \"Alert when p99 latency &gt; 500ms for &gt;2 minutes.\" This directly measures user experience.<br>\n      The test: \"If this alert fires at 3am, would I do something different immediately?\" If no \u2192 it should be a ticket, not a page.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">Multi-Window Alerting</div><div class=\"concept-def\"><strong>Use two windows to reduce false positives: a short window for detection, a longer window for confirmation.</strong><br>\n      Alert if: error rate &gt; 5% for last 2 minutes (fast detection) AND error rate &gt; 1% for last 1 hour (confirms ongoing issue, not a spike).<br>\n      Single-window alerts are noisy \u2014 a 30-second spike fires the alert. Multi-window only fires when the issue is sustained.</div></div>\n    <div class=\"concept-row\"><div class=\"concept-term\">On-Call Runbook</div><div class=\"concept-def\"><strong>Every alert must link to a runbook \u2014 documented steps the on-call engineer follows.</strong><br>\n      Runbook for \"p99 latency elevated\": (1) Check Grafana: which endpoint is slow? (2) Open Jaeger: find slow traces for that endpoint. (3) Is it a DB query? Check slow query log. (4) Is it an external API? Check circuit breaker status. (5) If new deploy is correlated: rollback procedure link.<br>\n      <span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Reduces mean time to resolution (MTTR). New engineers can handle alerts without senior help. Runbooks should be updated after every incident \u2014 add what was missed.</span></div></div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">03 \u00b7 Follow-ups</div>\n  <h2>Every hard follow-up, answered</h2>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you set meaningful SLOs \u2014 how do you know what 99.9% vs 99.99% means for your system?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Start with what users actually notice, not an arbitrary number.</strong><br><br>\n  <strong>Step 1 \u2014 Measure current reliability</strong>: what is your actual success rate over the last 30 days? This is your baseline. Setting an SLO below current performance is pointless.<br><br>\n  <strong>Step 2 \u2014 Understand user tolerance</strong>: what level of error do users actually experience and complain about? For a social feed, a 0.1% error rate might be imperceptible. For a payment API, even 0.01% errors (one in 10,000 payments failing) would cause serious complaints.<br><br>\n  <strong>Step 3 \u2014 Cost of reliability</strong>: going from 99.9% to 99.99% availability typically requires: redundant infrastructure, geographic distribution, more complex failure handling. Is the engineering investment justified by the product need?<br><br>\n  <strong>Typical starting points</strong>: User-facing read API: 99.9%. User-facing write API: 99.95%. Payment processing: 99.99%. Internal infrastructure services: 99.5%. Batch processing: 99%.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you avoid alert fatigue while still catching real incidents?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Alert on symptoms, not causes. Alert on SLO burn rate, not on individual metric thresholds.</strong><br><br>\n  <strong>The anti-pattern</strong>: \"Alert when CPU &gt; 80%.\" CPU spikes happen constantly and usually resolve without user impact. Engineers learn to ignore the alerts (alert fatigue). When a real incident happens, it is buried in noise.<br><br>\n  <strong>Better approach \u2014 SLO burn rate alerting</strong>: alert when you are burning your error budget faster than sustainable. \"Alert when error rate over the last 1 hour would exhaust the monthly error budget in 2 days.\" This alert is high-signal \u2014 it means users are actually experiencing problems at a rate that will violate your SLO.<br><br>\n  <strong>Alert design rules</strong>:<br>\n  1. Every alert must be actionable \u2014 if there is no runbook for it, delete it<br>\n  2. Alerts should page at most once per incident, not continuously<br>\n  3. Alert on p99 latency, not p50 \u2014 averages hide the long tail that users experience<br>\n  4. Distinguish page (wake someone up) vs ticket (fix in business hours) severity</div></div>\n\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you implement distributed tracing without instrumenting every microservice?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Use service mesh sidecar proxies (Envoy/Istio) for automatic trace propagation without touching application code.</strong><br><br>\n  <strong>Sidecar-based tracing</strong>: Istio injects Envoy sidecar proxies alongside every service. Envoy automatically: generates trace IDs for new requests, propagates <code>traceparent</code> header to outbound calls, records span timing for every hop, exports spans to Jaeger/Zipkin/Tempo.<br><br>\n  Application code does not need any instrumentation changes. You get traces for all service-to-service calls immediately.<br><br>\n  <strong>Limitation</strong>: Envoy can only trace at the network boundary. Internal operations (DB queries, function calls within a service) require application-level instrumentation.<br><br>\n  <strong>Hybrid approach</strong>: Envoy handles inter-service tracing automatically. Add OpenTelemetry SDK to only the highest-value services (payment, order creation) for internal DB query tracing. You get 80% of the value with 20% of the instrumentation effort.<br><br>\n  <strong>Trace context propagation</strong>: the key is that the <code>traceparent</code> header (W3C Trace Context standard) must be forwarded by every service. Even without full SDK instrumentation, if services forward this header, trace IDs connect across the call graph.</div></div>\n  <div class=\"faq-item\"><div class=\"faq-q\" onclick=\"toggle(this)\">How do you define SLOs for a complex system with multiple components?<span class=\"tog\">+</span></div>\n  <div class=\"faq-a\"><strong>Define SLOs at the user-facing level, not at the component level. Users do not care which component failed.</strong><br><br>\n  <strong>Wrong approach</strong>: separate SLOs for Kafka (99.9%), Flink (99.5%), Redis (99.99%), ClickHouse (99.9%), API (99.95%). These cascade \u2014 if any one component hits its limit, the user-facing system fails.<br><br>\n  <strong>Correct approach</strong>: one SLO for the user-observable service: \"<code>GET /top-k</code> returns a successful response in &lt;100ms for 99.9% of requests over any 30-day window.\"<br><br>\n  <strong>Component SLIs feed the top-level SLO</strong>: if Flink falls behind \u2192 rankings get stale \u2192 API still returns 200 but with stale data. Is this an SLO violation? Depends on your SLI definition \u2014 include freshness in the SLI if staleness is user-visible.<br><br>\n  <strong>The CUJ (Critical User Journey) approach</strong> from Google SRE: define SLOs per user journey, not per service. \"User can see updated trending content within 60 seconds of an event going viral.\" This SLO captures the entire pipeline (Kafka lag + Flink latency + Redis update + API response) as a single observable outcome.<br><br>\n  Start with 2\u20133 top-level SLOs per major user journey. Add component-level SLIs only when you need finer-grained alerting to diagnose which component is contributing to SLO burn.</div></div>\n</section></div>\n\n<section id=\"decision-obs\">\n  <div class=\"sec-tag\">06 \u00b7 Decision Framework</div>\n  <h2>Building your observability stack</h2>\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Observability Stack Selection</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Cloud provider or self-managed?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Managed (cloud) \u2192</span><span class=\"opt-text\"><strong>Datadog / New Relic / Dynatrace.</strong> One agent, everything included: metrics, logs, traces, APM, dashboards, alerting. Expensive at scale ($$$) but zero ops. Best for: startups to mid-size engineering teams without a dedicated platform team.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Self-managed (OSS) \u2192</span><span class=\"opt-text\"><strong>Prometheus + Grafana + Jaeger + Loki.</strong> Free, highly customisable, industry standard. Requires a platform team to operate. Best for: large engineering orgs, cost-sensitive at scale, need full data ownership.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">How do you alert \u2014 page or ticket?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Page (wake someone up) \u2192</span><span class=\"opt-text\"><strong>SLO burn rate alert.</strong> Only page when error budget is burning at an unsustainable rate. Alert on: p99 latency &gt; SLO threshold for &gt;2 minutes, error rate &gt; 1% sustained, SLO burn rate 10x normal. Every page must be actionable with a runbook.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Ticket (fix in business hours) \u2192</span><span class=\"opt-text\"><strong>Threshold alerts on symptoms.</strong> CPU consistently &gt;80%, disk &gt;70%, error rate trending up but below SLO. These are leading indicators \u2014 important to track but not urgent enough to wake someone up.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Microservices or monolith?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Microservices (&gt;5 services) \u2192</span><span class=\"opt-text\"><strong>Distributed tracing is non-negotiable.</strong> Without traces, debugging a latency spike across 10 services is impossible. Instrument with OpenTelemetry SDK or use Envoy sidecar for automatic trace propagation. Jaeger or Tempo as backend. Sample 100% errors, 1% normal traffic.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Monolith / few services \u2192</span><span class=\"opt-text\"><strong>Structured logs + metrics are sufficient.</strong> A single service's logs tell the full story. Elasticsearch + Kibana for log search. Prometheus + Grafana for metrics. Add traces later when you split into microservices.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n</section>\n<div class=\"footer\">MONITORING \u00b7 OBSERVABILITY \u00b7 PROMETHEUS \u00b7 JAEGER \u00b7 SLO \u00b7 ERROR BUDGET \u00b7 GOLDEN SIGNALS \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body></html>", tag: 'Observability' }
};

function openCollection(){
  document.getElementById('list').style.display='none';
  document.getElementById('coll-panel').classList.add('open');
}
function closeCollection(){
  document.getElementById('coll-item').classList.remove('open');
  var f=document.getElementById('ci-iframe');if(f)f.srcdoc='';
  document.getElementById('coll-panel').classList.remove('open');
  document.getElementById('list').style.display='block';
}
function openCollItem(id){
  var item=COLLECTION_DATA[id];
  if(!item)return;
  document.getElementById('ci-title').textContent=item.title;
  var iframe=document.getElementById('ci-iframe');
  document.getElementById('coll-item').classList.add('open');
  if(item.srcdoc){
    /* embedded — works on file://, GitHub Pages, everywhere */
    iframe.srcdoc=item.srcdoc;
  } else {
    /* fetch-based — for cms/topk/ai_handbook standalone files */
    iframe.srcdoc='<div style="font-family:-apple-system,sans-serif;padding:40px 24px;text-align:center;color:#aaa;font-size:14px">Loading…</div>';
    fetch(item.file)
      .then(function(r){ if(!r.ok)throw new Error('HTTP '+r.status); return r.text(); })
      .then(function(html){ iframe.srcdoc=html; })
      .catch(function(e){
        iframe.srcdoc='<div style="font-family:-apple-system,sans-serif;padding:40px 24px;color:#c00;font-size:14px">Could not load '+item.file+'.<br><small>'+e.message+'</small><br><br><small>Run via server: <code>python3 -m http.server</code></small></div>';
      });
  }
}
function closeCollItem(){
  document.getElementById('coll-item').classList.remove('open');
  /* Clear iframe to stop any running scripts */
  setTimeout(function(){
    var f=document.getElementById('ci-iframe');
    if(f)f.srcdoc='';
  },50);
}

function initCollection(){
  var pairs=[
    ['btn_collection',   function(){openCollection();}],
    ['btn_coll_back',    function(){closeCollection();}],
    ['btn_ci_back',      function(){closeCollItem();}],
    ['btn_coll_cms',     function(){openCollItem('cms');}],
    ['btn_coll_topk',    function(){openCollItem('topk');}],
    ['btn_coll_ai',      function(){openCollItem('ai_handbook');}],
    ['btn_coll_databases',function(){openCollItem('databases');}],
    ['btn_coll_olap',    function(){openCollItem('olap');}],
    ['btn_coll_streaming',function(){openCollItem('streaming');}],
    ['btn_coll_protocols',function(){openCollItem('protocols');}],
    ['btn_coll_caching',function(){openCollItem('caching');}],
    ['btn_coll_consistent_hashing',function(){openCollItem('consistent_hashing');}],
    ['btn_coll_rate_limiting',function(){openCollItem('rate_limiting');}],
    ['btn_coll_distributed_systems',function(){openCollItem('distributed_systems');}],
    ['btn_coll_load_balancing',function(){openCollItem('load_balancing');}],
    ['btn_coll_search',function(){openCollItem('search');}],
    ['btn_coll_object_storage',function(){openCollItem('object_storage');}],
    ['btn_coll_message_queues',function(){openCollItem('message_queues');}],
    ['btn_coll_cdn_edge',function(){openCollItem('cdn_edge');}],
    ['btn_coll_observability',function(){openCollItem('observability');}]
  ];
  pairs.forEach(function(p){
    var el=document.getElementById(p[0]);
    if(el) el.addEventListener('click',p[1]);
  });
}
